	public delegate void CharacterAddedEventHandler(GameObject character, CActor actor = null, CObjectProp prop = null);

	public class PendingAnimationScope : IDisposable
	{
		private object m_PendingAnimation;

		public PendingAnimationScope(object pendingAnimation)
		{
			m_PendingAnimation = pendingAnimation;
			s_Choreographer.AddPendingAnimationToWait(m_PendingAnimation);
		}

		public void Dispose()
		{
			if ((bool)s_Choreographer)
			{
				s_Choreographer.RemovePendingAnimationToWait(m_PendingAnimation);
			}
		}
	}

