	private void TickEndAbilityClientReadyRecovery()
	{
		if (m_ClientEndOfAbilityReadyPending)
		{
			float num = Timekeeper.instance.m_GlobalClock.unscaledTime - m_TimeOfEndAbilityClientReadySent;
			if (!m_LoggedEndAbilitySyncSoftlock && num >= 5f)
			{
				m_LoggedEndAbilitySyncSoftlock = true;
				UIMultiplayerNotifications.ShowPossibleTimeout();
				Log.Error($"[END ABILITY SYNC] Client has waited {num:F1}s for EndOfAbilityAllPlayersReady after sending EndOfAbilityClientReady but the host has not released it. Likely a host/client end-of-ability sync-point count mismatch (stacked sub-abilities diverging between machines). Forcing local recovery at {15f:F0}s.");
			}
		}
	}

	public static bool IsPlayingIdleAnimation(GameObject actorGO, bool tryToUnstuck = true)
	{
		if (Main.s_Pause3DWorld)
		{
			s_PausedWhileWaiting = true;
			s_LastReportedNotIdleForALongTimeWaitState = s_Choreographer.m_WaitState;
			return false;
		}
		if (IdleStates.Any((string x) => MF.GameObjectAnimatorControllerIsCurrentState(actorGO, x)))
		{
			s_PausedWhileWaiting = false;
			return true;
		}
		if (!tryToUnstuck)
		{
			return false;
		}
		if (s_Choreographer?.m_WaitState == null)
		{
			return false;
		}
		ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(actorGO);
		if (actorBehaviour.IsLocoPaused())
		{
			return false;
		}
		if (actorBehaviour.Actor.Interacting)
		{
			return false;
		}
		if (Environment.TickCount < s_Choreographer.m_WaitState.m_StateWaitTickFrame + 5000)
		{
			return false;
		}
		if (s_Choreographer.m_WaitState == s_LastReportedNotIdleForALongTimeWaitState)
		{
			if (s_PausedWhileWaiting)
			{
				return false;
			}
			return true;
		}
		s_LastReportedNotIdleForALongTimeWaitState = s_Choreographer.m_WaitState;
		s_PausedWhileWaiting = false;
		CActor actor = ActorBehaviour.GetActor(actorGO);
		Log.Error($"Actor not idle for a long time during {s_Choreographer.m_WaitState.m_State}: {actor} ");
		return true;
	}

