	public static void CharacterOutlineRegistration(CharacterManager characterManager, bool register)
	{
		int num = 0;
		IList<Outlinable> outlinables;
		IList<bool> canUseMaskedMode;
		if (CustomActorOutlinableConfig.TryFindInCharacter(characterManager, out var customConfig))
		{
			num = customConfig.GetControllableOutlines(out outlinables, out canUseMaskedMode);
		}
		else
		{
			num = ((Array)(outlinables = characterManager.GetComponentsInChildren<Outlinable>())).Length;
			canUseMaskedMode = Enumerable.Repeat(characterManager.CharacterActor != null, num).ToList();
		}
		bool flag = false;
		if (characterManager.CharacterActor is CObjectActor cObjectActor && (cObjectActor.Class.ID == "InvisibleDoorID" || cObjectActor.Class.ID == "PropDummyObject" || (cObjectActor.AttachedProp != null && num == 0)))
		{
			flag = true;
			if (cObjectActor.AttachedProp != null)
			{
				outlinables = FindPropGameObject(cObjectActor.AttachedProp)?.GetComponentsInChildren<Outlinable>(includeInactive: true);
				num = outlinables?.Count ?? 0;
				canUseMaskedMode = Enumerable.Repeat(characterManager.CharacterActor != null, num).ToList();
			}
		}
		if (outlinables != null)
		{
			for (int i = 0; i < num; i++)
			{
				if (register)
				{
					outlinables[i].OutlineParameters.Color = UIInfoTools.GetCharacterOutlineColor(characterManager.CharacterActor.OriginalType);
					WorldspaceUITools.Instance.AddOutlinableToList(outlinables[i], characterManager.CharacterActor, canUseMaskedMode[i]);
				}
				else
				{
					WorldspaceUITools.Instance.RemoveOutlinableFromList(outlinables[i]);
				}
			}
		}
		if (!flag && num == 0)
		{
			Log.Error("Character instance for prefab: " + characterManager.CharacterActor.GetPrefabName() + " is missing the Outlinable component");
		}
	}

	public GameObject CreateCharacterActor(CClientTile tile, CActor actor, bool isSummoned = false, string skinId = null, bool isExhaustedCharacter = false)
	{
		try
		{
			GameObject characterPrefabFromBundle = AssetBundleManager.Instance.GetCharacterPrefabFromBundle(actor.GetPrefabActorType(), actor.GetPrefabName(), skinId);
			if (characterPrefabFromBundle == null)
			{
				characterPrefabFromBundle = AssetBundleManager.Instance.LoadAssetFromBundle<GameObject>("npc_none", "NULLCharacter", "npcs");
				throw new Exception("Unable to find character with prefab name " + actor.GetPrefabName());
			}
			GameObject gameObject = ObjectPool.Spawn(characterPrefabFromBundle, null);
			CharacterManager characterManager = CharacterManager.GetCharacterManager(gameObject);
			gameObject.name = actor.ActorGuid;
			characterManager.CharacterPrefab = characterPrefabFromBundle;
			characterManager.CharacterActor = actor;
			characterManager.InitialiseCharacter();
			ActivateActorVisuals.SetActive(gameObject, active: true);
			SkinnedMeshRenderer[] componentsInChildren = characterManager.CharacterChildPrefabInstance.GetComponentsInChildren<SkinnedMeshRenderer>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				Material material = componentsInChildren[i].GetMaterialClonesSlow().First();
				if (!(material.shader.name == "Amp_Char_Shader"))
				{
					continue;
				}
				string htmlString = "#FFFFFF";
				float value = 0f;
				float num = 0f;
				if (actor.Type == CActor.EType.Player)
				{
					htmlString = (actor.Class as CCharacterClass).CharacterYML.ColourHTML;
					value = (actor.Class as CCharacterClass).CharacterYML.Fatness;
					num = (actor.Class as CCharacterClass).CharacterYML.VertexAnimIntensity;
				}
				else if (actor.Type == CActor.EType.Enemy || actor.Type == CActor.EType.Neutral || actor.Type == CActor.EType.Enemy2 || actor.Type == CActor.EType.Ally)
				{
					htmlString = (actor.Class as CMonsterClass).MonsterYML.ColourHTML;
					value = (actor.Class as CMonsterClass).MonsterYML.Fatness;
					num = (actor.Class as CMonsterClass).MonsterYML.VertexAnimIntensity;
				}
				else if (actor.Type == CActor.EType.HeroSummon)
				{
					htmlString = (actor.Class as CHeroSummonClass).SummonYML.ColourHTML;
					value = (actor.Class as CHeroSummonClass).SummonYML.Fatness;
					num = (actor.Class as CHeroSummonClass).SummonYML.VertexAnimIntensity;
				}
				if (material.HasProperty("_MOD_TINT") && ColorUtility.TryParseHtmlString(htmlString, out var color))
				{
					material.SetColor("_MOD_TINT", color);
				}
				if (material.HasProperty("_MOD_THICKEN"))
				{
					material.SetFloat("_MOD_THICKEN", value);
				}
				if (!material.HasProperty("_AddVertexAnim"))
				{
					continue;
				}
				if (material.GetFloat("_AddVertexAnim") == 0f)
				{
					if (num != 0f)
					{
						if (material.HasProperty("_NoiseSpeed"))
						{
							material.SetFloat("_NoiseSpeed", 0f);
						}
						if (material.HasProperty("_VertexAnim_Intensity"))
						{
							material.SetFloat("_VertexAnim_Intensity", num);
						}
						material.SetFloat("_AddVertexAnim", 1.1f);
					}
				}
				else if (material.GetFloat("_AddVertexAnim") == 1.1f && num == 0f)
				{
					material.SetFloat("_AddVertexAnim", 0f);
				}
			}
			GameObject gameObject2 = ObjectPool.Spawn(m_ActorPrefab, null);
			Log.Info("[Chor] Instantiated actor prefab for actorGuid: " + actor.ActorGuid);
			characterManager.CharacterActorGO = gameObject2;
			gameObject2.GetComponent<CInteractableActor>()?.Init(characterManager);
			Animator[] componentsInChildren2 = gameObject.transform.GetComponentsInChildren<Animator>(includeInactive: true);
			IEnumerable<Animator> enumerable = componentsInChildren2.Where((Animator x) => x.transform.gameObject.layer == LayerMask.NameToLayer("Hero") || x.transform.gameObject.layer == LayerMask.NameToLayer("Monster"));
			if (actor is CObjectActor && !enumerable.Any() && componentsInChildren2.Any())
			{
				GameObject characterChildPrefabInstance = characterManager.CharacterChildPrefabInstance;
				if ((object)characterChildPrefabInstance != null && characterChildPrefabInstance.TryGetComponent<Animator>(out var component) && componentsInChildren2.Contains(component))
				{
					enumerable = new Animator[1] { component };
					GameObject characterChildPrefabInstance2 = characterManager.CharacterChildPrefabInstance;
					if ((object)characterChildPrefabInstance2 != null && characterChildPrefabInstance2.TryGetComponent<PropHealthState>(out var component2))
					{
						component2.ResetPrevHealth();
					}
				}
			}
			foreach (Animator item in enumerable)
			{
				item.gameObject.AddComponent<ActorEvents>();
			}
			ActorLocationInUnityHierarchy componentInChildren = gameObject.transform.GetComponentInChildren<ActorLocationInUnityHierarchy>();
			if (componentInChildren != null)
			{
				gameObject2.transform.SetParent(componentInChildren.transform);
				Log.Info("[Chor] Set transform parent for actor prefab for actorGuid: " + actor.ActorGuid + " parent transform instance name: " + componentInChildren.transform.name);
			}
			else if (enumerable.Any())
			{
				Transform transform = enumerable.FirstOrDefault().transform;
				gameObject2.transform.SetParent(transform);
				Log.Info("[Chor] Set transform parent for actor prefab for actorGuid: " + actor.ActorGuid + " parent transform instance name: " + transform.name);
			}
			else
			{
				gameObject2.transform.SetParent(gameObject.transform);
				Log.Info("[Chor] Set transform parent for actor prefab for actorGuid: " + actor.ActorGuid + " parent transform instance name: " + gameObject.transform.name);
				Log.Warning("Unable to find animator on correct layer for CharacterPrefab:" + actor.GetPrefabName());
			}
			gameObject2.transform.localPosition = Vector3.zero;
			UnityGameEditorObject component3 = gameObject.GetComponent<UnityGameEditorObject>();
			if (tile != null)
			{
				gameObject.transform.SetParent(ClientScenarioManager.s_ClientScenarioManager.m_Board.transform);
				gameObject.transform.position = tile.m_GameObject.transform.position;
				if (!isExhaustedCharacter)
				{
					ActorBehaviour.SetActor(gameObject, actor, actor.SkipVisualsAndGUI);
					CharacterOutlineRegistration(characterManager, register: true);
				}
				ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
				if (actor.Interacting)
				{
					actorBehaviour.SkipInteractIntro(skip: true);
				}
				else if (actorBehaviour.ShouldLookAtActors())
				{
					if (actor.Type == CActor.EType.Enemy)
					{
						Vector3 enemyFocalPoint = GetEnemyFocalPoint(gameObject);
						gameObject.transform.LookAt(enemyFocalPoint);
					}
					else
					{
						GetAveragePositions(out var _, out var averageEnemyPosition, out var _, out var _, out var _);
						gameObject.transform.LookAt(averageEnemyPosition);
					}
				}
				else
				{
					actorBehaviour.SetTransformRotation(Quaternion.identity);
				}
				component3.m_ShouldSnapToHexSpacing = true;
			}
			else
			{
				component3.m_ShouldSnapToHexSpacing = false;
			}
			if (!isSummoned && actor.Type == CActor.EType.Player && SaveData.Instance.Global.GameMode != EGameMode.LevelEditor)
			{
				Singleton<CardsHandManager>.Instance.AddPlayer((CPlayerActor)actor);
			}
			SummonAppear componentInChildren2 = gameObject.GetComponentInChildren<SummonAppear>();
			if (componentInChildren2 != null)
			{
				componentInChildren2.enabled = isSummoned;
				if (isSummoned)
				{
					Animator gameObjectAnimator = MF.GetGameObjectAnimator(gameObject);
					MF.AnimatorPlay(gameObjectAnimator, "Summoned");
					gameObjectAnimator.Update(0.1f);
				}
			}
			else if (!ScenarioManager.IsFastReloading || !ScenarioManager.IsLoading)
			{
				Animator gameObjectAnimator2 = MF.GetGameObjectAnimator(gameObject);
				if (MF.AnimatorPlay(gameObjectAnimator2, "Spawned"))
				{
					gameObjectAnimator2.Update(0.1f);
				}
			}
			if (actor.IsDowned)
			{
				MF.AnimatorPlay(MF.GetGameObjectAnimator(gameObject), "DownedIdle");
			}
			AllActorsInScene.Add(gameObject);
			OnCharacterAdded(gameObject, actor);
			if (isExhaustedCharacter)
			{
				gameObject.transform.SetParent(null);
				gameObject.transform.position = DeadPlayerLocation;
				CharacterOutlineRegistration(characterManager, register: false);
				characterManager.DeinitializeCharacter();
			}
			if (actor is CHeroSummonActor { IsCompanionSummon: not false } cHeroSummonActor)
			{
				PreviewEffectInfo previewEffectConfig = UIInfoTools.Instance.GetPreviewEffectConfig(cHeroSummonActor.SummonData.Model);
				string format = ((previewEffectConfig != null && previewEffectConfig.previewEffectText != null) ? LocalizationManager.GetTranslation(previewEffectConfig.previewEffectText) : LocalizationManager.GetTranslation(cHeroSummonActor.HeroSummonClass.DefaultModel + "_TOOLTIP"));
				ActorBehaviour.GetActorBehaviour(gameObject).m_WorldspacePanelUI?.AddEffect("Companion", previewEffectConfig?.previewEffectIcon ?? UIInfoTools.Instance.GetCharacterSprite(cHeroSummonActor.Summoner.CharacterClass.CharacterModel, highlight: false, cHeroSummonActor.Summoner.CharacterClass.CharacterYML.CustomCharacterConfig), string.Format("<color=#{1}>{0}", LocalizationManager.GetTranslation(cHeroSummonActor.SummonData.LocKey), UIInfoTools.Instance.GetCharacterColor(cHeroSummonActor.Summoner.CharacterClass.CharacterModel, cHeroSummonActor.Summoner.CharacterClass.CharacterYML.CustomCharacterConfig).ToHex()), string.Format(format, cHeroSummonActor.MaxHealth, cHeroSummonActor.SummonData.Move, cHeroSummonActor.SummonData.Attack, (cHeroSummonActor.SummonData.Range < 2) ? "-" : cHeroSummonActor.SummonData.Range.ToString()));
			}
			if (actor.GetMirrorActor() is CPlayerActor cPlayerActor && !string.IsNullOrEmpty(actor.OverrideCharacterModel))
			{
				ChangeActorForm(ActorBehaviour.GetActorBehaviour(gameObject), cPlayerActor.Form, instant: true);
			}
			if (!isExhaustedCharacter)
			{
				Log.Info("[Chor] Creating character actor gameobject: " + LocalizationManager.GetTranslation(actor.ActorLocKey(), fixForRTL: true, 0, ignoreRTLnumbers: true, applyParameters: false, null, null, skipWarnings: true) + GetActorIDForCombatLogIfNeeded(actor) + " at tile: " + tile.m_Tile.m_ArrayIndex.ToString());
			}
			FHUICodex.UnlockCodexTag(actor);
			return gameObject;
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred within the Choreographer.CreateCharacterActor().");
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00149", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
			return null;
		}
	}

	public GameObject CreatePreviewPlayer(CClientTile tile, CActor actor, string skinId = null)
	{
		return CreatePreviewPlayer(tile, actor.Type, actor.GetPrefabName(), skinId);
	}

	public GameObject CreatePreviewPlayer(CClientTile tile, CActor.EType actorType, string prefabName, string skinId = null)
	{
		using (new MiniProfilerScope("CreatePreviewPlayer"))
		{
			try
			{
				GameObject characterPrefabFromBundle = AssetBundleManager.Instance.GetCharacterPrefabFromBundle(actorType, prefabName, skinId);
				if (characterPrefabFromBundle == null)
				{
					return null;
				}
				GameObject gameObject = ObjectPool.Spawn(characterPrefabFromBundle, ClientScenarioManager.s_ClientScenarioManager.m_Board.transform, actorType != CActor.EType.Enemy);
				CharacterManager characterManager = CharacterManager.GetCharacterManager(gameObject);
				characterManager.CharacterPrefab = characterPrefabFromBundle;
				characterManager.InitialiseCharacter(forMenu: false, isPreview: true);
				UnityGameEditorObject component = gameObject.GetComponent<UnityGameEditorObject>();
				if (tile != null)
				{
					gameObject.transform.position = tile.m_GameObject.transform.position;
				}
				component.m_ShouldSnapToHexSpacing = true;
				Cloth[] componentsInChildren = gameObject.transform.GetComponentsInChildren<Cloth>();
				foreach (Cloth obj in componentsInChildren)
				{
					obj.coefficients = obj.coefficients;
				}
				gameObject.gameObject.SetActive(value: false);
				return gameObject;
			}
			catch (Exception ex)
			{
				Log.Exception(ex, "An exception occurred within the Choreographer.CreateCharacterActor().");
				SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00149", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
				return null;
			}
		}
	}

	public void ClearPlayersEnemies()
	{
		ClearChars(m_ClientPlayers);
		m_ClientPlayers.Clear();
		m_ClientDeadActors.Clear();
		ClearChars(m_ClientEnemies);
		m_ClientEnemies.Clear();
		ClearChars(m_ClientHeroSummons);
		m_ClientHeroSummons.Clear();
		ClearChars(m_ClientAllyMonsters);
		m_ClientAllyMonsters.Clear();
		ClearChars(m_ClientEnemy2Monsters);
		m_ClientEnemy2Monsters.Clear();
		ClearChars(m_ClientNeutralMonsters);
		m_ClientNeutralMonsters.Clear();
		ClearChars(m_ClientObjects);
		m_ClientObjects.Clear();
		m_ActorBehaviourCache.Clear();
		m_PropGameObjectCache.Clear();
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		static void ClearChars(IEnumerable<GameObject> characters)
		{
			foreach (GameObject character in characters)
			{
				CharacterManager characterManager = CharacterManager.GetCharacterManager(character);
				if ((bool)characterManager)
				{
					CharacterOutlineRegistration(characterManager, register: false);
				}
				CharacterManager.RecycleCharacterInstance(character);
			}
		}
	}

	private async Task CreatePlayersEnemies()
	{
		using (new MiniProfilerScope("CreatePlayersEnemies"))
		{
			List<GameObject> prefabsToWarmUp = new List<GameObject>();
			HashSet<GameObject> effectsToWarmUp = new HashSet<GameObject>();
			using (new MiniProfilerScope("CreatePlayersEnemies.GatherPrefabsToWarmUp"))
			{
				double startTime = Time.realtimeSinceStartupAsDouble;
				int startFrame = Time.frameCount;
				foreach (CPlayerActor playerActor in ScenarioManager.Scenario.PlayerActors.Concat(ScenarioManager.Scenario.ExhaustedPlayers).ToList())
				{
					switch (SaveData.Instance.Global.GameMode)
					{
					case EGameMode.Campaign:
					{
						string skinString = SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.MapParty.SelectedCharacters.FirstOrDefault((CMapCharacter it) => it.CharacterID == playerActor.CharacterClass.ID)?.SkinId;
						GameObject gameObject2 = await AssetBundleManager.Instance.GetCharacterPrefabFromBundleAsync(CActor.EType.Player, playerActor.GetPrefabName(), skinString);
						if (!(gameObject2 == null))
						{
							CharacterManager.GatherCharacterPrefabsForWarmUp(gameObject2, prefabsToWarmUp, effectsToWarmUp);
							if (!m_ClientPlacementPreviews.ContainsKey(playerActor.CharacterClass.CharacterID))
							{
								CharacterManager.GatherCharacterPrefabsForWarmUp(gameObject2, prefabsToWarmUp, effectsToWarmUp);
							}
						}
						break;
					}
					case EGameMode.LevelEditor:
					case EGameMode.SingleScenario:
					case EGameMode.Autotest:
					case EGameMode.FrontEndTutorial:
					{
						GameObject gameObject = await AssetBundleManager.Instance.GetCharacterPrefabFromBundleAsync(CActor.EType.Player, playerActor.GetPrefabName());
						if (!(gameObject == null))
						{
							CharacterManager.GatherCharacterPrefabsForWarmUp(gameObject, prefabsToWarmUp, effectsToWarmUp);
						}
						break;
					}
					}
				}
				foreach (CHeroSummonActor heroSummon in ScenarioManager.Scenario.HeroSummons)
				{
					GameObject gameObject3 = await AssetBundleManager.Instance.GetCharacterPrefabFromBundleAsync(heroSummon.Type, heroSummon.GetPrefabName());
					if (!(gameObject3 == null))
					{
						CharacterManager.GatherCharacterPrefabsForWarmUp(gameObject3, prefabsToWarmUp, effectsToWarmUp);
					}
				}
				foreach (EnemyState enemyState in ScenarioManager.CurrentScenarioState.AllEnemyStates)
				{
					string text;
					if (enemyState is ObjectState)
					{
						text = MonsterClassManager.ObjectClasses.Single((CObjectClass x) => x.ID == enemyState.ClassID)?.Models[enemyState.ChosenModelIndex];
					}
					else
					{
						ScenarioManager.EPerPartySizeConfig configForPartySize = enemyState.GetConfigForPartySize(ScenarioManager.CurrentScenarioState.Players.Count);
						if (configForPartySize == ScenarioManager.EPerPartySizeConfig.Hidden)
						{
							continue;
						}
						if (configForPartySize == ScenarioManager.EPerPartySizeConfig.ToElite && !enemyState.IsElite)
						{
							text = MonsterClassManager.Classes.SingleOrDefault((CMonsterClass x) => x.NonEliteVariant != null && x.NonEliteVariant.ID == enemyState.ClassID)?.Models[enemyState.ChosenModelIndex];
							if (string.IsNullOrEmpty(text))
							{
								Log.Error("Cannot find Elite version of " + enemyState.ClassID + " to warm up for " + enemyState.ActorGuid + "!", this);
								continue;
							}
						}
						else
						{
							text = MonsterClassManager.Classes.SingleOrDefault((CMonsterClass x) => x.ID == enemyState.ClassID)?.Models[enemyState.ChosenModelIndex];
						}
					}
					GameObject gameObject4 = await AssetBundleManager.Instance.GetCharacterPrefabFromBundleAsync(CActor.EType.Enemy, text);
					if (!(gameObject4 == null))
					{
						CharacterManager.GatherCharacterPrefabsForWarmUp(gameObject4, prefabsToWarmUp, effectsToWarmUp);
					}
				}
				foreach (CObjectProp prop in ScenarioManager.CurrentScenarioState.Props)
				{
					if (prop.PropHealthDetails == null || !prop.PropHealthDetails.HasHealth || !prop.HasInitiative)
					{
						continue;
					}
					string text2 = MonsterClassManager.MonsterAndObjectClassesWithInitiative.SingleOrDefault((CMonsterClass x) => x.ID == prop.PropHealthDetails.ActorClass)?.Models[0];
					if (string.IsNullOrEmpty(text2))
					{
						Log.Error($"Cannot find prop {prop} actor class {prop.PropHealthDetails.ActorClass} to warm up!", this);
						continue;
					}
					GameObject gameObject5 = await AssetBundleManager.Instance.GetCharacterPrefabFromBundleAsync(CActor.EType.Enemy, text2);
					if (!(gameObject5 == null))
					{
						CharacterManager.GatherCharacterPrefabsForWarmUp(gameObject5, prefabsToWarmUp, effectsToWarmUp);
					}
				}
				double num = (double)Time.realtimeSinceStartup - startTime;
				int num2 = Time.frameCount - startFrame;
				int num3 = (int)(num * 1000.0);
				Log.Trace($"GatherPrefabsToWarmUp took {num3}ms over {num2} frame(s)");
			}
			using (new MiniProfilerScope("CreatePlayersEnemies.WarmUpPools"))
			{
				double startTime = Time.realtimeSinceStartupAsDouble;
				int startFrame = Time.frameCount;
				await Task.WhenAll(from prefab in prefabsToWarmUp
					group prefab by prefab into @group
					select ObjectPool.WarmUpPoolAsync(@group.Key, @group.Count()));
				await Task.WhenAll(from prefab in effectsToWarmUp
					group prefab by prefab into @group
					select ObjectPool.WarmUpPoolAsync(@group.Key, 2, "@ VFX Pool"));
				double num4 = (double)Time.realtimeSinceStartup - startTime;
				int num5 = Time.frameCount - startFrame;
				int num6 = (int)(num4 * 1000.0);
				Log.Trace($"WarmUpPools took {num6}ms over {num5} frame(s)");
			}
			using (new MiniProfilerScope("CreatePlayersEnemies.CreateActors"))
			{
				double realtimeSinceStartupAsDouble = Time.realtimeSinceStartupAsDouble;
				int frameCount = Time.frameCount;
				foreach (CPlayerActor playerActor2 in ScenarioManager.Scenario.PlayerActors)
				{
					CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[playerActor2.StartArrayIndex.X, playerActor2.StartArrayIndex.Y];
					if (cClientTile != null)
					{
						switch (SaveData.Instance.Global.GameMode)
						{
						case EGameMode.Campaign:
						{
							string skinId = SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.MapParty.SelectedCharacters.FirstOrDefault((CMapCharacter it) => it.CharacterID == playerActor2.CharacterClass.ID)?.SkinId;
							m_ClientPlayers.Add(CreateCharacterActor(cClientTile, playerActor2, isSummoned: false, skinId));
							if (!m_ClientPlacementPreviews.ContainsKey(playerActor2.CharacterClass.CharacterID))
							{
								m_ClientPlacementPreviews.Add(playerActor2.CharacterClass.CharacterID, CreatePreviewPlayer(cClientTile, playerActor2, skinId));
							}
							if (playerActor2.IsDead)
							{
								if (playerActor2.PhasedOut)
								{
									Handle_PhaseOut(new CPhaseOut_MessageData
									{
										m_Actor = playerActor2,
										m_Tile = ScenarioManager.Tiles[playerActor2.ArrayIndex.X, playerActor2.ArrayIndex.Y],
										m_PhaseOutInstantly = true
									});
								}
								else
								{
									Handle_ActorDead(new CActorDead_MessageData(playerActor2)
									{
										m_Actor = playerActor2,
										m_DontLog = true,
										m_InstantlyDeletePrefab = true
									});
								}
							}
							break;
						}
						case EGameMode.LevelEditor:
						case EGameMode.SingleScenario:
						case EGameMode.Autotest:
						case EGameMode.FrontEndTutorial:
							m_ClientPlayers.Add(CreateCharacterActor(cClientTile, playerActor2, isSummoned: false, null, playerActor2.IsDead));
							if (!m_ClientPlacementPreviews.ContainsKey(playerActor2.CharacterClass.CharacterID))
							{
								m_ClientPlacementPreviews.Add(playerActor2.CharacterClass.CharacterID, CreatePreviewPlayer(cClientTile, playerActor2));
							}
							break;
						}
					}
					else if (playerActor2.PhasedOut)
					{
						Singleton<CardsHandManager>.Instance.AddPlayer(playerActor2);
					}
				}
				foreach (CPlayerActor playerActor3 in ScenarioManager.Scenario.ExhaustedPlayers)
				{
					switch (SaveData.Instance.Global.GameMode)
					{
					case EGameMode.Campaign:
					{
						string skinId2 = SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.MapParty.SelectedCharacters.FirstOrDefault((CMapCharacter it) => it.CharacterID == playerActor3.CharacterClass.ID)?.SkinId;
						m_ClientDeadActors.Add(CreateCharacterActor(null, playerActor3, isSummoned: false, skinId2, isExhaustedCharacter: true));
						break;
					}
					case EGameMode.LevelEditor:
					case EGameMode.SingleScenario:
					case EGameMode.Autotest:
					case EGameMode.FrontEndTutorial:
						m_ClientDeadActors.Add(CreateCharacterActor(null, playerActor3, isSummoned: false, null, isExhaustedCharacter: true));
						break;
					}
				}
				foreach (CHeroSummonActor heroSummon2 in ScenarioManager.Scenario.HeroSummons)
				{
					if (heroSummon2.CauseOfDeath != CActor.ECauseOfDeath.ActorRemovedFromMap)
					{
						CClientTile cClientTile2 = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[heroSummon2.StartArrayIndex.X, heroSummon2.StartArrayIndex.Y];
						if (cClientTile2 != null && !heroSummon2.PhasedOut)
						{
							m_ClientHeroSummons.Add(CreateCharacterActor(cClientTile2, heroSummon2));
						}
					}
				}
				foreach (CEnemyActor enemy in ScenarioManager.Scenario.Enemies)
				{
					CClientTile cClientTile3 = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[enemy.StartArrayIndex.X, enemy.StartArrayIndex.Y];
					if (cClientTile3 != null)
					{
						m_ClientEnemies.Add(CreateCharacterActor(cClientTile3, enemy));
						if (enemy.PhasedOut)
						{
							Handle_PhaseOut(new CPhaseOut_MessageData
							{
								m_Actor = enemy,
								m_Tile = ScenarioManager.Tiles[enemy.ArrayIndex.X, enemy.ArrayIndex.Y],
								m_PhaseOutInstantly = true
							});
						}
					}
				}
				foreach (CEnemyActor allyMonster in ScenarioManager.Scenario.AllyMonsters)
				{
					CClientTile cClientTile4 = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[allyMonster.StartArrayIndex.X, allyMonster.StartArrayIndex.Y];
					if (cClientTile4 != null)
					{
						m_ClientAllyMonsters.Add(CreateCharacterActor(cClientTile4, allyMonster));
						if (allyMonster.PhasedOut)
						{
							Handle_PhaseOut(new CPhaseOut_MessageData
							{
								m_Actor = allyMonster,
								m_Tile = ScenarioManager.Tiles[allyMonster.ArrayIndex.X, allyMonster.ArrayIndex.Y],
								m_PhaseOutInstantly = true
							});
						}
					}
				}
				foreach (CEnemyActor enemy2Monster in ScenarioManager.Scenario.Enemy2Monsters)
				{
					CClientTile cClientTile5 = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[enemy2Monster.StartArrayIndex.X, enemy2Monster.StartArrayIndex.Y];
					if (cClientTile5 != null)
					{
						m_ClientEnemy2Monsters.Add(CreateCharacterActor(cClientTile5, enemy2Monster));
						if (enemy2Monster.PhasedOut)
						{
							Handle_PhaseOut(new CPhaseOut_MessageData
							{
								m_Actor = enemy2Monster,
								m_Tile = ScenarioManager.Tiles[enemy2Monster.ArrayIndex.X, enemy2Monster.ArrayIndex.Y],
								m_PhaseOutInstantly = true
							});
						}
					}
				}
				foreach (CEnemyActor neutralMonster in ScenarioManager.Scenario.NeutralMonsters)
				{
					CClientTile cClientTile6 = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[neutralMonster.StartArrayIndex.X, neutralMonster.StartArrayIndex.Y];
					if (cClientTile6 != null)
					{
						m_ClientNeutralMonsters.Add(CreateCharacterActor(cClientTile6, neutralMonster));
						if (neutralMonster.PhasedOut)
						{
							Handle_PhaseOut(new CPhaseOut_MessageData
							{
								m_Actor = neutralMonster,
								m_Tile = ScenarioManager.Tiles[neutralMonster.ArrayIndex.X, neutralMonster.ArrayIndex.Y],
								m_PhaseOutInstantly = true
							});
						}
					}
				}
				foreach (CObjectActor objectActor in ScenarioManager.Scenario.Objects)
				{
					if (objectActor.IsDead && objectActor.AttachedProp != null)
					{
						if (objectActor.AttachedProp.PropHealthDetails.DeathAction == PropHealthDetails.EDeathAction.Destruct)
						{
							EnvironmentLoader.Instance.GetProp(objectActor.AttachedProp.PropGuid).Then((GameObject propGO) => propGO.GetComponentInChildren<PropHealthState>()).Then((PropHealthState healthState) =>
							{
								healthState.UpdateState(objectActor.Health, objectActor.MaxHealth, isActorDead: true);
							});
							continue;
						}
						if (objectActor.AttachedProp is CObjectTrap && objectActor.AttachedProp.Activated)
						{
							continue;
						}
					}
					CClientTile cClientTile7 = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[objectActor.StartArrayIndex.X, objectActor.StartArrayIndex.Y];
					if (cClientTile7 != null)
					{
						m_ClientObjects.Add(CreateCharacterActor(cClientTile7, objectActor));
						if (objectActor.PhasedOut)
						{
							Handle_PhaseOut(new CPhaseOut_MessageData
							{
								m_Actor = objectActor,
								m_Tile = ScenarioManager.Tiles[objectActor.ArrayIndex.X, objectActor.ArrayIndex.Y],
								m_PhaseOutInstantly = true
							});
						}
					}
				}
				SetCharacterPositions();
				double num7 = (double)Time.realtimeSinceStartup - realtimeSinceStartupAsDouble;
				int num8 = Time.frameCount - frameCount;
				int num9 = (int)(num7 * 1000.0);
				Log.Trace($"CreateActors took {num9}ms over {num8} frame(s)");
			}
		}
	}

