	public void PostMessageFromUI(CMessageData message)
	{
		if (SceneController.Instance.GlobalErrorMessage.CheckShowingMessageFromThread)
		{
			return;
		}
		if (ScenarioRuleClient.IsWorkerThread)
		{
			Debug.LogError($"Sending UI message to Choreographer from the SRL! {message.m_Type} ({message.GetType().Name})\n{message.CallStack}");
		}
		lock (m_MessageQueue)
		{
			m_MessageQueue.Add(message);
		}
	}

