	public void Play(bool restart = false)
	{
		using (new MiniProfilerScope("Choreographer.Play"))
		{
			try
			{
				IsRestarting = false;
				try
				{
					if (SaveData.Instance.Global.GameMode == EGameMode.Campaign)
					{
						Log.Info("Load scenario \"" + SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentMapScenarioState.CustomLevelData.Name + "\"");
						if (restart)
						{
							UnityGameEditorRuntime.LoadScenario(SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentMapScenarioState.InitialState);
						}
						else
						{
							UnityGameEditorRuntime.LoadScenario(SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentMapScenarioState.CurrentState);
						}
					}
				}
				catch (Exception ex)
				{
					Log.Exception(ex, "Failed to load scenario.  Returning to main menu.");
					SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00152", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
				}
			}
			catch (Exception ex2)
			{
				Log.Exception(ex2, "An exception occurred within the Choreographer.Play().  The scene loading did not complete successfully.");
				SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00153", "GUI_ERROR_MAIN_MENU_BUTTON", ex2.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex2.Message);
			}
		}
	}

	public async Task ScenarioCreateClientBoardAndCharacters([CanBeNull] KronosProfilingScaffolding profiling)
	{
		using (new MiniProfilerScope("ScenarioCreateClientBoardAndCharacters"))
		{
			if (!Application.isPlaying)
			{
				return;
			}
			SEventLog.ClearProcessedEventCount();
			SEventLog.ClearEventLog();
			ScenarioManager.CurrentScenarioState.LoadChallenges();
			AllActorsInScene.RemoveAll((GameObject x) => x == null);
			AllActorsInScene.Clear();
			GameObject gameObject = GameObject.Find("ScenarioCamera");
			CameraController.s_CameraController.SetCamera(gameObject);
			WorldspaceUITools.Instance.Init(gameObject.GetComponent<Camera>());
			if (!ScenarioManager.IsFastReloading)
			{
				foreach (Transform item in s_Choreographer.m_MapSceneRoot.transform)
				{
					item.gameObject.SetActive(value: true);
				}
			}
			ScenarioManager.InitScenario(LevelEditorController.s_Instance.IsEditing);
			if (!FFSNetwork.IsOnline || FFSNetwork.IsHost)
			{
				FastReload.FastUndoEnabled = FastReload.setting_FastUndoEnabled;
				FastReload.FastRedoEnabled = FastReload.setting_FastRedoEnabled;
			}
			ClearPlayersEnemies();
			await CreatePlayersEnemies();
			foreach (HeroSummonState heroSummon in ScenarioManager.CurrentScenarioState.HeroSummons)
			{
				if (heroSummon.Actor is CHeroSummonActor cHeroSummonActor && heroSummon.TempTryFixOnSummonBonuses)
				{
					heroSummon.TempTryFixOnSummonBonuses = false;
					cHeroSummonActor.Cheat_ReapplyOnSummonBonuses();
				}
			}
			UnlockCodexTagsFromScenario();
			ScenarioManager.CurrentScenarioState.CheckObjectivesComplete();
			SetChooseAdvantageModifiers(SaveData.Instance.Global.ChooseAdvantageModifiers, force: true);
			SetConfirmAttackAbilityFinished(SaveData.Instance.Global.ConfirmAttackAbilityBeforeFinishing, force: true);
		}
	}

	public void ScenarioImportProcessedCallback(bool generatedScenario)
	{
		try
		{
			if (!LevelEditorController.s_Instance.IsEditing)
			{
				SetChoreographerState(ChoreographerStateType.Play, 0, null);
				ScenarioRuleClient.Start(ThreadManagerComponent.Manager);
				ScenarioRuleClient.WaitForSRLThreadInit();
				if (generatedScenario)
				{
					CLevelCameraProfile startingCameraProfile = ClientScenarioManager.s_ClientScenarioManager.CurrentState.StartingCameraProfile;
					if (startingCameraProfile != null && startingCameraProfile.ShouldForceCamera)
					{
						CameraController.s_CameraController.SetCameraWithProfile(startingCameraProfile);
					}
					else
					{
						GetAveragePositions(out var averagePlayerPosition, out var _, out var _, out var _, out var _);
						Transform transform = null;
						GameObject dungeonEntrance = ClientScenarioManager.s_ClientScenarioManager.DungeonEntrance;
						UnityGameEditorDoorProp unityGameEditorDoorProp = null;
						if (dungeonEntrance != null)
						{
							unityGameEditorDoorProp = dungeonEntrance.GetComponent<UnityGameEditorDoorProp>();
							transform = dungeonEntrance.transform;
						}
						else
						{
							transform = ClientScenarioManager.s_ClientScenarioManager.AllPossibleStartingTiles[0].m_GameObject.transform;
						}
						bool flag = unityGameEditorDoorProp != null && (unityGameEditorDoorProp.m_DoorType == CObjectDoor.EDoorType.ThinDoor || unityGameEditorDoorProp.m_DoorType == CObjectDoor.EDoorType.ThinNarrowDoor);
						CameraController.s_CameraController.SetCameraDirectionAndFocalPoint(transform, averagePlayerPosition, (!flag) ? 2 : 0);
					}
				}
			}
			WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred within the ScenarioImportProcessedCallback.  The scene loading did not complete successfully.");
			List<ErrorMessage.LabelAction> list = new List<ErrorMessage.LabelAction>();
			list.Add(new ErrorMessage.LabelAction("GUI_ERROR_RESET_SCENARIO_BUTTON", UnityGameEditorRuntime.ErrorHandlingUnloadSceneResetScenarioStateAndRetryLoad, InputFHManager.Controls.Generic.AlternativeChoice));
			list.Add(new ErrorMessage.LabelAction("GUI_ERROR_MAIN_MENU_BUTTON", UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, InputFHManager.Controls.Generic.Confirm));
			SceneController.Instance.GlobalErrorMessage.ShowMultiChoiceMessageDefaultTitle("ERROR_CHOREO_00154", ex.StackTrace, list, ex.Message);
		}
	}

