	public void TileHandler(CClientTile clientTile, List<CTile> optionalTileList = null, bool networkActionIfOnline = false, bool isUserClick = false, bool actingPlayerHasSecondClickConfirmationEnabled = false, CInteractable.EInputType inputType = CInteractable.EInputType.None)
	{
		CActor cActor = ((clientTile == null) ? null : ScenarioManager.Scenario.FindActorAt(clientTile.m_Tile.m_ArrayIndex));
		bool flag = m_WaitState.m_State == ChoreographerStateType.WaitingForCardSelection && Singleton<CardsHandManager>.Instance.IsActive();
		bool flag2 = flag && WorldspaceStarHexDisplay.Instance.CurrentDisplayState == WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.CharacterPlacement;
		if (flag2 && (!ScenarioManager.StartingTiles.Contains(clientTile.m_Tile) || (cActor != null && cActor.Type != CActor.EType.Player && cActor.Type != CActor.EType.Ally)))
		{
			cActor = null;
		}
		bool flag3 = clientTile == Waypoint.s_PlacementTile && cActor == null;
		bool flag4 = flag2 && ((cActor != null) | flag3);
		if ((isUserClick && inputType == CInteractable.EInputType.Alternative && InitiativeTrack.Instance.SelectedActor() != null && !flag4) || LevelEditorController.InterceptTileAction(clientTile) || (isUserClick && DebugMenu.InterceptTileAction(clientTile)))
		{
			return;
		}
		if (AutoTestController.s_AutoLogPlaybackInProgress)
		{
			Waypoint.s_PlacementTile = CAutoTileClick.TileIndexToClientTile((AutoTestController.s_Instance.CurrentAutoLogPlayback.CurrentEvent as CAutoTileClick)?.PlacementTile);
		}
		else if (!AutoTestIgnoreTileClick & isUserClick)
		{
			AutoTestController.LogTileClick(clientTile, optionalTileList, null, Waypoint.s_PlacementTile, inputType);
		}
		m_lastSelectedTile = clientTile;
		if (flag)
		{
			if (Singleton<InputFHManager>.Instance.UsingGamepad)
			{
				return;
			}
			CActor cActor2 = InitiativeTrack.Instance?.SelectedActor()?.Actor;
			if (cActor2 != null && cActor == cActor2)
			{
				return;
			}
			if ((inputType == CInteractable.EInputType.Alternative && cActor2 != null && cActor != null) & flag2)
			{
				CClientTile tile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cActor2.ArrayIndex.X, cActor2.ArrayIndex.Y];
				if (FFSNetwork.IsOnline)
				{
					if (cActor2 != null && cActor2.IsUnderMyControl() && !Singleton<UIReadyToggle>.Instance.ToggledOn && !Singleton<UIReadyToggle>.Instance.IsProgressingBar)
					{
						string supplementaryDataString = clientTile.m_Tile.LivingActor?.ActorGuid;
						if (FFSNetwork.IsHost)
						{
							AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
							SwapActorsAtRoundStart(cActor2, tile, cActor, clientTile);
						}
						int controllableID = ControllableRegistry.GetControllableID((CPlayerActor)cActor2);
						IProtocolToken supplementaryDataToken = new TileToken(clientTile.m_Tile.m_ArrayIndex);
						Synchronizer.ReplicateControllableStateChange(GameActionType.PlaceCharacter, ActionPhaseType.StartOfRound, controllableID, 0, 0, 0, supplementaryDataBoolean: false, supplementaryDataString, supplementaryDataToken, null, null, null, validateOnServerBeforeExecuting: true);
					}
				}
				else
				{
					AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
					SwapActorsAtRoundStart(cActor2, tile, cActor, clientTile);
				}
				return;
			}
			if (cActor != null)
			{
				if (!Singleton<InputFHManager>.Instance.UsingGamepad && cActor2 != cActor)
				{
					Log.Info("Tile  handler select actor");
					if (cActor is CPlayerActor cPlayerActor && InitiativeTrack.Instance.Select(cPlayerActor))
					{
						AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
						Singleton<CardsHandManager>.Instance.SwitchHand(cPlayerActor);
						WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
					}
				}
				return;
			}
			if (inputType == CInteractable.EInputType.Alternative && clientTile == Waypoint.s_PlacementTile && cActor2 != null)
			{
				CPlayerActor cPlayerActor2 = (CPlayerActor)cActor2;
				CTile item = ScenarioManager.Tiles[cPlayerActor2.ArrayIndex.X, cPlayerActor2.ArrayIndex.Y];
				if (ScenarioManager.StartingTiles.Contains(item))
				{
					if (FFSNetwork.IsOnline)
					{
						if (!cActor2.IsUnderMyControl() || Singleton<UIReadyToggle>.Instance.ToggledOn || Singleton<UIReadyToggle>.Instance.IsProgressingBar)
						{
							return;
						}
						string supplementaryDataString2 = clientTile.m_Tile.LivingActor?.ActorGuid;
						if (FFSNetwork.IsHost)
						{
							AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
							PlaceActorAtRoundStart(cActor2, clientTile);
						}
						int controllableID2 = ControllableRegistry.GetControllableID(cPlayerActor2);
						IProtocolToken supplementaryDataToken = new TileToken(clientTile.m_Tile.m_ArrayIndex);
						Synchronizer.ReplicateControllableStateChange(GameActionType.PlaceCharacter, ActionPhaseType.StartOfRound, controllableID2, 0, 0, 0, supplementaryDataBoolean: false, supplementaryDataString2, supplementaryDataToken, null, null, null, validateOnServerBeforeExecuting: true);
					}
					else
					{
						AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
						PlaceActorAtRoundStart(cActor2, clientTile);
					}
				}
			}
		}
		if (m_TileSelectionDisabled & isUserClick)
		{
			if (m_BufferedSelectedTile == null)
			{
				Log.NetworkTrace("TILEHANDLER - TILE SELECTION DISABLED - BUFFERING TILE");
				m_BufferedSelectedTile = clientTile;
				m_BufferedTileNetworked = networkActionIfOnline;
				m_BufferedSecondClickToConfirm = actingPlayerHasSecondClickConfirmationEnabled;
			}
			return;
		}
		if (m_WaitState.m_State == ChoreographerStateType.WaitingForAreaAttackFocusSelection && WorldspaceStarHexDisplay.Instance.CurrentNumberSelectedTargets() > 0)
		{
			AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
			bool hideHelpBox = true;
			if (WorldspaceStarHexDisplay.CurrentAbility is CAbilityAttack cAbilityAttack && cAbilityAttack.IsWaitingForSingleTargetItem())
			{
				hideHelpBox = false;
			}
			SetChoreographerState(ChoreographerStateType.Play, 0, null, hideHelpBox);
		}
		if (m_WaitState.m_State < ChoreographerStateType.Play || (isUserClick && WorldspaceStarHexDisplay.Instance.CurrentDisplayState == WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone) || PhaseManager.Phase == null || !(PhaseManager.Phase is CPhaseAction { CurrentPhaseAbility: var currentPhaseAbility } cPhaseAction) || currentPhaseAbility?.m_Ability == null)
		{
			return;
		}
		CActor targetingActor = cPhaseAction.CurrentPhaseAbility.m_Ability.TargetingActor;
		if (targetingActor == null || !targetingActor.IsPlayerControlled() || !cPhaseAction.CurrentPhaseAbility.m_Ability.CanReceiveTileSelection() || (cPhaseAction.CurrentPhaseAbility.m_Ability.RequiresWaypointSelection() && optionalTileList == null))
		{
			return;
		}
		CAbility cAbility = cPhaseAction.CurrentPhaseAbility.m_Ability;
		if (cAbility is CAbilityMerged cAbilityMerged)
		{
			cAbility = cAbilityMerged.ActiveAbility;
		}
		if (cAbility.RequiresWaypointSelection())
		{
			DisableTileSelection(active: true);
			if (FFSNetwork.IsOnline && !s_Choreographer.ThisPlayerHasTurnControl)
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionProcessor.CurrentPhase, savePreviousState: true);
			}
			ScenarioRuleClient.TileSelected(clientTile.m_Tile, optionalTileList);
		}
		else
		{
			if (FFSNetwork.IsOnline && ActionProcessor.CurrentPhase == ActionPhaseType.NONE)
			{
				return;
			}
			DisableTileSelection(active: true);
			Log.NetworkTrace("TILEHANDLER - ABILITY SECTION");
			if (cAbility.AreaEffect != null)
			{
				Log.NetworkTrace("TILEHANDLER - AOE ABILITY");
				if (WorldspaceStarHexDisplay.Instance.IsAOELocked() || inputType == CInteractable.EInputType.Alternative)
				{
					Log.NetworkTrace("TILEHANDLER - AOE LOCKED");
					if (cAbility.IsWaitingForSingleTargetItem() || cAbility.IsWaitingForSingleTargetActiveBonus())
					{
						Log.NetworkTrace("TILEHANDLER - AOE WAITING FOR SINGLE TARGET ITEM OR ACTIVE BONUS");
						CActor cActor3 = cAbility.ActorsToTarget.SingleOrDefault((CActor s) => s.GetTilesCanAttackFrom().Contains(clientTile.m_Tile));
						if (!cAbility.IsValidSingleTargetActiveBonusTarget(cActor3))
						{
							cActor3 = null;
						}
						IEnumerable<CItem> enumerable = cAbility.PendingSingleTargetItems();
						if (enumerable.Any())
						{
							bool flag5 = false;
							foreach (CItem item2 in enumerable)
							{
								if (item2?.YMLData?.Data?.ItemRequirements == null || item2.YMLData.Data.ItemRequirements.MeetsAbilityRequirements(cActor3, cAbility, null, item2))
								{
									flag5 = true;
								}
							}
							if (!flag5)
							{
								cActor3 = null;
							}
						}
						if (cActor3 != null)
						{
							AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
							ScenarioRuleClient.ApplySingleTarget(cActor3);
							readyButton.SetInteractable(interactable: true);
						}
						DisableTileSelection(active: false);
						if (FFSNetwork.IsOnline && m_CurrentActor.IsUnderMyControl())
						{
							NetworkTargetSelection(clientTile, optionalTileList);
						}
						if (ActionProcessor.IsWaitingForTileSelectionFinishedMessage != null)
						{
							ActionProcessor.FinishProcessingAction(ActionProcessor.IsWaitingForTileSelectionFinishedMessage);
							ActionProcessor.IsWaitingForTileSelectionFinishedMessage = null;
						}
					}
					else if (WorldspaceStarHexDisplay.Instance.AlreadySelected(clientTile) && ((cAbility.AbilityType != CAbility.EAbilityType.Push && cAbility.AbilityType != CAbility.EAbilityType.Pull && cAbility.AbilityType != CAbility.EAbilityType.Teleport2) || (!cAbility.IsInlineSubAbility && !cAbility.IsModifierAbility)))
					{
						Log.NetworkTrace("TILEHANDLER - AOE SELECTED ALREADY SELECTED TILE");
						if (actingPlayerHasSecondClickConfirmationEnabled)
						{
							Log.NetworkTrace("TILEHANDLER - AOE - ACTING PLAYER HAS SECOND CLICK CONFIRM ENABLED");
							if (FFSNetwork.IsOnline && m_CurrentActor.IsUnderMyControl())
							{
								NetworkTargetSelection(clientTile, optionalTileList);
							}
							WorldspaceStarHexDisplay.Instance.SetAOELocked(locked: false);
							ScenarioRuleClient.StepComplete();
							DisableButtons();
							if (ActionProcessor.IsWaitingForTileSelectionFinishedMessage != null)
							{
								ActionProcessor.FinishProcessingAction(ActionProcessor.IsWaitingForTileSelectionFinishedMessage);
								ActionProcessor.IsWaitingForTileSelectionFinishedMessage = null;
							}
							return;
						}
						Log.NetworkTrace("TILEHANDLER - AOE - ACTING PLAYER HAS SECOND CLICK CONFIRM DISABLED");
						if (FFSNetwork.IsOnline && m_CurrentActor.IsUnderMyControl())
						{
							NetworkTargetSelection(clientTile, optionalTileList, deselectInstead: true);
						}
						m_UndoButton.SetInteractable(active: false);
						readyButton.SetInteractable(interactable: false);
						m_SkipButton.SetInteractable(active: false);
						if (FFSNetwork.IsOnline && !s_Choreographer.ThisPlayerHasTurnControl)
						{
							ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionProcessor.CurrentPhase, savePreviousState: true);
						}
						ScenarioRuleClient.TileDeselected(clientTile.m_Tile, optionalTileList);
						SetChoreographerState(ChoreographerStateType.WaitingForTileSelected, 0, null);
					}
					else
					{
						Log.NetworkTrace("TILEHANDLER - AOE - LOCKED AOE + INVALID TILE, DO NOTHING");
						AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
						DisableTileSelection(active: false);
					}
				}
				else
				{
					Log.NetworkTrace("TILEHANDLER - NO AOE LOCK");
					cAbility.UpdateAreaEffect(clientTile?.m_Tile, WorldspaceStarHexDisplay.Instance.AreaEffectAngle, WorldspaceStarHexDisplay.Instance.AreaEffectFlipped);
					if (FFSNetwork.IsOnline && m_CurrentActor.IsUnderMyControl())
					{
						NetworkTargetSelection(clientTile, optionalTileList);
					}
					m_UndoButton.SetInteractable(active: false);
					readyButton.SetInteractable(interactable: false);
					m_SkipButton.SetInteractable(active: false);
					if (FFSNetwork.IsOnline && !s_Choreographer.ThisPlayerHasTurnControl)
					{
						ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionProcessor.CurrentPhase, savePreviousState: true);
					}
					ScenarioRuleClient.TileSelected(clientTile?.m_Tile, optionalTileList);
					SetChoreographerState(ChoreographerStateType.WaitingForTileSelected, 0, null);
				}
			}
			else if (cAbility.IsWaitingForSingleTargetItem() || cAbility.IsWaitingForSingleTargetActiveBonus())
			{
				Log.NetworkTrace("TILEHANDLER - TARGETED ABILITY WAITING FOR SINGLE TARGET ITEM OR ACTIVE BONUS");
				CActor cActor4 = cAbility.ActorsToTarget.SingleOrDefault((CActor s) => s.GetTilesCanAttackFrom().Contains(clientTile.m_Tile));
				if (!cAbility.IsValidSingleTargetActiveBonusTarget(cActor4))
				{
					cActor4 = null;
				}
				if (cActor4 != null)
				{
					AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
					ScenarioRuleClient.ApplySingleTarget(cActor4);
					readyButton.SetInteractable(interactable: true);
				}
				DisableTileSelection(active: false);
				if (FFSNetwork.IsOnline && m_CurrentActor.IsUnderMyControl())
				{
					NetworkTargetSelection(clientTile, optionalTileList);
				}
				if (ActionProcessor.IsWaitingForTileSelectionFinishedMessage != null)
				{
					ActionProcessor.FinishProcessingAction(ActionProcessor.IsWaitingForTileSelectionFinishedMessage);
					ActionProcessor.IsWaitingForTileSelectionFinishedMessage = null;
				}
			}
			else if (WorldspaceStarHexDisplay.Instance.AlreadySelected(clientTile) && ((cAbility.AbilityType != CAbility.EAbilityType.Push && cAbility.AbilityType != CAbility.EAbilityType.Teleport2) || (!cAbility.IsInlineSubAbility && !cAbility.IsModifierAbility)))
			{
				Log.NetworkTrace("TILEHANDLER - TARGETED ABILITY SELECTED ALREADY SELECTED TILE");
				if (actingPlayerHasSecondClickConfirmationEnabled)
				{
					Log.NetworkTrace("TILEHANDLER - TARGETED ABILITY - ACTING PLAYER HAS SECOND CLICK CONFIRM ENABLED");
					if (!cAbility.EnoughTargetsSelected())
					{
						InitiativeTrack.Instance.helpBox.Show("GUI_TOOLTIP_NOT_ENOUGH_TARGETS_SELECTED");
						DisableTileSelection(active: false);
						return;
					}
					if (FFSNetwork.IsOnline && m_CurrentActor.IsUnderMyControl())
					{
						NetworkTargetSelection(clientTile, optionalTileList);
					}
					Singleton<UIUseAugmentationsBar>.Instance.Hide();
					Singleton<UIUseItemsBar>.Instance.Hide();
					Singleton<UIActiveBonusBar>.Instance.LockToggledActiveBonuses();
					Singleton<UIActiveBonusBar>.Instance.Hide(toggle: true);
					ScenarioRuleClient.StepComplete();
					DisableButtons();
					if (ActionProcessor.IsWaitingForTileSelectionFinishedMessage != null)
					{
						ActionProcessor.FinishProcessingAction(ActionProcessor.IsWaitingForTileSelectionFinishedMessage);
						ActionProcessor.IsWaitingForTileSelectionFinishedMessage = null;
					}
				}
				else
				{
					Log.NetworkTrace("TILEHANDLER - TARGETED ABILITY - ACTING PLAYER HAS SECOND CLICK CONFIRM ENABLED");
					if (FFSNetwork.IsOnline && m_CurrentActor.IsUnderMyControl())
					{
						NetworkTargetSelection(clientTile, optionalTileList, deselectInstead: true);
					}
					m_UndoButton.SetInteractable(active: false);
					readyButton.SetInteractable(interactable: false);
					m_SkipButton.SetInteractable(active: false);
					if (FFSNetwork.IsOnline && !s_Choreographer.ThisPlayerHasTurnControl)
					{
						ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionProcessor.CurrentPhase, savePreviousState: true);
					}
					ScenarioRuleClient.TileDeselected(clientTile.m_Tile, optionalTileList);
					SetChoreographerState(ChoreographerStateType.WaitingForTileSelected, 0, null);
				}
			}
			else
			{
				Log.NetworkTrace("TILEHANDLER - TARGETED ABILITY - TILE NOT YET SELECTED. Current selected targets: " + WorldspaceStarHexDisplay.Instance.CurrentNumberSelectedTargets());
				if (FFSNetwork.IsOnline && m_CurrentActor.IsUnderMyControl())
				{
					NetworkTargetSelection(clientTile, optionalTileList);
				}
				m_UndoButton.SetInteractable(active: false);
				readyButton.SetInteractable(interactable: false);
				m_SkipButton.SetInteractable(active: false);
				if (FFSNetwork.IsOnline && !s_Choreographer.ThisPlayerHasTurnControl)
				{
					ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionProcessor.CurrentPhase, savePreviousState: true);
				}
				ScenarioRuleClient.TileSelected(clientTile.m_Tile, optionalTileList);
				SetChoreographerState(ChoreographerStateType.WaitingForTileSelected, 0, null);
			}
		}
	}

	private void SwapActorsAtRoundStart(CActor actor1, CClientTile tile1, CActor actor2, CClientTile tile2)
	{
		actor1.ArrayIndex = tile2.m_Tile.m_ArrayIndex;
		actor2.ArrayIndex = tile1.m_Tile.m_ArrayIndex;
		Log.SimpleInfo(LocalizationManager.GetTranslation(actor1.ActorLocKey()) + ": " + actor1.ArrayIndex.X + "," + actor1.ArrayIndex.Y + " swaps starting position with " + LocalizationManager.GetTranslation(actor2.ActorLocKey()) + ": " + actor2.ArrayIndex.X + ", " + actor2.ArrayIndex.Y);
		ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(actor1)).ForceSetLocoIntermediateTarget(tile2.m_GameObject.transform.position);
		ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(actor2)).ForceSetLocoIntermediateTarget(tile1.m_GameObject.transform.position);
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		CheckForPlacementReadyness();
		TriggerOnStartRoundMoveEffects(actor1);
		TriggerOnStartRoundMoveEffects(actor2);
	}

	private void PlaceActorAtRoundStart(CActor actor, CClientTile clientTile)
	{
		actor.ArrayIndex = clientTile.m_Tile.m_ArrayIndex;
		actor.StartArrayIndex = actor.ArrayIndex;
		Log.SimpleInfo(LocalizationManager.GetTranslation(actor.ActorLocKey()) + " swaps starting position to: " + actor.ArrayIndex.X + "," + actor.ArrayIndex.Y);
		ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(actor)).ForceSetLocoIntermediateTarget(clientTile.m_GameObject.transform.position);
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		CheckForPlacementReadyness();
		TriggerOnStartRoundMoveEffects(actor);
	}

	private void TriggerOnStartRoundMoveEffects(CActor actor)
	{
		ScenarioScript.current?.TickRepositionInCharacterPlacement(null, actor, null);
	}

	private void CheckForPlacementReadyness()
	{
		InitiativeTrack.Instance?.CheckRoundAbilityCardsOrLongRestSelected();
		if (!PlayersInValidStartingPositions)
		{
			Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_PLAYER_STARTING_PLACEMENT", "GUI_TOOLTIP_TITLE_START_TURN");
			readyButton.ShowWarning(() =>
			{
				m_RoomCameraButton.FocusOnEmptyRoom();
				Singleton<HelpBox>.Instance.HighlightWarning();
			});
		}
		else if (AnyPlayersInInvalidStartingPositionsForCompanionSummons)
		{
			List<CPlayerActor> list = PlayersInInvalidStartingPositionsForCompanionSummons();
			StringBuilder stringBuilder = new StringBuilder();
			for (int num = 0; num < list.Count; num++)
			{
				string value = LocalizationManager.GetTranslation(list[num].ActorLocKey()) + ((list.Count > 1 && num >= list.Count - 1) ? ", " : " ");
				stringBuilder.Append(value);
			}
			string text = string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_STARTING_PLACEMENT_COMPANION_SUMMONS"), stringBuilder);
			string translation = LocalizationManager.GetTranslation("GUI_TOOLTIP_TITLE_START_TURN");
			InitiativeTrack.Instance.helpBox.ShowTranslated(text, translation);
			Singleton<HelpBox>.Instance.HighlightWarning();
			readyButton.ShowWarning(() =>
			{
				Singleton<HelpBox>.Instance.HighlightWarning();
			});
		}
		else
		{
			readyButton.HideWarning();
		}
		Singleton<CardsHandManager>.Instance.CurrentHand?.UpdateShortRest();
	}

	public bool CheckForDoors(CClientTile clientTile, List<CTile> optionalTileList = null)
	{
		if ((LastMessage.m_Type == CMessageData.MessageType.ActorIsSelectingMoveTile || LastMessage.m_Type == CMessageData.MessageType.ActorIsSelectingTeleport2Tile) && clientTile.m_Tile.FindProp(ScenarioManager.ObjectImportType.Door) != null && !clientTile.m_Tile.FindProp(ScenarioManager.ObjectImportType.Door).Activated)
		{
			m_ConfirmationDoorTile = clientTile.m_Tile;
			m_ConfirmationDoorTileOptionalTileList = optionalTileList;
			return true;
		}
		return false;
	}

	public void ContinueTileSelection()
	{
		try
		{
			m_UndoButton.Toggle(active: false);
			m_SkipButton.Toggle(active: false);
			ScenarioRuleClient.TileSelected(m_ConfirmationDoorTile, m_ConfirmationDoorTileOptionalTileList);
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred within the Choreographer.ContinueTileSelection().");
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00159", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
		}
	}

	public void DisableTileSelection(bool active)
	{
		m_TileSelectionDisabled = active;
		if (!active)
		{
			m_BufferedSelectedTile = null;
			m_BufferedTileNetworked = false;
			m_BufferedSecondClickToConfirm = false;
		}
	}

	public GameObject FindClientEnemy(CEnemyActor enemyActor)
	{
		return ClientMonsterObjects.Find((GameObject x) => ActorBehaviour.GetActor(x)?.ActorGuid == enemyActor?.ActorGuid);
	}

	public GameObject FindClientPlayer(CPlayerActor playerActor)
	{
		return m_ClientPlayers.Find((GameObject x) => ActorBehaviour.GetActor(x)?.ActorGuid == playerActor?.ActorGuid);
	}

	public GameObject FindClientHeroSummon(CHeroSummonActor heroSummonActor)
	{
		return m_ClientHeroSummons.Find((GameObject x) => ActorBehaviour.GetActor(x)?.ActorGuid == heroSummonActor?.ActorGuid);
	}

	public GameObject FindClientPlayer(CActor actor)
	{
		return m_ClientPlayers.Find((GameObject x) => ActorBehaviour.GetActor(x)?.ActorGuid == actor?.ActorGuid);
	}

	public GameObject FindClientActor(CActor actor)
	{
		return ClientActorObjects.Find((GameObject x) => ActorBehaviour.GetActor(x)?.ActorGuid == actor?.ActorGuid);
	}

	public GameObject FindClientObjectActor(CActor actor)
	{
		return m_ClientObjects.Find((GameObject x) => ActorBehaviour.GetActor(x)?.ActorGuid == actor?.ActorGuid);
	}

	public CActor FindPlayerActor(int actorID)
	{
		foreach (GameObject clientPlayer in m_ClientPlayers)
		{
			CActor actor = ActorBehaviour.GetActor(clientPlayer);
			if (actor.ID == actorID)
			{
				return actor;
			}
		}
		return null;
	}

	public static GameObject FindPropGameObject(CObjectProp prop)
	{
		if (prop == null)
		{
			return null;
		}
		if (s_Choreographer?.m_PropGameObjectCache != null && s_Choreographer.m_PropGameObjectCache.TryGetValue(prop, out var value))
		{
			if (!(value == null))
			{
				return value;
			}
			s_Choreographer.m_PropGameObjectCache.Remove(prop);
		}
		GameObject gameObject = GameObject.Find(prop.InstanceName);
		if (gameObject != null && s_Choreographer?.m_PropGameObjectCache != null)
		{
			s_Choreographer.m_PropGameObjectCache[prop] = gameObject;
		}
		return gameObject;
	}

	public GameObject FindClientActorGameObject(CActor actor, bool shouldReturnDummyActorsProp = false)
	{
		if (actor == null)
		{
			return null;
		}
		if (!(actor is CPlayerActor playerActor))
		{
			if (!(actor is CObjectActor cObjectActor))
			{
				if (!(actor is CEnemyActor enemyActor))
				{
					if (actor is CHeroSummonActor heroSummonActor)
					{
						return FindClientHeroSummon(heroSummonActor);
					}
					return null;
				}
				return FindClientEnemy(enemyActor);
			}
			if (shouldReturnDummyActorsProp && cObjectActor.AttachedProp != null)
			{
				if (EnvironmentLoader.IsInstanceValid && EnvironmentLoader.Instance.IsLoadingComplete)
				{
					return EnvironmentLoader.Instance.GetProp(cObjectActor.AttachedProp.PropGuid);
				}
				return FindPropGameObject(cObjectActor.AttachedProp);
			}
			return FindClientActor(cObjectActor);
		}
		return FindClientPlayer(playerActor);
	}

	public void SetChoreographerState(ChoreographerStateType eState, int waitTickFrame, CActor waitActor, bool hideHelpBox = true, bool shouldContinueStep = true)
	{
		ChoreographerStateType choreographerStateType = ChoreographerStateType.NA;
		if (m_WaitState != null)
		{
			choreographerStateType = m_WaitState.m_State;
		}
		Log.Info("[Chor] Set wait state from " + Log.Colorize(choreographerStateType.ToString(), Color.yellow) + " to " + Log.Colorize(eState.ToString(), Color.yellow));
		m_WaitState = new CWaitState();
		m_WaitState.m_State = eState;
		m_WaitState.m_StateLastUpdateTickFrame = Environment.TickCount;
		m_WaitState.m_StateWaitTickFrame = Environment.TickCount + waitTickFrame;
		m_WaitState.m_StateWaitActor = waitActor;
		m_WaitState.m_StateWaitActorGO = ((waitActor != null) ? FindClientActorGameObject(waitActor) : null);
		m_WaitState.m_ShouldContinueStep = shouldContinueStep;
		if (m_WaitState.m_StateWaitActor != null && m_WaitState.m_StateWaitActorGO != null)
		{
			ActorEvents.GetActorEvents(m_WaitState.m_StateWaitActorGO).ClearActorEventState();
		}
		if (hideHelpBox)
		{
			InitiativeTrack.Instance?.helpBox?.Hide();
		}
		if (eState == ChoreographerStateType.Play && WorldspaceStarHexDisplay.Instance != null && WorldspaceStarHexDisplay.Instance.CurrentNumberSelectedTargets() <= 0 && choreographerStateType != ChoreographerStateType.WaitingForTileSelected)
		{
			WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		}
		if (eState == ChoreographerStateType.WaitingForEndAbilityAnimSync)
		{
			m_EndAbilitySyncComplete = false;
			m_LoggedEndAbilitySyncSoftlock = false;
		}
		if (eState == ChoreographerStateType.WaitingForEndTurnSync)
		{
			m_EndOfTurnSyncComplete = false;
			m_LoggedEndTurnSyncSoftlock = false;
		}
		if (eState == ChoreographerStateType.WaitingForEndRoundSync)
		{
			m_EndOfRoundSyncComplete = false;
			m_LoggedEndRoundSyncSoftlock = false;
		}
	}

	public void ClearAllActorEvents()
	{
		foreach (ActorEvents allActorEvent in m_AllActorEvents)
		{
			allActorEvent.ClearActorEventState();
		}
	}

	public void ClearMessageQueue()
	{
		lock (m_MessageQueue)
		{
			m_MessageQueue.Clear();
		}
	}

	public bool HasMessageOnQueue(CMessageData.MessageType messageType, bool checkCurrent = false)
	{
		if (checkCurrent && CurrentlyProcessingMessage != null && CurrentlyProcessingMessage.m_Type == messageType)
		{
			return true;
		}
		lock (m_MessageQueue)
		{
			return m_MessageQueue.Find((CMessageData x) => x.m_Type == messageType) != null;
		}
	}

	public void SetBlockClientMessageProcessing(bool active)
	{
		Log.Info("Block Choreographer Message Processing: " + active);
		m_BlockClientMessageProcessing = active;
	}

	private void Update()
	{
		TickUpdate(ignoreTimeQuota: false);
	}

	public void TickUpdate(bool ignoreTimeQuota)
	{
		WorldspacePanelUIController.RefreshActorHexHighlights();
		if (SaveData.Instance.Global.CurrentGameState != EGameState.Scenario || SceneController.Instance.GlobalErrorMessage.ShowingMessage || SaveData.Instance.IsSavingThreadActive || (FFSNetwork.IsOnline && PlayerRegistry.MyPlayer == null))
		{
			return;
		}
		bool flag = true;
		lock (ScenarioRuleClient.Synchronizer)
		{
			if (!ScenarioRuleClient.IsProcessingOrMessagesQueued)
			{
				ScenarioRuleClient.IsChoreographerProcessing = true;
			}
		}
		if (CardsActionControlller.s_Instance != null && !m_BlockClientMessageProcessing && (ScenarioRuleClient.IsChoreographerProcessing || GameState.ThreadIsSleeping))
		{
			long num = DateTime.Now.Ticks / 10000;
			while ((ScenarioManager.IsFastReloading | ignoreTimeQuota) || DateTime.Now.Ticks / 10000 - num < 8)
			{
				if (AutoTestController.s_AutoTestCurrentlyLoaded)
				{
					if (AutoTestController.s_ChoreographerPaused)
					{
						break;
					}
					lock (m_MessageQueue)
					{
						if (m_MessageQueue.Count > 0)
						{
							AutoTestController.ChoreographerMessageProcessed(m_MessageQueue[0].m_Type);
							m_CheckAutotestComplete = AutoTestController.s_AutoLogPlaybackInProgress;
						}
					}
				}
				CMessageData cMessageData = null;
				lock (m_MessageQueue)
				{
					if (m_MessageQueue.Count > 0)
					{
						cMessageData = m_MessageQueue[0];
						m_MessageQueue.RemoveAt(0);
						flag = m_MessageQueue.Count == 0;
					}
				}
				if (cMessageData != null)
				{
					ProcessMessage(cMessageData);
				}
				if (flag || m_BlockClientMessageProcessing || m_InterruptMessagesProcessing)
				{
					break;
				}
			}
		}
		m_InterruptMessagesProcessing = false;
		if (((ScenarioRuleClient.IsChoreographerProcessing || GameState.ThreadIsSleeping) & flag) && !m_BlockClientMessageProcessing)
		{
			Singleton<LevelEventsController>.Instance.TickEvents();
		}
		if ((flag && !Singleton<LevelEventsController>.Instance.IsBusy) || m_BlockClientMessageProcessing)
		{
			ScenarioRuleClient.IsChoreographerProcessing = false;
		}
		UpdateWaitState();
		if ((bool)m_Phase)
		{
			m_Phase.horizontalOverflow = HorizontalWrapMode.Overflow;
			m_Phase.text = PhaseDebugText();
		}
		if ((bool)m_StateText)
		{
			m_StateText.horizontalOverflow = HorizontalWrapMode.Overflow;
			m_StateText.text = StateDebugText();
		}
		if (FFSNetwork.IsOnline && !SceneController.Instance.IsLoading)
		{
			if (PhaseManager.PhaseType == CPhase.PhaseType.SelectAbilityCardsOrLongRest && PlayerRegistry.AllPlayers.Find((NetworkPlayer x) => !x.IsParticipant) != null)
			{
				if (Singleton<UIResultsManager>.Instance == null || !Singleton<UIResultsManager>.Instance.IsShown)
				{
					Singleton<UIReadyToggle>.Instance?.SetInteractable(interactable: false);
				}
			}
			else if (Singleton<UIResultsManager>.Instance == null || !Singleton<UIResultsManager>.Instance.IsShown)
			{
				InitiativeTrack.Instance?.CheckRoundAbilityCardsOrLongRestSelected();
			}
			DesyncDetector.CheckForDesync(isAtCheckpoint: false);
			GHNetworkCallbacks.CheckForSavePointReached();
		}
		FastReload.CheckAutoUndoRedo();
	}

	public static string PhaseDebugText()
	{
		string text = $"Phase: {PhaseManager.PhaseType}";
		CActor cActor = GameState.CurrentActor;
		if (cActor == null)
		{
			cActor = GameState.TurnActor;
		}
		if (cActor == null)
		{
			cActor = GameState.s_ShortRestingPlayer;
		}
		if (cActor != null)
		{
			text = text + ": " + cActor.Class.ID;
		}
		CAbility cAbility = (PhaseManager.CurrentPhase as CPhaseAction)?.CurrentPhaseAbility?.m_Ability;
		if (cAbility != null)
		{
			text = text + ", " + cAbility.GetType().Name + "(" + cAbility.CachedAbilityBaseCard?.Name + "." + cAbility.Name + ")";
		}
		return text;
	}

	public static string StateDebugText()
	{
		string text = $"Choreographer: {s_Choreographer?.m_WaitState.m_State}";
		if (FFSNetwork.IsOnline)
		{
			text = $"ActionProcessor: {ActionProcessor.CurrentState}; {text}";
		}
		return text;
	}

	private void UpdateWaitState()
	{
		switch (m_WaitState.m_State)
		{
		case ChoreographerStateType.WaitingForExhaustionClear:
			try
