				break;
			}
			catch (Exception ex10)
			{
				Log.Exception(ex10, "An exception occurred while processing WaitingForExhaustionClear");
				SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00161", "GUI_ERROR_MAIN_MENU_BUTTON", ex10.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex10.Message);
				break;
			}
		case ChoreographerStateType.WaitingForRewardsProcess:
			try
			{
				if (!Singleton<ScenarioRewardManager>.Instance.IsShown && m_ShouldShowRewards)
				{
					SaveData.Instance.Global.AllowSpeedUp();
				}
				if (Environment.TickCount < m_WaitState.m_StateWaitTickFrame || Singleton<ScenarioRewardManager>.Instance.IsShown || !m_ShouldShowRewards)
				{
					break;
				}
				Log.Info("Starting rewards showcase at " + Timekeeper.instance.m_GlobalClock.time);
				m_ShouldShowRewards = false;
				SaveData.Instance.Global.DisallowSpeedUp();
				Singleton<ScenarioRewardManager>.Instance.Show(() =>
				{
					Log.Info("Continuing after rewards showcase at " + Timekeeper.instance.m_GlobalClock.time);
					ScenarioRuleClient.ToggleMessageProcessing(process: true);
					m_BlockClientMessageProcessing = false;
					bool shouldContinueStep = m_WaitState.m_ShouldContinueStep;
					SetChoreographerState(ChoreographerStateType.Play, 0, null);
					if (shouldContinueStep)
					{
						if (WaitingForSyncPoint)
						{
							StepCompleteAfterSyncPoint();
						}
						else
						{
							ScenarioRuleClient.StepComplete();
						}
