	private bool IsActiveBonusEffectActive()
	{
		FieldInfo[] fields = GlobalSettings.Instance.m_ActiveBonusBuffTargetEffects.GetType().GetFields();
		for (int i = 0; i < fields.Length; i++)
		{
			GameObject prefab = fields[i].GetValue(GlobalSettings.Instance.m_ActiveBonusBuffTargetEffects) as GameObject;
			if (!ObjectPool.SpawnedContains(prefab))
			{
				continue;
			}
			foreach (GameObject match in ObjectPool.GetMatches(prefab))
			{
				if (match != null && match.activeSelf)
				{
					ParticleSystem component = match.GetComponent<ParticleSystem>();
					if (component != null && component.IsAlive(withChildren: false))
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private void OnGameSpeedChanged()
	{
		foreach (GameObject item in AllActorsInScene)
		{
			SetAnimSpeed(item);
		}
	}

	private void SetAnimSpeed(GameObject actor)
	{
		if (!(actor == null))
		{
			Animator componentInChildren = actor.GetComponentInChildren<Animator>();
			if (componentInChildren != null)
			{
				componentInChildren.speed = Timekeeper.instance.m_GlobalClock.timeScale;
			}
		}
	}

	public List<CPlayerActor> PlayersInInvalidStartingPositionsForCompanionSummons()
	{
		List<CPlayerActor> list = new List<CPlayerActor>();
		foreach (CPlayerActor playerActor in ScenarioManager.Scenario.PlayerActors)
		{
			if (playerActor.CharacterClass.CompanionSummonData == null)
			{
				continue;
			}
			List<CTile> allAdjacentTiles = ScenarioManager.GetAllAdjacentTiles(ScenarioManager.Tiles[playerActor.ArrayIndex.X, playerActor.ArrayIndex.Y]);
			bool flag = false;
			foreach (CTile item in allAdjacentTiles)
			{
				CNode cNode = ScenarioManager.PathFinder.Nodes[item.m_ArrayIndex.X, item.m_ArrayIndex.Y];
				if (cNode.Walkable && !cNode.Blocked && CAbilityFilter.IsValidTile(item, CAbilityFilter.EFilterTile.EmptyHex))
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				list.Add(playerActor);
			}
		}
		return list;
	}

	public bool WillMovingPlayerToTileMakeStartingPositionsValid(CClientTile tileToMoveTo)
	{
		int num = Mathf.RoundToInt((float)m_ClientPlayers.Count / (float)ClientScenarioManager.s_ClientScenarioManager.PossibleStartingTiles.Count);
		foreach (List<CClientTile> possibleStartingTile in ClientScenarioManager.s_ClientScenarioManager.PossibleStartingTiles)
		{
			int num2 = 0;
			foreach (CClientTile item in possibleStartingTile)
			{
				if (item != tileToMoveTo)
				{
					CPlayerActor cPlayerActor = ScenarioManager.Scenario.FindPlayerAt(item.m_Tile.m_ArrayIndex);
					if (cPlayerActor != null && cPlayerActor != InitiativeTrack.Instance.SelectedActor().Actor)
					{
						num2++;
					}
				}
				else
				{
					num2++;
				}
			}
			if (num2 > num)
			{
				return false;
			}
		}
		return true;
	}

	public void SetupGenericButton(bool interactable, string description, Action onClickCallback)
	{
		if (m_GenericButton.IsActive)
		{
			throw new InvalidOperationException("Trying to setup generic button, while someone else is using it.");
		}
		m_GenericButton.SetActive(active: true);
		m_GenericButton.SetInteractable(interactable);
		m_GenericButton.SetText(description);
		m_GenericButton.AddOnClickListener(() =>
		{
			ClearGenericButton();
			onClickCallback?.Invoke();
		});
		readyButton.AddExtraAction(ClearGenericButton);
		m_SkipButton.AddExtraAction(ClearGenericButton);
	}

	public void ClearGenericButton()
	{
		m_GenericButton.RemoveAllOnClickListeners();
		m_GenericButton.SetActive(active: false);
		readyButton.RemoveExtraAction(ClearGenericButton);
		m_SkipButton.RemoveExtraAction(ClearGenericButton);
	}

	public void AddPendingAnimationToWait(object animationHandle)
	{
		if (m_PendingAnimations.Contains(animationHandle))
		{
			throw new ArgumentException($"AnimationHandle already in progress: {animationHandle}");
		}
		m_PendingAnimations.Add(animationHandle);
	}

	public void RemovePendingAnimationToWait(object animationHandle)
	{
		if (m_PendingAnimations.Contains(animationHandle))
		{
			m_PendingAnimations.Remove(animationHandle);
		}
	}

	public PendingAnimationScope WaitPendingAnimationScope(object animationHandle)
	{
		return new PendingAnimationScope(animationHandle);
	}

	public static bool IsMultiplayerDisabled()
	{
		GameMode gameMode = SaveData.Instance?.Global?.CurrentAdventureData?.FrosthavenCampaign?.GameMode;
		bool num = gameMode != null && gameMode.MultiplayerDisabled;
		bool flag = SaveData.Instance?.Global?.CurrentAdventureData?.AdventureMapState?.CurrentSingleScenario != null && (SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentSingleScenario.Name.StartsWith("RFS_01") || SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentSingleScenario.Name.StartsWith("RFS_02") || SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentSingleScenario.Name.StartsWith("RFS_03"));
		return num | flag;
	}

	public static bool IsInNoPartyCampaign()
	{
		GameMode gameMode = SaveData.Instance?.Global?.CurrentAdventureData?.FrosthavenCampaign?.GameMode;
		if (!(gameMode != null) || !gameMode.CanPlayWithoutCharacters)
		{
			return IsInTutorial();
		}
		return true;
	}

	public static bool IsInTutorial()
	{
		if (SaveData.Instance?.Global?.CurrentAdventureData?.AdventureMapState?.CurrentSingleScenario != null)
		{
			if (!SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentSingleScenario.Name.StartsWith("RFS_01") && !SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentSingleScenario.Name.StartsWith("RFS_02"))
			{
				return SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentSingleScenario.Name.StartsWith("RFS_03");
			}
			return true;
		}
		return false;
	}

	public static bool IsInPrologue()
	{
		return SaveData.Instance?.Global?.CurrentAdventureData?.FrosthavenSaveData?.GameState?.IsInPrologue == true;
	}

	public static bool IsInFinalTutorial()
	{
		if (SaveData.Instance?.Global?.CurrentAdventureData?.ScenarioResult != null)
		{
			return SaveData.Instance.Global.CurrentAdventureData.ScenarioResult.ScenarioID.StartsWith("RFS_03");
		}
		return false;
	}

	[ConsoleCommand(Command = "set_fps")]
	public static void SetFPS(IConsole console, int val)
	{
		Application.targetFrameRate = val;
	}

	public bool ActorOrHisSummonerIsUnderMyControl(CActor actor)
	{
		if (actor.IsUnderMyControl())
		{
			return true;
		}
		if (actor.Type != actor.OriginalType && GameState.OverridingCurrentActor && GameState.OverridenActionActorStack.Count > 0 && GameState.OverridenActionActorStack.Peek().ControllingActor != null)
		{
			return GameState.OverridenActionActorStack.Peek().ControllingActor.IsUnderMyControl();
		}
		if (actor is CHeroSummonActor cHeroSummonActor)
		{
			return cHeroSummonActor.Summoner.IsUnderMyControl();
		}
		if (Singleton<TakeDamagePanel>.Instance.IsOpen)
		{
			return Singleton<TakeDamagePanel>.Instance.ThisPlayerHasTakeDamageControl;
		}
		return false;
	}

