	private void InitMessageHandlerMethods()
	{
		try
		{
			MethodInfo[] methods = GetType().GetMethods(BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic);
			foreach (MethodInfo methodInfo in methods)
			{
				MessageHandlerAttribute customAttribute = methodInfo.GetCustomAttribute<MessageHandlerAttribute>();
				if (customAttribute != null)
				{
					if (_handlerDelegates.ContainsKey(customAttribute.MessageType))
					{
						throw new Exception($"Handler method duplication for message type {customAttribute.MessageType}!\n" + "[" + methodInfo.Name + "] and [" + _handlerDelegates[customAttribute.MessageType].Method.Name + "]!");
					}
					_handlerDelegates[customAttribute.MessageType] = (MessageHandlerDelegate)methodInfo.CreateDelegate(typeof(MessageHandlerDelegate), this);
				}
			}
		}
		catch (Exception ex)
		{
			Log.Exception(ex, ex.Message);
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("MESSAGE TYPE HANDLER EXCEPTION", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
		}
	}

	private string GetNonOverloadAnim(CAbility ability)
	{
