		return "UseItem";
	}

	private static CardPileType GetCurrentTargetCardPileType(CPlayerActor playerActor)
	{
		if (!GameState.IsPerformingCardOutOfPhase)
		{
			if (!playerActor.IsTakingExtraTurn)
			{
				return CardPileType.Round;
			}
			return CardPileType.ExtraTurn;
		}
		return CardPileType.SelectedAbilityCardsOutOfPhase;
	}

	private void ProcessMessage(CMessageData message)
	{
		if (SceneController.Instance.GlobalErrorMessage.ShowingMessage)
		{
			return;
		}
		using (new MiniProfilerScope("ProcessMessage(" + message.GetType().Name + ")"))
		{
			if (message.m_Type == CMessageData.MessageType.SRLQueueDebugLog)
			{
				CSRLQueueStatusLog_MessageData cSRLQueueStatusLog_MessageData = (CSRLQueueStatusLog_MessageData)message;
				if (cSRLQueueStatusLog_MessageData.m_SRLMessage is ScenarioRuleClient.ArbitraryCommandMessage arbitraryCommandMessage && !string.IsNullOrEmpty(arbitraryCommandMessage.description))
				{
					GUIInterface.s_GUIInterface.SetSRLQueueStatusText(arbitraryCommandMessage.description);
				}
				else
				{
					GUIInterface.s_GUIInterface.SetSRLQueueStatusText(cSRLQueueStatusLog_MessageData.m_SRLMessage.m_MessageType.ToString());
				}
			}
			else
			{
				if (!message.m_Type.ToString().Contains("CombatLog"))
				{
					GUIInterface.s_GUIInterface.SetClientQueueStatusText(message.m_Type.ToString());
				}
				_ = LastMessage;
				string text = string.Format("{0} ProcessMessage Start: {1}    {2}", "[Chor]", Log.Colorize(message.m_Type.ToString(), Color.yellow), message.m_ActorSpawningMessage);
				if (message.LogCallStack)
				{
					text = text + "\nSender callstack:\n" + message.CallStack + "\n-----";
				}
				Log.Info(text);
				if (!m_debugMessage)
				{
					LastMessage = message;
				}
			}
			SendMessageToViewController(message);
			if (IsRestarting && _ignoredWhenRestarting.Contains(message.m_Type))
			{
				Log.Info(string.Format("{0} Ignoring {1} while restarting", "[Chor]", message.m_Type));
				return;
			}
			if (message.m_Type == CMessageData.MessageType.MonsterClassesToSelectAbilityCards && ScenarioManager.Scenario.PlayerActors.Count == 0)
			{
				Log.Info(string.Format("{0} Ignoring {1} on no players", "[Chor]", message.m_Type));
				return;
			}
			if ((message.m_Type == CMessageData.MessageType.ProcessAutosaves || message.m_Type == CMessageData.MessageType.PlayersHaveSelectedAbilityCardsOrLongRest) && Singleton<UIResultsManager>.Instance.IsShown)
			{
				Log.Info(string.Format("{0} Ignoring {1} while results are open", "[Chor]", message.m_Type));
				return;
			}
			try
			{
				if (_handlerDelegates.TryGetValue(message.m_Type, out var value))
				{
					CurrentlyProcessingMessage = message;
					value(message);
					CurrentlyProcessingMessage = null;
				}
			}
			catch (Exception ex)
			{
				if (!_messageTypeErrorKeys.TryGetValue(message.m_Type, out var value2))
				{
					value2 = "UNKNOWN ERROR";
				}
				if (!string.IsNullOrEmpty(message.CallStack))
				{
					Log.Error(string.Format("{0} Send call stack for message '{1}':\n{2}", "[Chor]", message.m_Type, message.CallStack));
				}
				Log.Exception(ex, $"An exception occurred while processing the {message.m_Type} message");
				SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle(value2, "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
				throw ex;
			}
			m_PreviousMessageType = message.m_Type;
			SendMessageToWorldspace(message);
			if (GameState.InitiativeSortedActors.Count > 0 && !ScenarioManager.IsFastReloading && _updateVisualOrder.Contains(message.m_Type))
			{
				if (PhaseManager.IsInCardsSelectionPhase)
				{
					Log.InfoFormat("[Chor] UpdateInitiativeTrack from SelectAbilityCardsOrLongRest {0}", message.m_Type);
					InitiativeTrack.Refresh(forceSelectFirstActor: false);
				}
				else
				{
					bool flag = message.m_Type != CMessageData.MessageType.ActivateProp;
					CSummon_MessageData summon = message as CSummon_MessageData;
					bool flag2 = summon != null && summon.m_SummonAbility != null && !summon.m_SummonAbility.IsMonsterSummon && ScenarioManager.Scenario.HeroSummons.Exists((CHeroSummonActor it) => it.HeroSummonClass.ID == summon.m_SummonAbility.SelectedSummonID && it.IsCompanionSummon);
					bool flag3 = flag && !flag2 && (message.m_Type != CMessageData.MessageType.ActorDead || ((CActorDead_MessageData)message).m_Actor is CPlayerActor);
					Log.InfoFormat("[Chor] UpdateInitiativeTrack from {0} (autoselect {1})", message.m_Type, flag3);
					InitiativeTrack.Refresh(flag3);
				}
			}
			if (message.m_Type == CMessageData.MessageType.EndAbilityAnimSync)
			{
				Singleton<TakeDamagePanel>.Instance.RefreshDamagePreview();
			}
			if (message.m_Type != CMessageData.MessageType.SRLQueueDebugLog)
			{
				Log.Info(Log.Colorize(string.Format("{0} ProcessMessage Ended: {1}", "[Chor]", message.m_Type), Color.gray));
			}
		}
	}

