	[MessageHandler(CMessageData.MessageType.PlayersExhausted)]
	private void Handle_PlayersExhausted(CMessageData message)
	{
		CPlayersExhausted_MessageData cPlayersExhausted_MessageData = (CPlayersExhausted_MessageData)message;
		bool flag = Singleton<CardsHandManager>.Instance.IsActive();
		StringBuilder stringBuilder = new StringBuilder();
		if (cPlayersExhausted_MessageData.m_Players.Count > 0)
		{
			for (int i = 0; i < cPlayersExhausted_MessageData.m_Players.Count; i++)
			{
				if (flag)
				{
					Singleton<CardsHandManager>.Instance.UpdateDeadPlayer(cPlayersExhausted_MessageData.m_Players[i]);
				}
				string statusText = "Player " + LocalizationManager.GetTranslation(cPlayersExhausted_MessageData.m_Players[i].ActorLocKey()) + " exhausted";
				GUIInterface.s_GUIInterface.SetStatusText(statusText);
				if (i > 0)
				{
					if (i == cPlayersExhausted_MessageData.m_Players.Count - 1)
					{
						stringBuilder.Append(" ");
						stringBuilder.Append(LocalizationManager.GetTranslation("AND"));
						stringBuilder.Append(" ");
					}
					else
					{
						stringBuilder.Append(", ");
					}
				}
				stringBuilder.Append(LocalizationManager.GetTranslation(cPlayersExhausted_MessageData.m_Players[i].ActorLocKey()));
				stringBuilder.Append(" ");
			}
			InitiativeTrack.Instance.helpBox.Show("GUI_CHARACTERS_EXHAUSTED_TIP", "GUI_CHARACTERS_EXHAUSTED_TITLE", HelpBox.FormatTarget.ALL);
			Singleton<PhaseBannerHandler>.Instance.ShowExhausted(stringBuilder.ToString());
			if (PhaseManager.IsInCardsSelectionPhase)
			{
				InitiativeTrack.Instance.CheckRoundAbilityCardsOrLongRestSelected();
			}
		}
		if (ScenarioManager.Scenario.AllPlayers.All((CPlayerActor p) => p.IsDead) && ScenarioManager.Scenario.AllPlayers.Any((CPlayerActor p) => p.IsDeadForObjectives) && PhaseManager.CurrentPhase is CPhasePlayerExhausted)
		{
			Log.SimpleInfo("Lose triggered at PlayersExhausted message as all player actors are dead.");
			LoseScenario();
		}
		else if (PhaseManager.PhaseType == CPhase.PhaseType.PlayerExhausted)
		{
			ScenarioRuleClient.StepComplete();
		}
	}

	[MessageHandler(CMessageData.MessageType.BattleGoalFailed)]
	private void Handle_BattleGoalFailed(CMessageData message)
	{
		CBattleGoalFailed_MessageData messageData = (CBattleGoalFailed_MessageData)message;
		Tuple<string, CBattleGoalState> tuple = SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.CurrentMapScenarioState.AllActiveBattleGoals.FirstOrDefault((Tuple<string, CBattleGoalState> x) => x.Item1 == messageData.characterID && x.Item2.ID == messageData.battleGoalID);
		if (tuple == null)
		{
			Log.Error("Can't find battle goal " + messageData.battleGoalID + " for character " + messageData.characterID + " while trying to show it as failed");
		}
		else if (!tuple.Item2.IsMastery)
		{
			CPlayerActor cPlayerActor = ScenarioManager.CurrentScenarioState.Players.FirstOrDefault((PlayerState x) => x.ClassID == messageData.characterID)?.Actor as CPlayerActor;
			if (!FFSNetwork.IsOnline || cPlayerActor.IsUnderMyControl())
			{
				string characterName = cPlayerActor.CharacterName;
				string translation = LocalizationManager.GetTranslation("GUI_FAILED_BATTLE_GOAL");
				string translation2 = LocalizationManager.GetTranslation(tuple.Item2.BattleGoal.LocalisedName);
				translation = string.Format(translation, characterName, translation2);
				(Singleton<FHScenarioViewController>.InstanceFast?.Modules?.SimpleActionBox).ShowWarning(translation);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ProcessAutosaves)]
	private async void Handle_ProcessAutosaves(CMessageData message)
	{
		if (UnityGameEditorRuntime.s_SkipNextAutoSave)
		{
			UnityGameEditorRuntime.s_SkipNextAutoSave = false;
			Log.Info("Skipping auto-save on join");
			SetChoreographerState(ChoreographerStateType.Play, 0, null);
			if (PhaseManager.CurrentPhase.Type == CPhase.PhaseType.Autosave)
			{
				ScenarioRuleClient.NextPhase();
			}
			return;
		}
		if (SaveData.Instance.Global.CurrentAdventureData == null)
		{
			Log.SimpleInfo("Round Chest Rewards were not applied because CurrentAdventureData is null");
		}
		else if (SaveData.Instance.Global.CurrentAdventureData.AdventureMapState == null)
		{
			Log.SimpleInfo("Round Chest Rewards were not applied because AdventureMapState is null");
		}
		else
		{
			SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.ApplyRoundChestRewards();
		}
		m_CurrentState.Update();
		if (!ScenarioManager.DisableCameraRotation())
		{
			m_CurrentState.StartingCameraProfile = CameraController.s_CameraController.GetCurrentCameraProfile();
			m_CurrentState.StartingCameraProfile.ShouldForceCamera = true;
		}
		if (SaveData.Instance.Global.GameMode == EGameMode.Autotest || SaveData.Instance.Global.GameMode == EGameMode.FrontEndTutorial)
		{
			SetChoreographerState(ChoreographerStateType.Play, 0, null);
			ScenarioRuleClient.NextPhase();
			return;
		}
		if (GameState.RoundCount > 0)
		{
			SaveData.Instance.IsSavingData = true;
			SetChoreographerState(ChoreographerStateType.WaitingForAutosave, 60000, null);
			ProcessAutosavesThreaded();
			return;
		}
		ScenarioRuleLibrary.ScenarioState currentState = await m_CurrentState.CopyScenarioState();
		if (SaveData.Instance.Global.GameMode == EGameMode.Campaign)
		{
			SaveData.Instance.IsSavingData = true;
			StartCoroutine(SaveData.Instance.Global.CurrentAdventureData.UpdateScenarioCheckpointAsync(currentState));
		}
		else if (SaveData.Instance.Global.GameMode == EGameMode.SingleScenario)
		{
			SaveData.Instance.IsSavingData = true;
			StartCoroutine(SaveData.Instance.Global.CurrentAdventureData.UpdateScenarioCheckpointAsync(currentState));
		}
		SetChoreographerState(ChoreographerStateType.WaitingForAutosave, 60000, null);
	}

	[MessageHandler(CMessageData.MessageType.RefreshStartingPostions)]
