	[MessageHandler(CMessageData.MessageType.PlayerToSelectAbilityCardsOrLongRest)]
	private void Handle_PlayerToSelectAbilityCardsOrLongRest(CMessageData message)
	{
		CPlayerToSelectAbilityCardsOrLongRest_MessageData cPlayerToSelectAbilityCardsOrLongRest_MessageData = message as CPlayerToSelectAbilityCardsOrLongRest_MessageData;
		if (m_PlayerToSelectAbilityCardsOrLongRest && Singleton<CardsHandManager>.Instance.IsShown)
		{
			return;
		}
		if (FFSNetwork.IsOnline && cPlayerToSelectAbilityCardsOrLongRest_MessageData.m_SyncMultiplayer)
		{
			if (!UnityGameEditorRuntime.s_SkipNextSelectCardSyncCheck)
			{
				ProcessMessage(new CWaitForMultiplayerSyncPoint_MessageData
				{
					m_OnFinish = () =>
					{
						ProcessMessage(new CPlayerToSelectAbilityCardsOrLongRest_MessageData(null));
					}
				});
				return;
			}
			UnityGameEditorRuntime.s_SkipNextSelectCardSyncCheck = false;
		}
		m_CurrentActor = null;
		if (m_CurrentState.RoundNumber == 1 && ClientScenarioManager.s_ClientScenarioManager.PossibleStartingTiles.Count > 1)
		{
			m_RoomCameraButton.Show();
		}
		else
		{
			m_RoomCameraButton.Hide();
		}
		InfusionBoardUI.Instance?.UpdateBoard();
		ClearStars();
		if (!m_FollowCameraDisabled)
		{
			CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
		}
		CActor currentActor = GameState.CurrentActor;
		bool flag = false;
		if (currentActor?.CharacterClass != null && !currentActor.CharacterClass.HasShortRested && GameState.HasShortRestWithPreRestAbilities)
		{
			flag = currentActor.CharacterClass.ImprovedShortRest && (!currentActor.CharacterClass.ImprovedShortRestCanExcludeCards || !currentActor.CharacterClass.ExcludedCardsFromShortRest);
		}
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = true;
		if (!flag)
		{
			int num;
			if (GameState.s_ShortRestingPlayer != null)
			{
				num = (ShortRest.Instant ? 1 : 0);
				if (num != 0)
				{
					GameState.s_ShortRestingPlayer = null;
					GameState.OverrideCurrentActor(null);
				}
			}
			else
			{
				num = 0;
			}
			CardsHandManager.ShowCardsSelection();
			if (num != 0)
			{
				m_PlayerToSelectAbilityCardsOrLongRest = true;
				PhaseManager.SetNextPhase(CPhase.PhaseType.SelectAbilityCardsOrLongRest);
			}
		}
		Singleton<CardsHandManager>.Instance.ResetShortRestFlags();
		if (FFSNetwork.IsOnline && PhaseManager.PhaseType == CPhase.PhaseType.SelectAbilityCardsOrLongRest)
		{
			readyButton.Toggle(active: false);
			Singleton<UIReadyToggle>.Instance.Initialize(show: true, () =>
			{
				Singleton<CardsHandManager>.Instance.SetHandInteractable(interactable: false);
				Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
			}, () =>
			{
				UIMultiplayerNotifications.HideCancelReadiedCards();
				Singleton<CardsHandManager>.Instance.SetHandInteractable(interactable: true);
				Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = true;
			}, () =>
			{
				Singleton<UIScenarioMultiplayerController>.Instance.HideReadyTracker();
				Singleton<CardsHandManager>.Instance.SetHandInteractable(interactable: true);
				Singleton<CardsHandManager>.Instance.Hide();
				Pass();
			}, (NetworkPlayer player, bool isReady) =>
			{
				Singleton<UIScenarioMultiplayerController>.Instance.UpdateReadyPlayer(player, isReady);
			}, null, "GUI_END_SELECTION", "GUI_REDOSELECTION", "PlaySound_UIMultiPlayerReady", bringToFront: false, (bool toReadyUp) =>
			{
				Singleton<CardsHandManager>.Instance.SetHandInteractable(interactable: false);
				Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
			}, (bool toReadyUp) =>
			{
				Singleton<CardsHandManager>.Instance.SetHandInteractable(interactable: true);
				Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = true;
			});
			if (FFSNetwork.IsHost)
			{
				Synchronizer.NotifyJoiningPlayersAboutReachingSavePoint();
				bool num2 = PlayerRegistry.JoiningPlayers.Count > 0 || PlayerRegistry.ConnectingUsers.Count > 0;
				bool flag2 = PlayerRegistry.AllPlayers.Count == 1;
				if (num2 | flag2)
				{
					Singleton<UIReadyToggle>.Instance.SetInteractable(interactable: false);
					PlayerRegistry.OnUserConnected = (ConnectionEstablishedEvent)Delegate.Remove(PlayerRegistry.OnUserConnected, new ConnectionEstablishedEvent(OnPlayerConnected));
					PlayerRegistry.OnUserConnected = (ConnectionEstablishedEvent)Delegate.Combine(PlayerRegistry.OnUserConnected, new ConnectionEstablishedEvent(OnPlayerConnected));
				}
				PlayerRegistry.OnUserEnterRoom = (UserEnterEvent)Delegate.Remove(PlayerRegistry.OnUserEnterRoom, new UserEnterEvent(OnUserEnter));
				PlayerRegistry.OnUserEnterRoom = (UserEnterEvent)Delegate.Combine(PlayerRegistry.OnUserEnterRoom, new UserEnterEvent(OnUserEnter));
				FFSNetwork.HostingEndedEvent.RemoveListener(OnSwitchedToSinglePlayer);
				FFSNetwork.HostingEndedEvent.AddListener(OnSwitchedToSinglePlayer);
			}
			PlayerRegistry.OnJoiningUserDisconnected = (ConnectionEstablishedEvent)Delegate.Remove(PlayerRegistry.OnJoiningUserDisconnected, new ConnectionEstablishedEvent(OnJoiningUserLeft));
			PlayerRegistry.OnJoiningUserDisconnected = (ConnectionEstablishedEvent)Delegate.Combine(PlayerRegistry.OnJoiningUserDisconnected, new ConnectionEstablishedEvent(OnJoiningUserLeft));
			PlayerRegistry.OnPlayerJoined = (PlayersChangedEvent)Delegate.Remove(PlayerRegistry.OnPlayerJoined, new PlayersChangedEvent(OnPlayerJoined));
			PlayerRegistry.OnPlayerJoined = (PlayersChangedEvent)Delegate.Combine(PlayerRegistry.OnPlayerJoined, new PlayersChangedEvent(OnPlayerJoined));
			PlayerRegistry.OnPlayerLeft = (PlayersChangedEvent)Delegate.Remove(PlayerRegistry.OnPlayerLeft, new PlayersChangedEvent(OnPlayerLeft));
			PlayerRegistry.OnPlayerLeft = (PlayersChangedEvent)Delegate.Combine(PlayerRegistry.OnPlayerLeft, new PlayersChangedEvent(OnPlayerLeft));
			ControllableRegistry.OnControllerChanged = (ControllerChangedEvent)Delegate.Remove(ControllableRegistry.OnControllerChanged, new ControllerChangedEvent(OnControllableOwnershipChanged));
			ControllableRegistry.OnControllerChanged = (ControllerChangedEvent)Delegate.Combine(ControllableRegistry.OnControllerChanged, new ControllerChangedEvent(OnControllableOwnershipChanged));
			Singleton<UIScenarioMultiplayerController>.Instance.OnCardSelection();
		}
		else
		{
			readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONENDSELECTION, LocalizationManager.GetTranslation("GUI_END_SELECTION"), hideOnClick: true, glowingEffect: true, interactable: false);
			FFSNetwork.HostingStartedEvent.RemoveListener(OnSwitchedToMultiplayer);
			FFSNetwork.HostingStartedEvent.AddListener(OnSwitchedToMultiplayer);
		}
		m_UndoButton.Toggle(active: false);
		m_SkipButton.Toggle(active: false);
		bool flag3 = m_LastRoundWhenShowCardSelection == GameState.RoundCount;
		InitiativeTrack.Refresh(!flag3 || InitiativeTrack.Instance?.SelectedActor() == null);
		InitiativeTrack.Instance.CheckRoundAbilityCardsOrLongRestSelected();
		m_LastRoundWhenShowCardSelection = GameState.RoundCount;
		GUIInterface.s_GUIInterface.SetStatusText("Once all players have round ability cards the end selection button is enabled");
		GUIInterface.s_GUIInterface.SetStatusText("Selecting a 3rd card will clear the set");
		GUIInterface.s_GUIInterface.SetStatusText("or Long Rest, if selecting ability cards then first one is the initiative lead card");
		GUIInterface.s_GUIInterface.SetStatusText("Select each player on the initiative track then select their 2 ability cards");
		m_InitialActionAbilityCard = null;
		CPlayerActor cPlayerActor = ((PhaseManager.PhaseType != CPhase.PhaseType.ShortRest) ? CardsHandManager.DecidePlayerToShowCardsFor() : GameState.s_ShortRestingPlayer);
		if (cPlayerActor != null && !GameState.HasShortRestWithPreRestAbilities)
		{
			Singleton<CardsHandManager>.Instance.SwitchHand(cPlayerActor);
			if (flag3)
			{
				CardsHandUI hand = Singleton<CardsHandManager>.Instance.GetHand(cPlayerActor);
				if (hand.CachedSelectedCards.Count > 0)
				{
					foreach (AbilityCardUI cachedSelectedCard in hand.CachedSelectedCards)
					{
						if (cachedSelectedCard.IsSelectable)
						{
							hand.SelectCard(cachedSelectedCard.AbilityCard);
						}
					}
					hand.CachedSelectedCards.Clear();
				}
			}
		}
		SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null);
		if (ClientScenarioManager.s_ClientScenarioManager.CurrentState.IsSelectingPositions && !AutoTestController.s_AutoTestCurrentlyLoaded && (!SaveData.Instance.Global.CurrentlyPlayingCustomLevel || SaveData.Instance.Global.CurrentCustomLevelData.PartySpawnType != ELevelPartyChoiceType.PresetSpawnSpecificLocations))
		{
			WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.CharacterPlacement;
		}
		InitiativeTrack.Instance.helpBox.ShowControllerOrKeyboardTip(LocalizationManager.GetTranslation(StartTurnHelpBoxKey()), () => string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_GAMEPAD_FOCUS_ABILITY_CARDS"), Singleton<InputFHManager>.Instance.InputContext.GetDisplayTextFor(InputFHManager.Controls.UI.Navigate)), LocalizationManager.GetTranslation("GUI_TOOLTIP_TITLE_START_TURN"));
		if (FFSNetwork.IsOnline)
		{
			if (!Singleton<StoryController>.Instance.IsBusy)
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.StartOfRound);
				if (FFSNetwork.IsClient && !SceneController.Instance.GameLoadedAndClientReady)
				{
					Synchronizer.SendSideAction(GameActionType.GameLoadedAndClientReady, null, canBeUnreliable: false, sendToHostOnly: true);
					SceneController.Instance.GameLoadedAndClientReady = true;
				}
			}
			if (PlayerRegistry.MyPlayer != null && PlayerRegistry.MyPlayer.IsParticipant && !PlayerRegistry.MyPlayer.MyControllables.Any((NetworkControllable x) => x.IsAlive))
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.StartOfRound);
				Singleton<UIReadyToggle>.Instance.ReadyUp(toggledOn: true);
			}
		}
		IsFirstTurnPlaying = false;
		if (FFSNetwork.IsClient && !PlayerRegistry.MyPlayer.SentPlayerReadyForAssignment)
		{
			PlayerRegistry.MyPlayer.PlayerReadyForAssignment = true;
			PlayerRegistry.MyPlayer.SentPlayerReadyForAssignment = true;
			Synchronizer.SendSideAction(GameActionType.ReadyForAssignment);
		}
		m_PlayerToSelectAbilityCardsOrLongRest = true;
		if (FFSNetwork.IsOnline)
		{
			InitiativeTrack.Instance.PlayersUI.ForEach((InitiativeTrackPlayerBehaviourExtension f) =>
			{
				f.Base.Avatar.RefreshActiveInteractable();
			});
		}
		DesyncDetector.CheckForDesync();
	}

	[MessageHandler(CMessageData.MessageType.PlayersHaveSelectedAbilityCardsOrLongRest)]
	private void Handle_PlayersHaveSelectedAbilityCardsOrLongRest(CMessageData message)
	{
		m_PlayerToSelectAbilityCardsOrLongRest = false;
		if (FFSNetwork.IsOnline)
		{
			InitiativeTrack.Instance.PlayersUI.ForEach((InitiativeTrackPlayerBehaviourExtension f) =>
			{
				f.Base.Avatar.RefreshActiveInteractable();
			});
		}
		foreach (CPlayerActor playerActor in ScenarioManager.Scenario.PlayerActors)
		{
			string text = "";
			if (FFSNetwork.IsOnline)
			{
				NetworkPlayer controller = ControllableRegistry.GetController(ControllableRegistry.GetControllableID(playerActor));
				text = text + "---> BACKEND CARD STATE FOR: " + controller.Username + ": " + LocalizationManager.GetTranslation(playerActor.ActorLocKey()) + "(" + (controller.IsClient ? "Client" : "Host") + ")<---\n";
			}
			else
			{
				text = text + "---> BACKEND CARD STATE FOR: " + LocalizationManager.GetTranslation(playerActor.ActorLocKey()) + "<---\n";
			}
			text = text + "LONG REST SELECTED: " + playerActor.IsLongRestSelected + "\n";
			text = text + "ROUND: " + playerActor.CharacterClass.RoundAbilityCards.Select((CAbilityCard x) => x.StrictName + " CardInstanceID: " + x.CardInstanceID).ToStringPretty() + "\n";
			text = text + "HAND: " + playerActor.CharacterClass.HandAbilityCards.Select((CAbilityCard x) => x.StrictName + " CardInstanceID: " + x.CardInstanceID).ToStringPretty() + "\n";
			text = text + "DISCARDED: " + playerActor.CharacterClass.DiscardedAbilityCards.Select((CAbilityCard x) => x.StrictName + " CardInstanceID: " + x.CardInstanceID).ToStringPretty() + "\n";
			text = text + "BURNED: " + playerActor.CharacterClass.LostAbilityCards.Select((CAbilityCard x) => x.StrictName + " CardInstanceID: " + x.CardInstanceID).ToStringPretty() + "\n";
			text = text + "ACTIVE: " + playerActor.CharacterClass.ActivatedAbilityCards.Select((CAbilityCard x) => x.StrictName + " CardInstanceID: " + x.CardInstanceID).ToStringPretty() + "\n";
			Log.SimpleInfo(text);
		}
		foreach (CPlayerActor playerActor2 in ScenarioManager.Scenario.PlayerActors)
		{
			string text2 = null;
			if (FFSNetwork.IsOnline)
			{
				NetworkPlayer controller2 = ControllableRegistry.GetController(ControllableRegistry.GetControllableID(playerActor2));
				text2 = controller2.Username + ": " + LocalizationManager.GetTranslation(playerActor2.ActorLocKey()) + "(" + (controller2.IsClient ? "Client" : "Host") + ")Scenario Actor Inventory Items: ";
			}
			else
			{
				text2 = LocalizationManager.GetTranslation(playerActor2.ActorLocKey()) + "Scenario Actor Inventory Items:";
			}
			foreach (CItem allItem in playerActor2.Inventory.AllItems)
			{
				text2 = text2 + "\n" + LocalizationNameConverter.MultiLookupLocalization(allItem.Name, out var _) + " Network ID: " + allItem.NetworkID + " State: " + allItem.SlotState.ToString() + ((AdventureState.MapState?.MapParty != null) ? (" Item Exists on corresponding MapCharacter: " + (AdventureState.MapState.MapParty.IsItemEquippedByParty(allItem) != null)) : "");
			}
			Log.SimpleInfo(text2);
		}
		Log.SimpleInfo("RNG STATES (PlayersHaveSelectedAbilityCardsOrLongRest): \nScenarioRNG:" + ScenarioManager.CurrentScenarioState.PeekScenarioRNG + "\nEnemyIDRNG:" + ScenarioManager.CurrentScenarioState.PeekEnemyIDRNG + "\nEnemyAbilityCardRNG:" + ScenarioManager.CurrentScenarioState.PeekEnemyAbilityCardRNG + "\nGuidRNG:" + ScenarioManager.CurrentScenarioState.PeekGuidRNG);
		m_RoomCameraButton.Hide();
		ClientScenarioManager.s_ClientScenarioManager.CurrentState.IsSelectingPositions = false;
		Singleton<CardsHandManager>.Instance.Hide();
		SetChoreographerState(ChoreographerStateType.Play, 0, null);
		WorldspaceStarHexDisplay.Instance.ClearStars();
	}

	[MessageHandler(CMessageData.MessageType.PlayerToShortRest)]
	private void Handle_PlayerToShortRest(CMessageData message)
	{
		CPlayerToShortRest_MessageData messageData = (CPlayerToShortRest_MessageData)message;
		if (FFSNetwork.IsOnline && messageData.m_SyncMultiplayer)
		{
			ProcessMessage(new CWaitForMultiplayerSyncPoint_MessageData
			{
				m_OnFinish = () =>
				{
					ProcessMessage(new CPlayerToShortRest_MessageData(messageData.m_ActorSpawningMessage)
					{
						m_SyncMultiplayer = false
					});
				}
			});
			return;
		}
		CPlayerActor cPlayerActor = message.m_ActorSpawningMessage as CPlayerActor;
		CardsHandUI hand = Singleton<CardsHandManager>.InstanceFast.GetHand(cPlayerActor);
		m_CurrentActor = cPlayerActor;
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(cPlayerActor.IsUnderMyControl() ? ActionProcessorStateType.Halted : ActionProcessorStateType.ProcessFreely, ActionPhaseType.StartOfRound);
		}
		m_PlayerToSelectAbilityCardsOrLongRest = false;
		SetChoreographerState(ChoreographerStateType.Play, 0, null);
		m_UndoButton.Toggle(active: false);
		m_SkipButton.Toggle(active: false);
		InitiativeTrack.Instance.Select(cPlayerActor, forced: true);
		InitiativeTrack.Instance.helpBox.ShowDefault();
		Singleton<CardsHandManager>.Instance.RefreshValidCards();
		hand.StartShortRest(cPlayerActor);
		InitiativeTrack.Instance.CheckRoundAbilityCardsOrLongRestSelected();
		DesyncDetector.CheckForDesync();
	}

	[MessageHandler(CMessageData.MessageType.MonsterClassesToSelectAbilityCards)]
	private void Handle_MonsterClassesToSelectAbilityCards(CMessageData message)
	{
		using (new CActiveBonus.ActiveBonusCalculationScope())
		{
			Singleton<ScenarioInfoModule>.Instance.HideBattleGoals();
			m_PlayerToSelectAbilityCardsOrLongRest = false;
			SetChoreographerState(ChoreographerStateType.Play, 0, null);
			Singleton<CardsHandManager>.InstanceFast?.Hide();
			FastReload.UpdateUndoRedoButtons();
			FaceNearestEnemies();
			foreach (CMonsterClass monsterClass in ((CMonsterClassesToSelectAbilityCards_MessageData)message).m_MonsterClasses)
			{
				if (monsterClass.RoundAbilityCard != null)
				{
					Log.SimpleInfo(LocalizationManager.GetTranslation(monsterClass.LocKey) + " selected card " + monsterClass.RoundAbilityCard.Name);
				}
			}
			DesyncDetector.CheckForDesync();
			List<CEnemyActor> list = (from x in ScenarioManager.Scenario.AllActorsThreadSafe
				select x as CEnemyActor into x
				where x != null
				select x).ToList();
			bool flag = false;
			foreach (CEnemyActor item in list)
			{
				if (InitiativeTrack.HasAvatar(item))
				{
					flag = true;
					break;
				}
			}
			int count = InitiativeTrack.Instance.GetExtraMonsterClasses().Keys.Count;
			if ((list.Count == 0 || !flag) && count == 0 && !Singleton<UIActiveBonusBar>.Instance.IsShowing)
			{
				Pass();
				return;
			}
			m_CurrentActor = null;
			ReadyButton.EButtonState state;
			string term;
			if (list.Count > 0 || count > 0)
			{
				InitiativeTrack.Instance.ShowMonsterClassesForSelectingRoundAbilityCards(list);
				state = ReadyButton.EButtonState.EREADYBUTTONCONTINUE;
				term = "GUI_CONTINUE";
			}
			else
			{
				state = ReadyButton.EButtonState.EREADYBUTTONPASS;
				term = "GUI_CONFIRM";
			}
			bool useProgressBar = FFSNetwork.IsOnline && !IsInNoPartyCampaign();
			readyButton.Toggle(active: true, state, LocalizationManager.GetTranslation(term), hideOnClick: true, glowingEffect: true, !FFSNetwork.IsClient, disregardTurnControlForInteractability: true, haltActionProcessorIfDeactivated: true, null, useProgressBar);
			if (FFSNetwork.IsOnline)
			{
				Singleton<UIScenarioMultiplayerController>.Instance.HidePlayerInfo();
				if (FFSNetwork.IsClient)
				{
					ActionProcessor.SetState(ActionProcessorStateType.ProcessOneAndHalt, ActionPhaseType.EnemyCardReveal);
				}
				else
				{
					ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.EnemyCardReveal);
				}
			}
			GUIInterface.s_GUIInterface.SetStatusText("Monster Classes selecting ability cards");
		}
	}

	[MessageHandler(CMessageData.MessageType.ShowNextMonsterClassAbilityCards)]
	private void Handle_ShowNextMonsterClassAbilityCards(CMessageData message)
	{
		using (new CActiveBonus.ActiveBonusCalculationScope())
		{
			Singleton<ScenarioInfoModule>.Instance.HideBattleGoals();
			CShowNextMonsterClassAbilityCards_MessageData messageData = (CShowNextMonsterClassAbilityCards_MessageData)message;
			List<CEnemyActor> allClientEnemies = (from x in ScenarioManager.Scenario.AllActorsThreadSafe
				select x as CEnemyActor into x
				where x != null
				select x).ToList();
			List<CEnemyActor> list = new List<CEnemyActor>();
			foreach (CMonsterClass monsterClass in messageData.m_MonsterClasses)
			{
				if (monsterClass.NextAbilityCard == null)
				{
					continue;
				}
				Log.SimpleInfo(LocalizationManager.GetTranslation(monsterClass.LocKey) + " selected card " + monsterClass.NextAbilityCard.Name);
				foreach (CEnemyActor item in ScenarioManager.Scenario.AllAliveActorsThreadSafe.Where((CActor x) => x.Class == monsterClass))
				{
					if (item != null)
					{
						list.Add(item);
					}
				}
			}
			Singleton<CardsHandManager>.Instance.Hide();
			bool flag = messageData.m_ActorSpawningMessage.IsUnderMyControl();
			int count = InitiativeTrack.Instance.GetExtraMonsterClasses().Keys.Count;
			Action action = null;
			m_SkipButton.Toggle(active: false);
			ReadyButton.EButtonState state;
			string term;
			if (list.Count > 0 || count > 0)
			{
				InitiativeTrack.Instance.ShowMonsterClassesForSelectingRoundAbilityCards(allClientEnemies, showNextCard: true, list);
				state = ReadyButton.EButtonState.EREADYBUTTONCONTINUE;
				term = "GUI_CONTINUE";
				GUIInterface.s_GUIInterface.SetStatusText("Monster Classes selecting ability cards");
				if (messageData.m_OfferPutBottomOfDeck)
				{
					if (!string.IsNullOrEmpty(messageData.m_AltHelpKey))
					{
						Singleton<HelpBox>.Instance.Show(messageData.m_AltHelpKey);
					}
					action = () =>
					{
						foreach (CMonsterClass monsterClass2 in messageData.m_MonsterClasses)
						{
							if (monsterClass2.NextAbilityCard != null)
							{
								CustomAbility.PutMonsterCardAtBottomOfDeck(monsterClass2.NextAbilityCard, monsterClass2);
							}
						}
						InitiativeTrack.Instance.HideMonsterClassesForSelectingRoundAbilityCards();
						GameState.SelectedContinueAbility();
					};
					term = "GUI_CONFIRM";
					m_SkipButton.Toggle(active: true, null, hideOnClick: true, true, () =>
					{
						InitiativeTrack.Instance.HideMonsterClassesForSelectingRoundAbilityCards();
						GameState.SelectedContinueAbility();
					});
				}
				else
				{
					action = GameState.SelectedContinueAbility;
				}
			}
			else
			{
				state = ReadyButton.EButtonState.EREADYBUTTONPASS;
				term = "GUI_CONFIRM";
				action = GameState.SelectedContinueAbility;
				if (messageData.m_MonsterClasses.Count > 1)
				{
					Singleton<HelpBox>.Instance.Show("FH/GUI_SELECTED_TARGETS_NO_NEXT_CARD");
				}
				else
				{
					Singleton<HelpBox>.Instance.Show("FH/GUI_SELECTED_TARGET_NO_NEXT_CARD");
				}
			}
			readyButton.Toggle(active: true, state, LocalizationManager.GetTranslation(term), hideOnClick: true, glowingEffect: true, flag, disregardTurnControlForInteractability: true);
			if (action != null)
			{
				readyButton.AlternativeAction(action);
			}
			if (FFSNetwork.IsOnline)
			{
				Singleton<UIScenarioMultiplayerController>.Instance.HidePlayerInfo();
				if (flag)
				{
					ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.EnemyCardReveal);
				}
				else
				{
					ActionProcessor.SetState(ActionProcessorStateType.ProcessOneAndHalt, ActionPhaseType.EnemyCardReveal);
				}
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.MonsterClassesHaveSelectedAbilityCards)]
	private void Handle_MonsterClassesHaveSelectedAbilityCards(CMessageData message)
	{
		Log.SimpleInfo("RNG STATES (MonsterClassesHaveSelectedAbilityCards): \nScenarioRNG:" + ScenarioManager.CurrentScenarioState.PeekScenarioRNG + "\nEnemyIDRNG:" + ScenarioManager.CurrentScenarioState.PeekEnemyIDRNG + "\nEnemyAbilityCardRNG:" + ScenarioManager.CurrentScenarioState.PeekEnemyAbilityCardRNG + "\nGuidRNG:" + ScenarioManager.CurrentScenarioState.PeekGuidRNG);
		InitiativeTrack.Instance?.UpdateSelectable(playersSelectable: false, enemiesSelectable: false, default);
	}

	[MessageHandler(CMessageData.MessageType.StartTurn)]
	private void Handle_StartTurn(CMessageData message)
	{
		CStartTurn_MessageData messageData = (CStartTurn_MessageData)message;
		if (messageData.m_ActorSpawningMessage.IsDead && Singleton<PhaseBannerHandler>.Instance.IsShowingDeath())
		{
			return;
		}
		ReproStepsLogger.LogEvent("StartTurn", message.m_ActorSpawningMessage.Class.ID, localOnly: true);
		Singleton<CardsHandManager>.Instance.Hide();
		m_CurrentActor = message.m_ActorSpawningMessage;
		if (FFSNetwork.IsOnline && m_CurrentActor is CPlayerActor)
		{
			InitiativeTrack.Instance.PlayersUI.ForEach((InitiativeTrackPlayerBehaviourExtension f) =>
			{
				f.Base.Avatar.RefreshActiveInteractable();
			});
		}
		if (m_CurrentActor is CPlayerActor)
		{
			SaveData.Instance.Global.DisallowSpeedUp();
		}
		else
		{
			SaveData.Instance.Global.AllowSpeedUp();
		}
		if (FFSNetwork.IsOnline && messageData.m_ActorSpawningMessage is CPlayerActor cPlayerActor)
		{
			NetworkPlayer controller = ControllableRegistry.GetController(ControllableRegistry.GetControllableID(cPlayerActor));
			_ = controller.Username + ": " + LocalizationManager.GetTranslation(cPlayerActor.ActorLocKey());
			_ = "  (" + (controller.IsClient ? "Client" : "Host") + ")";
		}
		else
		{
			_ = LocalizationManager.GetTranslation(messageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(messageData.m_ActorSpawningMessage);
		}
		readyButton.Toggle(active: false);
		readyButton.ClearAlternativeAction();
		s_Choreographer.onCharacterAbilityComplete = null;
		ClearHilightedActors();
		ActorBehaviour.SetHilighted(FindClientActorGameObject(message.m_ActorSpawningMessage), hilight: true);
		m_AbilitiesUsedThisTurn.Clear();
		if (!m_FollowCameraDisabled)
		{
			CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
		}
		m_CurrentActor = message.m_ActorSpawningMessage;
		if (FFSNetwork.IsOnline && m_CurrentActor is CPlayerActor)
		{
			InitiativeTrack.Instance.PlayersUI.ForEach((InitiativeTrackPlayerBehaviourExtension f) =>
			{
				f.Base.Avatar.RefreshActiveInteractable();
			});
		}
		if (CurrentPlayerActor == null)
		{
			Singleton<ScenarioInfoModule>.Instance.HideBattleGoals();
		}
		else
		{
			Singleton<ScenarioInfoModule>.Instance.ShowBattleGoals(CurrentPlayerActor);
		}
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = m_CurrentActor is CPlayerActor;
		ClientScenarioManager.s_ClientScenarioManager.ClearAIPathVisuals(null);
		Singleton<PhaseBannerHandler>.Instance.ResetAndHide();
		if (message.m_ActorSpawningMessage is CPlayerActor cPlayerActor2)
		{
			cPlayerActor2.IsLongRestActionSelected = false;
		}
		if (message.m_ActorSpawningMessage is CEnemyActor)
		{
			Singleton<PhaseBannerHandler>.Instance.ShowEnemyTurn(LocalizationManager.GetTranslation(message.m_ActorSpawningMessage.ActorLocKey()), () =>
			{
				Log.Info($"Finished phase banner. Skip next phase? {messageData.m_SkipNextPhase} (current phase: {PhaseManager.PhaseType})");
				if (PhaseManager.PhaseType == CPhase.PhaseType.StartTurn && !messageData.m_SkipNextPhase && GameState.CurrentActor == message.m_ActorSpawningMessage)
				{
					ScenarioRuleClient.NextPhase();
				}
			});
		}
		else
		{
			if (FFSNetwork.IsOnline && message.m_ActorSpawningMessage is CPlayerActor cPlayerActor3)
			{
				NetworkPlayer controller2 = ControllableRegistry.GetController(ControllableRegistry.GetControllableID(cPlayerActor3));
				Singleton<UIScenarioMultiplayerController>.Instance.OnStartTurn(cPlayerActor3);
				Singleton<PhaseBannerHandler>.Instance.ShowPlayerTurn(LocalizationManager.GetTranslation(message.m_ActorSpawningMessage.ActorLocKey()), string.Format(LocalizationManager.GetTranslation("GUI_COMBATLOG_PLAYER_TURN"), controller2.Username));
			}
			else
			{
				Singleton<PhaseBannerHandler>.Instance.ShowPlayerTurn(LocalizationManager.GetTranslation(message.m_ActorSpawningMessage.ActorLocKey()));
			}
			if (!messageData.m_SkipNextPhase && PhaseManager.PhaseType == CPhase.PhaseType.StartTurn)
			{
				ScenarioRuleClient.NextPhase();
			}
		}
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
	}

	[MessageHandler(CMessageData.MessageType.LogStartTurn)]
	private void Handle_LogStartTurn(CMessageData message)
	{
		CLogStartTurn_MessageData cLogStartTurn_MessageData = message as CLogStartTurn_MessageData;
		if (!cLogStartTurn_MessageData.m_ActorSpawningMessage.TurnStarted)
		{
			string text = "";
			string text2 = "";
			if (FFSNetwork.IsOnline && cLogStartTurn_MessageData.m_ActorSpawningMessage is CPlayerActor cPlayerActor)
			{
				NetworkPlayer controller = ControllableRegistry.GetController(ControllableRegistry.GetControllableID(cPlayerActor));
				text = controller.Username + ": " + LocalizationManager.GetTranslation(cPlayerActor.ActorLocKey());
				text2 = "  (" + (controller.IsClient ? LocalizationManager.GetTranslation("GUI_MULTIPLAYER_CLENT") : LocalizationManager.GetTranslation("GUI_MULTIPLAYER_HOST")) + ")";
			}
			else
			{
				text = LocalizationManager.GetTranslation(cLogStartTurn_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cLogStartTurn_MessageData.m_ActorSpawningMessage);
			}
			Singleton<CombatLogHandler>.Instance.AddHighlightedLog(string.Format("<b><font=\"MarcellusSC-Regular SDF\">{0}</font></b>", string.Format(LocalizationManager.GetTranslation("GUI_COMBATLOG_START_TURN"), text) + text2), message.m_ActorSpawningMessage.Type);
		}
	}

