	[MessageHandler(CMessageData.MessageType.ActionSelection)]
	private void Handle_ActionSelection(CMessageData message)
	{
		CActionSelection_MessageData messageData = message as CActionSelection_MessageData;
		if (messageData.m_SyncMultiplayer && FFSNetwork.IsOnline)
		{
			ProcessMessage(new CWaitForMultiplayerSyncPoint_MessageData
			{
				m_OnFinish = () =>
				{
					messageData.m_SyncMultiplayer = false;
					ProcessMessage(messageData);
				}
			});
			return;
		}
		InfusionBoardUI.Instance?.UpdateBoard();
		Singleton<UIUseAbilitiesBar>.Instance.Hide();
		ClearStars();
		DisableButtons();
		m_AbilitiesUsedThisTurn.Clear();
		m_CurrentActor = message.m_ActorSpawningMessage;
		if (message.m_ActorSpawningMessage.Class is CMonsterClass || message.m_ActorSpawningMessage.Class is CHeroSummonClass || (message.m_ActorSpawningMessage.Class is CCharacterClass && message.m_ActorSpawningMessage.Type != CActor.EType.Player))
		{
			Singleton<CardsHandManager>.Instance.Hide();
			Pass();
			if (message.m_ActorSpawningMessage.Class is CHeroSummonClass && FFSNetwork.IsOnline)
			{
				if (!message.m_ActorSpawningMessage.IsUnderMyControl())
				{
					ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.FirstAction);
				}
				else
				{
					ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.FirstAction);
				}
			}
		}
		else
		{
			CPlayerActor playerActor = (CPlayerActor)message.m_ActorSpawningMessage;
			CameraController.s_CameraController.SmartFocus(FindClientActorGameObject(playerActor), pauseDuringTransition: true);
			Singleton<UIActiveBonusBar>.Instance.ShowActiveBonus(playerActor, CAbility.EAbilityType.None, CActiveBonus.EActiveBonusBehaviourType.DuringTurnAbility);
			if (playerActor.CharacterClass.LongRest)
			{
				StartLongRest(playerActor);
			}
			else
			{
				Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = !FFSNetwork.IsOnline || playerActor.IsUnderMyControl();
				if (!playerActor.CharacterClass.HasLongRested || playerActor.IsTakingExtraTurn || GameState.CurrentOutOfPhaseCardSelectionAbility != null)
				{
					int selectedRoundCardsCount = playerActor.SelectedRoundCardsCount;
					if (GameState.CurrentOutOfPhaseCardSelectionAbility != null)
					{
						InitiativeTrack.Instance.helpBox.ShowControllerOrKeyboardTip(LocalizationManager.GetTranslation("FH/GUI_TOOLTIP_ABILITY_CHOOSING_OUT_OF_PHASE"), () => string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_GAMEPAD_FOCUS_ABILITY_CARDS"), Singleton<InputFHManager>.Instance.InputContext.GetDisplayTextFor(InputFHManager.Controls.UI.Navigate)));
						Singleton<CardsHandManager>.Instance.Show(playerActor, CardHandMode.ActionSelection, GetCurrentTargetCardPileType(playerActor), CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.FORCE_RESET);
						Singleton<UIUseItemsBar>.Instance.ShowUsableItems(playerActor, (CItem item) => GameState.CurrentSelectAndPlayCardAbility.GetAbilityBaseCard() != item && (!playerActor.IsTakingExtraTurn || item.SlotState != CItem.EItemSlotState.Locked || !Singleton<AbilityEffectManager>.Instance.IsItemAffectingActor(playerActor, item)));
						m_InitialActionAbilityCard = null;
						GUIInterface.s_GUIInterface.SetStatusText("Select out of phase action to use");
						if (FFSNetwork.IsOnline)
						{
							ActionPhaseType phaseType = FullAbilityCard.ActionSequenceTypeToActionPhaseType(GameState.GetCurrentActionSequenceType(playerActor.SelectedRoundCardsCount));
							if (!playerActor.IsUnderMyControl())
							{
								ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, phaseType);
							}
							else
							{
								ActionProcessor.SetState(ActionProcessorStateType.Halted, phaseType);
							}
						}
					}
					else if (GameState.GetCurrentActionSequenceType(selectedRoundCardsCount) == GameState.EActionSequenceType.FirstAction)
					{
						InitiativeTrack.Instance.helpBox.ShowControllerOrKeyboardTip(LocalizationManager.GetTranslation("GUI_TOOLTIP_ABILITY_CHOOSING_1"), () => string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_GAMEPAD_FOCUS_ABILITY_CARDS"), Singleton<InputFHManager>.Instance.InputContext.GetDisplayTextFor(InputFHManager.Controls.UI.Navigate)), playerActor.IsTakingExtraTurn ? Singleton<AbilityEffectManager>.Instance.ExtraTurnAbilityEffectTitle(playerActor) : LocalizationManager.GetTranslation("GUI_TOOLTIP_TITLE_ABILITY_CHOOSING"));
						Singleton<CardsHandManager>.Instance.Show(playerActor, CardHandMode.ActionSelection, GetCurrentTargetCardPileType(playerActor), CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.FORCE_RESET);
						Singleton<UIUseItemsBar>.Instance.ShowUsableItems(playerActor, (CItem item) => !playerActor.IsTakingExtraTurn || item.SlotState != CItem.EItemSlotState.Locked || !Singleton<AbilityEffectManager>.Instance.IsItemAffectingActor(playerActor, item));
						m_InitialActionAbilityCard = null;
						GUIInterface.s_GUIInterface.SetStatusText("Select Ability Card and first action to use");
						if (FFSNetwork.IsOnline)
						{
							if (!playerActor.IsUnderMyControl())
							{
								ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.FirstAction);
							}
							else
							{
								ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.FirstAction);
							}
						}
					}
					else if (GameState.GetCurrentActionSequenceType(selectedRoundCardsCount) == GameState.EActionSequenceType.SecondAction)
					{
						InitiativeTrack.Instance.helpBox.ShowControllerOrKeyboardTip(LocalizationManager.GetTranslation("GUI_TOOLTIP_ABILITY_CHOOSING_2"), () => string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_GAMEPAD_FOCUS_ABILITY_CARDS"), Singleton<InputFHManager>.Instance.InputContext.GetDisplayTextFor(InputFHManager.Controls.UI.Navigate)), playerActor.IsTakingExtraTurn ? Singleton<AbilityEffectManager>.Instance.ExtraTurnAbilityEffectTitle(playerActor) : LocalizationManager.GetTranslation("GUI_TOOLTIP_TITLE_ABILITY_CHOOSING"));
						Singleton<CardsHandManager>.Instance.Show(playerActor, CardHandMode.ActionSelection, GetCurrentTargetCardPileType(playerActor), CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.NONE);
						Singleton<UIUseItemsBar>.Instance.ShowUsableItems(playerActor, (CItem item) => !playerActor.IsTakingExtraTurn || item.SlotState != CItem.EItemSlotState.Locked || !Singleton<AbilityEffectManager>.Instance.IsItemAffectingActor(playerActor, item));
						GUIInterface.s_GUIInterface.SetStatusText("Select second action to use");
						if (FFSNetwork.IsOnline)
						{
							if (!playerActor.IsUnderMyControl())
							{
								ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.SecondAction);
							}
							else
							{
								ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.SecondAction);
							}
						}
					}
					else if (GameState.GetCurrentActionSequenceType(selectedRoundCardsCount) == GameState.EActionSequenceType.ThirdAction)
					{
						InitiativeTrack.Instance.helpBox.ShowControllerOrKeyboardTip(LocalizationManager.GetTranslation("FH/GUI_TOOLTIP_ABILITY_CHOOSING_3"), () => string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_GAMEPAD_FOCUS_ABILITY_CARDS"), Singleton<InputFHManager>.Instance.InputContext.GetDisplayTextFor(InputFHManager.Controls.UI.Navigate)), playerActor.IsTakingExtraTurn ? Singleton<AbilityEffectManager>.Instance.ExtraTurnAbilityEffectTitle(playerActor) : LocalizationManager.GetTranslation("GUI_TOOLTIP_TITLE_ABILITY_CHOOSING"));
						Singleton<CardsHandManager>.Instance.Show(playerActor, CardHandMode.ActionSelection, GetCurrentTargetCardPileType(playerActor), CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.NONE);
						Singleton<UIUseItemsBar>.Instance.ShowUsableItems(playerActor, (CItem item) => !playerActor.IsTakingExtraTurn || item.SlotState != CItem.EItemSlotState.Locked || !Singleton<AbilityEffectManager>.Instance.IsItemAffectingActor(playerActor, item));
						GUIInterface.s_GUIInterface.SetStatusText("Select third action to use");
						if (FFSNetwork.IsOnline)
						{
							if (!playerActor.IsUnderMyControl())
							{
								ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ThirdAction);
							}
							else
							{
								ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ThirdAction);
							}
						}
					}
					else
					{
						InitiativeTrack.Instance.helpBox.Hide();
						InitiativeTrack.Instance.helpBox.ClearOverrideController();
						CardsActionControlller s_Instance = CardsActionControlller.s_Instance;
						CardsHandUI.CardActionsCommand resetCardActions = (((object)s_Instance == null || !s_Instance.HasPlayedCards()) ? CardsHandUI.CardActionsCommand.RESET : CardsHandUI.CardActionsCommand.NONE);
						CardPileType filterType = ((!playerActor.IsTakingExtraTurn) ? CardPileType.Round : CardPileType.ExtraTurn);
						Singleton<CardsHandManager>.Instance.Show(playerActor, CardHandMode.ActionSelection, filterType, CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, resetCardActions);
						Singleton<CardsHandManager>.Instance.UpdateOriginalExtraTurnCards(playerActor);
						EnableEndTurnButton(playerActor);
						Singleton<UIUseItemsBar>.Instance.ShowUsableItems(playerActor, (CItem item) => item.YMLData.Data.CompareAbility == null || item.YMLData.Data.CompareAbility.CompareActor(playerActor));
						if (FFSNetwork.IsOnline)
						{
							if (!playerActor.IsUnderMyControl())
							{
								ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.EndOfTurn);
							}
							else
							{
								ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.EndOfTurn);
							}
						}
					}
				}
				else
				{
					if (playerActor.CharacterClass.HasLongRested)
					{
						Singleton<CardsHandManager>.Instance.Hide(playerActor);
					}
					Singleton<UIUseItemsBar>.Instance.ShowUsableItems(playerActor, (CItem item) => item.YMLData.Data.CompareAbility == null || item.YMLData.Data.CompareAbility.CompareActor(playerActor));
					EnableEndTurnButton(playerActor);
					Singleton<UIUseItemsBar>.Instance.ShowUsableItems(playerActor);
					if (FFSNetwork.IsOnline)
					{
						if (!playerActor.IsUnderMyControl())
						{
							ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.EndOfTurn);
						}
						else
						{
							ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.EndOfTurn);
						}
					}
				}
			}
		}
		CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
		DesyncDetector.CheckForDesync();
	}

