	public void StartLongRest(CPlayerActor playerActor)
	{
		if (GameState.HasPendingRestAbilities || playerActor.CharacterClass.HasQueuedPreRestBonuses)
		{
			ContinueLongRest(playerActor);
			return;
		}
		GameState.QueuePreRestBonuses(playerActor);
		if (GameState.HasPendingRestAbilities)
		{
			Singleton<CardsHandManager>.Instance.Hide();
			Singleton<HelpBox>.Instance.Hide();
			foreach (CItem allItemsAndPet in playerActor.Inventory.AllItemsAndPets)
			{
				if (allItemsAndPet.SlotState == CItem.EItemSlotState.Useable)
				{
					allItemsAndPet.SlotState = CItem.EItemSlotState.Equipped;
				}
			}
			ScenarioRuleClient.PreLongRest(playerActor);
		}
		else
		{
			ContinueLongRest(playerActor);
		}
	}

	public bool ContinueLongRest(CPlayerActor playerActor)
	{
		if (!playerActor.CharacterClass.HasStartedLongRest)
		{
			playerActor.CharacterClass.HasStartedLongRest = true;
			playerActor.LogActiveBonuses(atStartOfRest: true);
		}
		if (playerActor.CharacterClass.ID == "PyroclastID" && playerActor.CharacterClass.ActivatedAbilityCards.Any((CAbilityCard card) => card.HasMandatoryBonus()))
		{
			PerformPyroclastLongRest(playerActor);
			return false;
		}
		if (playerActor.CharacterClass.ID == "CrashingTideID" && !playerActor.DontCancelTidesOnRest && playerActor.ActiveBonuses.Any((CActiveBonus ab) => ab.Ability.ActiveBonusData.Flags.HasFlag(AbilityData.EActiveBonusFlag.CrashingTideRest)) && CustomAbility.GetCancellableTideActiveBonuses(playerActor).Count > 0)
		{
			PerformCrashingTideLongRest(playerActor);
			return false;
		}
		PerformNormalLongRest(playerActor);
		return true;
	}

	public void PerformPyroclastLongRest(CPlayerActor actor)
	{
		Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("FH/GUI_TOOLTIP_CHOOSE_PYROCLAST_ACTIVE_BONUS_TO_DEACTIVATE"));
		if (FFSNetwork.IsOnline)
		{
			Singleton<UIReadyToggle>.Instance?.ToggleVisibility(visible: false);
		}
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONLONGREST, LocalizationManager.GetTranslation("GUI_CONTINUE"), hideOnClick: true, glowingEffect: false, actor.IsUnderMyControl(), disregardTurnControlForInteractability: true, haltActionProcessorIfDeactivated: false);
		readyButton.QueueAlternativeAction(() =>
		{
			Singleton<HelpBox>.Instance.Hide();
			CardsHandManager.ShowCardsSelection(actor);
			PerformNormalLongRest(actor);
		});
		actor.CharacterClass.ActivatedAbilityCards.Where((CAbilityCard card) => card.HasMandatoryBonus());
		CardHandMode mode = CardHandMode.SelectCardsWithMandatoryActiveBonusesToDeactivate;
		CardPileType filterType = CardPileType.Active;
		List<CardPileType> selectableCardTypes = new List<CardPileType> { CardPileType.Active };
		int maxCardsSelected = 1;
		bool fadeUnselectableCards = true;
		bool highlightSelectableCards = true;
		if (!actor.IsUnderMyControl() || PhaseManager.PhaseType == CPhase.PhaseType.SelectAbilityCardsOrLongRest)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.LongRest, savePreviousState: true);
		}
		else
		{
			ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.LongRest, savePreviousState: true);
		}
		Singleton<CardsHandManager>.Instance.Show(actor, mode, filterType, selectableCardTypes, maxCardsSelected, fadeUnselectableCards, highlightSelectableCards, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: false, allowFullDeckPreview: true, null, (CAbilityCard card) => card.HasMandatoryBonus(), (CAbilityCard card) => card.HasMandatoryBonus());
	}

	private void PerformCrashingTideLongRest(CPlayerActor actor)
	{
		Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("FH/GUI_TOOLTIP_CHOOSE_TIDE_ACTIVE_BONUS_TO_KEEP"));
		if (FFSNetwork.IsOnline)
		{
			Singleton<UIReadyToggle>.Instance?.ToggleVisibility(visible: false);
		}
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONLONGREST, LocalizationManager.GetTranslation("GUI_PERFORM_LONG_REST"));
		readyButton.QueueAlternativeAction(() =>
		{
			InitiativeTrack.Instance.helpBox.Hide();
			PerformNormalLongRest(actor);
		});
		List<CActiveBonus> tideActiveBonuses = CustomAbility.GetCancellableTideActiveBonuses(actor);
		CardHandMode mode = CardHandMode.SelectCardsWithTideActiveBonusesToKeep;
		CardPileType filterType = CardPileType.Active;
		List<CardPileType> selectableCardTypes = new List<CardPileType> { CardPileType.Active };
		int maxCardsSelected = 1;
		bool fadeUnselectableCards = true;
		bool highlightSelectableCards = true;
		if (!actor.IsUnderMyControl() || PhaseManager.PhaseType == CPhase.PhaseType.SelectAbilityCardsOrLongRest)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.LongRest, savePreviousState: true);
		}
		else
		{
			ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.LongRest, savePreviousState: true);
		}
		Singleton<CardsHandManager>.Instance.Show(actor, mode, filterType, selectableCardTypes, maxCardsSelected, fadeUnselectableCards, highlightSelectableCards, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: false, allowFullDeckPreview: true, null, (CAbilityCard card) => tideActiveBonuses.Any((CActiveBonus ab) => ab.BaseCard == card), (CAbilityCard card) => tideActiveBonuses.Any((CActiveBonus ab) => ab.BaseCard == card));
	}

	public void PerformNormalLongRest(CPlayerActor actor, IList<int> tideActiveBonusCardsToKeep = null, bool cancelTideActiveBonuses = true)
	{
		CoroutineHelper.RunCoroutine(PerformNormalLongRestCoroutine(actor, tideActiveBonusCardsToKeep, cancelTideActiveBonuses));
	}

	public IEnumerator PerformNormalLongRestCoroutine(CPlayerActor actor, IList<int> tideActiveBonusCardsToKeep = null, bool cancelTideActiveBonuses = true)
	{
		InitiativeTrack.Instance.helpBox.OverrideControllerOrKeyboardTip(() => string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_GAMEPAD_FOCUS_ABILITY_CARDS"), Singleton<InputFHManager>.Instance.InputContext.GetDisplayTextFor(InputFHManager.Controls.UI.Navigate)), LocalizationManager.GetTranslation("GUI_LONG_REST"));
		Singleton<UIUseItemsBar>.Instance.ShowUsableItems(actor);
		if (cancelTideActiveBonuses && !actor.DontCancelTidesOnRest)
		{
			Singleton<CardsHandManager>.Instance.CancelTideActiveBonuses(actor, tideActiveBonusCardsToKeep);
			while ((ScenarioRuleClient.IsProcessingOrMessagesQueued && !ScenarioRuleClient.IsMessageProcessingBlocked) || (s_Choreographer.m_MessageQueue.Count > 0 && !s_Choreographer.BlockClientMessageProcessing))
			{
				yield return new WaitForEndOfFrame();
			}
		}
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = actor.IsUnderMyControl();
		Singleton<CardsHandManager>.Instance.ShowLongRestConfirmation(actor, (bool confirmed) =>
		{
			if (!confirmed)
			{
				PerformNormalLongRest(actor, tideActiveBonusCardsToKeep, cancelTideActiveBonuses);
			}
			else
			{
				Singleton<UIUseItemsBar>.Instance.Hide();
				Singleton<UIActiveBonusBar>.Instance.Hide();
				Singleton<UIUseAbilitiesBar>.Instance.Hide();
				Singleton<UIUseAugmentationsBar>.Instance.Hide();
				Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
				readyButton.Toggle(confirmed, ReadyButton.EButtonState.EREADYBUTTONNA, null, hideOnClick: true, glowingEffect: false, interactable: true, disregardTurnControlForInteractability: false, haltActionProcessorIfDeactivated: false);
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.LongResting;
			}
		});
		readyButton.ClearAlternativeAction();
		readyButton.Toggle(active: false, ReadyButton.EButtonState.EREADYBUTTONCONTINUE, LocalizationManager.GetTranslation("GUI_PERFORM_LONG_REST"));
		readyButton.QueueAlternativeAction(() =>
		{
			bool flag = actor.CharacterClass.DiscardedAbilityCards.Count == 0;
			if (!flag && AdventureState.MapState != null)
			{
				flag = ScenarioManager.CurrentScenarioState.FreeLongRest;
			}
			if (flag)
			{
				ScenarioRuleClient.HandleLongRest(null, null, fromStateUpdate: false, FastReload.CurrentHistoryID);
			}
			else
			{
				InitiativeTrack.Instance.helpBox.Show("GUI_TOOLTIP_LONG_REST", "GUI_LONG_REST");
				Singleton<UIUseItemsBar>.Instance.Hide();
				int num = 2;
				foreach (CActiveBonus item in CActiveBonus.FindApplicableActiveBonuses(actor, CAbility.EAbilityType.AddHeal, CActiveBonus.EActiveBonusBehaviourType.BuffHealPerActor))
				{
					num += item.Ability.Strength;
				}
				ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientPlayer(actor)).m_WorldspacePanelUI?.OnSelectingHealFocus(num);
				Singleton<CardsHandManager>.Instance.Show(actor, CardHandMode.LoseCard, CardPileType.Any, CardPileType.Discarded, 1, fadeUnselectableCards: true, highlightSelectableCards: true);
			}
			if (FFSNetwork.IsOnline)
			{
				if (!actor.IsUnderMyControl())
				{
					ActionProcessor.SetState(ActionProcessorStateType.ProcessOneAndHalt, ActionPhaseType.LongRest);
				}
				else
				{
					ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.LongRest);
				}
			}
		});
		if (FFSNetwork.IsOnline)
		{
			if (!actor.IsUnderMyControl())
			{
				Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.LongRest);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.LongRest);
			}
		}
	}

	public void ProxyContinueCrashingTideLongRest(GameAction action)
	{
		CPlayerActor cPlayerActor = (CPlayerActor)(((CharacterManager)(ControllableRegistry.GetControllable(action.ActorID)?.ControllableObject))?.CharacterActor);
		CardsToken cardsToken = (CardsToken)action.SupplementaryDataToken;
		if (GameState.s_ShortRestingPlayer == null)
		{
			PerformNormalLongRest(cPlayerActor, cardsToken?.CardIDs);
			return;
		}
		readyButton.ClearAlternativeAction();
		Singleton<CardsHandManager>.InstanceFast.GetHand(cPlayerActor).PerformShortRest(cPlayerActor, allowSpecificShortRest: false, cardsToken?.CardIDs);
	}

	[MessageHandler(CMessageData.MessageType.PlayerLongRested)]
	private void Handle_PlayerLongRested(CMessageData message)
	{
		CPlayerLongRested_MessageData messageData = (CPlayerLongRested_MessageData)message;
		if (FFSNetwork.IsOnline && messageData.m_SyncMultiplayer)
		{
			Singleton<CardsHandManager>.Instance.DisableHands();
			ProcessMessage(new CWaitForMultiplayerSyncPoint_MessageData
			{
				m_OnFinish = () =>
				{
					messageData.m_SyncMultiplayer = false;
					ProcessMessage(messageData);
				}
			});
			return;
		}
		FindClientActorGameObject(message.m_ActorSpawningMessage);
		CPlayerActor cPlayerActor = (CPlayerActor)message.m_ActorSpawningMessage;
		CardsHandUI hand = Singleton<CardsHandManager>.Instance.GetHand(cPlayerActor);
		hand.SetInteractable(interactable: false, allowHover: true);
		hand.SetAllCardsSelectable(selectable: false);
		if (!messageData.m_AfterLongRestFinishedHealing)
		{
			string arg = LocalizationManager.GetTranslation(messageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(messageData.m_ActorSpawningMessage);
			if (messageData.m_AbilityCard != null)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_LONG_REST"), arg, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(messageData.m_AbilityCard.Name)}</color></b></font>"));
			}
			else
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_LONG_REST_NO_CARD"), arg));
			}
			if (GameState.PendingOnLongRestBonuses.Count > 0 || GameState.PendingOnRestAbilities.Count > 0)
			{
				TriggerAnyOnLongRestAddActiveBonuses(cPlayerActor);
			}
			return;
		}
		IsFirstTurnPlaying = false;
		EnableEndTurnButton(cPlayerActor);
		Singleton<CardsHandManager>.Instance.ShowLongRested(cPlayerActor);
		Singleton<UIUseItemsBar>.Instance.ShowUsableItems(cPlayerActor);
		Singleton<UIActiveBonusBar>.Instance.ShowActiveBonus(cPlayerActor, CAbility.EAbilityType.None, CActiveBonus.EActiveBonusBehaviourType.DuringTurnAbility);
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = !FFSNetwork.IsOnline || cPlayerActor.IsUnderMyControl();
		if (FFSNetwork.IsOnline)
		{
			if (!message.m_ActorSpawningMessage.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.EndOfTurn);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.EndOfTurn);
			}
		}
		DesyncDetector.CheckForDesync();
	}

	[MessageHandler(CMessageData.MessageType.PlayerImprovedShortRested)]
	private void Handle_PlayerImprovedShortRested(CMessageData message)
	{
		CPlayerImprovedShortRested_MessageData messageData = (CPlayerImprovedShortRested_MessageData)message;
		if (FFSNetwork.IsOnline && messageData.m_SyncMultiplayer)
		{
			Singleton<CardsHandManager>.Instance.DisableHands();
			ProcessMessage(new CWaitForMultiplayerSyncPoint_MessageData
			{
				m_OnFinish = () =>
				{
					messageData.m_SyncMultiplayer = false;
					ProcessMessage(messageData);
				}
			});
			return;
		}
		ActorBehaviour.UpdateHealth(FindClientPlayer((CPlayerActor)message.m_ActorSpawningMessage), messageData.m_ActorOriginalHealth, updateUI: true);
		ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(message.m_ActorSpawningMessage)).m_WorldspacePanelUI?.RemoveEffect("ImprovedShortRest");
		InitiativeTrack.Refresh(messageData.m_ActorSpawningMessage, isActiveButton: true);
		string arg = LocalizationManager.GetTranslation(messageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(messageData.m_ActorSpawningMessage);
		Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_SHORT_REST"), arg, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(messageData.m_AbilityCard.Name)}</color></b></font>"));
		CPlayerActor playerActor = messageData.m_ActorSpawningMessage as CPlayerActor;
		if (GameState.PendingOnShortRestBonuses.Count > 0 || GameState.PendingOnRestAbilities.Count > 0)
		{
			TriggerAnyOnShortRestAddActiveBonuses(playerActor);
		}
		else if (ShortRest.Instant && PhaseManager.CurrentPhaseAction?.CurrentPhaseAbility == null && !GameState.HasPendingRestAbilities)
		{
			GameState.s_ShortRestingPlayer = null;
			GameState.OverrideCurrentActor(null);
			PhaseManager.SetNextPhase(CPhase.PhaseType.SelectAbilityCardsOrLongRest);
		}
		else
		{
			CardsHandManager.ShowCardsSelection(playerActor);
			m_PlayerToSelectAbilityCardsOrLongRest = false;
			(PhaseManager.CurrentPhase as CPhaseShortRest)?.NextStep();
		}
		DesyncDetector.CheckForDesync();
	}

	public static string StartTurnHelpBoxKey()
	{
		if (ScenarioManager.CurrentScenarioState?.ScenarioModifiers != null && ScenarioManager.CurrentScenarioState.ScenarioModifiers.Any((CScenarioModifier x) => x.IsActiveInRound(ScenarioManager.CurrentScenarioState.RoundNumber) && x.ScenarioModifierType == EScenarioModifierType.DisableRest))
		{
			return "FH/GUI_TOOLTIP_START_TURN_REST_DISABLED";
		}
		if (WorldspaceStarHexDisplay.Instance != null && WorldspaceStarHexDisplay.Instance.CurrentDisplayState == WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.CharacterPlacement)
		{
			return "GUI_TOOLTIP_FIRST_TURN";
		}
		string result = "GUI_TOOLTIP_START_TURN";
		if (!string.IsNullOrEmpty(ScenarioScript.current?.StartTurnHelpTextOverride))
		{
			return ScenarioScript.current.StartTurnHelpTextOverride;
		}
		return result;
	}

	[MessageHandler(CMessageData.MessageType.PlayerShortRested)]
	private void Handle_PlayerShortRested(CMessageData message)
	{
		CPlayerShortRested_MessageData messageData = (CPlayerShortRested_MessageData)message;
		if (FFSNetwork.IsOnline && messageData.m_SyncMultiplayer)
		{
			Singleton<CardsHandManager>.Instance.DisableHands();
			ProcessMessage(new CWaitForMultiplayerSyncPoint_MessageData
			{
				m_OnFinish = () =>
				{
					messageData.m_SyncMultiplayer = false;
					ProcessMessage(messageData);
				}
			});
			return;
		}
		CardsHandUI hand = Singleton<CardsHandManager>.Instance.GetHand(messageData.m_Player);
		messageData.m_Player.Agility = CPlayerActor.EAgility.None;
		hand.UpdateCharacterSpecificMechanic();
		if (PhaseManager.CurrentPhaseAction?.CurrentPhaseAbility == null && !GameState.HasPendingRestAbilities && !ShortRest.Instant)
		{
			CardsHandManager.ShowCardsSelection(messageData.m_Player);
			m_PlayerToSelectAbilityCardsOrLongRest = false;
		}
		ActorBehaviour.UpdateHealth(FindClientPlayer(messageData.m_Player));
		InitiativeTrack.Refresh(messageData.m_Player, isActiveButton: true);
		if (messageData.m_AbilityCard == null)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_SHORT_REST_FREE"), LocalizationManager.GetTranslation(messageData.m_Player.ActorLocKey())));
		}
		else
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_SHORT_REST"), LocalizationManager.GetTranslation(messageData.m_Player.ActorLocKey()), $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(messageData.m_AbilityCard.Name)}</color></b></font>"));
		}
		if (GameState.PendingOnShortRestBonuses.Count > 0 || GameState.PendingOnRestAbilities.Count > 0)
		{
			TriggerAnyOnShortRestAddActiveBonuses(messageData.m_Player);
		}
		else if (PhaseManager.CurrentPhaseAction?.CurrentPhaseAbility == null && !GameState.HasPendingRestAbilities)
		{
			if (ShortRest.Instant)
			{
				GameState.s_ShortRestingPlayer = null;
				GameState.OverrideCurrentActor(null);
				PhaseManager.SetNextPhase(CPhase.PhaseType.SelectAbilityCardsOrLongRest);
			}
			else
			{
				(PhaseManager.CurrentPhase as CPhaseShortRest)?.NextStep();
			}
		}
		DesyncDetector.CheckForDesync();
	}

