	[MessageHandler(CMessageData.MessageType.StartAbility)]
	private void Handle_StartAbility(CMessageData message)
	{
		CStartActorAbility_MessageData cStartActorAbility_MessageData = (CStartActorAbility_MessageData)message;
		SetChoreographerState(ChoreographerStateType.Play, 0, null);
		m_CurrentActor = cStartActorAbility_MessageData.m_ActorSpawningMessage;
		if (!cStartActorAbility_MessageData.merged)
		{
			Waypoint.s_LockWaypoints = false;
			WorldspaceStarHexDisplay.Instance.LockView = false;
			ClearStars();
			TryForceShowTilePreview(cStartActorAbility_MessageData.m_Ability);
		}
		Singleton<UIUseAbilitiesBar>.Instance.Hide();
		Singleton<UIUseItemsBar>.Instance.ShowCurrentlyPlayingItems(message.m_ActorSpawningMessage);
		bool flag = cStartActorAbility_MessageData.m_Ability != null && cStartActorAbility_MessageData.m_Ability.AbilityHasBeenCancelledImmediately;
		readyButton.ClearAlternativeAction();
		UndoButton undoButton = m_UndoButton;
		int active;
		if (!flag && message.m_ActorSpawningMessage.Type == CActor.EType.Player && cStartActorAbility_MessageData.m_Ability.CanUndo)
		{
			CAbility ability = cStartActorAbility_MessageData.m_Ability;
			if (ability != null)
			{
				AbilityData.MiscAbilityData miscAbilityData = ability.MiscAbilityData;
				if (miscAbilityData != null && miscAbilityData.AutotriggerAbility.HasValue)
				{
					active = ((!cStartActorAbility_MessageData.m_Ability.MiscAbilityData.AutotriggerAbility.Value) ? 1 : 0);
					goto IL_00f7;
				}
			}
			active = 1;
		}
		else
		{
			active = 0;
		}
		goto IL_00f7;
		IL_00f7:
		undoButton.Toggle((byte)active != 0, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
		m_UndoButton.SetInteractable(cStartActorAbility_MessageData.m_Ability.CanUndo && (cStartActorAbility_MessageData.m_IsFirstAbility || cStartActorAbility_MessageData.m_Ability.AllowUndoAfterFirst));
		SkipButton skipButton = m_SkipButton;
		int active2;
		if (!flag && message.m_ActorSpawningMessage.Type == CActor.EType.Player && cStartActorAbility_MessageData.m_Ability.CanSkip)
		{
			CAbility ability2 = cStartActorAbility_MessageData.m_Ability;
			if (ability2 != null)
			{
				AbilityData.MiscAbilityData miscAbilityData2 = ability2.MiscAbilityData;
				if (miscAbilityData2 != null && miscAbilityData2.AutotriggerAbility.HasValue)
				{
					active2 = ((!cStartActorAbility_MessageData.m_Ability.MiscAbilityData.AutotriggerAbility.Value) ? 1 : 0);
					goto IL_01aa;
				}
			}
			active2 = 1;
		}
		else
		{
			active2 = 0;
		}
		goto IL_01aa;
		IL_01aa:
		skipButton.Toggle((byte)active2 != 0, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, cStartActorAbility_MessageData.m_Ability.CanSkip);
		FirstAbility = cStartActorAbility_MessageData.m_IsFirstAbility;
		m_CurrentAbility = cStartActorAbility_MessageData.m_Ability;
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		if (m_CurrentActor is CPlayerActor cPlayerActor && (PhaseManager.PreviousPhase == null || PhaseManager.PreviousPhase.Type == CPhase.PhaseType.ActionSelection || PhaseManager.PreviousPhase.Type == CPhase.PhaseType.InfuserMechanicSelection || PhaseManager.PreviousPhase.Type == CPhase.PhaseType.Action))
		{
			if (Singleton<CardsHandManager>.Instance.CurrentHand?.PlayerActor != cPlayerActor || !Singleton<CardsHandManager>.Instance.IsShown || cStartActorAbility_MessageData.m_FromUnstack || Singleton<CardsHandManager>.Instance.CurrentHand.currentMode != CardHandMode.ActionSelection)
			{
				Singleton<CardsHandManager>.Instance.Show(cPlayerActor, CardHandMode.ActionSelection, GetCurrentTargetCardPileType(cPlayerActor), CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, GameState.IsPerformingCardOutOfPhase ? CardsHandUI.CardActionsCommand.FORCE_RESET : CardsHandUI.CardActionsCommand.NONE);
			}
			CardsActionControlller.s_Instance.RefreshConsumeBar(cPlayerActor, m_CurrentAbility);
		}
		Singleton<CardsHandManager>.Instance.OnAbilityStart(m_CurrentActor, m_CurrentAbility);
		if ((message.m_ActorSpawningMessage is CPlayerActor && cStartActorAbility_MessageData.m_Ability.CanApplyActiveBonusTogglesTo() && !cStartActorAbility_MessageData.m_Ability.AutoTrigger) || (ScenarioScript.current != null && ScenarioScript.current.CanToggleBonusesForNonPlayerAbilityStart(m_CurrentAbility)))
		{
			List<CActiveBonus.EActiveBonusBehaviourType> ignoreBehaviours = ((cStartActorAbility_MessageData.m_Ability is CAbilityControlActor) ? new List<CActiveBonus.EActiveBonusBehaviourType> { CActiveBonus.EActiveBonusBehaviourType.BetweenActionAbilities } : null);
			Singleton<UIActiveBonusBar>.Instance.ShowActiveBonus(cStartActorAbility_MessageData.m_ActorSpawningMessage, cStartActorAbility_MessageData.m_Ability.AbilityType, CActiveBonus.EActiveBonusBehaviourType.None, null, cStartActorAbility_MessageData.m_Ability.AbilityHasHappened, cStartActorAbility_MessageData.m_Ability, ignoreBehaviours);
		}
		DisableTileSelection(active: false);
	}

	[MessageHandler(CMessageData.MessageType.StartSecondMergedAbility)]
