	[MessageHandler(CMessageData.MessageType.ActorIsSelectingMoveTile)]
	private void Handle_ActorIsSelectingMoveTile(CMessageData message)
	{
		if (m_PlayerSelectingToAvoidDamageOrNot)
		{
			m_AfterTakeDamageProgressMessages.Add(message);
			return;
		}
		CActorIsSelectingMoveTile_MessageData messageData = (CActorIsSelectingMoveTile_MessageData)message;
		if (messageData.m_MoveAbility != null && messageData.m_MoveAbility.AbilityHasBeenCancelled)
		{
			return;
		}
		Waypoint.s_MovingActor = messageData.m_MoveAbility.CurrentMovingActor;
		s_Choreographer.m_CurrentActor = messageData.m_MoveAbility.CurrentMovingActor;
		s_Choreographer.m_CurrentAbility = messageData.m_MoveAbility;
		bool flag = false;
		GameObject gameObject = null;
		if (!messageData.m_MoveAbility.HasMoved)
		{
			WorldspaceStarHexDisplay.Instance.ResetLineDirection();
			Waypoint.RefreshWaypointMovesRemaining(messageData.m_MoveAbility);
			if (Waypoint.s_Waypoints.Count > 0)
			{
				int num = Waypoint.s_Waypoints.Sum((GameObject s) => s.GetComponent<Waypoint>().MoveCost);
				while (num > messageData.m_MoveAbility.MoveCountAfterLimit)
				{
					num -= Waypoint.GetLastWaypoint.MoveCost;
					Waypoint.GetLastWaypoint.OnDelete();
				}
			}
			CardsActionControlller.s_Instance.RefreshConsumeBar(message.m_ActorSpawningMessage, messageData.m_MoveAbility);
		}
		else
		{
			gameObject = Waypoint.GetNextWaypoint();
		}
		if (message.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			if (message.m_ActorSpawningMessage.OriginalType == CActor.EType.Player)
			{
				CPlayerActor cPlayerActor = message.m_ActorSpawningMessage as CPlayerActor;
				if (Singleton<CardsHandManager>.Instance.IsShown && !Singleton<CardsHandManager>.Instance.IsShowingPlayerHand(cPlayerActor) && messageData.m_MoveAbility.GetAbilityBaseCard() != null && messageData.m_MoveAbility.GetAbilityBaseCard().CardType != CBaseCard.ECardType.Dummy)
				{
					Singleton<CardsHandManager>.Instance.Show(cPlayerActor, CardHandMode.ActionSelection, (!cPlayerActor.IsTakingExtraTurn) ? CardPileType.Round : CardPileType.ExtraTurn, CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.NONE);
				}
			}
			foreach (GameObject clientActorObject in ClientActorObjects)
			{
				if (clientActorObject != null)
				{
					ActorBehaviour.GetActorBehaviour(clientActorObject).m_WorldspacePanelUI?.ResetPreview();
				}
			}
			if (!m_FollowCameraDisabled)
			{
				CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
			}
			if (message.m_ActorSpawningMessage.Type == CActor.EType.Player && gameObject == null)
			{
				Singleton<UIUseItemsBar>.Instance.ShowUsableItems(message.m_ActorSpawningMessage, (CItem item) => item.YMLData.Data.CompareAbility != null && item.YMLData.Data.CompareAbility.CompareAbility(messageData.m_MoveAbility), "GUI_USE_ITEM_MOVEMENT_TIP");
				Singleton<UIActiveBonusBar>.Instance.ShowActiveBonus(messageData.m_ActorSpawningMessage, CAbility.EAbilityType.Move, CActiveBonus.EActiveBonusBehaviourType.None, null, messageData.m_MoveAbility.HasMoved, messageData.m_MoveAbility);
			}
			if (gameObject != null)
			{
				Waypoint waypointComponent = Waypoint.GetWaypointComponent(gameObject);
				bool tileSelectionDisabled = m_TileSelectionDisabled;
				DisableTileSelection(active: false);
				s_Choreographer.TileHandler(waypointComponent.ClientTile, Waypoint.GetCTileList());
				DisableTileSelection(tileSelectionDisabled);
				Waypoint.DestroyWaypoint(gameObject);
				GUIInterface.s_GUIInterface.SetStatusText("Next stage of path" + message.m_ActorSpawningMessage.ID + " Waypoint Order " + waypointComponent.Order);
			}
			else
			{
				flag = true;
				WorldspaceStarHexDisplay.Instance.LockView = false;
				TileBehaviour.SetCallback(Waypoint.TileHandler);
				SetChoreographerState(ChoreographerStateType.WaitingForPlayerWaypointSelection, 0, null);
				WorldspaceStarHexDisplay.Instance.CurrentMoveDisplayType = WorldspaceStarHexDisplay.EMoveDisplayType.Normal;
				if (WorldspaceStarHexDisplay.Instance.CurrentDisplayState.Equals(WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.MovementSelection))
				{
					WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
				}
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.MovementSelection;
				DisableTileSelection(active: false);
				GUIInterface.s_GUIInterface.SetStatusText("Select way points for player path" + message.m_ActorSpawningMessage.ID + " . Number moves " + messageData.m_MoveAbility.RemainingMovesAfterLimit);
			}
			foreach (CActiveBonus showingActiveBonuse in Singleton<UIActiveBonusBar>.Instance.ShowingActiveBonuses)
			{
				ShowAbilityHelpBoxTooltip(showingActiveBonuse.Ability);
			}
		}
		else
		{
			GUIInterface.s_GUIInterface.SetStatusText("Monster " + LocalizationManager.GetTranslation(message.m_ActorSpawningMessage.ActorLocKey()) + "(" + message.m_ActorSpawningMessage.ID + ") moving , moves remaining " + messageData.m_MoveAbility.RemainingMovesAfterLimit);
		}
		if (!m_FollowCameraDisabled)
		{
			GameObject target = FindClientActorGameObject(message.m_ActorSpawningMessage);
			CameraController.s_CameraController.SmartFocus(target, pauseDuringTransition: true);
		}
		if (m_WaitState.m_State != ChoreographerStateType.WaitingForMoveAnim && gameObject == null)
		{
			m_SkipButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player, LocalizationManager.GetTranslation("GUI_SKIP_MOVEMENT"), hideOnClick: true, messageData.m_MoveAbility.CanSkip, () =>
			{
				messageData.m_MoveAbility.OnSkippedByPlayer();
			});
			bool flag2 = true;
			if (messageData.m_MoveAbility.MoveRestrictionType.Equals(CAbilityMove.EMoveRestrictionType.MustEndOnShadow))
			{
				flag2 = Waypoint.GetLastWaypoint?.ClientTile.m_Tile.FindProps(ScenarioManager.ObjectImportType.Shadow) != null;
				if (Waypoint.IsLastWaypointADoor && GameState.GetTilesInRange(range: (messageData.m_MoveAbility.Strength - Waypoint.GetLastWaypoint?.MoveCost).Value, origin: messageData.m_MoveAbility.CurrentMovingActor.ArrayIndex).ToList().Any((CTile tile) => tile.FindProp(ScenarioManager.ObjectImportType.Shadow) != null))
				{
					flag2 = true;
				}
			}
			else if (messageData.m_MoveAbility.MoveRestrictionType.Equals(CAbilityMove.EMoveRestrictionType.MustEndOnSpecificTiles))
			{
				flag2 = messageData.m_MoveAbility.CheckMustEndOnSpecificTiles(Waypoint.GetLastWaypoint?.ClientTile.m_Tile);
				if (messageData.m_MoveAbility.MiscAbilityData != null && messageData.m_MoveAbility.MiscAbilityData.CanSkip.HasValue && !messageData.m_MoveAbility.MiscAbilityData.CanSkip.Value && !messageData.m_MoveAbility.HasMoved && !messageData.m_MoveAbility.CheckMustEndOnSpecificTiles(messageData.m_MoveAbility.CurrentMovingActor.Tile))
				{
					m_SkipButton.SetInteractable(active: false);
				}
			}
			ReadyButton.EButtonState state = ((flag2 && Waypoint.s_Waypoints.Count > 0) ? ReadyButton.EButtonState.EREADYBUTTONCONFIRMMOVEMENT : ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED);
			readyButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player, state, LocalizationManager.GetTranslation("GUI_CONFIRM_MOVEMENT"), hideOnClick: true, glowingEffect: true);
			if (Waypoint.s_Waypoints.Count <= 0)
			{
				m_UndoButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player);
			}
			bool flag3 = message.m_ActorSpawningMessage is CPlayerActor;
			m_UndoButton.SetInteractable(flag3 && messageData.m_MoveAbility.CanUndo && (FirstAbility || messageData.m_MoveAbility.IsItemAbility));
			if ((FFSNetwork.IsOnline && message.m_ActorSpawningMessage.Type == CActor.EType.Player) & flag)
			{
				if (!message.m_ActorSpawningMessage.IsUnderMyControl())
				{
					ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.MoveTileSelection);
				}
				else
				{
					ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.MoveTileSelection);
				}
			}
		}
		Singleton<HelpBox>.Instance.OverrideControllerOrKeyboardTip(() => string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_GAMEPAD_SELECT_MOVE_TILE"), Singleton<InputFHManager>.Instance.InputContext.GetDisplayTextFor(InputFHManager.Controls.ScenarioWorldspace.PickTarget)), LocalizationManager.GetTranslation("Move"));
		ScenarioScriptFrontend.ShowAbilityHelpBoxTooltip(messageData.m_MoveAbility);
	}

	[MessageHandler(CMessageData.MessageType.ActorHasMoved)]
	private void Handle_ActorHasMoved(CMessageData message)
	{
		using (new CActiveBonus.ActiveBonusCalculationScope())
		{
			Log.SimpleInfo("ActorHasMoved starting");
			CActorHasMoved_MessageData cActorHasMoved_MessageData = (CActorHasMoved_MessageData)message;
			Waypoint.s_MovingActor = cActorHasMoved_MessageData.m_MovingActor;
			ClearStars();
			Singleton<UIUseItemsBar>.Instance.Hide(resetSlots: false);
			Singleton<UIActiveBonusBar>.Instance.Hide();
			Singleton<UIUseAugmentationsBar>.Instance.Hide();
			DisableButtons();
			TileBehaviour.SetCallback(TileHandler);
			GameObject gameObject = FindClientActorGameObject(message.m_ActorSpawningMessage);
			if (gameObject != null)
			{
				m_PropFading.FadeAlongActorPath(cActorHasMoved_MessageData.m_Waypoints, gameObject.transform, message.m_ActorSpawningMessage);
				if (!m_FollowCameraDisabled)
				{
					CameraController.s_CameraController.SetFocalPointGameObject(gameObject);
					CameraController.s_CameraController.DisableCameraInput(CameraController.ECameraInput.Move, this);
				}
				Vector3 position = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[message.m_ActorSpawningMessage.ArrayIndex.X, message.m_ActorSpawningMessage.ArrayIndex.Y].m_GameObject.transform.position;
				int num = 0;
				if (MF.GetGameObjectAnimatorController(gameObject) != null && MF.GameObjectAnimatorControllerHasState(gameObject, "Idle-Run"))
				{
					if (!cActorHasMoved_MessageData.m_ForceMoveViaLoco && ((message.m_ActorSpawningMessage.Class is CMonsterClass cMonsterClass && cMonsterClass.CurrentMonsterStat.Move <= 0) || (message.m_ActorSpawningMessage is CHeroSummonActor cHeroSummonActor && cHeroSummonActor.SummonData.Move <= 0)))
					{
						if (MF.GetGameObjectAnimatorController(gameObject) != null)
						{
							num = 10000;
							Log.SimpleInfo("ActorHasMoved waitTickFrame = 10000");
							ActorBehaviour.GetActorBehaviour(gameObject).PushPullToLocation(position);
						}
						else
						{
							num = 400;
							Log.SimpleInfo("ActorHasMoved waitTickFrame = 400");
							gameObject.transform.position = position;
						}
					}
					else
					{
						num = 10000;
						Log.SimpleInfo("ActorHasMoved waitTickFrame = 10000");
						List<CTile> waypoints = cActorHasMoved_MessageData.m_Waypoints;
						if (cActorHasMoved_MessageData.m_MovingActor.Type != CActor.EType.Player && cActorHasMoved_MessageData.m_Ability is CAbilityMove { FixedPath: null } && ((cActorHasMoved_MessageData != null && cActorHasMoved_MessageData.m_MovingActor?.AIMoveFocusPath?.Count == 0) || cActorHasMoved_MessageData?.m_MovingActor?.AIMoveFocusPath == null))
						{
							waypoints = null;
						}
						ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
						actorBehaviour.SetLocoTarget(position, cActorHasMoved_MessageData.m_Jump, waypoints, cActorHasMoved_MessageData.m_ForceMoveViaLoco, cActorHasMoved_MessageData.m_DontTeleport, cActorHasMoved_MessageData.m_Slide, cActorHasMoved_MessageData.m_UseActorRunSpeedAsSlideSpeed ? actorBehaviour.RunSpeed : cActorHasMoved_MessageData.m_SlideSpeed, cActorHasMoved_MessageData.m_ForcedSpeed);
						actorBehaviour.FadeCharacterOnPosition(message.m_ActorSpawningMessage.ArrayIndex);
					}
				}
				else
				{
					num = 400;
					gameObject.transform.position = position;
				}
				if (cActorHasMoved_MessageData.m_ActorsToCarry != null)
				{
					foreach (CActor item in cActorHasMoved_MessageData.m_ActorsToCarry)
					{
						GameObject gameObject2 = FindClientActorGameObject(item);
						if (MF.GetGameObjectAnimatorController(gameObject2) != null)
						{
							num = 10000;
							Log.SimpleInfo("ActorHasMoved waitTickFrame = 10000");
							ActorBehaviour.GetActorBehaviour(gameObject2).PushPullToLocation(position);
						}
					}
				}
				if (cActorHasMoved_MessageData.m_ShouldWait)
				{
					SetChoreographerState(ChoreographerStateType.WaitingForMoveAnim, num, message.m_ActorSpawningMessage);
					Log.SimpleInfo("ActorHasMoved ChoreographerStateType.WaitingForMoveAnim set.");
				}
				if (cActorHasMoved_MessageData.m_Ability != null && cActorHasMoved_MessageData.m_Ability.IsMergedAbility)
				{
					AttackModBar.s_AttackModifierBarFlowCanBegin = true;
				}
			}
			else
			{
				Log.SimpleInfo("ActorHasMoved currentActorGameObject is Null! Movement not performed.");
			}
		}
	}

