	[Obsolete]
	[MessageHandler(CMessageData.MessageType.UpdatePropTransparency)]
	private void Handle_UpdatePropTransparency(CMessageData message)
	{
		CUpdatePropTransparency_MessageData cUpdatePropTransparency_MessageData = (CUpdatePropTransparency_MessageData)message;
		for (int num = ScenarioManager.CurrentScenarioState.TransparentProps.Count - 1; num >= 0; num--)
		{
			CObjectObstacle cObjectObstacle = ScenarioManager.CurrentScenarioState.TransparentProps[num];
			List<TileIndex> pathingBlockers = cObjectObstacle.PathingBlockers;
			CActor cActor = null;
			foreach (TileIndex item in pathingBlockers)
			{
				CTile cTile = ScenarioManager.Tiles[item.X, item.Y];
				CActor cActor2 = ScenarioManager.Scenario.FindActorAt(cTile.m_ArrayIndex);
				if (cActor2 != null && (cObjectObstacle.RuntimeAttachedActor == null || cActor2.ActorGuid != cObjectObstacle.RuntimeAttachedActor.ActorGuid))
				{
					cActor = cActor2;
				}
			}
			if (cActor == null)
			{
				ScenarioManager.CurrentScenarioState.TransparentProps.Remove(cObjectObstacle);
				GameObject gameObject = FindPropGameObject(cObjectObstacle);
				if (gameObject != null)
				{
					Log.Info("Prop found for transparency");
					CustomObjectPositionToChildMaterials componentInChildren = gameObject.GetComponentInChildren<CustomObjectPositionToChildMaterials>();
					if (componentInChildren != null)
					{
						Log.Info("Script found for transparency");
						componentInChildren.fadeSourceObject = null;
						componentInChildren.enableFade = false;
						Log.Info("Transparency disabled");
					}
					else
					{
						Log.Warning("Could not find CustomObjectPositionToChildMaterial.cs script on Prop\n" + cObjectObstacle.PrefabName);
					}
				}
				else
				{
					Log.Info("Could not find prop for transparency");
				}
			}
		}
		foreach (CObjectObstacle prop in cUpdatePropTransparency_MessageData.m_PropList)
		{
			if (ScenarioManager.CurrentScenarioState.TransparentProps.Contains(prop))
			{
				continue;
			}
			ScenarioManager.CurrentScenarioState.TransparentProps.Add(prop);
			GameObject gameObject2 = FindPropGameObject(prop);
			if (gameObject2 != null)
			{
				CustomObjectPositionToChildMaterials componentInChildren2 = gameObject2.GetComponentInChildren<CustomObjectPositionToChildMaterials>();
				if (componentInChildren2 == null)
				{
					Log.Warning("Could not find CustomObjectPositionToChildMaterial.cs script on Prop\n" + prop.PrefabName);
					continue;
				}
				GameObject fadeSourceObject = FindClientActorGameObject(cUpdatePropTransparency_MessageData.m_ActorSpawningMessage);
				componentInChildren2.fadeSourceObject = fadeSourceObject;
				componentInChildren2.enableFade = true;
			}
			else
			{
				Log.Info("Could not find prop");
			}
		}
	}

