		if (cActorHasTeleported_MessageData.m_UseFade)
		{
			StartCoroutine(TeleportFadeOutCrt(gameObject, position, cActorHasTeleported_MessageData.m_ActorTeleported, callFadeIn: true));
		}
		else
		{
			ActorBehaviour.GetActorBehaviour(gameObject).TeleportToLocation(position);
		}
		if (cActorHasTeleported_MessageData.m_UseAnimation)
		{
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = cActorHasTeleported_MessageData.m_ActorTeleported;
			ProcessActorAnimation(cActorHasTeleported_MessageData.m_TeleportAbility, cActorHasTeleported_MessageData.m_ActorTeleported, new List<string>
			{
				cActorHasTeleported_MessageData.AnimOverload,
				cActorHasTeleported_MessageData.m_TeleportAbility?.AnimOverload,
				"Jump Outof",
				"PowerUp"
			}, out animationShouldPlay, out animatingActorToWaitFor);
			if (animatingActorToWaitFor != null && m_WaitState.m_State != ChoreographerStateType.WaitingForEndAbilityAnimSync)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
			}
		}
	}

	private IEnumerator TeleportFadeOutCrt(GameObject actorGO, Vector3 targetPosition, CActor actor, bool callFadeIn)
	{
		SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, 2000, actor);
		using (WaitPendingAnimationScope(actorGO))
		{
			Renderer[] renderers = (from r in actorGO.GetComponentsInChildren<Renderer>()
				where 0 == 0
				select r).ToArray();
			float dissTime = 0.6f;
			float timer = dissTime;
			while (timer > 0f)
			{
				float value = 1f - timer / dissTime;
				Renderer[] array = renderers;
				foreach (Renderer renderer in array)
				{
					if (renderer != null)
					{
						Material[] materialClonesSlow = renderer.GetMaterialClonesSlow();
						for (int num2 = 0; num2 < materialClonesSlow.Length; num2++)
						{
							materialClonesSlow[num2].SetFloat("_DeathDissolve", value);
						}
					}
				}
				timer -= Timekeeper.instance.m_GlobalClock.deltaTime;
				yield return new WaitForEndOfFrame();
			}
		}
		if (callFadeIn)
		{
			StartCoroutine(TeleportFadeInCrt(actorGO, targetPosition, actor));
		}
		else
		{
			ActorEvents.GetActorEvents(actorGO).ProgressChoreographer();
		}
	}

	private IEnumerator TeleportFadeInCrt(GameObject actorGO, Vector3 targetPosition, CActor actor, Renderer[] renderers = null)
	{
		SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, 2000, actor);
		ActorBehaviour.GetActorBehaviour(actorGO).TeleportToLocation(targetPosition);
		if (renderers == null)
		{
			renderers = (from r in actorGO.GetComponentsInChildren<Renderer>()
				where 0 == 0
				select r).ToArray();
		}
		float dissTime = 0.6f;
		float timer = dissTime;
		while (timer > 0f)
		{
			float value = timer / dissTime;
			Renderer[] array = renderers;
			foreach (Renderer renderer in array)
			{
				if (renderer != null)
				{
					Material[] materialClonesSlow = renderer.GetMaterialClonesSlow();
					for (int num2 = 0; num2 < materialClonesSlow.Length; num2++)
					{
						materialClonesSlow[num2].SetFloat("_DeathDissolve", value);
					}
				}
			}
			timer -= Timekeeper.instance.m_GlobalClock.deltaTime;
			yield return new WaitForEndOfFrame();
		}
		ActorEvents.GetActorEvents(actorGO).ProgressChoreographer();
	}

