	[MessageHandler(CMessageData.MessageType.ActorIsSelectingAttackFocusTargets)]
	private void Handle_ActorIsSelectingAttackFocusTargets(CMessageData message)
	{
		CActorIsSelectingAttackFocusTargets_MessageData messageData = (CActorIsSelectingAttackFocusTargets_MessageData)message;
		bool flag = false;
		bool flag2 = false;
		string text = ((messageData.m_AttackAbility.ActiveBonusData.Duration != CActiveBonus.EActiveBonusDurationType.NA) ? LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION") : LocalizationManager.GetTranslation("GUI_CONFIRM_ATTACK"));
		WorldspaceStarHexDisplay.Instance.LockView = false;
		WorldspaceStarHexDisplay.Instance.ClearCachedAbilityTiles();
		WorldspaceStarHexDisplay.Instance.ResetPlayerAttackType();
		m_CurrentActor = messageData.m_ActorSpawningMessage;
		ClearAllActorEvents();
		bool flag3 = messageData.m_AttackAbility.EnoughTargetsSelected() && !messageData.m_AttackAbility.IsWaitingForSingleTargetItem() && !messageData.m_AttackAbility.IsWaitingForSingleTargetActiveBonus();
		bool flag4 = messageData.m_AttackingActor.Type == CActor.EType.Player;
		bool flag5 = flag4 && (!messageData.m_AttackAbility.ProcessIfDead || messageData.m_AttackingActor.IsDead);
		Singleton<HelpBox>.Instance.ClearHelpInfo();
		if (flag5)
		{
			s_Choreographer.m_CurrentAbility = messageData.m_AttackAbility;
			TileBehaviour.SetCallback(TileHandler);
			foreach (GameObject clientActorObject in ClientActorObjects)
			{
				if (clientActorObject != null)
				{
					ActorBehaviour.GetActorBehaviour(clientActorObject).m_WorldspacePanelUI?.ResetPreview();
				}
			}
			DisableTileSelection(active: false);
			flag2 = true;
			if (messageData.m_AttackAbility.AreaEffect != null || messageData.m_AttackAbility.AreaEffectBackup != null)
			{
				WorldspaceStarHexDisplay.Instance.SetAOELocked(messageData.m_AttackAbility.AreaEffectLocked);
				bool flag6 = (messageData.m_AttackAbility.RequiresWaypointSelection() ? (Waypoint.s_Waypoints.Count > 0) : (messageData.m_AttackAbility.EnoughTargetsSelected() && messageData.m_AttackAbility.CanBePerformed()));
				bool interactable = (messageData.m_AttackAbility.RequiresAllyTargeting() ? messageData.m_AttackAbility.ValidAlliesTargeted() : flag6);
				readyButton.SetInteractable(interactable);
				bool hideHelpBox = false;
				if (messageData.m_AttackAbility.MiscAbilityData != null && messageData.m_AttackAbility.MiscAbilityData.ExactRange.HasValue && messageData.m_AttackAbility.MiscAbilityData.ExactRange.Value)
				{
					hideHelpBox = true;
				}
				else if (messageData.m_AttackAbility.AreaEffect != null && messageData.m_AttackAbility.AreaEffect.CanFlip)
				{
					if (messageData.m_AttackAbility.ActorsToTarget.Count > 0)
					{
						Singleton<HelpBox>.Instance.Hide();
					}
					else
					{
						Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_HELPBOX_R_TO_ROTATE", HelpBox.FormatTarget.NONE, "ROTATE_AREA_EFFECT");
					}
				}
				SetChoreographerState(ChoreographerStateType.WaitingForAreaAttackFocusSelection, 0, null, hideHelpBox);
				WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_AttackAbility, WorldspaceStarHexDisplay.EAbilityDisplayType.AreaOfEffect);
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
				GUIInterface.s_GUIInterface.SetStatusText("Set Area Effect position/rotation to attack with ability strength = " + messageData.m_AttackAbility.Strength);
			}
			else if (messageData.m_AttackAbility.AllTargetsOnAttackPath && !messageData.m_AttackAbility.IsMeleeAttack)
			{
				TileBehaviour.SetCallback(Waypoint.TileHandler);
				GUIInterface.s_GUIInterface.SetStatusText("Select way points for attack path" + message.m_ActorSpawningMessage.ID + " . Number moves " + messageData.m_AttackAbility.Range);
				Waypoint.s_MovingActor = messageData.m_AttackAbility.TargetingActor;
				SetChoreographerState(ChoreographerStateType.WaitingForAreaAttackFocusSelection, 0, null);
				WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_AttackAbility, WorldspaceStarHexDisplay.EAbilityDisplayType.SelectPath);
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
				GUIInterface.s_GUIInterface.SetStatusText("Set Select Path to attack with ability strength = " + messageData.m_AttackAbility.Strength);
			}
			else
			{
				WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_AttackAbility, WorldspaceStarHexDisplay.EAbilityDisplayType.Normal);
				if (WorldspaceStarHexDisplay.Instance.CurrentDisplayState.Equals(WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection) && !messageData.m_AttackAbility.Flags.HasFlag(CAbility.EAbilityFlag.DontRefreshTargetingUI))
				{
					WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
				}
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
				GUIInterface.s_GUIInterface.SetStatusText("Select target(s) to attack with ability strength = " + messageData.m_AttackAbility.Strength);
			}
			if (flag4)
			{
				if (messageData.m_AttackAbility.CanClearTargets() || messageData.m_AttackAbility.UseSubAbilityTargeting)
