	[MessageHandler(CMessageData.MessageType.ActorSelectedAttackFocus)]
	private void Handle_ActorSelectedAttackFocus(CMessageData message)
	{
		CActorSelectedAttackFocus_MessageData cActorSelectedAttackFocus_MessageData = (CActorSelectedAttackFocus_MessageData)message;
		if (cActorSelectedAttackFocus_MessageData.m_Ability != null && cActorSelectedAttackFocus_MessageData.m_Ability.AutoTrigger)
		{
			return;
		}
		bool flag = cActorSelectedAttackFocus_MessageData.m_AttackingActor.Type == CActor.EType.Player;
		string text = null;
		string text2 = null;
		ReadyButton.EButtonState state;
		if (cActorSelectedAttackFocus_MessageData.m_Ability.AreaEffect != null)
		{
			if (WorldspaceStarHexDisplay.Instance.IsAOELocked())
			{
				if (flag)
				{
					m_SkipButton.SetInteractable(active: false);
				}
				else
				{
					m_SkipButton.Toggle(active: false);
				}
				state = ReadyButton.EButtonState.EREADYBUTTONCONFIRMTARGETS;
				text = "GUI_CONFIRM_TARGETS";
			}
			else
			{
				m_SkipButton.Toggle(flag, LocalizationManager.GetTranslation("GUI_SKIP_ATTACK"), hideOnClick: true, cActorSelectedAttackFocus_MessageData.m_Ability.CanSkip);
				state = ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED;
				text = "GUI_CONFIRM_ATTACK";
			}
		}
		else if (cActorSelectedAttackFocus_MessageData.m_Ability.NumberTargets > 0)
		{
			if (flag)
			{
				m_SkipButton.SetInteractable(active: false);
			}
			else
			{
				m_SkipButton.Toggle(active: false);
			}
			state = ReadyButton.EButtonState.EREADYBUTTONCONFIRMTARGETS;
			text2 = AbilityConfirmTargetText(cActorSelectedAttackFocus_MessageData.m_Ability);
		}
		else
		{
			m_SkipButton.Toggle(flag, LocalizationManager.GetTranslation("GUI_SKIP_ATTACK"), hideOnClick: true, cActorSelectedAttackFocus_MessageData.m_Ability.CanSkip);
			state = ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED;
			text = "GUI_CONFIRM_ATTACK";
		}
		if (text2.IsNullOrEmpty() && !text.IsNullOrEmpty())
		{
			text2 = LocalizationManager.GetTranslation(text);
		}
		readyButton.Toggle(flag, state, text2, hideOnClick: true, glowingEffect: true);
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
	}

