	public void FaceNearestEnemies()
	{
		if (ScenarioManager.IsFastReloading)
		{
			return;
		}
		foreach (GameObject clientActorObject in ClientActorObjects)
		{
			FaceNearestEnemy(clientActorObject);
		}
	}

	private void FaceNearestEnemy(GameObject go)
	{
		CActor actor = ActorBehaviour.GetActor(go);
		if (actor == null || actor.IsDead || actor.IsDowned || actor.Interacting)
		{
			return;
		}
		List<GameObject> clientActorObjects = ClientActorObjects;
		GameObject gameObject = null;
		float num = float.MaxValue;
		foreach (GameObject item in clientActorObjects)
		{
			if (item == go)
			{
				continue;
			}
			CActor actor2 = ActorBehaviour.GetActor(item);
			if (actor2 != null && !actor2.IsDead && !actor2.IsDowned && CActor.AreActorsEnemies(actor.Type, actor2.Type, actor, actor2))
			{
				float sqrMagnitude = (item.transform.position - go.transform.position).sqrMagnitude;
				if (sqrMagnitude < num)
				{
					num = sqrMagnitude;
					gameObject = item;
				}
			}
		}
		if (gameObject != null)
		{
			StartCoroutine(RotateToFaceTarget(go, gameObject.transform.position));
		}
	}

	private IEnumerator RotateToFaceTarget(GameObject go, Vector3 target, bool forceRotate = false, float duration = 0.35f)
	{
		yield return null;
		CActor actor = ActorBehaviour.GetActor(go);
		if (actor == null || actor.Interacting)
		{
			yield break;
		}
		ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(go);
		if (actorBehaviour == null || (!forceRotate && !actorBehaviour.ShouldLookAtActors()))
		{
			yield break;
		}
		Vector3 vector = target - go.transform.position;
		vector.y = 0f;
		if (vector.sqrMagnitude <= 1E-05f)
		{
			yield break;
		}
		Quaternion startRotation = go.transform.rotation;
		Quaternion targetRotation = Quaternion.LookRotation(vector.normalized, go.transform.up);
		float elapsed = 0f;
		while (elapsed < duration)
		{
			if (go == null || actor.Interacting)
			{
				yield break;
			}
			elapsed += Time.deltaTime;
			go.transform.rotation = Quaternion.Lerp(startRotation, targetRotation, elapsed / duration);
			yield return null;
		}
		go.transform.rotation = targetRotation;
	}

	[MessageHandler(CMessageData.MessageType.ActorFinishedDrawingModifiers)]
