		{
			cActor2 = targetSummary.RedirectedFromActor;
		}
		cActor2 = (cActor.IsScenarioActor ? targetSummary.DamageSourceActor : cActor2);
		ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(cActor2)).m_WorldspacePanelUI.ConfirmFinishedDrawing();
	}

	[MessageHandler(CMessageData.MessageType.ActorIsAttacking)]
	private void Handle_ActorIsAttacking(CMessageData message)
	{
		CurrentAttackArea.Clear();
		DisableNextPhaseButtons();
		bool flag = false;
		CActorIsAttacking_MessageData cActorIsAttacking_MessageData = (CActorIsAttacking_MessageData)message;
		CActor actorBeingAttacked = cActorIsAttacking_MessageData.m_ActorBeingAttacked;
		CActor cActor = actorBeingAttacked;
		if (cActorIsAttacking_MessageData?.m_TargetSummary?.RedirectedFromActor != null)
		{
			cActor = cActorIsAttacking_MessageData.m_TargetSummary.RedirectedFromActor;
		}
		cActor = (actorBeingAttacked.IsScenarioActor ? cActorIsAttacking_MessageData.m_AttackingActor : cActor);
		m_CurrentAbility = cActorIsAttacking_MessageData.m_AttackAbility;
		m_CurrentActor = m_CurrentAbility?.TargetingActor;
		Singleton<UIUseAbilitiesBar>.Instance.Hide();
		Singleton<UIUseItemsBar>.Instance.Hide();
		Singleton<UIActiveBonusBar>.Instance.Hide();
		Singleton<UIUseAugmentationsBar>.Instance.Hide();
		if (cActorIsAttacking_MessageData.m_AttackAbility.OnDeath)
		{
			m_CurrentOnDeathActor = cActorIsAttacking_MessageData.m_AttackingActor;
		}
		else
		{
			m_CurrentOnDeathActor = null;
		}
		ClearAllActorEvents();
		if (!m_FollowCameraDisabled)
		{
			CameraController.s_CameraController.DisableCameraInput(CameraController.ECameraInput.Move, this);
		}
		if (actorBeingAttacked.IsScenarioActor)
		{
			flag = true;
		}
		GameObject gameObject = FindClientActorGameObject(cActorIsAttacking_MessageData.m_AttackingActor);
		Vector3 zero = Vector3.zero;
		List<CActor> list = ((cActorIsAttacking_MessageData.m_AttackAbility.RedirectedActors.Count > 0) ? new List<CActor>() : null);
		foreach (CActor actor in cActorIsAttacking_MessageData.m_ActorsAttackingAll)
		{
			CActor actor2 = actor;
			(CActor, CActor) tuple = cActorIsAttacking_MessageData.m_AttackAbility.RedirectedActors.FirstOrDefault(((CActor, CActor) pair) => pair.Item1 == actor);
			var (cActor2, cActor3) = tuple;
			if ((cActor2 != null || cActor3 != null) && !list.Contains(actor))
			{
				actor2 = tuple.Item2;
				list.Add(actor);
			}
			GameObject gameObject2 = FindClientActorGameObject(actor2);
			if (gameObject2 != null)
			{
				zero += gameObject2.transform.position;
			}
		}
		CurrentAttackTargets.Add(FindClientActorGameObject(cActor));
		zero /= (float)cActorIsAttacking_MessageData.m_ActorsAttackingAll.Count;
		if (gameObject != null && cActorIsAttacking_MessageData.m_ActorsAttackingAll[0] == cActorIsAttacking_MessageData.m_ActorBeingAttacked)
		{
			StartCoroutine(RotateToFaceTarget(gameObject, zero));
		}
		m_PerformAttackFX = true;
		List<CActor> list2 = new List<CActor> { actorBeingAttacked };
		if (m_ActorsBeingTargetedForVFX == null)
		{
			m_ActorsBeingTargetedForVFX = new List<CActor>(list2);
		}
		else
		{
			m_ActorsBeingTargetedForVFX.AddRange(list2);
		}
		WorldspaceStarHexDisplay.Instance.ClearNonTargetHexHighlights(list2);
		AttackModBar.s_LongestAttackModSequence = 1;
		CAttackSummary.TargetSummary targetSummary = cActorIsAttacking_MessageData.m_TargetSummary;
		if (targetSummary != null)
		{
			ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(cActor)).m_WorldspacePanelUI?.DisplayAttackModifierFlow(targetSummary, cActorIsAttacking_MessageData.m_AttackAbility);
			AttackModBar.s_AttackModifierBarFlowCanBegin = true;
		}
		else
		{
			Log.Error("Unable to find Attack Summary for " + actorBeingAttacked.GetPrefabName());
		}
		float num = GlobalSettings.DefInstance.m_AttackModifierSettings.RollingModDuration * 1000f * (float)AttackModBar.s_LongestAttackModSequence;
		SetChoreographerState(ChoreographerStateType.WaitingForAttackModifierCards, (int)num, null);
		if (!m_FollowCameraDisabled && !ScenarioManager.DisableCameraRotation())
		{
			if (flag)
			{
				GameObject gameObject3 = FindClientActorGameObject(cActorIsAttacking_MessageData.m_AttackingActor);
				if (gameObject3 != null)
				{
					CameraController.s_CameraController.SetOptimalViewPoint(gameObject3.transform.position, gameObject3.transform.position, cActorIsAttacking_MessageData.m_ActorSpawningMessage.Type);
				}
				CameraController.s_CameraController.SmartFocus(gameObject3, pauseDuringTransition: true);
			}
			else
			{
				if (FindClientActorGameObject(cActorIsAttacking_MessageData.m_AttackingActor) != null)
				{
					CameraController.s_CameraController.SetOptimalViewPoint(FindClientActorGameObject(cActorIsAttacking_MessageData.m_AttackingActor).transform.position, zero, cActorIsAttacking_MessageData.m_ActorSpawningMessage.Type);
				}
				if (!cActorIsAttacking_MessageData.m_AttackAbility.IsMeleeAttack)
				{
					CameraController.s_CameraController.SetFocalPointBetweenTwoObjects(CurrentAttackTargets[0], FindClientActorGameObject(cActorIsAttacking_MessageData.m_AttackingActor));
				}
				else if (CurrentAttackTargets.Count > 0)
				{
					CameraController.s_CameraController.SmartFocus(CurrentAttackTargets[0], pauseDuringTransition: true);
				}
			}
		}
		if (!(FindClientActorGameObject(cActorIsAttacking_MessageData.m_AttackingActor) != null))
		{
			return;
		}
		WeaponCollision[] componentsInChildren = FindClientActorGameObject(cActorIsAttacking_MessageData.m_AttackingActor).GetComponentsInChildren<WeaponCollision>();
		if (componentsInChildren != null)
		{
			WeaponCollision[] array = componentsInChildren;
			for (int num2 = 0; num2 < array.Length; num2++)
			{
				array[num2].enabled = true;
			}
		}
	}

