	[MessageHandler(CMessageData.MessageType.ResetAttackEvents)]
	private void Handle_ResetAttackEvents(CMessageData message)
	{
		foreach (GameObject clientActorObject in s_Choreographer.ClientActorObjects)
		{
			ActorEvents actorEvents = ActorEvents.GetActorEvents(clientActorObject);
