	[MessageHandler(CMessageData.MessageType.ActorHasAttacked)]
	private void Handle_ActorHasAttacked(CMessageData message)
	{
		CActorHasAttacked_MessageData messageData = (CActorHasAttacked_MessageData)message;
		ClearAllActorEvents();
		if (messageData.m_AttackAbility.OnDeath)
		{
			m_CurrentOnDeathActor = messageData.m_AttackingActor;
		}
		else
		{
			m_CurrentOnDeathActor = null;
		}
		if (m_CurrentOnDeathActor != null)
		{
			Log.SimpleInfo("ActorHasAttacked is processing an OnDeath attack");
		}
		if (ScenarioManager.Scenario.HasActor(messageData.m_AttackingActor))
		{
			CurrentAttackArea.Clear();
			if (messageData.m_AttackAbility.AreaEffect != null || messageData.m_AttackAbility.AreaEffectBackup != null)
			{
				foreach (CTile item2 in messageData.m_AttackAbility.ValidTilesInAreaAffected)
				{
					CurrentAttackArea.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item2.m_ArrayIndex.X, item2.m_ArrayIndex.Y]);
				}
				if (messageData.m_AttackAbility.AreaEffectBackup != null)
				{
					foreach (CActor item3 in messageData.m_AttackAbility.ActorsToTarget)
					{
						CClientTile item = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item3.ArrayIndex.X, item3.ArrayIndex.Y];
						if (!CurrentAttackArea.Contains(item))
						{
							CurrentAttackArea.Add(item);
						}
					}
				}
				if (messageData.m_AttackingActor.Type != CActor.EType.Player)
				{
					WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_AttackAbility, WorldspaceStarHexDisplay.EAbilityDisplayType.EnemyAreaOfEffect);
				}
			}
			else
			{
				foreach (CTile item4 in messageData.m_AttackAbility.TilesInRange)
				{
					CurrentAttackArea.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item4.m_ArrayIndex.X, item4.m_ArrayIndex.Y]);
				}
			}
			if (!messageData.m_AttackAbility.AllTargetsOnMovePath)
			{
				bool animationShouldPlay = false;
				CActor animatingActorToWaitFor = messageData.m_AttackingActor;
				if (ScenarioScript.current != null)
				{
					CActor target = messageData.m_AttackAbility.AttackSummary.Targets.FirstOrDefault()?.ActorToAttack;
					messageData.m_AttackingActor.SpawnProjectilesOnRangedAttack = ScenarioScript.current.ShouldSpawnProjectile(messageData.m_AttackingActor, target);
				}
				else
				{
					messageData.m_AttackingActor.SpawnProjectilesOnRangedAttack = true;
				}
				string text = "";
				if (messageData.m_AttackAbility.GetVar("RangeDependentAnim").GetBool())
				{
					Point arrayIndex = messageData.m_AttackedActors[0].ArrayIndex;
					if (messageData.m_AttackAbility.AreaEffect != null)
					{
						arrayIndex = messageData.m_AttackAbility.ValidTilesInAreaAffected[0].m_ArrayIndex;
					}
					switch (messageData.m_AttackingActor.GetDistanceTo(arrayIndex))
					{
					case 2:
						text = "_Range2";
						break;
					case 3:
						text = "_Range3";
						break;
					}
				}
				string text2 = "";
				if (messageData.m_AttackAbility.TargetingActor is CHeroSummonActor && messageData.m_AttackAbility.Name == "DefaultAttack" && !messageData.m_AttackAbility.IsMeleeAttack)
				{
					text2 = "RangedAttack";
				}
				string text3 = ((messageData.m_AttackAbility != null && messageData.m_AttackAbility.IsItemAbility) ? "UseItem" : "");
				List<string> list = new List<string>
				{
					text3 + text,
					messageData.AnimOverload + text,
					text2 + text,
					"Attack" + text
				};
				if ((messageData.m_ActiveBonusesFlags & AbilityData.EActiveBonusFlag.DrifterShockWaveAttack) != 0)
				{
					List<string> list2 = new List<string>(list);
					for (int num = list.Count - 1; num >= 0; num--)
					{
						string text4 = list[num];
						if (text4 == "Attack")
						{
							list2.Insert(num, text4 + "_AOE_Cone");
						}
					}
					list = list2;
				}
				if ((messageData.m_ActiveBonusesFlags & AbilityData.EActiveBonusFlag.EnhancedEffects) != 0)
				{
					List<string> list3 = new List<string>(list);
					for (int num2 = list.Count - 1; num2 >= 0; num2--)
					{
						list3.Insert(num2, list[num2] + "_Enhanced");
					}
					list = list3;
				}
				if (messageData.m_AttackedActors.Count == 1 && messageData.m_AttackedActors[0].IsScenarioActor)
				{
					list.Insert(0, "Stomp");
				}
				ProcessActorAnimation(messageData.m_AttackAbility, messageData.m_AttackingActor, list, out animationShouldPlay, out animatingActorToWaitFor);
				if (animatingActorToWaitFor != null)
				{
					SetChoreographerState(ChoreographerStateType.WaitingForAttackAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
				}
				if (!animationShouldPlay)
				{
					GameObject gameObject = FindClientActorGameObject(animatingActorToWaitFor);
					if (gameObject != null)
					{
						ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
					}
				}
				if ((messageData.m_AttackingActor?.Class?.ID == "DeathwalkerID" || messageData.m_AttackingActor?.GetMirrorActor()?.Class?.ID == "DeathwalkerID") && messageData.m_AttackingActor.OverrideArrayIndex != default(Point))
				{
					GameObject caster = FindClientActorGameObject(messageData.m_AttackingActor);
					CActor actor = messageData.m_AttackedActors[0];
					GameObject gameObject2 = FindClientActorGameObject(actor);
					CObjectProp cObjectProp = ScenarioManager.CurrentScenarioState.ShadowProps.Find((CObjectProp p) => new Point(p.ArrayIndex) == messageData.m_AttackingActor.OverrideArrayIndex);
					if (cObjectProp != null)
					{
						GameObject gameObject3 = FindPropGameObject(cObjectProp);
						if (messageData.m_AttackAbility.IsMeleeAttack && gameObject3 != null)
						{
							GameObject propPrefab = GlobalSettings.GetPropPrefab("ShadowAttack");
							if (propPrefab == null)
							{
								Log.Error("Unable to find asset for dethwalker melee attack");
								return;
							}
							Quaternion value = Quaternion.LookRotation((gameObject2.transform.position - gameObject3.transform.position).normalized, gameObject3.transform.up);
							TryPlayEffect(propPrefab, gameObject3.transform, null, value);
						}
						else
						{
							SpawnProjectile(gameObject3, gameObject2, "AttackProjectileSettings", caster);
						}
					}
				}
			}
			else
			{
				m_SMB_Control_WaitingForAttackAnim = false;
				SetChoreographerState(ChoreographerStateType.WaitingForAttackAnim, (int)GlobalSettings.DefInstance.m_AttackModifierSettings.SlowMoDuration * 1000, messageData.m_AttackingActor);
			}
			if (messageData.m_AttackedActors.Count == messageData.m_AttackAbility.ActorsToTarget.Count || messageData.m_AttackedActors[0] == messageData.m_AttackAbility.ActorsToTarget[0])
			{
				LogConsumes(messageData.m_AttackingActor, messageData.m_AttackAbility);
			}
		}
		else
		{
			ScenarioRuleClient.StepComplete();
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorBeenAttacked)]
	private void Handle_ActorBeenAttacked(CMessageData message)
	{
		CActorBeenAttacked_MessageData cActorBeenAttacked_MessageData = (CActorBeenAttacked_MessageData)message;
		SEventAbilityAttack sEventAbilityAttack = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilityAttack>(onlyUnprocessed: false, CAbility.EAbilityType.Attack, ESESubTypeAbility.None, checkQueue: true);
		SEventAttackModifier sEventAttackModifier = SEventLog.FindLastAttackModifierEventWithID(onlyUnprocessed: false, cActorBeenAttacked_MessageData.m_ActorBeingAttacked.ID, cActorBeenAttacked_MessageData.m_ActorBeingAttacked.Class.ID, toScrape: false, checkQueue: true, (cActorBeenAttacked_MessageData.m_AttackAbility?.MiscAbilityData == null || !cActorBeenAttacked_MessageData.m_AttackAbility.MiscAbilityData.TargetOneEnemyWithAllAttacks.HasValue || !cActorBeenAttacked_MessageData.m_AttackAbility.MiscAbilityData.TargetOneEnemyWithAllAttacks.Value) ? cActorBeenAttacked_MessageData.m_AttackIndex : 0);
		if (cActorBeenAttacked_MessageData.m_LogDamageCalculationOnly && sEventAbilityAttack != null && sEventAttackModifier != null)
		{
			return;
		}
		if (ScenarioManager.Scenario.HasActor(cActorBeenAttacked_MessageData.m_AttackingActor))
		{
			GameObject gameObject = FindClientActorGameObject(cActorBeenAttacked_MessageData.m_AttackingActor);
			if (gameObject != null)
			{
				WeaponCollision[] componentsInChildren = gameObject.GetComponentsInChildren<WeaponCollision>();
				if (componentsInChildren != null)
				{
					WeaponCollision[] array = componentsInChildren;
					for (int i = 0; i < array.Length; i++)
					{
						array[i].enabled = false;
					}
				}
			}
		}
		Log.NetworkInfo("Actor being attacked: " + cActorBeenAttacked_MessageData.m_ActorBeingAttacked.GetPrefabName());
		GameObject gameObject2 = FindClientActorGameObject(cActorBeenAttacked_MessageData.m_ActorBeingAttacked);
		if (!cActorBeenAttacked_MessageData.m_ActorBeingAttacked.IsDowned)
		{
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = cActorBeenAttacked_MessageData.m_ActorBeingAttacked;
			string text = ((cActorBeenAttacked_MessageData.m_ActorOriginalHealth == cActorBeenAttacked_MessageData.m_ActorBeingAttacked.Health) ? "HitMiss" : "Hit");
			ProcessActorAnimation(cActorBeenAttacked_MessageData.m_AttackAbility, cActorBeenAttacked_MessageData.m_ActorBeingAttacked, new List<string>
			{
				cActorBeenAttacked_MessageData.m_ActorWasAsleep ? "SleepWakeUp" : text,
				text
			}, out animationShouldPlay, out animatingActorToWaitFor);
		}
		if (cActorBeenAttacked_MessageData.m_ActorBeingAttacked.Type != CActor.EType.Player)
		{
			ActorBehaviour.UpdateHealth(gameObject2, cActorBeenAttacked_MessageData.m_ActorOriginalHealth, updateUI: true);
		}
		if (gameObject2 != null)
		{
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject2);
			if (actorBehaviour != null)
			{
				actorBehaviour.UpdateWorldspaceConditionsUI();
			}
		}
		m_CurrentOnDeathActor = null;
		DebugMenu.Instance.AttackValueOverride = int.MaxValue;
		CurrentAttackArea.Clear();
	}

	[MessageHandler(CMessageData.MessageType.LogAttackModifier)]
	private void Handle_LogAttackModifier(CMessageData message)
	{
		CLogAttackModifier_MessageData cLogAttackModifier_MessageData = (CLogAttackModifier_MessageData)message;
		LogAttackModifier(cLogAttackModifier_MessageData.m_ModifierEvent, cLogAttackModifier_MessageData.m_AttackingActor, cLogAttackModifier_MessageData.m_ActorBeingAttacked, cLogAttackModifier_MessageData.m_Ability);
	}

	[MessageHandler(CMessageData.MessageType.LogDamageCalculation)]
	private void Handle_LogDamageCalculation(CMessageData message)
	{
		CLogDamageCalculation_MessageData cLogDamageCalculation_MessageData = (CLogDamageCalculation_MessageData)message;
		if (cLogDamageCalculation_MessageData.m_DamageEvent != null)
		{
			LogDamageCalculation(cLogDamageCalculation_MessageData.m_DamageEvent, cLogDamageCalculation_MessageData.m_AttackingActor, cLogDamageCalculation_MessageData.m_ActorBeingAttacked, cLogDamageCalculation_MessageData.m_Ability);
		}
		else if (cLogDamageCalculation_MessageData.m_AttackEvent != null && cLogDamageCalculation_MessageData.m_ModifierEvent != null)
		{
			LogDamageCalculation(cLogDamageCalculation_MessageData.m_AttackEvent, cLogDamageCalculation_MessageData.m_ModifierEvent, cLogDamageCalculation_MessageData.m_AttackingActor, cLogDamageCalculation_MessageData.m_ActorBeingAttacked, cLogDamageCalculation_MessageData.m_Ability, cLogDamageCalculation_MessageData.m_OverrideLogKey);
		}
	}

	[MessageHandler(CMessageData.MessageType.RedirectAttack)]
	private void Handle_RedirectAttack(CMessageData message)
	{
		CRedirectedAttack_MessageData cRedirectedAttack_MessageData = (CRedirectedAttack_MessageData)message;
		FireSpawnedProjectile.ExternalSettings projectileSettings = GlobalSettings.GetProjectileSettings(cRedirectedAttack_MessageData.m_ProjectileName);
		GameObject gameObject = FindClientActorGameObject(cRedirectedAttack_MessageData.m_OriginalTarget);
		GameObject gameObject2 = FindClientActorGameObject(cRedirectedAttack_MessageData.m_Target);
		if (projectileSettings != null && !(gameObject == null) && !(gameObject2 == null))
		{
			GameObject gameObject3 = gameObject.FindInChildren("RedirectProjectileMono");
			FireSpawnedProjectile fireSpawnedProjectile;
			if (gameObject3 == null)
			{
				gameObject3 = new GameObject("RedirectProjectileMono");
				gameObject3.transform.SetParent(gameObject.transform);
				gameObject3.transform.localPosition = Vector3.zero;
				fireSpawnedProjectile = gameObject3.AddComponent<FireSpawnedProjectile>();
			}
			else
			{
				fireSpawnedProjectile = gameObject3.GetComponent<FireSpawnedProjectile>();
			}
			fireSpawnedProjectile.LoadSettings(projectileSettings);
			m_BlockClientMessageProcessing = true;
			fireSpawnedProjectile.Fire(gameObject, gameObject2, null, () =>
			{
				m_BlockClientMessageProcessing = false;
			});
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorBeenAttackedAndKilled)]
	private void Handle_ActorBeenAttackedAndKilled(CMessageData message)
