		SEventLog.FindLastAttackModifierEventWithID(onlyUnprocessed: false, cActorBeenAttackedAndKilled_MessageData.m_ActorBeingAttacked.ID, cActorBeenAttackedAndKilled_MessageData.m_ActorBeingAttacked.Class.ID, toScrape: false, checkQueue: true, cActorBeenAttackedAndKilled_MessageData.m_AttackIndex);
		m_CurrentOnDeathActor = null;
