	[MessageHandler(CMessageData.MessageType.PlayerSelectingToAvoidDamageOrNot)]
	private void Handle_PlayerSelectingToAvoidDamageOrNot(CMessageData message)
	{
		CPlayerSelectingToAvoidDamageOrNot_MessageData cPlayerSelectingToAvoidDamageOrNot_MessageData = (CPlayerSelectingToAvoidDamageOrNot_MessageData)message;
		CActor actorBeingAttacked = cPlayerSelectingToAvoidDamageOrNot_MessageData.m_ActorBeingAttacked;
		CPlayerActor actorToShowCardsFor = cPlayerSelectingToAvoidDamageOrNot_MessageData.m_ActorToShowCardsFor;
		GameObject focalPointGameObject = FindClientActorGameObject(actorBeingAttacked);
		InitiativeTrackActorBehaviourBase initiativeTrackActorBehaviourBase = InitiativeTrack.Instance.FindInitiativeTrackActor(actorBeingAttacked);
		if (initiativeTrackActorBehaviourBase != null && initiativeTrackActorBehaviourBase.Extension is InitiativeTrackPlayerBehaviourExtension initiativeTrackPlayerBehaviourExtension)
		{
			initiativeTrackPlayerBehaviourExtension.ShowWarning(show: true);
		}
		if (!m_FollowCameraDisabled)
		{
			CameraController.s_CameraController.SetFocalPointGameObject(focalPointGameObject);
		}
		Singleton<UIUseAugmentationsBar>.Instance.Hide();
		readyButton.Toggle(active: false, ReadyButton.EButtonState.EREADYBUTTONNA, null, hideOnClick: true, glowingEffect: false, interactable: true, disregardTurnControlForInteractability: false, haltActionProcessorIfDeactivated: false);
		m_SkipButton.Toggle(active: false);
		m_UndoButton.Toggle(active: false);
		if (FFSNetwork.IsOnline)
		{
			Singleton<UIReadyToggle>.Instance.ToggleVisibility(visible: false);
		}
		m_PlayerSelectingToAvoidDamageOrNot = true;
		if (FFSNetwork.IsOnline)
		{
			Singleton<UIScenarioMultiplayerController>.Instance.OnTakeDamage(actorToShowCardsFor, cPlayerSelectingToAvoidDamageOrNot_MessageData);
			if (!Singleton<TakeDamagePanel>.Instance.ThisPlayerHasTakeDamageControl || PhaseManager.PhaseType == CPhase.PhaseType.SelectAbilityCardsOrLongRest)
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.TakeDamageConfirmation, savePreviousState: true);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.TakeDamageConfirmation, savePreviousState: true);
			}
		}
		else
		{
			Singleton<TakeDamagePanel>.Instance.Show(actorBeingAttacked, actorToShowCardsFor, cPlayerSelectingToAvoidDamageOrNot_MessageData.m_ModifiedStrength, (cPlayerSelectingToAvoidDamageOrNot_MessageData.m_TargetSummary != null) ? Mathf.Max(0, cPlayerSelectingToAvoidDamageOrNot_MessageData.m_TargetSummary.Pierce - cPlayerSelectingToAvoidDamageOrNot_MessageData.m_TargetSummary.Shield) : 0, cPlayerSelectingToAvoidDamageOrNot_MessageData.m_IsDirectDamage, cPlayerSelectingToAvoidDamageOrNot_MessageData.m_DamagingAbility, cPlayerSelectingToAvoidDamageOrNot_MessageData.m_AllowBurnCards, cPlayerSelectingToAvoidDamageOrNot_MessageData.m_DamageType, cPlayerSelectingToAvoidDamageOrNot_MessageData.m_TargetSummary);
		}
	}

