	[MessageHandler(CMessageData.MessageType.PlayerSelectedToAvoidDamage)]
	private void Handle_PlayerSelectedToAvoidDamage(CMessageData message)
	{
		CPlayerSelectedToAvoidDamage_MessageData cPlayerSelectedToAvoidDamage_MessageData = (CPlayerSelectedToAvoidDamage_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(cPlayerSelectedToAvoidDamage_MessageData.m_ActorBeingAttacked);
		ActorBehaviour.GetActorBehaviour(gameObject).m_WorldspacePanelUI?.FinalizeAttackFlow();
		ActorBehaviour.UpdateHealth(gameObject);
		string arg = LocalizationManager.GetTranslation(cPlayerSelectedToAvoidDamage_MessageData.m_ActorBeingAttacked.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cPlayerSelectedToAvoidDamage_MessageData.m_ActorBeingAttacked);
		switch (cPlayerSelectedToAvoidDamage_MessageData.m_AvoidDamageOption)
		{
		case GameState.EAvoidDamageOption.Lose1HandCard:
		{
			if (cPlayerSelectedToAvoidDamage_MessageData.m_CardsBurnedToAvoidDamage.Count == 0)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("FH/COMBAT_LOG_PREVENT_DAMAGE_BURNED_0_HAND"), arg));
				break;
			}
			string arg5 = $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationNameConverter.MultiLookupLocalization(cPlayerSelectedToAvoidDamage_MessageData.m_CardsBurnedToAvoidDamage[0].Name, out var _)}</color></b></font>";
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_PREVENT_DAMAGE_BURNED_1_HAND"), arg, arg5));
			break;
		}
		case GameState.EAvoidDamageOption.Lose2DiscardCards:
			if (cPlayerSelectedToAvoidDamage_MessageData.m_CardsBurnedToAvoidDamage.Count == 0)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("FH/COMBAT_LOG_PREVENT_DAMAGE_BURNED_0_DISCARDED"), arg));
			}
			else if (cPlayerSelectedToAvoidDamage_MessageData.m_CardsBurnedToAvoidDamage.Count == 1)
			{
				string arg2 = $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationNameConverter.MultiLookupLocalization(cPlayerSelectedToAvoidDamage_MessageData.m_CardsBurnedToAvoidDamage[0].Name, out var _)}</color></b></font>";
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("FH/COMBAT_LOG_PREVENT_DAMAGE_BURNED_1_DISCARDED"), arg, arg2));
			}
			else
			{
				string arg3 = $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationNameConverter.MultiLookupLocalization(cPlayerSelectedToAvoidDamage_MessageData.m_CardsBurnedToAvoidDamage[0].Name, out var _)}</color></b></font>";
				string arg4 = $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationNameConverter.MultiLookupLocalization(cPlayerSelectedToAvoidDamage_MessageData.m_CardsBurnedToAvoidDamage[1].Name, out var _)}</color></b></font>";
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_PREVENT_DAMAGE_BURNED_2_DISCARDED"), arg, arg3, arg4));
			}
			break;
		}
	}

