	[MessageHandler(CMessageData.MessageType.PlayerFinishedSelectingToAvoidDamageOrNot)]
	private void Handle_PlayerFinishedSelectingToAvoidDamageOrNot(CMessageData message)
	{
		CPlayerFinishedSelectingToAvoidDamageOrNot_MessageData cPlayerFinishedSelectingToAvoidDamageOrNot_MessageData = (CPlayerFinishedSelectingToAvoidDamageOrNot_MessageData)message;
		foreach (GameObject clientActorObject in ClientActorObjects)
		{
			ActorBehaviour.GetActorBehaviour(clientActorObject)?.PauseLoco(pause: false);
		}
		if (CurrentActor != null && CurrentActor.Type == CActor.EType.Player && PhaseManager.CurrentPhase is CPhaseAction { CurrentPhaseAbility: not null } cPhaseAction)
		{
			CAbility ability = cPhaseAction.CurrentPhaseAbility.m_Ability;
			if (ability.CanReceiveTileSelection())
			{
				m_UndoButton.Toggle(active: true, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
				m_UndoButton.SetInteractable(ability.CanUndo && FirstAbility);
				m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, ability.CanSkip);
			}
		}
		readyButton.ClearAlternativeAction();
		Singleton<TakeDamagePanel>.Instance.ClearPreviouslyPreviewed();
		InitiativeTrackActorBehaviourBase initiativeTrackActorBehaviourBase = InitiativeTrack.Instance.FindInitiativeTrackActor(cPlayerFinishedSelectingToAvoidDamageOrNot_MessageData.m_ActorBeingAttacked);
		if (initiativeTrackActorBehaviourBase != null && initiativeTrackActorBehaviourBase.Extension is InitiativeTrackPlayerBehaviourExtension)
		{
			((InitiativeTrackPlayerBehaviourExtension)initiativeTrackActorBehaviourBase.Extension).ShowWarning(show: false);
		}
		if (m_CurrentActor is CPlayerActor cPlayerActor && ((!cPlayerActor.IsDead && !m_CurrentActor.m_PlayedThisRound) || cPlayerActor.MindControlDuration == CAbilityControlActor.EControlDurationType.ControlForOneAction))
		{
			Singleton<UIScenarioMultiplayerController>.Instance.OnFinishTakeDamage(hidePlayerInfo: false);
			if (cPlayerActor.MindControlDuration == CAbilityControlActor.EControlDurationType.None && (cPlayerActor == GameState.TurnActor || GameState.IsPerformingCardOutOfPhase))
			{
				Singleton<CardsHandManager>.Instance.Show(cPlayerActor, CardHandMode.ActionSelection, GameState.IsPerformingCardOutOfPhase ? CardPileType.SelectedAbilityCardsOutOfPhase : ((!cPlayerActor.IsTakingExtraTurn) ? CardPileType.Round : CardPileType.ExtraTurn), CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, GameState.IsPerformingCardOutOfPhase ? CardsHandUI.CardActionsCommand.FORCE_RESET : CardsHandUI.CardActionsCommand.NONE);
			}
		}
		else
		{
			Singleton<UIScenarioMultiplayerController>.Instance.OnFinishTakeDamage();
		}
		m_PlayerSelectingToAvoidDamageOrNot = false;
		Singleton<TakeDamagePanel>.Instance.ClearTakeDamageInvoked();
		m_AfterTakeDamageProgressMessages.ForEach(ProcessMessage);
		m_AfterTakeDamageProgressMessages.Clear();
	}

	[MessageHandler(CMessageData.MessageType.PlayerFinishedTogglingShields)]
	private void Handle_PlayerFinishedTogglingShields(CMessageData message)
	{
		CPlayerFinishedTogglingShields_MessageData cPlayerFinishedTogglingShields_MessageData = (CPlayerFinishedTogglingShields_MessageData)message;
		Singleton<UIScenarioMultiplayerController>.Instance.OnFinishToggleShields();
		CActor actorBeingAttacked = cPlayerFinishedTogglingShields_MessageData.m_ActorBeingAttacked;
		string arg = LocalizationManager.GetTranslation(actorBeingAttacked.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorBeingAttacked);
		foreach (CItem toggledShield in cPlayerFinishedTogglingShields_MessageData.m_ToggledShields)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_USES"), arg, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(toggledShield.YMLData.Name)}</color></b></font>"), CombatLogFilter.ITEMS);
		}
		foreach (CActiveBonus toggledBonuse in cPlayerFinishedTogglingShields_MessageData.m_ToggledBonuses)
		{
			if (toggledBonuse.Ability.ActiveBonusData.IsToggleBonus)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_USES"), arg, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(toggledBonuse.Ability.GetAbilityBaseCard().Name)}</color></b></font>"), CombatLogFilter.ITEMS);
			}
		}
		m_PlayerSelectingToAvoidDamageOrNot = false;
	}

