	[MessageHandler(CMessageData.MessageType.AttackDone)]
	private void Handle_AttackDone(CMessageData message)
	{
		if (m_ActorsBeingTargetedForVFX != null)
		{
			foreach (CActor item in m_ActorsBeingTargetedForVFX)
			{
				GameObject gameObject = FindClientActorGameObject(item);
				if (gameObject != null)
				{
					ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
					if (actorBehaviour.m_WorldspacePanelUI != null)
					{
						actorBehaviour.m_WorldspacePanelUI.CancelRetaliateEffect();
					}
				}
			}
			m_ActorsBeingTargetedForVFX.Clear();
		}
		m_PerformAttackFX = false;
		_ = (CAttackDone_MessageData)message;
		if (message.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			WorldspaceStarHexDisplay.Instance.ResetPlayerAttackType();
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorIsKilling)]
	private void Handle_ActorIsKilling(CMessageData message)
	{
		CActorIsKilling_MessageData cActorIsKilling_MessageData = (CActorIsKilling_MessageData)message;
		ClearAllActorEvents();
		if (cActorIsKilling_MessageData.m_ActorsAppliedTo.Count > 0 && cActorIsKilling_MessageData.m_KillAbility.ValidTilesInAreaAffected != null && cActorIsKilling_MessageData.m_KillAbility.ValidTilesInAreaAffected.Count > 0)
		{
			CurrentAttackArea.Clear();
			foreach (CTile item in cActorIsKilling_MessageData.m_KillAbility.ValidTilesInAreaAffected)
			{
				CurrentAttackArea.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item.m_ArrayIndex.X, item.m_ArrayIndex.Y]);
			}
		}
		m_ActorsBeingTargetedForVFX = new List<CActor>(cActorIsKilling_MessageData.m_ActorsAppliedTo);
		WorldspaceStarHexDisplay.Instance.ClearNonTargetHexHighlights(cActorIsKilling_MessageData.m_ActorsAppliedTo);
		GameObject gameObject = FindClientActorGameObject(message.m_ActorSpawningMessage);
		Vector3 zero = Vector3.zero;
		bool flag = false;
		foreach (CActor item2 in cActorIsKilling_MessageData.m_ActorsAppliedTo)
		{
			GameObject gameObject2 = FindClientActorGameObject(item2);
			if (gameObject2 != null)
			{
				zero += gameObject2.transform.position;
				flag = true;
			}
		}
		if (flag)
		{
			zero /= (float)cActorIsKilling_MessageData.m_ActorsAppliedTo.Count;
			StartCoroutine(RotateToFaceTarget(gameObject, zero));
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cActorIsKilling_MessageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cActorIsKilling_MessageData.m_KillAbility, cActorIsKilling_MessageData.m_ActorSpawningMessage, new List<string> { cActorIsKilling_MessageData.AnimOverload, "Attack" }, out animationShouldPlay, out animatingActorToWaitFor);
		DisableNextPhaseButtons();
		Singleton<UIActiveBonusBar>.Instance.Hide();
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (animationShouldPlay)
		{
			CharacterManager.EnableWeaponColliderForAttack(gameObject);
		}
		else
		{
			ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
		}
	}

