	[MessageHandler(CMessageData.MessageType.ActorIsHealing)]
	private void Handle_ActorIsHealing(CMessageData message)
	{
		CActorIsHealing_MessageData messageData = (CActorIsHealing_MessageData)message;
		List<CActor> list = messageData.m_ActorsHealedAndHealStrength.Keys.ToList();
		WorldspaceStarHexDisplay.Instance.ClearNonTargetHexHighlights(list);
		m_ActorsBeingTargetedForVFX = new List<CActor>(list);
		string arg = LocalizationManager.GetTranslation(messageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(messageData.m_ActorSpawningMessage);
		foreach (KeyValuePair<CActor, int> item in messageData.m_ActorsHealedAndHealStrength)
		{
			string arg2 = LocalizationManager.GetTranslation(item.Key.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(item.Key);
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_HEAL"), arg, arg2, string.Format("<b>{0}</b>", LocalizationManager.GetTranslation("Heal") + " <sprite name=Heal>" + item.Value)), CombatLogFilter.HEALING);
		}
		ClearAllActorEvents();
		GameObject gameObject = ((messageData.m_ActorsHealedAndHealStrength.Count == 1) ? FindClientActorGameObject(messageData.m_ActorsHealedAndHealStrength.First().Key) : null);
		GameObject go = FindClientActorGameObject(message.m_ActorSpawningMessage);
		if (gameObject != null)
		{
			StartCoroutine(RotateToFaceTarget(go, gameObject.transform.position));
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = messageData.m_ActorSpawningMessage;
		if (!messageData.m_HealAbility.IsModifierAbility)
		{
			List<string> list2 = new List<string> { messageData.AnimOverload, "PowerUp" };
			if ((messageData.m_bonusesFlags & AbilityData.EActiveBonusFlag.EnhancedEffects) != 0)
			{
				list2.Insert(0, "PowerUp_Enhanced");
				list2.Insert(0, messageData.AnimOverload + "_Enhanced");
			}
			ProcessActorAnimation(messageData.m_HealAbility, messageData.m_ActorSpawningMessage, list2, out animationShouldPlay, out animatingActorToWaitFor);
		}
		DisableNextPhaseButtons();
		if (PhaseManager.CurrentPhaseAction?.CurrentPhaseAbilities != null && PhaseManager.CurrentPhaseAction.CurrentPhaseAbilities.Concat(PhaseManager.CurrentPhaseAction.PreviousPhaseAbilities).Any((CPhaseAction.CPhaseAbility x) => x.m_Ability == messageData.m_HealAbility))
		{
			if (animatingActorToWaitFor != null)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
			}
			if (!animationShouldPlay)
			{
				ActorEvents.GetActorEvents(go).ProgressChoreographer();
			}
		}
		Singleton<UIActiveBonusBar>.Instance.Hide();
	}

