	[MessageHandler(CMessageData.MessageType.ActorBeenHealed)]
	private void Handle_ActorBeenHealed(CMessageData message)
	{
		CActorBeenHealed_MessageData cActorBeenHealed_MessageData = (CActorBeenHealed_MessageData)message;
		CActor actorBeingHealed = cActorBeenHealed_MessageData.m_ActorBeingHealed;
		FindClientActorGameObject(message.m_ActorSpawningMessage);
		GameObject gameObject = FindClientActorGameObject(actorBeingHealed);
		if (!(gameObject == null))
		{
			TryPlayConditionEffectOnActor(GlobalSettings.Instance.m_GlobalParticles.DefaultHealEffect, actorBeingHealed);
			ActorBehaviour.UpdateHealth(gameObject, cActorBeenHealed_MessageData.m_ActorOriginalHealth, updateUI: true);
			string arg = LocalizationManager.GetTranslation(actorBeingHealed.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorBeingHealed);
			StringBuilder stringBuilder = new StringBuilder(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_HEALED"), arg));
			if (cActorBeenHealed_MessageData.m_PoisonTokenRemoved)
			{
				stringBuilder.AppendFormat(" {0}", LocalizationManager.GetTranslation("COMBAT_LOG_HEALED_POISON") + " <sprite name=Poison>");
			}
			else
			{
				stringBuilder.AppendFormat(" {0}", string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_HEALED_HEAL"), string.Format("<b>{0}</b>", "<sprite name=Heal>" + cActorBeenHealed_MessageData.m_HealAmount)));
			}
			if (cActorBeenHealed_MessageData.m_WoundTokenRemoved)
			{
				stringBuilder.AppendFormat(" {0}", LocalizationManager.GetTranslation("COMBAT_LOG_HEALED_WOUND") + " <sprite name=Wound>");
			}
			if (cActorBeenHealed_MessageData.m_BaneTokenRemoved)
			{
				stringBuilder.AppendFormat(" {0}", LocalizationManager.GetTranslation("COMBAT_LOG_HEALED_BANE") + " <sprite name=Bane>");
			}
			if (cActorBeenHealed_MessageData.m_BrittleTokenRemoved)
			{
				stringBuilder.AppendFormat(" {0}", LocalizationManager.GetTranslation("COMBAT_LOG_HEALED_BRITTLE") + " <sprite name=Brittle>");
			}
			Singleton<CombatLogHandler>.Instance.AddLog(stringBuilder.ToString(), CombatLogFilter.HEALING);
		}
	}

