	[MessageHandler(CMessageData.MessageType.ActorIsSelectingItemCards)]
	private void Handle_ActorIsSelectingItemCards(CMessageData message)
	{
		CActorIsSelectingItemCards_MessageData cActorIsSelectingItemCards_MessageData = (CActorIsSelectingItemCards_MessageData)message;
		if (cActorIsSelectingItemCards_MessageData.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			WorldspaceStarHexDisplay.Instance.ResetPlayerAttackType();
		}
		ClearAllActorEvents();
		GameObject gameObject = ((cActorIsSelectingItemCards_MessageData.m_ActorsRefreshed.Count == 1) ? FindClientActorGameObject(cActorIsSelectingItemCards_MessageData.m_ActorsRefreshed[0]) : null);
		GameObject go = FindClientActorGameObject(message.m_ActorSpawningMessage);
		if (gameObject != null)
		{
			StartCoroutine(RotateToFaceTarget(go, gameObject.transform.position));
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cActorIsSelectingItemCards_MessageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cActorIsSelectingItemCards_MessageData.m_ItemSelectionAbility, cActorIsSelectingItemCards_MessageData.m_ActorSpawningMessage, new List<string> { cActorIsSelectingItemCards_MessageData.AnimOverload, "PowerUp" }, out animationShouldPlay, out animatingActorToWaitFor);
		DisableNextPhaseButtons();
		ClearStars();
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(go).ProgressChoreographer();
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorHasRefreshedItemCards)]
	private void Handle_ActorHasRefreshedItemCards(CMessageData message)
	{
		CActor actorBeenRefreshed = ((CActorHasRefreshedItemCards_MessageData)message).m_ActorBeenRefreshed;
		FindClientActorGameObject(message.m_ActorSpawningMessage);
		GameObject gameObject = FindClientActorGameObject(actorBeenRefreshed);
		GameObject gameObject2 = ObjectPool.Spawn(GlobalSettings.Instance.m_GlobalParticles.DefaultPositiveCondition, gameObject.transform);
		ObjectPool.Recycle(gameObject2, VFXShared.GetEffectLifetime(gameObject2), GlobalSettings.Instance.m_GlobalParticles.DefaultPositiveCondition, "@ VFX Pool");
		actorBeenRefreshed.ActivatePassiveItems(firstLoad: true);
		if (s_Choreographer.m_WaitState.m_State == ChoreographerStateType.WaitingForItemRefresh)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, 10000, message.m_ActorSpawningMessage);
		}
	}

	[MessageHandler(CMessageData.MessageType.SelectRefreshOrConsumeItems)]
	private void Handle_SelectRefreshOrConsumeItems(CMessageData message)
	{
		CSelectRefreshOrConsumeItems_MessageData messageData = (CSelectRefreshOrConsumeItems_MessageData)message;
		CActor actorBeenRefreshed = messageData.m_ActorBeenRefreshed;
		FindClientActorGameObject(message.m_ActorSpawningMessage);
		GameObject gameObject = FindClientActorGameObject(actorBeenRefreshed);
		GameObject gameObject2 = ObjectPool.Spawn(GlobalSettings.Instance.m_GlobalParticles.DefaultPositiveCondition, gameObject.transform);
		ObjectPool.Recycle(gameObject2, VFXShared.GetEffectLifetime(gameObject2), GlobalSettings.Instance.m_GlobalParticles.DefaultPositiveCondition, "@ VFX Pool");
		if (messageData.m_Ability.Strength == CAbilityRefreshItemCards.STRENGTH_ALL)
		{
			IEnumerable<CItem> source;
			if (messageData.m_SpecificItems == null || messageData.m_SpecificItems.Count <= 0)
			{
				source = actorBeenRefreshed.Inventory.AllItems.Where((CItem it) => (messageData.m_SlotStatesToChooseFrom == null || messageData.m_SlotStatesToChooseFrom.Count == 0 || messageData.m_SlotStatesToChooseFrom.Contains(it.SlotState)) && (messageData.m_SlotsToChooseFrom == null || messageData.m_SlotsToChooseFrom.Count == 0 || messageData.m_SlotsToChooseFrom.Contains(it.YMLData.Slot)));
			}
			else
			{
				IEnumerable<CItem> specificItems = messageData.m_SpecificItems;
				source = specificItems;
			}
			foreach (CItem item in (IEnumerable<CItem>)source.ToList())
			{
				ItemPickerFinishSelectingItem(item, actorBeenRefreshed, messageData.m_Ability);
			}
		}
		else
		{
			if (messageData.m_Ability.AbilityType == CAbility.EAbilityType.RefreshItemCards)
			{
				Singleton<HelpBox>.Instance.Show("GUI_REFRESH_ITEMS_TIP", "GUI_REFRESH_ITEMS_TITLE");
			}
			else
			{
				string arg = (messageData.m_SlotsToChooseFrom.IsNullOrEmpty() ? string.Empty : LocalizationManager.GetTranslation($"GUI_ITEM_SLOT_{messageData.m_SlotsToChooseFrom[0]}"));
				if (messageData.m_Ability.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
				{
					ShowAbilityHelpBoxTooltip(messageData.m_Ability);
				}
				else
				{
					Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_CONSUME_ITEMS_TIP"), arg), string.Format(LocalizationManager.GetTranslation("GUI_CONSUME_ITEMS_TITLE"), arg));
				}
			}
			if (!FFSNetwork.IsOnline || messageData.m_ActorBeenRefreshed.IsUnderMyControl())
			{
				Singleton<ItemCardRefreshPicker>.Instance.Show(actorBeenRefreshed, messageData.m_Ability.AbilityType == CAbility.EAbilityType.RefreshItemCards, messageData.m_SlotStatesToChooseFrom, messageData.m_SlotsToChooseFrom, messageData.m_SpecificItems, messageData.m_Ability.Strength, messageData.m_Ability.GetMiscVar("MaxSelectIsOptional").GetBool(), messageData.m_Ability);
			}
			else
			{
				Singleton<ItemCardRefreshPicker>.Instance.ShowForOtherPlayers(actorBeenRefreshed, messageData.m_Ability.AbilityType == CAbility.EAbilityType.RefreshItemCards, messageData.m_SlotStatesToChooseFrom, messageData.m_SlotsToChooseFrom, messageData.m_SpecificItems, messageData.m_Ability.Strength, messageData.m_Ability.GetMiscVar("MaxSelectIsOptional").GetBool(), messageData.m_Ability);
			}
		}
		DisableButtons();
		if (messageData.m_Ability.Strength == CAbilityRefreshItemCards.STRENGTH_ALL)
		{
			return;
		}
		SetChoreographerState(ChoreographerStateType.WaitingForItemRefresh, 10000000, message.m_ActorSpawningMessage);
		if (FFSNetwork.IsOnline)
		{
			if (!actorBeenRefreshed.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessOneAndSwitchBack, (messageData.m_Ability.AbilityType == CAbility.EAbilityType.RefreshItemCards) ? ActionPhaseType.ItemRefreshing : ActionPhaseType.ItemConsuming);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, (messageData.m_Ability.AbilityType == CAbility.EAbilityType.RefreshItemCards) ? ActionPhaseType.ItemRefreshing : ActionPhaseType.ItemConsuming);
			}
		}
	}

	public static void ItemPickerFinishSelectingItem(CItem item, CActor currentActorBeingRefreshed, CAbility ability = null)
	{
		if (ability.AbilityType == CAbility.EAbilityType.RefreshItemCards)
		{
			currentActorBeingRefreshed.Inventory.ReactivateItem(item, currentActorBeingRefreshed, force: true);
			return;
		}
		TValue miscVar = ability.GetMiscVar("AlternativeConsume");
		CVarsContext cVarsContext = null;
		if (!miscVar.isUnknown)
		{
			CVars cVars = new CVars();
			cVars.Set("actor", new TValue(currentActorBeingRefreshed));
			cVars.Set("item", new TValue(item));
			cVarsContext = new CVarsContext(cVars);
			miscVar.Calc(cVarsContext);
		}
		else
		{
			currentActorBeingRefreshed.Inventory.UseItem(item);
		}
	}

