	[MessageHandler(CMessageData.MessageType.ActorWantsAnActionConfirmation)]
	private void Handle_ActorWantsAnActionConfirmation(CMessageData message)
	{
		CActorWantsAnActionConfirmation_MessageData cActorWantsAnActionConfirmation_MessageData = (CActorWantsAnActionConfirmation_MessageData)message;
		m_CurrentActor = cActorWantsAnActionConfirmation_MessageData.m_ActorSpawningMessage;
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		WorldspaceStarHexDisplay.Instance.LockView = false;
		WorldspaceStarHexDisplay.Instance.ClearCachedAbilityTiles();
		WorldspaceStarHexDisplay.Instance.ResetPlayerAttackType();
		GameObject gameObject = FindClientActor(m_CurrentActor);
		if (gameObject != null)
		{
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
			if (actorBehaviour != null)
			{
				actorBehaviour.UpdateWorldspaceConditionsUI();
			}
		}
		Singleton<UIUseAugmentationsBar>.Instance.Hide();
		if (cActorWantsAnActionConfirmation_MessageData.m_HideHand)
		{
			Singleton<CardsHandManager>.Instance.Hide();
		}
		bool flag = cActorWantsAnActionConfirmation_MessageData.m_Ability != null;
		m_SkipButton.Toggle(cActorWantsAnActionConfirmation_MessageData.m_CanSkip, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, !flag || cActorWantsAnActionConfirmation_MessageData.m_Ability.CanSkip);
		m_UndoButton.Toggle(cActorWantsAnActionConfirmation_MessageData.m_CanUndo);
		m_UndoButton.SetInteractable(flag && cActorWantsAnActionConfirmation_MessageData.m_Ability.CanUndo && FirstAbility);
		readyButton.ClearAlternativeAction();
		ReadyButton.EButtonState state = ReadyButton.EButtonState.EREADYBUTTONCONFIRM;
		string translation = LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION");
		if (cActorWantsAnActionConfirmation_MessageData.m_ContinueAbility)
		{
			state = ReadyButton.EButtonState.EREADYBUTTONCONTINUE;
			translation = LocalizationManager.GetTranslation("GUI_CONTINUE");
			readyButton.QueueAlternativeAction(() =>
			{
				GameState.SelectedContinueAbility();
				Singleton<UIUseAbilitiesBar>.Instance.Hide();
			});
			if (cActorWantsAnActionConfirmation_MessageData.m_ShowShadowBonuses)
			{
				Singleton<UIUseAbilitiesBar>.Instance.Hide();
				Singleton<UIUseItemsBar>.Instance.Hide();
				Singleton<UIActiveBonusBar>.Instance.Hide();
				Singleton<UIUseAugmentationsBar>.Instance.Hide();
				Singleton<UIUseAbilitiesBar>.Instance.ShowAbilityToggle(cActorWantsAnActionConfirmation_MessageData.m_ActorSpawningMessage, cActorWantsAnActionConfirmation_MessageData.m_Ability, (CAbility ab) =>
				{
					if (ab is CAbilityAttack cAbilityAttack)
					{
						cAbilityAttack.ShadowMarkTarget = true;
					}
				}, (CAbility ab) =>
				{
					if (ab is CAbilityAttack cAbilityAttack)
					{
						cAbilityAttack.ShadowMarkTarget = false;
					}
				}, LocalizationManager.GetTranslation("FH/090_character_ability_cards_deathwalker_call_to_the_abyss_2"));
				if (flag && cActorWantsAnActionConfirmation_MessageData.m_ShowHelpBox && cActorWantsAnActionConfirmation_MessageData.m_Target != null)
				{
					Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_ATTACKS_TARGET"), LocalizationManager.GetTranslation(cActorWantsAnActionConfirmation_MessageData.m_ActorSpawningMessage.ActorLocKey()), LocalizationManager.GetTranslation(cActorWantsAnActionConfirmation_MessageData.m_Target.ActorLocKey()), cActorWantsAnActionConfirmation_MessageData.m_Target.ID));
				}
				else
				{
					Singleton<HelpBox>.Instance.Hide();
				}
			}
			CAbility ability = cActorWantsAnActionConfirmation_MessageData.m_Ability;
			CActor actor = cActorWantsAnActionConfirmation_MessageData.m_ActorSpawningMessage;
			CItem.EItemTrigger trigger = cActorWantsAnActionConfirmation_MessageData.m_Trigger;
			CVarsContext context = cActorWantsAnActionConfirmation_MessageData.m_Context;
			if (trigger != CItem.EItemTrigger.None)
			{
				Singleton<UIUseItemsBar>.Instance.ShowItems(actor, (CItem item) => item.YMLData.Trigger.Equals(trigger) && actor.Inventory.IsItemUsable(item) && (item.YMLData.Data.CompareAbility == null || (ability != null && item.YMLData.Data.CompareAbility.CompareAbility(ability, actor))) && (item.YMLData.Data.ItemRequirements == null || item.YMLData.Data.ItemRequirements.MeetsAbilityRequirements(actor, ability, context, item)), (CItem item, bool networkActionIfOnline) =>
				{
					readyButton.ClearAlternativeAction();
					if (item.SlotState == CItem.EItemSlotState.Selected)
					{
						message.m_ActorSpawningMessage.Inventory.DeselectItem(item);
					}
					else if (item.SlotState == CItem.EItemSlotState.Useable)
					{
						message.m_ActorSpawningMessage.Inventory.SelectItem(item);
					}
					readyButton.QueueAlternativeAction(() =>
					{
						GameState.SelectedContinueAbility();
						Singleton<UIUseItemsBar>.Instance.Hide();
					});
				}, clear: true);
				if (flag && cActorWantsAnActionConfirmation_MessageData.m_ShowHelpBox)
				{
					CActor cActor = message.m_ActorSpawningMessage;
					if (cActorWantsAnActionConfirmation_MessageData.m_Target != null)
					{
						cActor = cActorWantsAnActionConfirmation_MessageData.m_Target;
					}
					Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_WILL_RECIEVE_CONDITION"), LocalizationManager.GetTranslation(cActor.ActorLocKey()), LocalizationManager.GetTranslation(cActorWantsAnActionConfirmation_MessageData.m_Ability.AbilityType.ToString())));
				}
				else
				{
					Singleton<HelpBox>.Instance.Hide();
				}
			}
		}
		readyButton.Toggle(active: true, state, translation, hideOnClick: true, glowingEffect: false, cActorWantsAnActionConfirmation_MessageData.m_ActorSpawningMessage.IsUnderMyControl(), disregardTurnControlForInteractability: true, haltActionProcessorIfDeactivated: true, cActorWantsAnActionConfirmation_MessageData.m_CustomHelpBoxTextLocKey);
		if (FFSNetwork.IsOnline)
		{
			if (!cActorWantsAnActionConfirmation_MessageData.m_ActorSpawningMessage.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ActionConfirmation);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ActionConfirmation);
			}
		}
	}

