		m_UndoButton.Toggle(cActorWantsAPerkConfirmation_MessageData.m_CanUndo);
		m_UndoButton.SetInteractable(flag && cActorWantsAPerkConfirmation_MessageData.m_Ability.CanUndo && FirstAbility);
		readyButton.ClearAlternativeAction();
		ReadyButton.EButtonState state = ReadyButton.EButtonState.EREADYBUTTONCONFIRM;
		string translation = LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION");
		if (cActorWantsAPerkConfirmation_MessageData.m_ContinueAbility)
		{
			state = ReadyButton.EButtonState.EREADYBUTTONCONTINUE;
			translation = LocalizationManager.GetTranslation("GUI_CONTINUE");
			readyButton.QueueAlternativeAction(() =>
			{
				GameState.SelectedContinueAbility();
				Singleton<UIUseAbilitiesBar>.Instance.Hide();
			});
			ScenarioRuleLibrary.YML.EPerkFlag trigger = cActorWantsAPerkConfirmation_MessageData.m_Trigger;
			Singleton<UIUseAbilitiesBar>.Instance.ShowPerkAbilities(cActorWantsAPerkConfirmation_MessageData.m_ActorSpawningMessage as CPlayerActor, trigger, null, null);
			if (flag && cActorWantsAPerkConfirmation_MessageData.m_ShowHelpBox)
			{
				Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_WILL_RECIEVE_CONDITION"), LocalizationManager.GetTranslation(message.m_ActorSpawningMessage.ActorLocKey()), LocalizationManager.GetTranslation(cActorWantsAPerkConfirmation_MessageData.m_Ability.AbilityType.ToString())));
			}
		}
		readyButton.Toggle(active: true, state, translation, hideOnClick: true, glowingEffect: false, cActorWantsAPerkConfirmation_MessageData.m_ActorSpawningMessage.IsUnderMyControl(), disregardTurnControlForInteractability: true);
		if (FFSNetwork.IsOnline)
		{
			if (!cActorWantsAPerkConfirmation_MessageData.m_ActorSpawningMessage.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ActionConfirmation);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ActionConfirmation);
			}
		}
	}

