		m_SkipButton.Toggle(cActorWantsAnAttackModifierConfirmation_MessageData.m_CanSkip, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, !flag || cActorWantsAnAttackModifierConfirmation_MessageData.m_Ability.CanSkip);
		m_UndoButton.Toggle(cActorWantsAnAttackModifierConfirmation_MessageData.m_CanUndo);
		m_UndoButton.SetInteractable(flag && cActorWantsAnAttackModifierConfirmation_MessageData.m_Ability.CanUndo && FirstAbility);
		readyButton.ClearAlternativeAction();
		ReadyButton.EButtonState state = ReadyButton.EButtonState.EREADYBUTTONCONFIRM;
		string translation = LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION");
