		{
			state = ReadyButton.EButtonState.EREADYBUTTONCONTINUE;
			translation = LocalizationManager.GetTranslation("GUI_CONTINUE");
			readyButton.QueueAlternativeAction(() =>
			{
				GameState.SelectedContinueAbility();
				Singleton<UIUseItemsBar>.Instance.Hide();
			});
			AttackModifierCard trigger = cActorWantsAnAttackModifierConfirmation_MessageData.m_Trigger;
			CPlayerActor actor = cActorWantsAnAttackModifierConfirmation_MessageData.m_ActorSpawningMessage as CPlayerActor;
			if (cActorWantsAnAttackModifierConfirmation_MessageData.m_ActorSpawningMessage is CHeroSummonActor cHeroSummonActor)
			{
				actor = cHeroSummonActor.Summoner;
			}
			Singleton<UIUseAbilitiesBar>.Instance.ShowAttackModifierOption(actor, trigger, null, null);
			if (flag && cActorWantsAnAttackModifierConfirmation_MessageData.m_ShowHelpBox)
			{
				Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_WILL_RECIEVE_CONDITION"), LocalizationManager.GetTranslation(message.m_ActorSpawningMessage.ActorLocKey()), LocalizationManager.GetTranslation(cActorWantsAnAttackModifierConfirmation_MessageData.m_Ability.AbilityType.ToString())));
			}
