		readyButton.Toggle(active: true, state, translation, hideOnClick: true, glowingEffect: false, message.m_ActorSpawningMessage.IsUnderMyControl(), disregardTurnControlForInteractability: true);
		if (FFSNetwork.IsOnline)
		{
			if (!cActorWantsAnAttackModifierConfirmation_MessageData.m_ActorSpawningMessage.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ActionConfirmation);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ActionConfirmation);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorWantsGenericConfirmation)]
	private void Handle_ActorWantsGenericConfirmation(CMessageData message)
	{
		CActorWantsGenericConfirmation_MessageData cActorWantsGenericConfirmation_MessageData = (CActorWantsGenericConfirmation_MessageData)message;
		CActor actor = cActorWantsGenericConfirmation_MessageData.m_ActorSpawningMessage;
		Action<bool> answerHandler = (bool answer) =>
		{
			if (FFSNetwork.IsOnline && actor.IsUnderMyControl())
			{
				Synchronizer.SendGameAction(GameActionType.ConfirmationBoxAnswer, ActionProcessor.CurrentPhase, validateOnServerBeforeExecuting: false, disableAutoReplication: false, actor.ID, 0, 0, 0, answer);
			}
			GameState.GenericConfirmButtonToggled = answer;
			GameState.SelectedContinueAbility();
		};
		string text = (string.IsNullOrEmpty(cActorWantsGenericConfirmation_MessageData.m_HelpBoxTextLocKey) ? null : LocalizationManager.GetTranslation(cActorWantsGenericConfirmation_MessageData.m_HelpBoxTextLocKey));
		if (cActorWantsGenericConfirmation_MessageData.m_HelpParams != null)
		{
			text = string.Format(text, cActorWantsGenericConfirmation_MessageData.m_HelpParams);
		}
		UIConfirmationBoxManager instance = Singleton<UIConfirmationBoxManager>.Instance;
		string explanation = text;
		UnityAction onActionConfirmed = () =>
		{
			answerHandler(obj: true);
		};
		UnityAction onActionCancelled = () =>
		{
			answerHandler(obj: false);
		};
		string confirmButtonKey = (string.IsNullOrEmpty(cActorWantsGenericConfirmation_MessageData.m_ConfirmButtonLocKey) ? null : cActorWantsGenericConfirmation_MessageData.m_ConfirmButtonLocKey);
		string cancelButtonKey = (string.IsNullOrEmpty(cActorWantsGenericConfirmation_MessageData.m_CancelButtonLocKey) ? null : cActorWantsGenericConfirmation_MessageData.m_CancelButtonLocKey);
		bool showHeader = cActorWantsGenericConfirmation_MessageData.m_ShowHeader;
		instance.ShowGenericConfirmation(null, explanation, onActionConfirmed, onActionCancelled, confirmButtonKey, cancelButtonKey, null, showHeader);
		Singleton<UIConfirmationBoxManager>.Instance.SetButtonsInteraction(actor.IsUnderMyControl());
		if (FFSNetwork.IsOnline)
		{
			if (!actor.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessOneAndSwitchBack, ActionPhaseType.ActionConfirmation);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ActionConfirmation);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.Immunity)]
	private void Handle_Immunity(CMessageData message)
	{
		CImmunity_MessageData cImmunity_MessageData = (CImmunity_MessageData)message;
		string arg = LocalizationManager.GetTranslation(cImmunity_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cImmunity_MessageData.m_ActorSpawningMessage);
		string text = "";
		bool isItem;
		if (cImmunity_MessageData.negativeCondition != CCondition.ENegativeCondition.NA)
		{
			text = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_IMMUNE"), LocalizationNameConverter.MultiLookupLocalization(cImmunity_MessageData.m_ImmunityAbility.BaseCard.Name, out isItem), string.Format("<b>{0}</b>", " " + LocalizationManager.GetTranslation(cImmunity_MessageData.negativeCondition.ToString()) + " <sprite name=" + cImmunity_MessageData.negativeCondition.ToString() + ">"), arg);
		}
		else if (cImmunity_MessageData.positiveCondition != CCondition.EPositiveCondition.NA)
		{
			text = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_IMMUNE"), LocalizationNameConverter.MultiLookupLocalization(cImmunity_MessageData.m_ImmunityAbility.BaseCard.Name, out isItem), string.Format("<b>{0}</b>", " " + LocalizationManager.GetTranslation(cImmunity_MessageData.positiveCondition.ToString()) + " <sprite name=" + cImmunity_MessageData.positiveCondition.ToString() + ">"), arg);
		}
		Singleton<CombatLogHandler>.Instance.AddLog(text, CombatLogFilter.CONDITIONS);
	}

	[MessageHandler(CMessageData.MessageType.ActorIsSelectingTargetingFocus)]
	private void Handle_ActorIsSelectingTargetingFocus(CMessageData message)
	{
		CActorIsSelectingTargetingFocus_MessageData messageData = (CActorIsSelectingTargetingFocus_MessageData)message;
		bool flag = message.m_ActorSpawningMessage.Type == CActor.EType.Player && !messageData.m_TargetingAbility.AutoTrigger;
		using (new CActiveBonus.ActiveBonusCalculationScope())
		{
			ClearAllActorEvents();
			DisableTileSelection(active: false);
			TileBehaviour.SetCallback(TileHandler);
			m_CurrentActor = messageData.m_ActorSpawningMessage;
			SetChoreographerState(ChoreographerStateType.Play, 0, null);
			ShowAbilityHelpBoxTooltip(messageData.m_TargetingAbility);
			if (flag && messageData.m_ActorSpawningMessage is CPlayerActor cPlayerActor && Singleton<CardsHandManager>.Instance.IsShown && !Singleton<CardsHandManager>.Instance.IsShowingPlayerHand(cPlayerActor) && messageData.m_TargetingAbility.GetAbilityBaseCard() != null && messageData.m_TargetingAbility.GetAbilityBaseCard().CardType != CBaseCard.ECardType.Dummy)
			{
				Singleton<CardsHandManager>.Instance.Show(cPlayerActor, CardHandMode.ActionSelection, GameState.IsPerformingCardOutOfPhase ? CardPileType.SelectedAbilityCardsOutOfPhase : ((!cPlayerActor.IsTakingExtraTurn) ? CardPileType.Round : CardPileType.ExtraTurn), CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.NONE);
			}
			if (!m_FollowCameraDisabled)
			{
				CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
			}
			foreach (GameObject clientActorObject in ClientActorObjects)
			{
				if (!(clientActorObject == null))
				{
					ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(clientActorObject);
					CTile item = ScenarioManager.Tiles[actorBehaviour.Actor.ArrayIndex.X, actorBehaviour.Actor.ArrayIndex.Y];
					if (!messageData.m_TargetingAbility.TilesSelected.Contains(item))
					{
						actorBehaviour.m_WorldspacePanelUI?.ResetPreview();
					}
				}
			}
			if (messageData.m_TargetingAbility.AreaEffect != null)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForAreaAttackFocusSelection, 0, null);
				WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_TargetingAbility, WorldspaceStarHexDisplay.EAbilityDisplayType.AreaOfEffect);
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
				GUIInterface.s_GUIInterface.SetStatusText("Set Area Effect position/rotation");
			}
			else
			{
				if (messageData.m_ObjectiveRelated)
				{
					WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_TargetingAbility, WorldspaceStarHexDisplay.EAbilityDisplayType.ObjectiveAbility);
				}
				else if (messageData.m_IsPositive)
				{
					WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_TargetingAbility, WorldspaceStarHexDisplay.EAbilityDisplayType.TargetingAbility);
				}
				else
				{
					WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_TargetingAbility, WorldspaceStarHexDisplay.EAbilityDisplayType.NegativeAbility);
				}
				WorldspaceStarHexDisplay.Instance.LockView = false;
				WorldspaceStarHexDisplay.Instance.ClearCachedAbilityTiles();
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
				WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
				if (!m_FollowCameraDisabled && !messageData.m_TargetingAbility.GetMiscVar("DontMoveCamera").GetBool())
				{
					GameObject target = FindClientActorGameObject((messageData.m_CameraFocusActor != null) ? messageData.m_CameraFocusActor : messageData.m_ActorSpawningMessage);
					CameraController.s_CameraController.SmartFocus(target, pauseDuringTransition: true);
					CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
				}
				if (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Heal)
				{
					if (flag)
					{
						GUIInterface.s_GUIInterface.SetStatusText("Select target to heal");
						WorldspacePanelUIController.RefreshHealPreviews(messageData.m_TargetingAbility as CAbilityHeal, messageData.m_ActorSpawningMessage);
					}
					else
					{
						Singleton<HelpBox>.Instance.Hide();
						GUIInterface.s_GUIInterface.SetStatusText("Monster trying to heal target with strength = " + messageData.m_TargetingAbility.ModifiedStrength());
					}
				}
				else if (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Kill)
				{
					foreach (CEnemyActor enemy in ScenarioManager.Scenario.Enemies)
					{
						ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(enemy)).m_WorldspacePanelUI?.ResetDamagePreview(0);
					}
				}
				else if (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.AddDoom)
				{
					Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_ADD_DOOM"), string.Format("<color=#{0}>{1}</color>", UIInfoTools.Instance.GetCharacterHexColor(ECharacter.Doomstalker), LocalizationManager.GetTranslation("ChooseAbility")));
					foreach (CActor item2 in messageData.m_TargetingAbility.ValidActorsInRange)
					{
						ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(item2)).m_WorldspacePanelUI?.OnSelectingDoomFocus(messageData.m_TargetingAbility);
					}
				}
				else if (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.TransferDooms)
				{
					Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_TRANSFER_DOOM"), $"<color=#{UIInfoTools.Instance.GetCharacterHexColor(ECharacter.Doomstalker)}>{LocalizationManager.GetTranslation(messageData.m_TargetingAbility.GetAbilityBaseCard().Name)}</color>");
					foreach (CActor item3 in messageData.m_TargetingAbility.ValidActorsInRange)
					{
						ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(item3)).m_WorldspacePanelUI?.OnSelectingDoomFocus(messageData.m_TargetingAbility);
					}
				}
				else if (messageData.m_TargetingAbility.AbilityType != CAbility.EAbilityType.Swap)
				{
					if (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.RemoveConditions)
					{
						if (messageData.m_TargetingAbility.Strength == -1)
						{
							if (messageData.m_TargetingAbility.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
							{
								ShowAbilityHelpBoxTooltip(messageData.m_TargetingAbility);
							}
							else if (messageData.m_TargetingAbility.AbilityFilter.HasTargetTypeFlag(CAbilityFilter.EFilterTargetType.Ally, exclusive: true))
							{
								Singleton<HelpBox>.Instance.Show("FH/GUI_TOOLTIP_REMOVE_CONDITIONS_ALLY", messageData.m_TargetingAbility);
							}
							else
							{
								Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_REMOVE_CONDITIONS", messageData.m_TargetingAbility);
							}
						}
					}
					else if (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Choose)
					{
						foreach (CActor item4 in messageData.m_TargetingAbility.ValidActorsInRange)
						{
							ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(item4)).m_WorldspacePanelUI?.Focus(focus: true);
						}
						if (messageData.m_TargetingAbility.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
						{
							ShowAbilityHelpBoxTooltip(messageData.m_TargetingAbility);
						}
						else if (messageData.m_TargetingAbility.PerkID != null)
						{
							Singleton<HelpBox>.Instance.Show($"GUI_CHOOSE_ABILITY_TARGET_{messageData.m_TargetingAbility.PerkID}", messageData.m_TargetingAbility);
						}
						else
						{
							string text = messageData.m_TargetingAbility.GetAbilityBaseCard().Name;
							if (!string.IsNullOrEmpty(text) && messageData.m_TargetingAbility.GetAbilityBaseCard().CardType != CBaseCard.ECardType.Dummy)
							{
								Singleton<HelpBox>.Instance.Show($"GUI_CHOOSE_ABILITY_TARGET_{text}", messageData.m_TargetingAbility);
							}
						}
					}
					else if (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Loot)
					{
						if (((CAbilityLoot)messageData.m_TargetingAbility).HasPassedState(CAbilityLoot.ELootState.LootTiles))
						{
							Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_TAKE_QUEST_ITEM", messageData.m_TargetingAbility);
						}
					}
					else if (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Bless || messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Strengthen || messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Wound || messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Ward || messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Regenerate || messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Push || messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Pull)
					{
						CAbility targetingAbility = messageData.m_TargetingAbility;
						foreach (CActor item5 in targetingAbility.ValidActorsInRange)
						{
							ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(item5))?.m_WorldspacePanelUI?.PreviewEffects(targetingAbility, item5);
						}
					}
					else if (messageData.m_TargetingAbility is CAbilityModeTransfer cAbilityModeTransfer)
					{
						if (cAbilityModeTransfer.m_State == CAbilityModeTransfer.EModeTransferState.SelectTargetSummon)
						{
							Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_MODE_CHOOSE_SUMMON_TO_KILL", messageData.m_TargetingAbility);
						}
					}
					else
					{
						ShowAbilityHelpBoxTooltip(messageData.m_TargetingAbility);
					}
				}
			}
		}
		TryShowAbilityInvalidTile(messageData.m_TargetingAbility);
		if (messageData.m_TargetingAbility.GetMiscVar("NoButtons").GetBool())
		{
			m_UndoButton.Toggle(active: false);
			m_SkipButton.Toggle(active: false);
			readyButton.Toggle(active: false);
		}
		else
		{
			if (!messageData.m_TargetingAbility.CanUndo || !FirstAbility)
			{
				m_UndoButton.Toggle(active: false);
			}
			CAbility.EAbilityType abilityType = messageData.m_TargetingAbility.AbilityType;
			m_SkipButton.Toggle(flag, LocalizationManager.GetTranslation(abilityType switch
			{
				CAbility.EAbilityType.Push => "GUI_SKIP_PUSH", 
				CAbility.EAbilityType.Pull => "GUI_SKIP_PULL", 
				_ => "GUI_SKIP_ABILITY", 
			}), hideOnClick: true, messageData.m_TargetingAbility.CanSkip);
			if (messageData.m_TargetingAbility.GetMiscVar("NoReadyButton").GetBool())
			{
				readyButton.Toggle(active: false);
			}
			else
			{
				ReadyButton.EButtonState state;
				string text2;
				bool interactable;
				if (messageData.m_TargetingAbility.AreaEffect != null)
				{
					state = ((messageData.m_TargetingAbility.ActorsToTarget.Count > 0) ? ReadyButton.EButtonState.EREADYBUTTONCONFIRM : ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED);
					text2 = LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION");
					interactable = messageData.m_TargetingAbility.AbilityType != CAbility.EAbilityType.Disarm && messageData.m_TargetingAbility.CanBePerformed();
				}
				else
				{
					interactable = messageData.m_TargetingAbility.CanBePerformed();
					text2 = AbilityConfirmTargetText(messageData.m_TargetingAbility);
					state = ((messageData.m_TargetingAbility.ActorsToTarget.Count > 0 && (messageData.m_TargetingAbility.EnoughTargetsSelected() || (messageData.m_TargetingAbility is CAbilityLoot cAbilityLoot && cAbilityLoot.HasPassedState(CAbilityLoot.ELootState.LootTiles))) && (messageData.m_TargetingAbility.AbilityType != CAbility.EAbilityType.Push || (messageData.m_TargetingAbility.AbilityType == CAbility.EAbilityType.Push && messageData.m_TargetingAbility.ActorsToTarget.Count == 1))) ? ReadyButton.EButtonState.EREADYBUTTONCONFIRM : ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED);
				}
				readyButton.Toggle(flag, state, text2, hideOnClick: true, glowingEffect: true, interactable);
			}
		}
		if (messageData.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			CardsActionControlller.s_Instance.RefreshConsumeBar(messageData.m_ActorSpawningMessage, messageData.m_TargetingAbility);
		}
		if (message.m_ActorSpawningMessage is CPlayerActor)
		{
			Singleton<UIUseItemsBar>.Instance.ShowUsableItems(message.m_ActorSpawningMessage, (CItem cItem) => cItem.YMLData.Data.CompareAbility != null && cItem.YMLData.Data.CompareAbility.CompareAbility(messageData.m_TargetingAbility));
			Singleton<UIUseAbilitiesBar>.Instance.Hide();
		}
		if (message.m_ActorSpawningMessage is CPlayerActor)
		{
			Singleton<UIUseItemsBar>.Instance.ShowUsableItems(message.m_ActorSpawningMessage, (CItem cItem) => cItem.YMLData.Data.CompareAbility != null && cItem.YMLData.Data.CompareAbility.CompareAbility(messageData.m_TargetingAbility));
			Singleton<UIUseAbilitiesBar>.Instance.Hide();
		}
		if (FFSNetwork.IsOnline & flag)
		{
			if (!message.m_ActorSpawningMessage.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.TargetSelection);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.TargetSelection);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorIsSelectingDamageFocus)]
	private void Handle_ActorIsSelectingDamageFocus(CMessageData message)
	{
		CActorIsSelectingDamageFocus_MessageData cActorIsSelectingDamageFocus_MessageData = (CActorIsSelectingDamageFocus_MessageData)message;
		DisableTileSelection(active: false);
		m_CurrentActor = cActorIsSelectingDamageFocus_MessageData.m_ActorSpawningMessage;
		m_CurrentAbility = cActorIsSelectingDamageFocus_MessageData.m_DamageAbility;
		bool flag = message.m_ActorSpawningMessage.Type == CActor.EType.Player;
		if (cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.ValidActorsInRange == null)
		{
			return;
		}
		TileBehaviour.SetCallback(TileHandler);
		m_SkipButton.Toggle(flag, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.CanSkip);
		int count = cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.ActorsToTarget.Count;
		int numberTargets = cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.NumberTargets;
		string text = ((numberTargets == 1 || numberTargets >= 99) ? LocalizationManager.GetTranslation("GUI_CONFIRM_TARGETS") : string.Format("{0} {1}/{2}", LocalizationManager.GetTranslation("GUI_CONFIRM_TARGETS"), count, numberTargets));
		ReadyButton.EButtonState state = ((count > 0) ? ReadyButton.EButtonState.EREADYBUTTONCONFIRM : ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED);
		readyButton.Toggle(flag, state, text, hideOnClick: true, glowingEffect: true);
		if (flag && !cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.AllTargets && cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.ActorsToTarget.Count > 0)
		{
			m_UndoButton.Toggle(active: true, UndoButton.EButtonState.EUNDOBUTTONCLEARTARGETS, LocalizationManager.GetTranslation("GUI_CLEARTARGETS"));
		}
		else
		{
			m_UndoButton.Toggle(FirstAbility && cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.CanUndo, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
		}
		WorldspaceStarHexDisplay.Instance.SetDisplayAbility(cActorIsSelectingDamageFocus_MessageData.m_DamageAbility, (cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.AreaEffect == null) ? WorldspaceStarHexDisplay.EAbilityDisplayType.Normal : WorldspaceStarHexDisplay.EAbilityDisplayType.AreaOfEffect);
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
		WaitingForConfirm = true;
		int targetIndex = 0;
		foreach (GameObject clientActorObject in ClientActorObjects)
		{
			if (!(clientActorObject == null))
			{
				ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(clientActorObject);
				CActor actor = actorBehaviour.Actor;
				if (!cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.ValidActorsInRange.Contains(actor))
				{
					actorBehaviour.m_WorldspacePanelUI?.ResetPreview();
					continue;
				}
				CAttackSummary.TargetSummary damageSummary = cActorIsSelectingDamageFocus_MessageData.m_DamageAbility.DamageSummary.FindTarget(actor, ref targetIndex);
				actorBehaviour.m_WorldspacePanelUI?.OnSelectingDamageFocus(cActorIsSelectingDamageFocus_MessageData.m_DamageAbility, cActorIsSelectingDamageFocus_MessageData.m_ActorSpawningMessage, damageSummary);
			}
		}
		if (FFSNetwork.IsOnline && message.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			if (!message.m_ActorSpawningMessage.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.TargetSelection);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.TargetSelection);
			}
		}
		ShowAbilityHelpBoxTooltip(cActorIsSelectingDamageFocus_MessageData.m_DamageAbility);
	}

	[MessageHandler(CMessageData.MessageType.ActorHasDamaged)]
	private void Handle_ActorHasDamaged(CMessageData message)
	{
		CActorHasDamaged_MessageData cActorHasDamaged_MessageData = (CActorHasDamaged_MessageData)message;
		if (cActorHasDamaged_MessageData.AnimOverload.Length == 0 && (cActorHasDamaged_MessageData.m_DamageAbility.UseSubAbilityTargeting || (cActorHasDamaged_MessageData.m_DamageAbility.MiscAbilityData.AutotriggerAbility.HasValue && cActorHasDamaged_MessageData.m_DamageAbility.MiscAbilityData.AutotriggerAbility.Value)))
		{
			return;
		}
		CurrentAttackTargets.Clear();
		if (cActorHasDamaged_MessageData.m_DamageAbility.ActorsToTarget == null || cActorHasDamaged_MessageData.m_DamageAbility.ActorsToTarget.Count == 0)
		{
			ScenarioRuleClient.StepComplete();
			return;
		}
		foreach (CActor item in cActorHasDamaged_MessageData.m_DamageAbility.ActorsToTarget)
		{
			GameObject gameObject = FindClientActorGameObject(item);
			if (gameObject != null)
			{
				CurrentAttackTargets.Add(gameObject);
			}
		}
		Singleton<UIUseAugmentationsBar>.Instance.Hide();
		m_UndoButton.Toggle(active: false);
		ClearAllActorEvents();
		m_ActorsBeingTargetedForVFX = new List<CActor>(cActorHasDamaged_MessageData.m_DamageAbility.ActorsToTarget);
		CurrentAttackArea.Clear();
		foreach (CTile item2 in cActorHasDamaged_MessageData.m_DamageAbility.TilesInRange)
		{
			CurrentAttackArea.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item2.m_ArrayIndex.X, item2.m_ArrayIndex.Y]);
		}
		if (cActorHasDamaged_MessageData.m_DamageAbility.NumberTargets == 1 && cActorHasDamaged_MessageData.m_DamageAbility.ActorsToTarget != null && cActorHasDamaged_MessageData.m_DamageAbility.ActorsToTarget.Count > 0 && !cActorHasDamaged_MessageData.m_DamageAbility.SkipAnim)
		{
			GameObject gameObject2 = FindClientActorGameObject(cActorHasDamaged_MessageData.m_DamageAbility.ActorsToTarget[0]);
			GameObject gameObject3 = FindClientActorGameObject(cActorHasDamaged_MessageData.m_ActorSpawningMessage);
			if (gameObject3 != null && gameObject2 != null)
			{
				StartCoroutine(RotateToFaceTarget(gameObject3, gameObject2.transform.position));
			}
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cActorHasDamaged_MessageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cActorHasDamaged_MessageData.m_DamageAbility, cActorHasDamaged_MessageData.m_ActorSpawningMessage, new List<string>
		{
			cActorHasDamaged_MessageData.AnimOverload,
			"Damage",
			cActorHasDamaged_MessageData.m_DamageAbility.IsItemAbility ? "UseItem" : ""
		}, out animationShouldPlay, out animatingActorToWaitFor);
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForDamageAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
	}

	[MessageHandler(CMessageData.MessageType.ReturnToSummoner)]
	private void Handle_ReturnToSummoner(CMessageData message)
	{
		_ = (CReturnToSummoner_MessageData)message;
		CActor actorSpawningMessage = message.m_ActorSpawningMessage;
		CHeroSummonActor summonActor = actorSpawningMessage as CHeroSummonActor;
		if (summonActor == null)
		{
			ScenarioRuleClient.StepComplete();
			return;
		}
		Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_SELECT_SUMMON_MOVEMENT", "GUI_TOOLTIP_SELECT_SUMMON_MOVEMENT_TITLE");
		m_UndoButton.Toggle(active: true, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
		m_UndoButton.SetInteractable(active: false);
		m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"));
		readyButton.ClearAlternativeAction();
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONTINUE, LocalizationManager.GetTranslation("GUI_CONFIRM_MOVEMENT"), hideOnClick: true, glowingEffect: true);
		summonActor.ReturnToSummoner = false;
		readyButton.QueueAlternativeAction(() =>
		{
			summonActor.ReturnToSummoner = true;
			readyButton.ClearAlternativeAction();
			ScenarioRuleClient.StepComplete();
		});
		if (FFSNetwork.IsOnline && !message.m_ActorSpawningMessage.IsUnderMyControl())
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ReturnToSummonerChoice);
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorBeenDamaged)]
	private void Handle_ActorBeenDamaged(CMessageData message)
	{
		CActorBeenDamaged_MessageData cActorBeenDamaged_MessageData = (CActorBeenDamaged_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(cActorBeenDamaged_MessageData.m_ActorBeingDamaged);
		if (!(gameObject != null))
		{
			return;
		}
		ActorBehaviour.UpdateHealth(gameObject, cActorBeenDamaged_MessageData.m_ActorOriginalHealth, updateUI: true);
		if (!ActorBehaviour.IsPaused(gameObject))
		{
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = cActorBeenDamaged_MessageData.m_ActorBeingDamaged;
			List<string> list = new List<string>();
			if (cActorBeenDamaged_MessageData.m_ActorWasAsleep)
			{
				list.Add("SleepWakeUp");
			}
			if (cActorBeenDamaged_MessageData.m_OverrideAnimState != null)
			{
				list.Add(cActorBeenDamaged_MessageData.m_OverrideAnimState);
			}
			CActor cActor = cActorBeenDamaged_MessageData?.m_DamageAbility?.TargetingActor;
			if (cActorBeenDamaged_MessageData.m_ActorBeingDamaged == cActor)
			{
				list.Add("Suffer");
			}
			list.Add((cActorBeenDamaged_MessageData.m_ActualDamage == 0) ? "HitMiss" : "Hit");
			if (!cActorBeenDamaged_MessageData.m_ActorBeingDamaged.IsDowned && !cActorBeenDamaged_MessageData.m_skipHitAnimation)
			{
				ProcessActorAnimation(cActorBeenDamaged_MessageData.m_DamageAbility, cActorBeenDamaged_MessageData.m_ActorBeingDamaged, list, out animationShouldPlay, out animatingActorToWaitFor, ignoreSkipAnimation: true);
			}
			if (cActorBeenDamaged_MessageData.m_DamageAbility != null)
			{
				GUIInterface.s_GUIInterface.SetStatusText("Damaging (" + (cActorBeenDamaged_MessageData.m_DamageAbility.NumberTargets - cActorBeenDamaged_MessageData.m_DamageAbility.NumberTargetsRemaining + 1) + " of " + cActorBeenDamaged_MessageData.m_DamageAbility.NumberTargets + ") target modified strength = " + cActorBeenDamaged_MessageData.m_DamageAbility.ModifiedStrength());
			}
			if (ActorsBeingTargetedForVFX != null)
			{
				ActorsBeingTargetedForVFX.Clear();
			}
		}
		if (cActorBeenDamaged_MessageData.m_DamageSourceLocKey != null)
		{
			string translation = LocalizationManager.GetTranslation(cActorBeenDamaged_MessageData.m_DamageSourceLocKey);
			string text = LocalizationManager.GetTranslation(cActorBeenDamaged_MessageData.m_ActorBeingDamaged.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cActorBeenDamaged_MessageData.m_ActorBeingDamaged);
			int? actualDamage = cActorBeenDamaged_MessageData.m_ActualDamage;
			if (cActorBeenDamaged_MessageData.m_OverrideLogMessageLocKey != null)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(cActorBeenDamaged_MessageData.m_OverrideLogMessageLocKey), text, $"<b><color=#f76767>{actualDamage}</color></b>", translation), CombatLogFilter.DAMAGE);
			}
			else
			{
				LogDamage(actualDamage.Value, text, translation, cActorBeenDamaged_MessageData.m_TreatAsScenarioEffect, cActorBeenDamaged_MessageData.m_TreatAsScenarioRule, cActorBeenDamaged_MessageData.m_TreatAsEventEffect);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.FocusCamera)]
	private void Handle_FocusCamera(CMessageData message)
	{
		StartCoroutine(FocusCamera(message));
	}

	private IEnumerator FocusCamera(CMessageData message)
	{
		CFocusCamera_MessageData messageData = (CFocusCamera_MessageData)message;
		if (messageData.m_delay > 0f)
		{
			yield return Timekeeper.instance.WaitForSeconds(messageData.m_delay);
		}
		CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[messageData.m_Point.X, messageData.m_Point.Y];
		if (cClientTile != null)
		{
			CameraController.s_CameraController.SetFocalPointGameObject(cClientTile.m_GameObject);
			if (messageData.m_Zoom.HasValue)
			{
				CameraController.s_CameraController.ZoomToPercent(messageData.m_Zoom.Value, 1f);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.Looting)]
	private void Handle_Looting(CMessageData message)
	{
		CLooting_MessageData messageData = (CLooting_MessageData)message;
		if (messageData.m_SyncMultiplayer && FFSNetwork.IsOnline)
		{
			ProcessMessage(new CWaitForMultiplayerSyncPoint_MessageData
			{
				m_OnFinish = () =>
				{
					messageData.m_SyncMultiplayer = false;
					ProcessMessage(messageData);
				}
			});
			return;
		}
		GameObject gameObject = FindClientActorGameObject(messageData.m_ActorLooting);
		if (gameObject != null)
		{
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = messageData.m_ActorLooting;
			if (messageData.m_FocusCamera)
			{
				CameraController.s_CameraController.SetFocalPointGameObject(gameObject);
			}
			ProcessActorAnimation(messageData.m_LootAbility, messageData.m_ActorLooting, new List<string> { messageData.AnimOverload, "Loot" }, out animationShouldPlay, out animatingActorToWaitFor);
			if (animatingActorToWaitFor != null)
			{
				if (Singleton<ScenarioRewardManager>.Instance.ReadyToShow)
				{
					m_BlockClientMessageProcessing = true;
					m_ShouldShowRewards = true;
					SetChoreographerState(ChoreographerStateType.WaitingForRewardsProcess, 1150, messageData.m_ActorLooting, hideHelpBox: true, !messageData.m_OutOfPhase);
				}
				else
				{
					SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
				}
			}
			List<CollectLootSMB> list = MF.GameObjectAnimatorStateBehaviours<CollectLootSMB>(gameObject);
			for (int num = 0; num < list.Count; num++)
			{
				list[num].SetActor(messageData.m_ActorLooting);
				if (messageData.m_LootAbility != null)
				{
					list[num].SetTilesToCheckForDelayedDropSMB(m_ActorObjectsToDropLootDelayed, messageData.m_ActorLooting);
				}
				list[num].SetExtraGoldFromAdditionalEffects(messageData.m_ExtraGoldFromAdditionalEffects);
			}
			if (!animationShouldPlay)
			{
				ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
			}
			if (messageData.m_LootAbility != null)
			{
				GUIInterface.s_GUIInterface.SetStatusText("Looting - Range " + messageData.m_LootAbility.Range);
			}
		}
		else if (Singleton<ScenarioRewardManager>.Instance.ReadyToShow)
		{
			m_BlockClientMessageProcessing = true;
			m_ShouldShowRewards = true;
			SetChoreographerState(ChoreographerStateType.WaitingForRewardsProcess, 1150, messageData.m_ActorLooting, hideHelpBox: true, !messageData.m_OutOfPhase);
			if (messageData.m_LootAbility != null)
			{
				GUIInterface.s_GUIInterface.SetStatusText("Looting - Range " + messageData.m_LootAbility.Range);
			}
		}
	}

	public static string AbilityConfirmTargetText(CAbility ability)
	{
		string text = ability.GetMiscVar("OverrideReadyButtonText").GetString();
		if (!string.IsNullOrEmpty(text))
		{
			return LocalizationManager.GetTranslation(text);
		}
		if (ability is CAbilityMoveTrap cAbilityMoveTrap)
		{
			text = LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION");
			if (!cAbilityMoveTrap.OneTargetAtATime)
			{
				int num = ability.NumberTargets - ability.NumberTargetsRemaining;
				int numberTargets = ability.NumberTargets;
				text = $"{text} {num}/{numberTargets}";
			}
		}
		else if (ability.AbilityType == CAbility.EAbilityType.Pull || ability.AbilityType == CAbility.EAbilityType.Push)
		{
			text = LocalizationManager.GetTranslation("GUI_CONFIRM_TARGET");
		}
		else if (ability.NumberTargets <= 1 || ability.NumberTargets >= 99 || ability.OriginalTargetCount == -1 || ability is CAbilityTargeting { OneTargetAtATime: not false })
		{
			text = LocalizationManager.GetTranslation("GUI_CONFIRM_TARGETS");
		}
		else
		{
			int num2 = ability.NumberTargets - ability.NumberTargetsRemaining;
			int numberTargets2 = ability.NumberTargets;
			text = string.Format("{0} {1}/{2}", LocalizationManager.GetTranslation("GUI_CONFIRM_TARGETS"), num2, numberTargets2);
		}
		return text;
	}

	[MessageHandler(CMessageData.MessageType.PlayerSelectedTile)]
	private void Handle_PlayerSelectedTile(CMessageData message)
	{
		CPlayerSelectedTile_MessageData cPlayerSelectedTile_MessageData = (CPlayerSelectedTile_MessageData)message;
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		bool active = message.m_ActorSpawningMessage.Type == CActor.EType.Player;
		string text = AbilityConfirmTargetText(cPlayerSelectedTile_MessageData.m_Ability);
		ReadyButton.EButtonState state;
		if (cPlayerSelectedTile_MessageData.m_Ability.TilesSelected.Count > 0 || cPlayerSelectedTile_MessageData.m_Ability.AllowNoTargets())
		{
			m_SkipButton.SetInteractable(active: false);
			state = ReadyButton.EButtonState.EREADYBUTTONCONFIRMTARGETS;
			if (cPlayerSelectedTile_MessageData.m_Ability.TilesSelected.Count > 0)
			{
				m_LastSelectedTiles = new List<CClientTile>();
				foreach (CTile item2 in cPlayerSelectedTile_MessageData.m_Ability.TilesSelected)
				{
					CClientTile item = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item2.m_ArrayIndex.X, item2.m_ArrayIndex.Y];
					if (!m_LastSelectedTiles.Contains(item))
					{
						m_LastSelectedTiles.Add(item);
					}
				}
			}
		}
		else
		{
			m_SkipButton.Toggle(active, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, cPlayerSelectedTile_MessageData.m_Ability.CanSkip);
			state = ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED;
		}
		readyButton.Toggle(active: true, state, text, hideOnClick: true, glowingEffect: true);
		if (cPlayerSelectedTile_MessageData.m_ActorSpawningMessage.Type == CActor.EType.Player && cPlayerSelectedTile_MessageData.m_Ability is CAbilitySummon cAbilitySummon)
		{
			string translation = LocalizationManager.GetTranslation(cAbilitySummon.SelectedLocKey);
			Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SUMMON_SELECT_HEX"), translation), string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SUMMON"), translation));
		}
		WorldspacePanelUIController.RefreshPreviewPotentialTileSubabilities(cPlayerSelectedTile_MessageData.m_Ability);
	}

	[MessageHandler(CMessageData.MessageType.CreatingTerrain)]
	private void Handle_CreatingTerrain(CMessageData message)
	{
		CCreatingTerrain_MessageData cCreatingTerrain_MessageData = (CCreatingTerrain_MessageData)message;
		ClearAllActorEvents();
		ActorsBeingTargetedForVFX?.Clear();
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cCreatingTerrain_MessageData.m_ActorCreatingTerrain;
		ProcessActorAnimation(cCreatingTerrain_MessageData.m_Ability, cCreatingTerrain_MessageData.m_ActorCreatingTerrain, new List<string>
		{
			cCreatingTerrain_MessageData.AnimOverload,
			GetNonOverloadAnim(cCreatingTerrain_MessageData.m_Ability)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		if (cCreatingTerrain_MessageData.m_Tiles != null)
		{
			m_lastSelectedTile = null;
			m_LastSelectedTiles = cCreatingTerrain_MessageData.m_Tiles.Select((CTile cTile) => ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cTile.m_ArrayIndex.X, cTile.m_ArrayIndex.Y]).ToList();
		}
		GameObject go = FindClientActorGameObject(cCreatingTerrain_MessageData.m_ActorCreatingTerrain);
		StartCoroutine(RotateToFaceTarget(go, m_LastSelectedTiles[0].m_GameObject.transform.position));
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(go).ProgressChoreographer();
		}
		GUIInterface.s_GUIInterface.SetStatusText("Creating Terrain");
	}

	[MessageHandler(CMessageData.MessageType.PlacingTrap)]
	private void Handle_PlacingTrap(CMessageData message)
	{
		CPlacingTrap_MessageData cPlacingTrap_MessageData = (CPlacingTrap_MessageData)message;
		ClearAllActorEvents();
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cPlacingTrap_MessageData.m_ActorPlacingTrap;
		ProcessActorAnimation(cPlacingTrap_MessageData.m_TrapAbility, cPlacingTrap_MessageData.m_ActorPlacingTrap, new List<string>
		{
			cPlacingTrap_MessageData.AnimOverload,
			GetNonOverloadAnim(cPlacingTrap_MessageData.m_TrapAbility)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		GameObject go = FindClientActorGameObject(cPlacingTrap_MessageData.m_ActorPlacingTrap);
		m_lastSelectedTile = null;
		m_LastSelectedTiles = cPlacingTrap_MessageData.m_Tiles?.Select((CTile t) => ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[t.m_ArrayIndex.X, t.m_ArrayIndex.Y]).ToList();
		if (m_LastSelectedTiles != null)
		{
			Vector3 zero = Vector3.zero;
			foreach (CClientTile lastSelectedTile in m_LastSelectedTiles)
			{
				zero += lastSelectedTile.m_GameObject.transform.position;
			}
			zero /= (float)m_LastSelectedTiles.Count;
			StartCoroutine(RotateToFaceTarget(go, zero));
		}
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(go).ProgressChoreographer();
		}
		GUIInterface.s_GUIInterface.SetStatusText("Placing Trap");
	}

	[MessageHandler(CMessageData.MessageType.DisarmTrap)]
	private void Handle_DisarmTrap(CMessageData message)
	{
		CDisarmTrap_MessageData cDisarmTrap_MessageData = (CDisarmTrap_MessageData)message;
		ClearAllActorEvents();
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cDisarmTrap_MessageData.m_ActorDisarmingTrap;
		ProcessActorAnimation(cDisarmTrap_MessageData.m_DisarmTrapAbility, cDisarmTrap_MessageData.m_ActorDisarmingTrap, new List<string>
		{
			cDisarmTrap_MessageData.AnimOverload,
			GetNonOverloadAnim(cDisarmTrap_MessageData.m_DisarmTrapAbility)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		if (cDisarmTrap_MessageData.m_Tiles != null && cDisarmTrap_MessageData.m_Tiles.Count > 0)
		{
			m_lastSelectedTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cDisarmTrap_MessageData.m_Tiles.Last().m_ArrayIndex.X, cDisarmTrap_MessageData.m_Tiles.Last().m_ArrayIndex.Y];
			if (m_LastSelectedTiles == null)
			{
				m_LastSelectedTiles = new List<CClientTile>();
			}
			foreach (CTile tile in cDisarmTrap_MessageData.m_Tiles)
			{
				m_LastSelectedTiles.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[tile.m_ArrayIndex.X, tile.m_ArrayIndex.Y]);
			}
		}
		WorldspaceStarHexDisplay.Instance.ClearNonTargetHexHighlights(null, cDisarmTrap_MessageData.m_Tiles);
		GameObject gameObject = FindClientActorGameObject(cDisarmTrap_MessageData.m_ActorDisarmingTrap);
		if (gameObject != null && cDisarmTrap_MessageData.m_Tiles != null)
		{
			Vector3 zero = Vector3.zero;
			foreach (CTile tile2 in cDisarmTrap_MessageData.m_Tiles)
			{
				CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[tile2.m_ArrayIndex.X, tile2.m_ArrayIndex.Y];
				zero += cClientTile.m_GameObject.transform.position;
			}
			zero /= (float)cDisarmTrap_MessageData.m_Tiles.Count;
			StartCoroutine(RotateToFaceTarget(gameObject, zero));
		}
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
