	[MessageHandler(CMessageData.MessageType.DestroyProp)]
	private void Handle_DestroyProp(CMessageData message)
	{
		if (EnvironmentLoader.Instance == null || !EnvironmentLoader.Instance.IsLoadingComplete)
		{
			StartCoroutine(RetryWhenEnvironmentIsReady());
			return;
		}
		CDestroyProp_MessageData cDestroyProp_MessageData = (CDestroyProp_MessageData)message;
		if (cDestroyProp_MessageData.m_DestroyDelay > 0f)
		{
			StartCoroutine(DestroyPropDelayedCoro(cDestroyProp_MessageData.m_DestroyDelay, cDestroyProp_MessageData.m_Prop, cDestroyProp_MessageData.m_PropTile, cDestroyProp_MessageData.m_ForceDestroy));
		}
		else
		{
			DestroyPropImmediate(cDestroyProp_MessageData.m_Prop, cDestroyProp_MessageData.m_PropTile, cDestroyProp_MessageData.m_ForceDestroy);
		}
		IEnumerator RetryWhenEnvironmentIsReady()
		{
			while (EnvironmentLoader.Instance == null || !EnvironmentLoader.Instance.IsLoadingComplete)
			{
				yield return null;
			}
			Handle_DestroyProp(message);
		}
	}

	[MessageHandler(CMessageData.MessageType.DestroyingObstacle)]
	private void Handle_DestroyingObstacle(CMessageData message)
	{
		CDestroyingObstacle_MessageData cDestroyingObstacle_MessageData = (CDestroyingObstacle_MessageData)message;
		CActor animatingActorToWaitFor = cDestroyingObstacle_MessageData.m_ActorDestroyingObstacle;
		bool animationShouldPlay = false;
		GameObject gameObject = FindClientActorGameObject(cDestroyingObstacle_MessageData.m_ActorDestroyingObstacle);
		if (animatingActorToWaitFor != null)
		{
			ClearAllActorEvents();
			m_CurrentAttackTargets?.Clear();
			m_ActorsBeingTargetedForVFX?.Clear();
			if ((cDestroyingObstacle_MessageData.m_ActorDestroyingObstacle.Type != CActor.EType.Player || cDestroyingObstacle_MessageData.m_OverrideSetLastSelectedTile) && cDestroyingObstacle_MessageData.m_Tiles != null)
			{
				m_lastSelectedTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cDestroyingObstacle_MessageData.m_Tiles[0].m_ArrayIndex.X, cDestroyingObstacle_MessageData.m_Tiles[0].m_ArrayIndex.Y];
				if (cDestroyingObstacle_MessageData.m_OverrideSetLastSelectedTile)
				{
					m_LastSelectedTiles?.Clear();
					m_LastSelectedTiles?.Add(m_lastSelectedTile);
				}
			}
			WorldspaceStarHexDisplay.Instance.ClearNonTargetHexHighlights(null, null, m_LastSelectedTiles ?? new List<CClientTile>());
			ProcessActorAnimation(cDestroyingObstacle_MessageData.m_DestroyObstacleAbility, cDestroyingObstacle_MessageData.m_ActorDestroyingObstacle, new List<string>
			{
				cDestroyingObstacle_MessageData.AnimOverload,
				GetNonOverloadAnim(cDestroyingObstacle_MessageData.m_DestroyObstacleAbility)
			}, out animationShouldPlay, out animatingActorToWaitFor);
			if (cDestroyingObstacle_MessageData.m_FaceObstacle && gameObject != null && cDestroyingObstacle_MessageData.m_Tiles != null)
			{
				Vector3 zero = Vector3.zero;
				foreach (CTile tile in cDestroyingObstacle_MessageData.m_Tiles)
				{
					zero += ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[tile.m_ArrayIndex.X, tile.m_ArrayIndex.Y].m_GameObject.transform.position;
				}
				zero /= (float)cDestroyingObstacle_MessageData.m_Tiles.Count;
				StartCoroutine(RotateToFaceTarget(gameObject, zero));
			}
		}
		if (animatingActorToWaitFor != null && (m_WaitState == null || m_WaitState.m_State != ChoreographerStateType.WaitingForEndAbilityAnimSync))
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay && gameObject != null)
		{
			ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
		}
		GUIInterface.s_GUIInterface.SetStatusText("Destroying Obstacle");
	}

	[MessageHandler(CMessageData.MessageType.DestroyObstacle)]
	private void Handle_DestroyObstacle(CMessageData message)
	{
		CDestroyObstacle_MessageData cDestroyObstacle_MessageData = (CDestroyObstacle_MessageData)message;
		_ = cDestroyObstacle_MessageData.m_ActorDestroyingObstacle;
		FindClientActorGameObject(cDestroyObstacle_MessageData.m_ActorDestroyingObstacle);
		foreach (CObjectProp destroyedProp in cDestroyObstacle_MessageData.m_DestroyedProps)
		{
			if (cDestroyObstacle_MessageData.m_DestroyDelay > 0f)
			{
				StartCoroutine(DestroyPropDelayedCoro(cDestroyObstacle_MessageData.m_DestroyDelay, destroyedProp));
			}
			else
			{
				DestroyPropImmediate(destroyedProp);
			}
		}
		GUIInterface.s_GUIInterface.SetStatusText("Destroy Obstacle");
	}

	private void SpawnProjectile(GameObject from, GameObject to, string settingsName, GameObject caster = null)
	{
		FireSpawnedProjectile[] componentsInChildren = from.GetComponentsInChildren<FireSpawnedProjectile>();
		foreach (FireSpawnedProjectile fireSpawnedProjectile in componentsInChildren)
		{
			if (!(fireSpawnedProjectile.gameObject.name != settingsName))
			{
				fireSpawnedProjectile.Fire(from, to, caster);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.SpawnProjectiles)]
	private void Handle_SpawnProjectiles(CMessageData message)
	{
		CSpawnProjectiles_MessageData cSpawnProjectiles_MessageData = (CSpawnProjectiles_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(cSpawnProjectiles_MessageData.m_TargetActor);
		if (gameObject == null)
		{
			return;
		}
		foreach (CObjectProp fromProp in cSpawnProjectiles_MessageData.m_FromProps)
		{
			GameObject gameObject2 = FindPropGameObject(fromProp);
			if (!(gameObject2 == null))
			{
				SpawnProjectile(gameObject2, gameObject, cSpawnProjectiles_MessageData.projectileSettingsName);
			}
		}
	}

