	[MessageHandler(CMessageData.MessageType.PreventDamageTriggered)]
	private void Handle_PreventDamageTriggered(CMessageData message)
	{
		CPreventDamageTriggered_MessageData cPreventDamageTriggered_MessageData = (CPreventDamageTriggered_MessageData)message;
		CBaseCard preventDamageBaseCard = cPreventDamageTriggered_MessageData.m_PreventDamageBaseCard;
		if (preventDamageBaseCard != null)
		{
			if (preventDamageBaseCard is CItem cItem && cItem.YMLData.Data.ShieldValue > 0 && cItem.YMLData.Data.ShieldValue < int.MaxValue)
			{
				string arg = LocalizationManager.GetTranslation(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage);
				if (cPreventDamageTriggered_MessageData.m_DamageAbility is CAbilityAttack)
				{
					SEventAbilityAttack sEventAbilityAttack = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilityAttack>(onlyUnprocessed: false, CAbility.EAbilityType.Attack, ESESubTypeAbility.None, checkQueue: true);
					SEventAttackModifier sEventAttackModifier = SEventLog.FindLastAttackModifierEventWithID(onlyUnprocessed: false, cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.ID, cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.Class.ID, toScrape: false, checkQueue: true);
					if (sEventAttackModifier == null && cPreventDamageTriggered_MessageData.m_DamageAbility.ActorsTargeted.Contains(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage))
					{
						int attackIndex = cPreventDamageTriggered_MessageData.m_DamageAbility.ActorsTargeted.IndexOf(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage);
						sEventAttackModifier = SEventLog.FindLastAttackModifierEventWithID(onlyUnprocessed: false, cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.ID, cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.Class.ID, toScrape: false, checkQueue: true, attackIndex);
					}
					if (sEventAbilityAttack != null && sEventAttackModifier != null)
					{
						LogDamageCalculation(sEventAbilityAttack, sEventAttackModifier, cPreventDamageTriggered_MessageData.m_DamageAbility.TargetingActor, cPreventDamageTriggered_MessageData.m_ActorSpawningMessage, cPreventDamageTriggered_MessageData.m_DamageAbility);
					}
				}
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_PREVENT_DAMAGE_AMOUNT"), arg, (cPreventDamageTriggered_MessageData.m_OverridePreventedDamage != -1) ? cPreventDamageTriggered_MessageData.m_OverridePreventedDamage : cItem.YMLData.Data.ShieldValue, $"<b>{LocalizationManager.GetTranslation(cItem.YMLData.Name)}</b>"), CombatLogFilter.ITEMS);
				return;
			}
			CActiveBonus cActiveBonus = preventDamageBaseCard.ActiveBonuses.FirstOrDefault((CActiveBonus a) => a.Ability.ActiveBonusData.HasBehaviour(CActiveBonus.EActiveBonusBehaviourType.ShieldIncomingAttacks, CActiveBonus.EActiveBonusBehaviourType.PreventPartialDamage));
			if (cActiveBonus != null)
			{
				string arg2 = LocalizationManager.GetTranslation(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage);
				string translation = LocalizationManager.GetTranslation(preventDamageBaseCard.Name, fixForRTL: true, 0, ignoreRTLnumbers: true, applyParameters: false, null, null, skipWarnings: true, useDefaultIfMissing: false, returnNullIfNotFound: true);
				if (translation == null)
				{
					translation = LocalizationManager.GetTranslation("Innate");
				}
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_PREVENT_DAMAGE_AMOUNT"), arg2, (cPreventDamageTriggered_MessageData.m_OverridePreventedDamage != -1) ? cPreventDamageTriggered_MessageData.m_OverridePreventedDamage : cActiveBonus.Ability.Strength, $"<b>{translation}</b>"), CombatLogFilter.ABILITIES);
				return;
			}
			if (preventDamageBaseCard.CardType == CBaseCard.ECardType.ScenarioModifier && PhaseManager.CurrentPhase is CPhaseAction { CurrentPhaseAbility: not null } cPhaseAction && cPhaseAction.CurrentPhaseAbility.m_Ability != null && cPhaseAction.CurrentPhaseAbility.m_Ability.AbilityType == CAbility.EAbilityType.ChangeAllegiance)
			{
				string arg3 = LocalizationManager.GetTranslation(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage);
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_CHANGE_ALLEGIANCE"), arg3), CombatLogFilter.ABILITIES);
				return;
			}
			string arg4 = LocalizationManager.GetTranslation(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage);
			string translation2 = LocalizationManager.GetTranslation(preventDamageBaseCard.Name, fixForRTL: true, 0, ignoreRTLnumbers: true, applyParameters: false, null, null, skipWarnings: true, useDefaultIfMissing: false, returnNullIfNotFound: true);
			if (translation2 == null)
			{
				translation2 = LocalizationManager.GetTranslation("Innate");
			}
			if (translation2 != null)
			{
				string text = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_PREVENT_DAMAGE"), arg4, $"<b>{translation2}</b>");
				Singleton<CombatLogHandler>.Instance.AddLog(text, CombatLogFilter.ABILITIES);
			}
		}
		else
		{
			string arg5 = LocalizationManager.GetTranslation(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cPreventDamageTriggered_MessageData.m_ActorSpawningMessage);
			string translation3 = LocalizationManager.GetTranslation("Innate");
			if (translation3 != null)
			{
				string text2 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_PREVENT_DAMAGE"), arg5, $"<b>{translation3}</b>");
				Singleton<CombatLogHandler>.Instance.AddLog(text2, CombatLogFilter.ABILITIES);
			}
		}
	}

