	[MessageHandler(CMessageData.MessageType.UnpauseAura)]
	private void Handle_UnpauseAura(CMessageData message)
	{
		CUnpauseAura_MessageData cUnpauseAura_MessageData = (CUnpauseAura_MessageData)message;
		Animator animator = FindClientActorGameObject(message.m_ActorSpawningMessage)?.GetComponentInChildren<Animator>();
		if (cUnpauseAura_MessageData == null || !(animator != null))
		{
			return;
		}
		List<VFXShared.BasicEffectTyped> basicAuraEffects = new List<VFXShared.BasicEffectTyped>();
		VFXShared.HitEffectTargets hitEffectTargets = new VFXShared.HitEffectTargets(animator.gameObject);
		CBaseCard cBaseCard = cUnpauseAura_MessageData.m_ActorSpawningMessage.FindCard(cUnpauseAura_MessageData.m_AuraBaseCardID, cUnpauseAura_MessageData.m_AuraBaseCardName);
		if (cBaseCard != null && cBaseCard.ActiveBonuses.Count > 0)
		{
			CActiveBonus cActiveBonus = cBaseCard?.ActiveBonuses[0];
			if (cActiveBonus != null && VFXShared.RegisteredAuraHexEffects.Count > 0 && VFXShared.RegisteredAuraHexEffects.TryGetValue(cUnpauseAura_MessageData.m_AuraBaseCardID, out var value))
			{
				VFXShared.ProcessAuraHexEffects(cActiveBonus.Ability, value, cUnpauseAura_MessageData.m_ActorSpawningMessage, ref basicAuraEffects, ref hitEffectTargets);
				VFXShared.PlayAuraEffectsFromTimeline(basicAuraEffects, cUnpauseAura_MessageData.m_AuraBaseCardID);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorIsApplyingConditionActiveBonus)]
	private void Handle_ActorIsApplyingConditionActiveBonus(CMessageData message)
	{
		CActorIsApplyingConditionActiveBonus_MessageData cActorIsApplyingConditionActiveBonus_MessageData = (CActorIsApplyingConditionActiveBonus_MessageData)message;
		ClearAllActorEvents();
		if (cActorIsApplyingConditionActiveBonus_MessageData.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			Singleton<UIUseItemsBar>.Instance.Hide();
			Singleton<UIActiveBonusBar>.Instance.Hide();
			Singleton<UIUseAugmentationsBar>.Instance.Hide();
		}
		if (cActorIsApplyingConditionActiveBonus_MessageData.m_ActorsAppliedTo.Count > 0)
		{
			if (cActorIsApplyingConditionActiveBonus_MessageData.m_Ability.ValidTilesInAreaAffected != null && cActorIsApplyingConditionActiveBonus_MessageData.m_Ability.ValidTilesInAreaAffected.Count > 0)
			{
				CurrentAttackArea.Clear();
				foreach (CTile item in cActorIsApplyingConditionActiveBonus_MessageData.m_Ability.ValidTilesInAreaAffected)
				{
					CurrentAttackArea.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item.m_ArrayIndex.X, item.m_ArrayIndex.Y]);
				}
			}
			else
			{
				foreach (CTile item2 in cActorIsApplyingConditionActiveBonus_MessageData.m_Ability.TilesInRange)
				{
					CurrentAttackArea.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item2.m_ArrayIndex.X, item2.m_ArrayIndex.Y]);
				}
			}
			m_ActorsBeingTargetedForVFX = new List<CActor>(cActorIsApplyingConditionActiveBonus_MessageData.m_ActorsAppliedTo);
			CurrentAttackTargets.Clear();
			WorldspaceStarHexDisplay.Instance.ClearNonTargetHexHighlights(cActorIsApplyingConditionActiveBonus_MessageData.m_ActorsAppliedTo);
			GameObject gameObject = FindClientActorGameObject(cActorIsApplyingConditionActiveBonus_MessageData.m_ActorSpawningMessage);
			if (cActorIsApplyingConditionActiveBonus_MessageData.m_ActorsAppliedTo != null && cActorIsApplyingConditionActiveBonus_MessageData.m_ActorsAppliedTo.Count > 0)
			{
				Vector3 zero = Vector3.zero;
				int num = 0;
				foreach (CActor item3 in cActorIsApplyingConditionActiveBonus_MessageData.m_ActorsAppliedTo)
				{
					GameObject gameObject2 = FindClientActorGameObject(item3);
					if (gameObject2 != null)
					{
						num++;
						zero += gameObject2.transform.position;
						CurrentAttackTargets.Add(gameObject2);
					}
				}
				zero /= (float)num;
				if (FindClientActorGameObject(cActorIsApplyingConditionActiveBonus_MessageData.m_ActorSpawningMessage) != null)
				{
					StartCoroutine(RotateToFaceTarget(gameObject, zero));
				}
			}
			s_Choreographer.m_CurrentAbility = cActorIsApplyingConditionActiveBonus_MessageData.m_Ability;
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = cActorIsApplyingConditionActiveBonus_MessageData.m_ActorSpawningMessage;
			ProcessActorAnimation(cActorIsApplyingConditionActiveBonus_MessageData.m_Ability, cActorIsApplyingConditionActiveBonus_MessageData.m_ActorSpawningMessage, new List<string>
			{
				cActorIsApplyingConditionActiveBonus_MessageData.AnimOverload,
				GetNonOverloadAnim(cActorIsApplyingConditionActiveBonus_MessageData.m_Ability)
			}, out animationShouldPlay, out animatingActorToWaitFor);
			DisableButtons();
			if (animatingActorToWaitFor != null)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
			}
			if (!animationShouldPlay && !cActorIsApplyingConditionActiveBonus_MessageData.m_Ability.IsModifierAbility && gameObject != null)
			{
				ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
			}
		}
		else if (PhaseManager.CurrentPhaseAction?.CurrentPhaseAbility?.m_Ability == cActorIsApplyingConditionActiveBonus_MessageData.m_Ability)
		{
			ScenarioRuleClient.StepComplete();
		}
	}

	[MessageHandler(CMessageData.MessageType.AbilityTargetingCombatLog)]
	private void Handle_AbilityTargetingCombatLog(CMessageData message)
	{
		if (m_ActorsKilledThisAbility.Count > 0)
		{
			m_MessagesAfterKilledActors.Add(message);
			return;
		}
		CAbilityTargetingCombatLog_MessageData cAbilityTargetingCombatLog_MessageData = (CAbilityTargetingCombatLog_MessageData)message;
		if (cAbilityTargetingCombatLog_MessageData.m_Ability.ActiveBonusData.HiddenInLog)
		{
			return;
		}
		if (cAbilityTargetingCombatLog_MessageData.m_Ability is CAbilityCondition)
		{
			LogConditionApplied(cAbilityTargetingCombatLog_MessageData.m_ActorSpawningMessage, cAbilityTargetingCombatLog_MessageData.m_Ability, cAbilityTargetingCombatLog_MessageData.m_ActorsAppliedTo);
		}
		else
		{
			if (!(cAbilityTargetingCombatLog_MessageData.m_Ability is CAbilityTargeting))
			{
				return;
			}
			SEventAbility sEventAbility = SEventLog.FindLastAbilityEventOfAbilityType(onlyUnprocessed: false, cAbilityTargetingCombatLog_MessageData.m_Ability.AbilityType, toScrape: false, ESESubTypeAbility.None, checkQueue: true);
			if (sEventAbility == null)
			{
				return;
			}
			string arg = LocalizationManager.GetTranslation(cAbilityTargetingCombatLog_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cAbilityTargetingCombatLog_MessageData.m_ActorSpawningMessage);
			foreach (CActor item in cAbilityTargetingCombatLog_MessageData.m_ActorsAppliedTo)
			{
				if (TargetingAbilityTypesToSkip.Contains(sEventAbility.AbilityType))
				{
					continue;
				}
				string text = LocalizationManager.GetTranslation(item.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(item);
				string text2 = string.Empty;
				if (!TargetingAbilitySpritesToSkip.Contains(sEventAbility.AbilityType))
				{
					text2 = text2 + " <sprite name=" + HelperTools.GetCorrectSprite(sEventAbility.AbilityType) + ">";
				}
				if (cAbilityTargetingCombatLog_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.ImmunityTo)
				{
					foreach (CCondition.EPositiveCondition key in cAbilityTargetingCombatLog_MessageData.m_Ability.PositiveConditions.Keys)
					{
						text2 = text2 + " <sprite name=" + key.ToString() + ">";
					}
					foreach (CCondition.ENegativeCondition key2 in cAbilityTargetingCombatLog_MessageData.m_Ability.NegativeConditions.Keys)
					{
						text2 = text2 + " <sprite name=" + key2.ToString() + ">";
					}
				}
				switch (cAbilityTargetingCombatLog_MessageData.m_Ability.AbilityType)
				{
				case CAbility.EAbilityType.PlaySong:
					if (!m_AbilitiesUsedThisTurn.Contains(cAbilityTargetingCombatLog_MessageData.m_Ability.GetAbilityBaseCard().Name))
					{
						m_AbilitiesUsedThisTurn.Add(cAbilityTargetingCombatLog_MessageData.m_Ability.GetAbilityBaseCard().Name);
						text2 = LocalizationManager.GetTranslation(cAbilityTargetingCombatLog_MessageData.m_Ability.GetAbilityBaseCard().Name) ?? "";
						string text10 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_PLAYS"), arg, text2);
						Singleton<CombatLogHandler>.Instance.AddLog(text10, CombatLogFilter.ABILITIES);
					}
					break;
				case CAbility.EAbilityType.ChooseAbility:
				{
					string text7 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_CHOOSE_ABILITY"), arg);
					Singleton<CombatLogHandler>.Instance.AddLog(text7, CombatLogFilter.ABILITIES);
					break;
				}
				case CAbility.EAbilityType.Kill:
				{
					string text8 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_KILL"), arg, text);
					Singleton<CombatLogHandler>.Instance.AddLog(text8, CombatLogFilter.ABILITIES);
					break;
				}
				case CAbility.EAbilityType.RepeatAbility:
				case CAbility.EAbilityType.PreventLoseCard:
				case CAbility.EAbilityType.AddAttackModifier:
				case CAbility.EAbilityType.RemoveAttackModifier:
					if (!(cAbilityTargetingCombatLog_MessageData.m_Ability.GetAbilityBaseCard().Name == "DummyCardID"))
					{
						string text9 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_PLAYS"), arg, LocalizationManager.GetTranslation(cAbilityTargetingCombatLog_MessageData.m_Ability.GetAbilityBaseCard().Name));
						Singleton<CombatLogHandler>.Instance.AddLog(text9, CombatLogFilter.ABILITIES);
					}
					break;
				case CAbility.EAbilityType.GiveSupplyCard:
				{
					List<string> supplyCardNames = CAbilityGiveSupplyCard.GetSupplyCardNames(cAbilityTargetingCombatLog_MessageData.m_Ability as CAbilityGiveSupplyCard);
					string arg2 = string.Join(", ", supplyCardNames.Select((string x) => $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(x)}</color></b></font>"));
					string text6 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_GIVE_CARD"), arg, arg2, text);
					Singleton<CombatLogHandler>.Instance.AddLog(text6, CombatLogFilter.ABILITIES);
					break;
				}
				case CAbility.EAbilityType.Capture:
				{
					string text5 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_APPLY_ABILITY_CAPTURE"), arg, text);
					Singleton<CombatLogHandler>.Instance.AddLog(text5, CombatLogFilter.ABILITIES);
					break;
				}
				case CAbility.EAbilityType.ConsumeItemCards:
				case CAbility.EAbilityType.ShowNextAttackModifier:
					return;
				case CAbility.EAbilityType.SetNextAttackModifiers:
				{
					CAbilitySetNextAttackModifiers cAbilitySetNextAttackModifiers = cAbilityTargetingCombatLog_MessageData.m_Ability as CAbilitySetNextAttackModifiers;
					string text4 = string.Format(LocalizationManager.GetTranslation("$GUI_NextAttackModifier$"), 0, CreateLayout.LocaliseText(CShowNextAttackModifierActiveBonus.NextAttackModifierString(cAbilitySetNextAttackModifiers.NewNextAttackModifiers)));
					Singleton<CombatLogHandler>.Instance.AddLog(text4, CombatLogFilter.ABILITIES);
					break;
				}
				default:
				{
					string text3 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_APPLY_ABILITY"), arg, $"<b>{LocalizationManager.GetTranslation(sEventAbility.AbilityType.ToString()) + text2}</b>", text);
					Singleton<CombatLogHandler>.Instance.AddLog(text3, CombatLogFilter.CONDITIONS);
					break;
				}
				case CAbility.EAbilityType.ImprovedShortRest:
				case CAbility.EAbilityType.AdjustInitiative:
				case CAbility.EAbilityType.Choose:
				case CAbility.EAbilityType.MirrorDamage:
					break;
				}
			}
		}
	}

