	[MessageHandler(CMessageData.MessageType.Muddle)]
	private void Handle_Muddle(CMessageData message)
	{
		CMuddle_MessageData messageData = (CMuddle_MessageData)message;
		TryPlayConditionEffectOnActor(GlobalSettings.Instance.m_ActiveBonusBuffTargetEffects.GainMuddle, messageData.m_ActorToMuddle, messageData.m_ConditionAlreadyApplied, onNewlyAppliedMuddle, EffectsBar.FEffect.Muddled);
		void onNewlyAppliedMuddle()
		{
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(messageData.m_ActorToMuddle));
			if (actorBehaviour?.m_WorldspacePanelUI != null && messageData.m_ActorToMuddle.Tokens.ModifiedNegativeCondition == CCondition.ENegativeCondition.Muddle && !messageData.m_ActorToMuddle.Tokens.HasKey(CCondition.ENegativeCondition.Muddle))
			{
				List<CCondition.EPositiveCondition> newConditions = (from it in CActiveBonus.FindApplicableActiveBonuses(messageData.m_ActorToMuddle, CAbility.EAbilityType.ChangeCondition)
					where it.Ability?.MiscAbilityData?.ReplaceNegativeConditions != null && it.Ability.MiscAbilityData.ReplaceWithPositiveConditions != null && it.Ability.MiscAbilityData.ReplaceNegativeConditions.Contains(CCondition.ENegativeCondition.Muddle)
					select it.Ability.MiscAbilityData.ReplaceWithPositiveConditions[it.Ability.MiscAbilityData.ReplaceNegativeConditions.IndexOf(CCondition.ENegativeCondition.Muddle)]).ToList();
				actorBehaviour.m_WorldspacePanelUI.ReplaceCondition(EffectsBar.FEffect.Muddled, newConditions);
			}
		}
	}

