	[MessageHandler(CMessageData.MessageType.WoundTriggered)]
	private void Handle_WoundTriggered(CMessageData message)
	{
		CWoundTriggered_MessageData cWoundTriggered_MessageData = (CWoundTriggered_MessageData)message;
		GUIInterface.s_GUIInterface.SetStatusText("Wound Triggered on " + cWoundTriggered_MessageData.m_WoundedActor.GetPrefabName());
		GameObject gameObject = FindClientActorGameObject(cWoundTriggered_MessageData.m_WoundedActor);
		if (!(gameObject == null))
		{
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = cWoundTriggered_MessageData.m_WoundedActor;
			if (!cWoundTriggered_MessageData.m_WoundedActor.IsDowned)
			{
				ProcessActorAnimation(null, cWoundTriggered_MessageData.m_WoundedActor, new List<string>
				{
					cWoundTriggered_MessageData.m_ActorWasAsleep ? "SleepWakeUp" : "Hit",
					"Hit"
				}, out animationShouldPlay, out animatingActorToWaitFor);
			}
			if (animatingActorToWaitFor != null && PhaseManager.CurrentPhaseAction?.CurrentPhaseAbility == null)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
			}
			if (!animationShouldPlay)
			{
				ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
			}
			TryPlayEffect(GlobalSettings.Instance.m_MagicEffects.WoundDamage, gameObject.transform);
			ActorBehaviour.UpdateHealth(gameObject, cWoundTriggered_MessageData.m_ActorOriginalHealth, updateUI: true);
			string arg = LocalizationManager.GetTranslation(cWoundTriggered_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cWoundTriggered_MessageData.m_ActorSpawningMessage);
			int? num = cWoundTriggered_MessageData.m_ActorOriginalHealth - cWoundTriggered_MessageData.m_ActorSpawningMessage.Health;
			if (num > 0)
			{
				CombatLogHandler instance = Singleton<CombatLogHandler>.Instance;
				string translation = LocalizationManager.GetTranslation("COMBAT_LOG_WOUND_TRIGGERED");
				int? num2 = num;
				instance.AddLog(string.Format(translation, arg, string.Format("<b><color=#f76767>{0}</color></b>", num2 + " " + LocalizationManager.GetTranslation("Damage").ToLower())), CombatLogFilter.DAMAGE);
			}
		}
	}

