	[MessageHandler(CMessageData.MessageType.TargetRetaliate)]
	private void Handle_TargetRetaliate(CMessageData message)
	{
		CTargetRetaliate_MessageData cTargetRetaliate_MessageData = (CTargetRetaliate_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(cTargetRetaliate_MessageData.m_ActorBeingAttacked);
		GameObject gameObject2 = FindClientActorGameObject(cTargetRetaliate_MessageData.m_ActorAttacking);
		string arg = LocalizationManager.GetTranslation(cTargetRetaliate_MessageData.m_ActorBeingAttacked.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cTargetRetaliate_MessageData.m_ActorBeingAttacked);
		string arg2 = LocalizationManager.GetTranslation(cTargetRetaliate_MessageData.m_ActorAttacking.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cTargetRetaliate_MessageData.m_ActorAttacking);
		Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_RETALIATE"), arg, arg2, string.Format("<b>{0}</b>", LocalizationManager.GetTranslation("Retaliate") + " <sprite name=Retaliate> " + cTargetRetaliate_MessageData.m_retaliateBuff)), CombatLogFilter.ABILITIES);
		if (MF.GetGameObjectAnimator(gameObject).HasState(0, Animator.StringToHash("Retaliate")))
		{
			StartCoroutine(TargetRetaliateAnimation(cTargetRetaliate_MessageData.m_ActorBeingAttacked, gameObject, gameObject2));
			return;
		}
		Quaternion value = Quaternion.LookRotation((gameObject2.transform.position - gameObject.transform.position).normalized, gameObject.transform.up);
		Quaternion value2 = Quaternion.LookRotation((gameObject.transform.position - gameObject2.transform.position).normalized, gameObject2.transform.up);
		ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(cTargetRetaliate_MessageData.m_ActorBeingAttacked));
		if (actorBehaviour.m_WorldspacePanelUI != null)
		{
			int distanceTo = cTargetRetaliate_MessageData.m_ActorBeingAttacked.GetDistanceTo(cTargetRetaliate_MessageData.m_ActorAttacking, viaPathfinding: true);
			actorBehaviour.m_WorldspacePanelUI.RetaliateActivatedEffect(distanceTo);
		}
		TryPlayEffect(GlobalSettings.Instance.m_MagicEffects.RetaliateHit, null, gameObject.transform.position, value);
		TryPlayEffect(GlobalSettings.Instance.m_MagicEffects.RetaliateTarget, null, gameObject2.transform.position, value2);
		if (ProlongedSpawn.AreSpawnsInProgress())
		{
			m_BlockClientMessageProcessing = true;
			SetChoreographerState(ChoreographerStateType.WaitingForRetaliate, 0, null);
		}
	}

	private IEnumerator TargetRetaliateAnimation(CActor defendingActor, GameObject defendingActorGameObject, GameObject attackingActorGameObject)
	{
		bool prevBlockMessageProcess = m_BlockClientMessageProcessing;
		m_BlockClientMessageProcessing = true;
		int waitCount = 1000;
		while (!IsPlayingIdleAnimation(defendingActorGameObject) && waitCount-- > 0)
		{
			yield return null;
		}
		if (waitCount <= 0)
		{
			m_BlockClientMessageProcessing = false;
			Log.Error("Error couldn't handle Retaliate Animation: Endless Idle");
			yield break;
		}
		yield return StartCoroutine(RotateToFaceTarget(defendingActorGameObject, attackingActorGameObject.transform.position));
		ProcessActorAnimation(null, defendingActor, new List<string> { "Retaliate" }, out var animationShouldPlay, out var _);
		if (!animationShouldPlay)
		{
			m_BlockClientMessageProcessing = prevBlockMessageProcess;
			yield break;
		}
		waitCount = 1000;
		do
		{
			yield return null;
		}
		while (!IsPlayingIdleAnimation(defendingActorGameObject) && waitCount-- > 0);
		m_BlockClientMessageProcessing = prevBlockMessageProcess;
	}

