	private IEnumerator RedirectDamageAnimated(CRedirectDamageAnimated_MessageData messageData)
	{
		CActor actor = messageData.m_RedirectingActor;
		GameObject actorGO = FindClientActorGameObject(actor);
		bool prevBlockMessageProcess = m_BlockClientMessageProcessing;
		m_BlockClientMessageProcessing = true;
		int waitCount = 1000;
		while (!IsPlayingIdleAnimation(actorGO) && waitCount-- > 0)
		{
			yield return null;
		}
		if (waitCount <= 0)
		{
			m_BlockClientMessageProcessing = prevBlockMessageProcess;
			Log.Error("Error couldn't handle Redirect daamage Animation: Endless Idle");
			yield break;
		}
		m_ActorsBeingTargetedForVFX = new List<CActor> { messageData.m_TargetedActor };
		GameObject gameObject = FindClientActorGameObject(messageData.m_TargetedActor);
		yield return StartCoroutine(RotateToFaceTarget(actorGO, gameObject.transform.position));
		ProcessActorAnimation(null, actor, new List<string> { messageData.AnimOverload }, out var animationShouldPlay, out var _);
		if (!animationShouldPlay)
		{
			m_BlockClientMessageProcessing = prevBlockMessageProcess;
			yield break;
		}
		waitCount = 1000;
		s_PausedWhileWaiting = true;
		do
		{
			yield return null;
		}
		while (!IsPlayingIdleAnimation(actorGO) && waitCount-- > 0);
		m_BlockClientMessageProcessing = prevBlockMessageProcess;
	}

