	[MessageHandler(CMessageData.MessageType.SelectRecoverCards)]
	private void Handle_SelectRecoverCards(CMessageData message)
	{
		CSelectRecoverCards_MessageData messageData = (CSelectRecoverCards_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(messageData.m_ActorSpawningMessage);
		GameObject gameObject2 = FindClientActorGameObject(messageData.m_ActorRecoveringLostCards);
		m_ActorsBeingTargetedForVFX = new List<CActor> { messageData.m_ActorRecoveringLostCards };
		if (gameObject != gameObject2)
		{
			StartCoroutine(RotateToFaceTarget(gameObject, gameObject2.transform.position));
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = messageData.m_ActorSpawningMessage;
		ProcessActorAnimation(messageData.m_Ability, messageData.m_ActorSpawningMessage, new List<string>
		{
			messageData.AnimOverload,
			GetNonOverloadAnim(messageData.m_Ability)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		ClearStars();
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		CPlayerActor playerActor = (CPlayerActor)messageData.m_ActorRecoveringLostCards;
		CardHandMode recoverMode = ((messageData.m_Ability is CAbilityRecoverDiscardedCards) ? CardHandMode.RecoverDiscardedCard : CardHandMode.RecoverLostCard);
		CardPileType selectableCardType = ((!(messageData.m_Ability is CAbilityRecoverDiscardedCards)) ? CardPileType.Lost : CardPileType.Discarded);
		int cardsToRecover = 0;
		Func<CAbilityCard, bool> cardFilter = null;
		GetCardsToRecover(out cardsToRecover, out cardFilter);
		Singleton<CardsHandManager>.Instance.Show((CPlayerActor)messageData.m_ActorRecoveringLostCards, recoverMode, CardPileType.Any, selectableCardType, cardsToRecover, fadeUnselectableCards: true, highlightSelectableCards: true, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: false, allowFullDeckPreview: true, null, cardFilter);
		if (messageData.m_Ability.Flags.HasFlag(CAbility.EAbilityFlag.FrozenFistMechanic))
		{
			List<CActiveBonus> roundBonuses = (from ab in CharacterClassManager.FindAllActiveBonuses()
				where ab.Duration == CActiveBonus.EActiveBonusDurationType.Round && ab.BaseCard is CAbilityCard
				select ab).ToList();
			if (ReactionViewService.UseExperimental)
			{
				Singleton<FHScenarioViewController>.Instance.GetService<ReactionViewService>()?.FrozenFistOneWithTheMountain_SelectCardToRecover(playerActor, messageData.m_Ability, playerActor.CharacterClass.DiscardedAbilityCards.Where((CAbilityCard card) => cardFilter(card)).ToList(), (from bonus in roundBonuses
					select (CAbilityCard)bonus.BaseCard into card
					where cardFilter(card)
					select card).ToList());
			}
			DeselectCards();
			UpdateButtons();
			ActorBehaviour.GetActorBehaviour(gameObject2).m_WorldspacePanelUI.ResetPreview();
			if (roundBonuses.Count > 0 && !ReactionViewService.UseExperimental)
			{
				string description = LocalizationManager.GetTranslation("FH/GUI_CANCEL_ROUND_ACTIVE_BONUSES");
				Action callback = null;
				callback = () =>
				{
					string title = "";
					Singleton<UIConfirmationBoxManager>.Instance.ShowGenericConfirmation(title, description, () =>
					{
						foreach (CActiveBonus item in roundBonuses)
						{
							Singleton<CardsHandManager>.Instance.CancelActiveAbility(playerActor, (CAbilityCard)item.BaseCard);
							Singleton<CardsHandManager>.Instance.NetworkCancelingActiveBonuses(playerActor, (CAbilityCard)item.BaseCard);
						}
						GetCardsToRecover(out cardsToRecover, out cardFilter);
						Singleton<CardsHandManager>.Instance.Show(playerActor, CardHandMode.RecoverDiscardedCard, CardPileType.Any, CardPileType.Discarded, cardsToRecover, fadeUnselectableCards: true, highlightSelectableCards: true, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: false, allowFullDeckPreview: true, null, cardFilter);
						DeselectCards();
						UpdateButtons();
					}, () =>
					{
						SetupGenericButton(playerActor.IsUnderMyControl(), description, callback);
						DeselectCards();
						UpdateButtons();
					});
				};
				SetupGenericButton(playerActor.IsUnderMyControl(), description, callback);
			}
		}
		else
		{
			SetReadyButtonEndSelection(active: false);
			m_SkipButton.Toggle(active: false);
		}
		m_UndoButton.Toggle(active: false);
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, messageData.m_ActorSpawningMessage);
		string text = string.Empty;
		if (m_CurrentAbility != null)
		{
			text = m_CurrentAbility.GetVar("OverrideCardSelectionKey").GetString();
		}
		if (!string.IsNullOrEmpty(text))
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation(text));
		}
		else if (recoverMode == CardHandMode.RecoverDiscardedCard)
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated((cardsToRecover > 1) ? string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_RECOVER_DISCARDED_CARDS"), cardsToRecover) : LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_RECOVER_DISCARDED_CARD"));
		}
		else if (recoverMode == CardHandMode.RecoverLostCard)
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated((cardsToRecover > 1) ? string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_RECOVER_LOST_CARDS"), cardsToRecover) : LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_RECOVER_LOST_CARD"));
		}
		if (FFSNetwork.IsOnline)
		{
			if (!playerActor.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.CardRecovery);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.CardRecovery);
			}
		}
		void DeselectCards()
		{
			Singleton<CardsHandManager>.Instance.GetHand(playerActor.ID).DeselectAllCards();
		}
		void GetCardsToRecover(out int outCardsToRecover, out Func<CAbilityCard, bool> outCardFilter)
		{
			outCardsToRecover = 0;
			outCardFilter = null;
			bool isFFMechanic = messageData.m_Ability.Flags.HasFlag(CAbility.EAbilityFlag.FrozenFistMechanic);
			if (recoverMode == CardHandMode.RecoverDiscardedCard)
			{
				CAbility ability = messageData.m_Ability;
				CAbilityRecoverDiscardedCards discarded = ability as CAbilityRecoverDiscardedCards;
				if (discarded != null && !discarded.RecoverCardsWithAbilityOfTypeFilter.IsNullOrEmpty())
				{
					Func<CAbilityCard, bool> filter = (CAbilityCard card) => discarded.RecoverCardsWithAbilityOfTypeFilter.Exists((CAbility.EAbilityType type) => card.HasAbilityOfType(type)) && card.Level <= messageData.m_MaxCardLevel && (!isFFMechanic || isFFMechanic != card.GetActions().Any((CAction action) => action.Abilities.Any((CAbility cAbility) => cAbility.Flags.HasFlag(CAbility.EAbilityFlag.ImmuneFrozenFistMechanic))));
					Func<CAbilityCard, bool> func = filter;
					if (isFFMechanic)
					{
						func = (CAbilityCard card) => filter(card) && playerActor.CharacterClass.RoundAbilityCardsSelectedInCardSelection.Contains(card);
					}
					outCardFilter = func;
					outCardsToRecover = playerActor.CharacterClass.DiscardedAbilityCards.Count(outCardFilter);
				}
				else
				{
					Func<CAbilityCard, bool> filter2 = (CAbilityCard card) => card.Level <= messageData.m_MaxCardLevel && (!isFFMechanic || isFFMechanic != card.GetActions().Any((CAction action) => action.Abilities.Any((CAbility cAbility) => cAbility.Flags.HasFlag(CAbility.EAbilityFlag.ImmuneFrozenFistMechanic))));
					Func<CAbilityCard, bool> func2 = filter2;
					if (isFFMechanic)
					{
						func2 = (CAbilityCard card) => filter2(card) && playerActor.CharacterClass.RoundAbilityCardsSelectedInCardSelection.Contains(card);
					}
					outCardFilter = func2;
					outCardsToRecover = playerActor.CharacterClass.DiscardedAbilityCards.Count;
				}
			}
			else if (recoverMode == CardHandMode.RecoverLostCard)
			{
				CAbility ability = messageData.m_Ability;
				CAbilityRecoverLostCards lost = ability as CAbilityRecoverLostCards;
				if (lost != null && !lost.RecoverCardsWithAbilityOfTypeFilter.IsNullOrEmpty())
				{
					Func<CAbilityCard, bool> filter3 = (CAbilityCard card) => lost.RecoverCardsWithAbilityOfTypeFilter.Exists((CAbility.EAbilityType type) => card.HasAbilityOfType(type)) && card.Level <= messageData.m_MaxCardLevel && (!isFFMechanic || isFFMechanic != card.GetActions().Any((CAction action) => action.Abilities.Any((CAbility cAbility) => cAbility.Flags.HasFlag(CAbility.EAbilityFlag.ImmuneFrozenFistMechanic))));
					Func<CAbilityCard, bool> func3 = filter3;
					if (isFFMechanic)
					{
						func3 = (CAbilityCard card) => filter3(card) && playerActor.CharacterClass.RoundAbilityCardsSelectedInCardSelection.Contains(card);
					}
					outCardFilter = func3;
					outCardsToRecover = playerActor.CharacterClass.LostAbilityCards.Count(outCardFilter);
				}
				else
				{
					Func<CAbilityCard, bool> filter4 = (CAbilityCard card) => card.Level <= messageData.m_MaxCardLevel && (!isFFMechanic || isFFMechanic != card.GetActions().Any((CAction action) => action.Abilities.Any((CAbility cAbility) => cAbility.Flags.HasFlag(CAbility.EAbilityFlag.ImmuneFrozenFistMechanic))));
					Func<CAbilityCard, bool> func4 = filter4;
					if (isFFMechanic)
					{
						func4 = (CAbilityCard card) => filter4(card) && playerActor.CharacterClass.RoundAbilityCardsSelectedInCardSelection.Contains(card);
					}
					outCardFilter = func4;
					outCardsToRecover = playerActor.CharacterClass.LostAbilityCards.Count;
				}
			}
			outCardsToRecover = Math.Min(outCardsToRecover, messageData.m_Ability.Strength);
		}
		void UpdateButtons()
		{
			readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONRECOVERCARD, LocalizationManager.GetTranslation("GUI_CONFIRM"), hideOnClick: true, glowingEffect: true, interactable: false, disregardTurnControlForInteractability: true);
			m_SkipButton.Toggle(active: true, null, hideOnClick: true, messageData.m_Ability.CanSkip);
		}
	}

	[MessageHandler(CMessageData.MessageType.PlayDiscardedCard)]
	private void Handle_PlayDiscardedCard(CMessageData message)
	{
		CSelectReplayCard_MessageData messageData = (CSelectReplayCard_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(messageData.m_ActorSpawningMessage);
		GameObject gameObject2 = FindClientActorGameObject(messageData.m_ActorReplayingCard);
		m_ActorsBeingTargetedForVFX = new List<CActor> { messageData.m_ActorReplayingCard };
		if (gameObject != gameObject2)
		{
			StartCoroutine(RotateToFaceTarget(gameObject, gameObject2.transform.position));
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = messageData.m_ActorSpawningMessage;
		ProcessActorAnimation(messageData.m_Ability, messageData.m_ActorSpawningMessage, new List<string>
		{
			messageData.AnimOverload,
			GetNonOverloadAnim(messageData.m_Ability)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		ClearStars();
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		CPlayerActor playerActor = (CPlayerActor)messageData.m_ActorReplayingCard;
		CAbilityPlayDiscardedCard replayCardAbility = messageData.m_Ability as CAbilityPlayDiscardedCard;
		CardPileType cardPileType = (messageData.m_useLostCards ? CardPileType.Lost : CardPileType.Discarded);
		CardHandMode cardHandMode = (messageData.m_useLostCards ? CardHandMode.RecoverLostCard : CardHandMode.RecoverDiscardedCard);
		Func<CAbilityCard, bool> func = null;
		int cardsToRecoverCount = 0;
		if (messageData.m_ValidCards != null && messageData.m_ValidCards.Count > 0)
		{
			func = (CAbilityCard card) => messageData.m_ValidCards.Contains(card.ID);
			cardsToRecoverCount = messageData.m_ValidCards.Count;
			Action<AbilityCardUI> overrideCardCallback = (AbilityCardUI card) =>
			{
				CAction action = null;
				if (messageData.m_ReplayAbilityType != CAbility.EAbilityType.None)
				{
					CAbility cAbility = card.AbilityCard?.GetAllAbilities()?.FirstOrDefault((CAbility a) => a.AbilityType == messageData.m_ReplayAbilityType);
					if (cAbility != null)
					{
						action = card.AbilityCard?.GetAction(cAbility);
					}
				}
				else if (messageData.m_CardAction != CAbility.ECardAction.None)
				{
					if (messageData.m_CardAction == CAbility.ECardAction.Top)
					{
						action = card.AbilityCard?.TopAction;
					}
					else
					{
						action = card.AbilityCard?.BottomAction;
					}
					cardsToRecoverCount = 1;
				}
				if (action != null)
				{
					card.SetValid(isValid: false, () =>
					{
						if (playerActor.IsUnderMyControl())
						{
							if (FFSNetwork.IsOnline)
							{
								Synchronizer.SendGameAction(GameActionType.SelectDiscardedCardToPlay, ActionProcessor.CurrentPhase, validateOnServerBeforeExecuting: false, disableAutoReplication: false, playerActor.ID, 0, 0, card.CardInstanceID);
							}
						}
						else if (!FFSNetwork.IsExecutingGameAction)
						{
							return;
						}
						card.AbilityCard.SetSelectedAction(action);
						Singleton<CardsHandManager>.Instance.GetSelectedCards(playerActor.ID).Add(card);
						foreach (CAbility ability2 in action.Abilities)
						{
							ability2.AbilityHasHappened = true;
						}
						CPhaseAction cPhaseAction = PhaseManager.Phase as CPhaseAction;
						List<CAbility> list = new List<CAbility>();
						for (int i = 0; i < action.Abilities.Count; i++)
						{
							CAbility cAbility2 = action.Abilities[i];
							CAbility cAbility3 = CAbility.CopyAbility(cAbility2, generateNewID: false, fullCopy: false, copyCurrentOverrides: false, applyCurrentStatIsBasedOnX: false, messageData.m_Ability.VarsContext);
							if (messageData.m_UseParentTargeting)
							{
								cAbility3.Targeting = messageData.m_Ability.Targeting;
								cAbility3.TargetingVars = messageData.m_Ability.TargetingVars;
							}
							list.Add(cAbility3);
							if (cAbility2.SubAbilities != null)
							{
								foreach (CAbility subAbility in cAbility2.SubAbilities)
								{
									if (!subAbility.IsInlineSubAbility)
									{
										CAbility cAbility4 = CAbility.CopyAbility(subAbility, generateNewID: false);
										cAbility4.ParentAbility = cAbility2;
										list.Add(cAbility4);
									}
								}
							}
						}
						List<CAbilityCard> fromAbilityCardList = (messageData.m_useLostCards ? playerActor.CharacterClass.LostAbilityCards : playerActor.CharacterClass.DiscardedAbilityCards);
						if (messageData.m_useLostCards)
						{
							playerActor.CharacterClass.MoveAbilityCard(card.AbilityCard, fromAbilityCardList, playerActor.CharacterClass.RoundAbilityCards, "LostAbilityCards", "RoundAbilityCards");
						}
						else
						{
							playerActor.CharacterClass.MoveAbilityCard(card.AbilityCard, fromAbilityCardList, playerActor.CharacterClass.RoundAbilityCards, "DiscardedAbilityCards", "RoundAbilityCards");
						}
						bool happened = false;
						bool gainedXP = false;
						for (int num = list.Count - 1; num >= 0; num--)
						{
							CAbility ability = list[num];
							if (messageData.m_DamageReduction > 0 && ability.IsSubAbility && ability.AbilityType == CAbility.EAbilityType.Damage)
							{
								ability.Strength = Math.Max(0, ability.Strength - messageData.m_DamageReduction);
							}
							cPhaseAction.InjectAbility(ability, playerActor, card.AbilityCard, () =>
							{
								if (ability.AbilityHasHappened)
								{
									replayCardAbility.AbilityHasHappened = true;
									replayCardAbility.GetAbilityBaseCard().ActionHasHappened = true;
								}
								if (!happened)
								{
									happened = true;
									if (!playerActor.CharacterClass.ActivatedAbilityCards.Contains(card.AbilityCard))
									{
										card.AbilityCard.SetSelectedAction(action);
										playerActor.CharacterClass.DiscardRoundAbilityCard(card.AbilityCard);
									}
									else
									{
										playerActor.CharacterClass.MoveAbilityCard(card.AbilityCard, playerActor.CharacterClass.RoundAbilityCards, null, "RoundAbilityCards", null);
									}
								}
								if (!gainedXP && ability.AbilityHasHappened)
								{
									gainedXP = true;
									playerActor.GainXP(action.ActionXP, "AbilityCards");
								}
							});
						}
						cPhaseAction.InjectInfusions(action.Infusions);
						PhaseManager.NextStep();
						Singleton<CardsHandManager>.Instance.Hide();
					});
				}
			};
			CardsHandManager instance = Singleton<CardsHandManager>.Instance;
			CPlayerActor playerActor2 = playerActor;
			int maxCardsSelected = cardsToRecoverCount;
			Func<CAbilityCard, bool> cardSelectableFilter = func;
			instance.Show(playerActor2, cardHandMode, cardPileType, cardPileType, maxCardsSelected, fadeUnselectableCards: true, highlightSelectableCards: true, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: false, allowFullDeckPreview: true, overrideCardCallback, cardSelectableFilter);
			DisableButtons(disableUndo: true, disableReady: false);
			SetReadyButtonEndSelection(active: false);
			WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
			SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null);
			switch (cardHandMode)
			{
			case CardHandMode.RecoverDiscardedCard:
				if (messageData.m_ReplayAbilityType == CAbility.EAbilityType.Summon)
				{
					string text = LocalizationManager.GetTranslation("FH/GUI_DISCARDED_SUMMON_REPLAY_TOOLTIP");
					if (messageData.m_DamageReduction > 0)
					{
						text = text + " " + string.Format(LocalizationManager.GetTranslation("FH/GUI_DISCARDED_SUMMON_REPLAY_DMG_REDUCE_TOOLTIP"), messageData.m_DamageReduction);
					}
					InitiativeTrack.Instance.helpBox.ShowTranslated(text);
				}
				else
				{
					InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("FH/GUI_DISCARDED_CARD_REPLAY_TOOLTIP"));
				}
				break;
			case CardHandMode.RecoverLostCard:
				if (messageData.m_ReplayAbilityType == CAbility.EAbilityType.Summon)
				{
					InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("FH/GUI_LOST_SUMMON_REPLAY_TOOLTIP"));
				}
				else
				{
					InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("FH/GUI_LOST_CARD_REPLAY_TOOLTIP"));
				}
				break;
			}
			if (FFSNetwork.IsOnline)
			{
				if (!playerActor.IsUnderMyControl())
				{
					ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ExtraTurnCardSelection);
				}
				else
				{
					ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ExtraTurnCardSelection);
				}
			}
		}
		else
		{
			Log.Error("Playing a discarded/lost card with invalid cards list");
		}
	}

	public void OnCardForModeSelected(CAbilityModeTransfer modeAbility, AbilityCardUI cardUI)
	{
		if (modeAbility.SelectedModeCard == cardUI.AbilityCard)
		{
			modeAbility.SetSelectedModeCard(null);
		}
		else
		{
			modeAbility.SetSelectedModeCard(cardUI.AbilityCard);
		}
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONFIRM, null, hideOnClick: true, glowingEffect: false, modeAbility.SelectedModeCard != null);
		readyButton.AlternativeAction(() =>
		{
			Singleton<CardsHandManager>.Instance.Hide();
			ScenarioRuleClient.StepComplete();
		}, (modeAbility.SelectedModeCard != null) ? ReadyButton.EButtonState.EREADYBUTTONCONFIRM : ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED, LocalizationManager.GetTranslation("GUI_CONFIRM"));
	}

	public void ProxyCardForModeSelected(GameAction action)
	{
		AbilityCardUI card = Singleton<CardsHandManager>.Instance.GetHand(action.ActorID).GetCard(action.SupplementaryDataIDMax);
		CAbilityModeTransfer modeAbility = (PhaseManager.CurrentPhase as CPhaseAction)?.CurrentPhaseAbility?.m_Ability as CAbilityModeTransfer;
		OnCardForModeSelected(modeAbility, card);
	}

	[MessageHandler(CMessageData.MessageType.SelectCardForMode)]
	private void Handle_SelectCardForMode(CMessageData message)
	{
		CSelectCardForMode_MessageData messageData = (CSelectCardForMode_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(messageData.m_ActorSpawningMessage);
		GameObject gameObject2 = FindClientActorGameObject(messageData.m_ActorReplayingCard);
		m_ActorsBeingTargetedForVFX = new List<CActor> { messageData.m_ActorReplayingCard };
		if (gameObject != gameObject2)
		{
			StartCoroutine(RotateToFaceTarget(gameObject, gameObject2.transform.position));
		}
		CAbilityModeTransfer cAbilityModeTransfer = messageData.m_Ability as CAbilityModeTransfer;
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = messageData.m_ActorSpawningMessage;
		List<string> list = new List<string> { GetNonOverloadAnim(messageData.m_Ability) };
		if (cAbilityModeTransfer.m_State != CAbilityModeTransfer.EModeTransferState.SelectModeCardToSummonOrDeactivate && cAbilityModeTransfer.ModeUsage != CAbilityModeTransfer.EModeUse.DeactivateMode)
		{
			list.Insert(0, messageData.AnimOverload);
		}
		ProcessActorAnimation(messageData.m_Ability, messageData.m_ActorSpawningMessage, list, out animationShouldPlay, out animatingActorToWaitFor);
		ClearStars();
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		CPlayerActor cPlayerActor = (CPlayerActor)messageData.m_ActorReplayingCard;
		if (cAbilityModeTransfer.m_State == CAbilityModeTransfer.EModeTransferState.SelectModeCardToActivate)
		{
			Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_MODE_ACTIVATE_CHOOSE", cAbilityModeTransfer);
		}
		else if (cAbilityModeTransfer.m_State == CAbilityModeTransfer.EModeTransferState.SelectModeCardToSummonOrDeactivate)
		{
			if (cAbilityModeTransfer.ModeUsage == CAbilityModeTransfer.EModeUse.DeactivateMode)
			{
				Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_MODE_DEACTIVATE_CHOOSE", cAbilityModeTransfer);
			}
			else
			{
				Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_MODE_SUMMON_CHOOSE", cAbilityModeTransfer);
			}
		}
		Func<CAbilityCard, bool> func = null;
		int num = 0;
		if (messageData.m_ValidCards != null && messageData.m_ValidCards.Count > 0)
		{
			func = (CAbilityCard card) => messageData.m_ValidCards.Contains(card.ID);
			num = 1;
			CardPileType cardPileType = CrossReference.ECardPileToCardPileType(messageData.m_PileToChooseFrom);
			Singleton<CardsHandManager>.Instance.Show(cPlayerActor, CardHandMode.CardsSelection, cardPileType, cardPileType, num, fadeUnselectableCards: true, highlightSelectableCards: true, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: false, allowFullDeckPreview: true, null, func);
			m_SkipButton.Toggle(cAbilityModeTransfer.ModeUsage != CAbilityModeTransfer.EModeUse.Transfer && cAbilityModeTransfer.CanSkip);
			readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONNA, LocalizationManager.GetTranslation("GUI_CONFIRM"), hideOnClick: true, glowingEffect: false, interactable: false);
			WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
			SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null, hideHelpBox: false);
			if (FFSNetwork.IsOnline)
			{
				if (!cPlayerActor.IsUnderMyControl())
				{
					ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ExtraTurnCardSelection);
				}
				else
				{
					ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ExtraTurnCardSelection);
				}
			}
		}
		else
		{
			Log.Error("Playing a mode card with invalid cards list");
		}
	}

	[MessageHandler(CMessageData.MessageType.MoveSelectedCards)]
	private void Handle_MoveSelectedCards(CMessageData message)
	{
		CMoveSelectedCards cMoveSelectedCards = (CMoveSelectedCards)message;
		string text = null;
		string text2 = "";
		for (int i = 0; i < cMoveSelectedCards.m_Cards.Count; i++)
		{
			text2 = text2 + ((i != 0) ? ", " : "") + $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(cMoveSelectedCards.m_Cards[i].Name)}</color></b></font>";
		}
		switch (cMoveSelectedCards.m_MoveFromPile)
		{
		case CBaseCard.ECardPile.Discarded:
			text = ((cMoveSelectedCards.m_quantity <= 2) ? string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_RECOVER_DISCARDED_CARDS_NAME"), text2) : string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_RECOVER_DISCARDED_CARDS"), cMoveSelectedCards.m_quantity));
			break;
		case CBaseCard.ECardPile.Lost:
			text = ((cMoveSelectedCards.m_quantity <= 2) ? string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_RECOVER_LOST_CARDS_NAME"), text2) : string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_RECOVER_LOST_CARDS"), cMoveSelectedCards.m_quantity));
			break;
		case CBaseCard.ECardPile.Hand:
			if (cMoveSelectedCards.m_MoveToPile == CBaseCard.ECardPile.Discarded)
			{
				text = ((cMoveSelectedCards.m_quantity <= 2) ? string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_DISCARD_CARDS_NAME"), text2) : string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_DISCARD_CARDS"), cMoveSelectedCards.m_quantity));
			}
			else if (cMoveSelectedCards.m_MoveToPile == CBaseCard.ECardPile.Lost)
			{
				text = ((cMoveSelectedCards.m_quantity <= 2) ? string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_LOSE_CARDS_NAME"), text2) : string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_LOSE_CARDS"), cMoveSelectedCards.m_quantity));
			}
			break;
		case CBaseCard.ECardPile.None:
			text = ((cMoveSelectedCards.m_quantity <= 2) ? string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_GAIN_CARDS_NAME"), text2) : string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_GAIN_CARDS"), cMoveSelectedCards.m_quantity));
			break;
		}
		string text3 = LocalizationManager.GetTranslation(cMoveSelectedCards.m_ActorRecoveringCards.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cMoveSelectedCards.m_ActorRecoveringCards);
		Singleton<CombatLogHandler>.Instance.AddLog(text3 + string.Format("<b>{0}</b>", " " + text), CombatLogFilter.ABILITIES);
	}

	[MessageHandler(CMessageData.MessageType.MoveActiveBonusTrackers)]
	private void Handle_MoveActiveBonusTrackers(CMessageData message)
	{
		CMoveActiveBonusTrackers cMoveActiveBonusTrackers = (CMoveActiveBonusTrackers)message;
		string text = "";
		for (int i = 0; i < cMoveActiveBonusTrackers.m_Cards.Count; i++)
		{
			text = text + ((i != 0) ? ", " : "") + $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(cMoveActiveBonusTrackers.m_Cards[i].Name)}</color></b></font>";
		}
		string text2 = string.Format(LocalizationManager.GetTranslation("FH/COMBAT_LOG_MOVE_ACTIVE_BONUS_TRACKERS"), text);
		string text3 = LocalizationManager.GetTranslation(cMoveActiveBonusTrackers.m_Actor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cMoveActiveBonusTrackers.m_Actor);
		Singleton<CombatLogHandler>.Instance.AddLog(text3 + string.Format("<b>{0}</b>", " " + text2), CombatLogFilter.ABILITIES);
		CardsHandUI.CardActionsCommand resetCardActions = (GameState.IsPerformingCardOutOfPhase ? CardsHandUI.CardActionsCommand.FORCE_RESET : CardsHandUI.CardActionsCommand.NONE);
		Singleton<CardsHandManager>.Instance.Show((CPlayerActor)cMoveActiveBonusTrackers.m_Actor, CardHandMode.ActionSelection, CardPileType.Round, CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, resetCardActions);
		m_UndoButton.Toggle(active: false);
		m_SkipButton.Toggle(active: false);
		CAbilityMoveActiveBonusTracker ability = cMoveActiveBonusTrackers.m_Ability;
		if (ability != null)
		{
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = cMoveActiveBonusTrackers.m_ActorSpawningMessage;
			ProcessActorAnimation(ability, cMoveActiveBonusTrackers.m_ActorSpawningMessage, new List<string>
			{
				cMoveActiveBonusTrackers.AnimOverload,
				GetNonOverloadAnim(ability)
			}, out animationShouldPlay, out animatingActorToWaitFor);
		}
	}

	[MessageHandler(CMessageData.MessageType.SelectLoseCards)]
	public void Handle_SelectLoseCards(CMessageData message)
	{
		CSelectLoseCards_MessageData cSelectLoseCards_MessageData = (CSelectLoseCards_MessageData)message;
		s_Choreographer.m_CurrentAbility = cSelectLoseCards_MessageData.m_Ability;
		m_CurrentActor = cSelectLoseCards_MessageData.m_ActorSpawningMessage;
		GameObject gameObject = FindClientActorGameObject(cSelectLoseCards_MessageData.m_ActorSpawningMessage);
		GameObject gameObject2 = FindClientActorGameObject(cSelectLoseCards_MessageData.m_ActorLosingCards);
		m_ActorsBeingTargetedForVFX = new List<CActor> { cSelectLoseCards_MessageData.m_ActorLosingCards };
		if (gameObject != gameObject2)
		{
			StartCoroutine(RotateToFaceTarget(gameObject, gameObject2.transform.position));
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cSelectLoseCards_MessageData.m_ActorSpawningMessage;
		if (!cSelectLoseCards_MessageData.m_SkipAnim)
		{
			ProcessActorAnimation(cSelectLoseCards_MessageData.m_Ability, cSelectLoseCards_MessageData.m_ActorSpawningMessage, new List<string>
			{
				cSelectLoseCards_MessageData.AnimOverload,
				GetNonOverloadAnim(cSelectLoseCards_MessageData.m_Ability)
			}, out animationShouldPlay, out animatingActorToWaitFor);
		}
		ClearStars();
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		CPlayerActor playerActor = (CPlayerActor)cSelectLoseCards_MessageData.m_ActorLosingCards;
		CardHandMode cardHandMode = ((cSelectLoseCards_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.DiscardCards) ? CardHandMode.DiscardCard : CardHandMode.LoseCard);
		CardPileType filterType = CardPileType.Hand;
		int num = 0;
		if (cSelectLoseCards_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.DiscardCards)
		{
			num = ((playerActor.CharacterClass.HandAbilityCards.Count < cSelectLoseCards_MessageData.m_Ability.Strength) ? playerActor.CharacterClass.HandAbilityCards.Count : cSelectLoseCards_MessageData.m_Ability.Strength);
		}
		else
		{
			if (cSelectLoseCards_MessageData.m_Ability.GetVar("ChooseOneHandOrTwoDiscard").GetBool())
			{
				Singleton<LoseCardsOptionsPanel>.Instance.Show(playerActor);
				if (FFSNetwork.IsOnline)
				{
					if (!playerActor.IsUnderMyControl())
					{
						ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.CardRecovery);
					}
					else
					{
						ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.CardRecovery);
					}
				}
				return;
			}
			num = ((playerActor.CharacterClass.HandAbilityCards.Count + playerActor.CharacterClass.DiscardedAbilityCards.Count < cSelectLoseCards_MessageData.m_Ability.Strength) ? playerActor.CharacterClass.HandAbilityCards.Count : cSelectLoseCards_MessageData.m_Ability.Strength);
			filterType = CardPileType.Any;
		}
		Func<CAbilityCard, bool> cardSelectableFilter = null;
		CAbility ability = cSelectLoseCards_MessageData.m_Ability;
		CAbilityDiscardCards discardAbility = ability as CAbilityDiscardCards;
		if (discardAbility != null)
		{
			cardSelectableFilter = (CAbilityCard card) =>
			{
				CExpression cExpression = discardAbility.CardFilterExpression();
				if (cExpression != null)
				{
					CVars cVars = new CVars();
					CVarsContext context = new CVarsContext(cVars);
					cVars.Set("obj", new TValue(card));
					if (!cExpression.Calc(context).GetBool())
					{
						return false;
					}
				}
				return (((PhaseManager.PreviousPhase == null || PhaseManager.PreviousPhase.Type != CPhase.PhaseType.StartScenarioEffects) && (PhaseManager.CurrentPhase == null || PhaseManager.CurrentPhase.Type != CPhase.PhaseType.StartScenarioEffects)) || playerActor == null || !playerActor.CharacterClass.AbilityCardsPool.Any((CAbilityCard cAbilityCard) => cAbilityCard.HasAvailableMode()) || playerActor.CharacterClass.ActivatedAbilityCards.Any((CAbilityCard cAbilityCard) => cAbilityCard.HasModeActive()) || playerActor.CharacterClass.HandAbilityCards.Count((CAbilityCard cAbilityCard) => cAbilityCard.HasAvailableMode()) != 1 || !card.HasAvailableMode()) ? true : false;
			};
		}
		Singleton<CardsHandManager>.Instance.Show((CPlayerActor)cSelectLoseCards_MessageData.m_ActorLosingCards, cardHandMode, filterType, new List<CardPileType>
		{
			CardPileType.Hand,
			CardPileType.Discarded
		}, num, fadeUnselectableCards: true, highlightSelectableCards: true, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: false, allowFullDeckPreview: true, null, cardSelectableFilter);
		SetReadyButtonEndSelection(active: false);
		m_UndoButton.Toggle(cSelectLoseCards_MessageData.m_Ability.MiscAbilityData?.CanUndo == true);
		m_SkipButton.Toggle(cSelectLoseCards_MessageData.m_Ability.MiscAbilityData?.CanSkip == true);
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null);
		if (!string.IsNullOrEmpty(cSelectLoseCards_MessageData.m_Ability.HelpBoxTooltipLocKey))
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation(cSelectLoseCards_MessageData.m_Ability.HelpBoxTooltipLocKey));
		}
		else if (cardHandMode == CardHandMode.LoseCard)
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated((num > 1) ? string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_LOSE_CARDS"), cSelectLoseCards_MessageData.m_Ability.Strength) : LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_LOSE_CARD"));
		}
		else
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation((num > 1) ? "GUI_TOOLTIP_SELECT_DISCARD_CARDS" : "GUI_TOOLTIP_SELECT_DISCARD_CARD"), cSelectLoseCards_MessageData.m_Ability.Strength), string.Format(LocalizationManager.GetTranslation((num > 1) ? "GUI_TOOLTIP_SELECT_DISCARD_CARDS_TITLE" : "GUI_TOOLTIP_SELECT_DISCARD_CARD_TITLE"), cSelectLoseCards_MessageData.m_Ability.Strength));
		}
		if (FFSNetwork.IsOnline)
		{
			if (!playerActor.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.CardRecovery);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.CardRecovery);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.SelectCardsWithActiveBonusTracker)]
	private void Handle_SelectCardsWithActiveBonusTracker(CMessageData message)
	{
		CSelectCardsWithActiveBonusTracker_MessageData cSelectCardsWithActiveBonusTracker_MessageData = (CSelectCardsWithActiveBonusTracker_MessageData)message;
		s_Choreographer.m_CurrentAbility = cSelectCardsWithActiveBonusTracker_MessageData.m_Ability;
		m_CurrentActor = cSelectCardsWithActiveBonusTracker_MessageData.m_ActorSpawningMessage;
		FirstAbility = cSelectCardsWithActiveBonusTracker_MessageData.m_FirstAbility;
		GameObject gameObject = FindClientActorGameObject(cSelectCardsWithActiveBonusTracker_MessageData.m_ActorSpawningMessage);
		GameObject gameObject2 = FindClientActorGameObject(cSelectCardsWithActiveBonusTracker_MessageData.m_Actor);
		m_ActorsBeingTargetedForVFX = new List<CActor> { cSelectCardsWithActiveBonusTracker_MessageData.m_Actor };
		if (gameObject != gameObject2)
		{
			StartCoroutine(RotateToFaceTarget(gameObject, gameObject2.transform.position));
		}
		ClearStars();
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		CPlayerActor cPlayerActor = (CPlayerActor)cSelectCardsWithActiveBonusTracker_MessageData.m_Actor;
		List<CActiveBonus> activeBonuses = CAbilityMoveActiveBonusTracker.GetActiveBonusesWithMovableTrackers(cPlayerActor, cSelectCardsWithActiveBonusTracker_MessageData.m_Ability.Strength).ToList();
		List<CActiveBonus> activeBonusesWithTrackers = CAbilityMoveActiveBonusTracker.GetActiveBonusesWithTrackers(cPlayerActor).ToList();
		CardHandMode mode = CardHandMode.SelectCardsWithActiveBonusTracker;
		CardPileType filterType = CardPileType.Active;
		List<CardPileType> selectableCardTypes = new List<CardPileType> { CardPileType.Active };
		int num = Mathf.Min(activeBonuses.Count, cSelectCardsWithActiveBonusTracker_MessageData.m_Ability.GetVar("NumberOfCardsToSelect").GetInt());
		bool fadeUnselectableCards = true;
		bool highlightSelectableCards = true;
		if (ReactionViewService.UseExperimental)
		{
			Singleton<FHScenarioViewController>.Instance.GetService<ReactionViewService>().SelectCardsWithActiveBonusTracker(cPlayerActor, (from ab in activeBonuses
				select ab.BaseCard as CAbilityCard into c
				where c != null
				select c).ToList(), num, cSelectCardsWithActiveBonusTracker_MessageData.m_Ability.Strength > 0);
			Singleton<CardsHandManager>.Instance.Hide();
		}
		else
		{
			Singleton<CardsHandManager>.Instance.Show(cPlayerActor, mode, filterType, selectableCardTypes, num, fadeUnselectableCards, highlightSelectableCards, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: false, allowFullDeckPreview: true, null, (CAbilityCard card) => activeBonuses.Any((CActiveBonus ab) => ab.BaseCard == card), (CAbilityCard card) => activeBonusesWithTrackers.Any((CActiveBonus ab) => ab.BaseCard == card));
		}
		SetReadyButtonEndSelection(active: false);
		m_UndoButton.Toggle(cSelectCardsWithActiveBonusTracker_MessageData.m_Ability.CanUndo && FirstAbility);
		m_SkipButton.Toggle(cSelectCardsWithActiveBonusTracker_MessageData.m_Ability.CanSkip);
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null);
		string translation = LocalizationManager.GetTranslation((num > 1) ? "FH/GUI_TOOLTIP_SELECT_ACTIVE_BONUS_CARDS" : "FH/GUI_TOOLTIP_SELECT_ACTIVE_BONUS_CARD");
		string translation2 = LocalizationManager.GetTranslation((num > 1) ? "FH/GUI_TOOLTIP_SELECT_ACTIVE_BONUS_CARDS_TITLE" : "FH/GUI_TOOLTIP_SELECT_ACTIVE_BONUS_CARD_TITLE");
		InitiativeTrack.Instance.helpBox.ShowTranslated(translation, translation2);
		if (PhaseManager.CurrentPhaseAction?.CurrentPhaseAbility?.m_Ability == cSelectCardsWithActiveBonusTracker_MessageData.m_Ability && FFSNetwork.IsOnline)
		{
			if (!cPlayerActor.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.MoveActiveBonusTracker);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.MoveActiveBonusTracker);
			}
		}
	}

