	[MessageHandler(CMessageData.MessageType.SelectAndPlayCard)]
	private void Handle_SelectAndPlayCard(CMessageData message)
	{
		CSelectAndPlayCard_MessageData messageData = (CSelectAndPlayCard_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(messageData.m_ActorSpawningMessage);
		CAbilitySelectAndPlayCard cAbilitySelectAndPlayCard = (CAbilitySelectAndPlayCard)(m_CurrentAbility = messageData.m_Ability);
		m_ActorsBeingTargetedForVFX = new List<CActor> { messageData.m_ActorSpawningMessage };
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = messageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cAbilitySelectAndPlayCard, messageData.m_ActorSpawningMessage, new List<string>
		{
			messageData.AnimOverload,
			GetNonOverloadAnim(cAbilitySelectAndPlayCard)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		ClearStars();
		CPlayerActor cPlayerActor = (CPlayerActor)messageData.m_ActorSpawningMessage;
		Singleton<AbilityEffectManager>.Instance.ShowExtraTurn(cAbilitySelectAndPlayCard, ActorBehaviour.GetActorBehaviour(gameObject), messageData.m_ActorSpawningMessage as CPlayerActor);
		ShowAbilityHelpBoxTooltip(cAbilitySelectAndPlayCard);
		Func<CAbilityCard, bool> func = (CAbilityCard card) => messageData.m_ValidCards.Contains(card.ID);
		CardPileType filterType = ((messageData.m_PilesToChooseFrom.Count > 1) ? CardPileType.Any : CrossReference.ECardPileToCardPileType(messageData.m_PilesToChooseFrom[0]));
		List<CardPileType> selectableCardTypes = messageData.m_PilesToChooseFrom.Select(CrossReference.ECardPileToCardPileType).ToList();
		if (ReactionViewService.UseExperimental)
		{
			List<CAbilityCard> cards = cPlayerActor.CharacterClass.OwnedAbilityCards.Where((CAbilityCard card) => messageData.m_ValidCards.Contains(card.ID)).ToList();
			Singleton<FHScenarioViewController>.Instance.GetService<ReactionViewService>()?.SelectAndPlayCard(cPlayerActor, messageData.m_Ability, cards, Math.Min(cAbilitySelectAndPlayCard.Strength, messageData.m_ValidCards.Count));
		}
		else
		{
			Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
			CardsHandManager instance = Singleton<CardsHandManager>.Instance;
			int maxCardsSelected = Math.Min(cAbilitySelectAndPlayCard.Strength, messageData.m_ValidCards.Count);
			Func<CAbilityCard, bool> cardSelectableFilter = func;
			Func<CAbilityCard, bool> cardVisibleFilter = func;
			instance.Show(cPlayerActor, CardHandMode.CardsSelection, filterType, selectableCardTypes, maxCardsSelected, func != null, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: true, allowFullDeckPreview: true, null, cardSelectableFilter, cardVisibleFilter);
		}
		SetReadyButtonEndSelection(active: true);
		readyButton.AlternativeAction(() =>
		{
			Singleton<CardsHandManager>.Instance.cardsActionController.OnActionFinished();
			GameState.CurrentSelectAndPlayCardAbility.StartOutOfPhaseAbilities();
			readyButton.ClearAlternativeAction();
		});
		readyButton.SetInteractable(interactable: false);
		m_UndoButton.Toggle(active: false);
		m_UndoButton.SetInteractable(active: false);
		m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP"), hideOnClick: true, messageData.m_Ability.CanSkip);
		m_CurrentActor = messageData.m_ActorSpawningMessage;
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null, string.IsNullOrEmpty(cAbilitySelectAndPlayCard.HelpBoxTooltipLocKey));
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ExtraTurnCardSelection);
		}
	}

	[MessageHandler(CMessageData.MessageType.SelectAndMoveCard)]
	private void Handle_SelectAndMoveCard(CMessageData message)
	{
		CSelectAndMoveCard_MessageData messageData = (CSelectAndMoveCard_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(messageData.m_ActorSpawningMessage);
		CAbilitySelectAndMoveCard ability = messageData.m_Ability;
		m_ActorsBeingTargetedForVFX = new List<CActor> { messageData.m_ActorSpawningMessage };
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = messageData.m_ActorSpawningMessage;
		ProcessActorAnimation(ability, messageData.m_ActorSpawningMessage, new List<string>
		{
			messageData.AnimOverload,
			GetNonOverloadAnim(ability)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		ClearStars();
		CPlayerActor playerActor = (CPlayerActor)messageData.m_ActorSpawningMessage;
		Singleton<AbilityEffectManager>.Instance.ShowExtraTurn(ability, ActorBehaviour.GetActorBehaviour(gameObject), messageData.m_ActorSpawningMessage as CPlayerActor);
		ShowAbilityHelpBoxTooltip(ability);
		Func<CAbilityCard, bool> func = (CAbilityCard card) => messageData.m_ValidCards.Contains(card.ID);
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		if (messageData.m_PilesToChooseFrom.Contains(CBaseCard.ECardPile.Taken) && !ScenarioScript.current.ShowTakenPile())
		{
			throw new InvalidOperationException("SelectAndMoveCard targets the Taken pile but " + ScenarioScript.current.GetType().Name + " does not override TakenPileTooltipKey(). Add TakenPileTooltipKey() and TakenPileNameKey() overrides to the scenario script.");
		}
		CardPileType filterType = ((messageData.m_PilesToChooseFrom.Count > 1) ? CardPileType.Any : CrossReference.ECardPileToCardPileType(messageData.m_PilesToChooseFrom[0]));
		List<CardPileType> selectableCardTypes = messageData.m_PilesToChooseFrom.Select(CrossReference.ECardPileToCardPileType).ToList();
		CardsHandManager instance = Singleton<CardsHandManager>.Instance;
		int maxCardsSelected = Math.Min(ability.Strength, messageData.m_ValidCards.Count);
		Func<CAbilityCard, bool> cardSelectableFilter = func;
		Func<CAbilityCard, bool> cardVisibleFilter = func;
		instance.Show(playerActor, CardHandMode.CardsSelection, filterType, selectableCardTypes, maxCardsSelected, func != null, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: true, allowFullDeckPreview: true, null, cardSelectableFilter, cardVisibleFilter);
		Singleton<CardsHandManager>.Instance.RefreshValidCards();
		SetReadyButtonEndSelection(active: true);
		readyButton.AlternativeAction(() =>
		{
			Singleton<CardsHandManager>.Instance.cardsActionController.OnActionFinished();
			GameState.CurrentSelectAndMoveCardsAbility.PerformSwap();
		});
		readyButton.SetInteractable(interactable: false);
		m_UndoButton.Toggle(active: false);
		m_UndoButton.SetInteractable(active: false);
		m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP"), hideOnClick: true, messageData.m_Ability.CanSkip, () =>
		{
			GameState.CurrentSelectAndMoveCardsAbility.EndSwap(fromLogicThread: false);
		});
		m_CurrentActor = messageData.m_ActorSpawningMessage;
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null, string.IsNullOrEmpty(ability.HelpBoxTooltipLocKey));
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ExtraTurnCardSelection);
			Singleton<UIReadyToggle>.Instance?.ToggleVisibility(visible: false);
		}
	}

	[MessageHandler(CMessageData.MessageType.SelectCard)]
	private void Handle_SelectCard(CMessageData message)
	{
		CSelectCard_MessageData messageData = (CSelectCard_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(messageData.m_ActorSpawningMessage);
		CAbilitySelectCard ability = messageData.m_Ability;
		m_ActorsBeingTargetedForVFX = new List<CActor> { messageData.m_ActorSpawningMessage };
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = messageData.m_ActorSpawningMessage;
		ProcessActorAnimation(ability, messageData.m_ActorSpawningMessage, new List<string>
		{
			messageData.AnimOverload,
			GetNonOverloadAnim(ability)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		ClearStars();
		CPlayerActor playerActor = (CPlayerActor)messageData.m_ActorSpawningMessage;
		Singleton<AbilityEffectManager>.Instance.ShowExtraTurn(ability, ActorBehaviour.GetActorBehaviour(gameObject), messageData.m_ActorSpawningMessage as CPlayerActor);
		ShowAbilityHelpBoxTooltip(ability);
		Func<CAbilityCard, bool> func = (CAbilityCard card) => messageData.m_ValidCards.Contains(card.ID);
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = ability.PilesToMoveFrom.Contains(CBaseCard.ECardPile.Activated);
		CardPileType filterType = ((messageData.m_PilesToChooseFrom.Count > 1) ? CardPileType.Any : CrossReference.ECardPileToCardPileType(messageData.m_PilesToChooseFrom[0]));
		List<CardPileType> selectableCardTypes = messageData.m_PilesToChooseFrom.Select(CrossReference.ECardPileToCardPileType).ToList();
		CardsHandManager instance = Singleton<CardsHandManager>.Instance;
		CPlayerActor playerActor2 = playerActor;
		int maxCardsSelected = Math.Min(ability.Strength, messageData.m_ValidCards.Count);
		Func<CAbilityCard, bool> cardSelectableFilter = func;
		instance.Show(playerActor2, CardHandMode.CardsSelection, filterType, selectableCardTypes, maxCardsSelected, func != null, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: true, allowFullDeckPreview: true, null, cardSelectableFilter);
		if (ability.GetMiscVar("ShowFullCardPicker").GetBool())
		{
			List<AbilityCardChoice> list = new List<AbilityCardChoice>();
			CCharacterClass characterClass = playerActor.CharacterClass;
			IEnumerable<CAbilityCard> source = from x in Singleton<CardsHandManager>.Instance.GetHand(playerActor).AllCards
				where x.gameObject.activeSelf
				select x.AbilityCard;
			bool flag = ability.GetMiscVar("TopAction").GetBool();
			Singleton<CardsHandManager>.Instance.Hide();
			foreach (CAbilityCard item in source.Distinct())
			{
				list.Add(new AbilityCardChoice(item, characterClass, (!flag) ? CBaseCard.ActionType.TopAction : CBaseCard.ActionType.BottomAction));
			}
			Singleton<UIAbilityCardPicker>.Instance.Show(ability.TargetingActor, list, 1, (List<IAbilityCardOption> selectedAbility) =>
			{
				if (selectedAbility?.FirstOrDefault() is AbilityCardChoice abilityCardChoice)
				{
					Singleton<CardsHandManager>.Instance.GetHand(playerActor).SelectCard(abilityCardChoice.AbilityCard as CAbilityCard);
					readyButton.SetInteractable(interactable: true);
				}
			}, () =>
			{
				for (int num = playerActor.CharacterClass.SelectedAbilityCardsOutOfPhase.Count - 1; num >= 0; num--)
				{
					CAbilityCard card = playerActor.CharacterClass.SelectedAbilityCardsOutOfPhase[num];
					Singleton<CardsHandManager>.Instance.GetHand(playerActor).UnselectCard(card);
				}
				readyButton.SetInteractable(interactable: false);
			});
		}
		SetReadyButtonEndSelection(active: true);
		readyButton.AlternativeAction(() =>
		{
			Singleton<CardsHandManager>.Instance.cardsActionController.OnActionFinished();
			GameState.CurrentSelectCardsAbility.PerformSelection();
			Singleton<UIAbilityCardPicker>.Instance.Hide();
		});
		readyButton.SetInteractable(interactable: false);
		m_UndoButton.Toggle(active: false);
		m_UndoButton.SetInteractable(active: false);
		m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP"), hideOnClick: true, messageData.m_Ability.CanSkip, () =>
		{
			GameState.CurrentSelectCardsAbility.EndSelectCard();
			Singleton<UIAbilityCardPicker>.Instance.Hide();
		});
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null, string.IsNullOrEmpty(ability.HelpBoxTooltipLocKey));
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ExtraTurnCardSelection);
		}
	}

	[MessageHandler(CMessageData.MessageType.SelectExtraTurnCards)]
	private void Handle_SelectExtraTurnCards(CMessageData message)
	{
		CSelectExtraTurnCards_MessageData cSelectExtraTurnCards_MessageData = (CSelectExtraTurnCards_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(cSelectExtraTurnCards_MessageData.m_ActorSpawningMessage);
		GameObject gameObject2 = FindClientActorGameObject(cSelectExtraTurnCards_MessageData.m_ActorTakingExtraTurn);
		m_ActorsBeingTargetedForVFX = new List<CActor> { cSelectExtraTurnCards_MessageData.m_ActorTakingExtraTurn };
		if (gameObject != gameObject2)
		{
			StartCoroutine(RotateToFaceTarget(gameObject, gameObject2.transform.position));
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cSelectExtraTurnCards_MessageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility, cSelectExtraTurnCards_MessageData.m_ActorSpawningMessage, new List<string>
		{
			cSelectExtraTurnCards_MessageData.AnimOverload,
			GetNonOverloadAnim(cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		ClearStars();
		CPlayerActor playerActor = (CPlayerActor)cSelectExtraTurnCards_MessageData.m_ActorTakingExtraTurn;
		Singleton<AbilityEffectManager>.Instance.ShowExtraTurn(cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility, ActorBehaviour.GetActorBehaviour(gameObject2), cSelectExtraTurnCards_MessageData.m_ActorSpawningMessage as CPlayerActor);
		string title = Singleton<AbilityEffectManager>.Instance.ExtraTurnAbilityEffectTitle(cSelectExtraTurnCards_MessageData.m_ActorTakingExtraTurn);
		if (cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility.ExtraTurnType == CAbilityExtraTurn.EExtraTurnType.BottomAction)
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_EXTRA_TURN_BOTTOM_ACTION"), title);
		}
		else if (cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility.ExtraTurnType == CAbilityExtraTurn.EExtraTurnType.TopAction)
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_EXTRA_TURN_TOP_ACTION"), title);
		}
		else if (cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility.ExtraTurnType == CAbilityExtraTurn.EExtraTurnType.SingleCardAnyActionAtTheEndOfTurn)
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_EXTRA_TURN_ANY_ACTION_LATER"), title);
		}
		else if (cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility.ExtraTurnType == CAbilityExtraTurn.EExtraTurnType.BothActionsLater)
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_EXTRA_TURN_BOTH_ACTIONS_LATER"), playerActor.Initiative()), title);
		}
		else
		{
			InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_EXTRA_TURN"), title);
		}
		int maxCardsSelected = ((cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility.ExtraTurnType != CAbilityExtraTurn.EExtraTurnType.BothActions && cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility.ExtraTurnType != CAbilityExtraTurn.EExtraTurnType.BothActionsLater) ? 1 : 2);
		GameState.CurrentExtraTurnAbility = cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility;
		Func<CAbilityCard, bool> func = null;
		if (GameState.CurrentExtraTurnAbility.AbilityTypeFilter.Count > 0)
		{
			func = (CAbilityCard card) => GameState.CurrentExtraTurnAbility.IsValidAbility(card) ? true : false;
		}
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		CardsHandManager instance = Singleton<CardsHandManager>.Instance;
		CPlayerActor playerActor2 = playerActor;
		List<CardPileType> selectableCardTypes = new List<CardPileType> { CardPileType.Hand };
		Func<CAbilityCard, bool> cardSelectableFilter = func;
		instance.Show(playerActor2, CardHandMode.CardsSelection, CardPileType.Any, selectableCardTypes, maxCardsSelected, func != null, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.RESET, forceUseCurrentRoundCards: true, allowFullDeckPreview: true, null, cardSelectableFilter);
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONENDSELECTION, (cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility.GetAbilityBaseCard() is CItem) ? LocalizationManager.GetTranslation("GUI_CONFIRM_USE_ITEM") : LocalizationManager.GetTranslation("GUI_END_SELECTION"));
		readyButton.SetInteractable(interactable: false);
		m_UndoButton.Toggle(active: true);
		UndoButton undoButton = m_UndoButton;
		CAbilityExtraTurn extraTurnAbility = cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility;
		int interactable;
		if (extraTurnAbility != null)
		{
			AbilityData.MiscAbilityData miscAbilityData = extraTurnAbility.MiscAbilityData;
			if (miscAbilityData != null && miscAbilityData.CanUndo.HasValue)
			{
				interactable = (cSelectExtraTurnCards_MessageData.m_ExtraTurnAbility.MiscAbilityData.CanUndo.Value ? 1 : 0);
				goto IL_036a;
			}
		}
		interactable = 0;
		goto IL_036a;
		IL_036a:
		undoButton.SetInteractable((byte)interactable != 0);
		m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP"), hideOnClick: true, true, () =>
		{
			Singleton<CardsHandManager>.Instance.Hide(playerActor);
			GameState.CancelExtraTurn();
			readyButton.ClearAlternativeAction();
		});
		m_CurrentActor = cSelectExtraTurnCards_MessageData.m_ActorSpawningMessage;
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		SetChoreographerState(ChoreographerStateType.WaitingForCardSelection, 0, null);
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ExtraTurnCardSelection);
		}
	}

