		GameState.FinishEndExtraTurn();
		_ = LocalizationManager.GetTranslation(cEndedExtraTurn.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cEndedExtraTurn.m_ActorSpawningMessage);
	}

