	[MessageHandler(CMessageData.MessageType.PlayerSelectingObjectPosition)]
	private void Handle_PlayerSelectingObjectPosition(CMessageData message)
	{
		m_LastSelectedTiles = null;
		CPlayerSelectingObjectPosition_MessageData messageData = (CPlayerSelectingObjectPosition_MessageData)message;
		CActor cActor = (m_CurrentActor = messageData.m_Ability.TargetingActor);
		m_CurrentAbility = messageData.m_Ability;
		TileBehaviour.SetCallback(TileHandler);
		DisableTileSelection(active: false);
		CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
		if (!messageData.m_ShowConsumeBar)
		{
			Singleton<UIUseAugmentationsBar>.Instance.Hide();
		}
		if (!messageData.m_ShowActiveBonusBar)
		{
			Singleton<UIActiveBonusBar>.Instance.Hide();
		}
		CardsActionControlller.s_Instance?.RefreshConsumeBar(m_CurrentActor, m_CurrentAbility, WaitingForConfirm);
		Singleton<HelpBox>.Instance.Hide();
		if (message.m_ActorSpawningMessage is CPlayerActor)
		{
			Singleton<UIUseItemsBar>.Instance.ShowUsableItems(message.m_ActorSpawningMessage, (CItem item) => item.YMLData.Data.CompareAbility != null && (item.YMLData.Data.CompareAbility.CompareAbility(messageData.m_Ability) || item.SlotState == CItem.EItemSlotState.Selected), (messageData.m_SpawnType == ScenarioManager.ObjectImportType.Trap) ? null : "GUI_USE_ITEM_MOVEMENT_TIP");
		}
		if (m_CurrentAbility is CAbilityNullHex && message.m_ActorSpawningMessage is CPlayerActor playerActor && !m_CurrentAbility.GetMiscVar("SkipPlayerFocus").GetBool())
		{
			InitiativeTrack.Instance?.Select(playerActor, forced: true);
		}
		if (messageData.m_Ability is CAbilityDestroyObstacle)
		{
			GUIInterface.s_GUIInterface.SetStatusText(LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_DESTROY_OBSTACLES"));
		}
		else if (messageData.m_TileFilter.Contains(CAbilityFilter.EFilterTile.EmptyHex))
		{
			GUIInterface.s_GUIInterface.SetStatusText("Select Position to place " + messageData.m_SpawnType);
		}
		else
		{
			GUIInterface.s_GUIInterface.SetStatusText("Select " + messageData.m_TileFilter.ToString());
		}
		if (cActor != null)
		{
			WorldspaceStarHexDisplay.Instance.ResetPlayerAttackType();
			ShowAbilityHelpBoxTooltip(messageData.m_Ability);
			if (messageData.m_SpawnType == ScenarioManager.ObjectImportType.HeroSummons && messageData.m_Ability is CAbilitySummon cAbilitySummon)
			{
				string translation = LocalizationManager.GetTranslation(cAbilitySummon.SelectedLocKey);
				Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SUMMON_SELECT_HEX"), translation), string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SUMMON"), translation));
			}
		}
		if (messageData.m_Ability.AreaEffect != null)
		{
			WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_Ability, WorldspaceStarHexDisplay.EAbilityDisplayType.SelectObjectPositionAreaOfEffect, messageData.m_SpawnType, messageData.m_TileFilter);
		}
		else
		{
			WorldspaceStarHexDisplay.EAbilityDisplayType attackType = (messageData.m_IsPositive ? WorldspaceStarHexDisplay.EAbilityDisplayType.SelectObjectPosition : WorldspaceStarHexDisplay.EAbilityDisplayType.SelectObjectPositionNegative);
			WorldspaceStarHexDisplay.Instance.SetDisplayAbility(messageData.m_Ability, attackType, messageData.m_SpawnType, messageData.m_TileFilter);
		}
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
		WorldspacePanelUIController.RefreshPreviewPotentialTileSubabilities(messageData.m_Ability);
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		bool flag = WorldspaceStarHexDisplay.Instance.CurrentNumberSelectedTargets() > 0;
		m_UndoButton.Toggle(cActor != null, flag ? UndoButton.EButtonState.EUNDOBUTTONCLEARTARGETS : UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
		m_UndoButton.SetInteractable(messageData.m_Ability.CanUndo && ((flag && !messageData.m_Ability.AllTargets) || FirstAbility || messageData.m_Ability.AllowUndoAfterFirst));
		m_SkipButton.Toggle(cActor != null, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, messageData.m_Ability.CanSkip);
		if (messageData.m_Ability.TilesSelected.Count > 0)
		{
			string text = ((!messageData.m_Ability.AllTargets && messageData.m_Ability.NumberTargets != 1 && messageData.m_Ability.NumberTargets < 99 && !(messageData.m_Ability is CAbilityLoot) && !(messageData.m_Ability is CAbilityMoveTrap { OneTargetAtATime: not false }) && (messageData.m_Ability.NumberTargets != -1 || !(messageData.m_Ability is CAbilityCreateLimitedHazardousTerrain))) ? string.Format("{0} {1}/{2}", LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION"), messageData.m_Ability.NumberTargets - messageData.m_Ability.NumberTargetsRemaining, messageData.m_Ability.NumberTargets) : LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION"));
			readyButton.Toggle(cActor != null, ReadyButton.EButtonState.EREADYBUTTONCONFIRM, text, hideOnClick: true, glowingEffect: true);
			readyButton.SetInteractable(messageData.m_Ability.EnoughTargetsSelected() && !messageData.m_Ability.IsWaitingForSingleTargetItem() && !messageData.m_Ability.IsWaitingForSingleTargetActiveBonus());
			m_LastSelectedTiles = new List<CClientTile>();
			foreach (CTile item in messageData.m_Ability.TilesSelected)
			{
				m_LastSelectedTiles.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item.m_ArrayIndex.X, item.m_ArrayIndex.Y]);
			}
		}
		else
		{
			readyButton.Toggle(cActor != null, ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED, LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION"), hideOnClick: true, glowingEffect: true);
		}
		List<CActiveBonus.EActiveBonusBehaviourType> ignoreBehaviours = ((messageData.m_Ability is CAbilityControlActor) ? new List<CActiveBonus.EActiveBonusBehaviourType> { CActiveBonus.EActiveBonusBehaviourType.BetweenActionAbilities } : null);
		Singleton<UIActiveBonusBar>.Instance.ShowActiveBonus(messageData.m_ActorSpawningMessage, messageData.m_Ability.AbilityType, CActiveBonus.EActiveBonusBehaviourType.None, null, messageData.m_Ability.AbilityHasHappened, messageData.m_Ability, ignoreBehaviours, clearPrev: false);
		TryShowAbilityInvalidTile(messageData.m_Ability);
		if (FFSNetwork.IsOnline && cActor != null)
		{
			if (!cActor.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.TargetSelection);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.TargetSelection);
			}
		}
	}

	private void TryShowAbilityInvalidTile(CAbility ability)
	{
		if (!string.IsNullOrEmpty(ability.InvalidTileReason))
		{
			Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation(ability.InvalidTileReason), HelpBox.FormatTarget.NONE, "INVALID_TILE");
		}
		else
		{
			Singleton<HelpBox>.Instance.Hide("INVALID_TILE", onlyIfIdMatches: true);
		}
	}

