		m_LastSelectedTiles?.Clear();
		if (m_LastSelectedTiles == null)
		{
			m_LastSelectedTiles = new List<CClientTile>();
		}
		m_LastSelectedTiles.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cMovingTerrain_MessageData.m_From.m_ArrayIndex.X, cMovingTerrain_MessageData.m_From.m_ArrayIndex.Y]);
		m_LastSelectedTiles.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cMovingTerrain_MessageData.m_To.m_ArrayIndex.X, cMovingTerrain_MessageData.m_To.m_ArrayIndex.Y]);
		WorldspaceStarHexDisplay.Instance.ClearNonTargetHexHighlights(null, null, m_LastSelectedTiles);
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cMovingTerrain_MessageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cMovingTerrain_MessageData.m_Ability, cMovingTerrain_MessageData.m_ActorSpawningMessage, new List<string>
		{
			cMovingTerrain_MessageData.AnimOverload,
			GetNonOverloadAnim(cMovingTerrain_MessageData.m_Ability)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
