	[MessageHandler(CMessageData.MessageType.WaitForMultiplayerSyncPoint)]
	private void Handle_WaitForMultiplayerSyncPoint(CMessageData message)
	{
		CWaitForMultiplayerSyncPoint_MessageData cWaitForMultiplayerSyncPoint_MessageData = (CWaitForMultiplayerSyncPoint_MessageData)message;
		SetBlockClientMessageProcessing(active: true);
		if (FFSNetwork.IsOnline)
		{
			SyncPointCoroutine = StartCoroutine(WaitForMultiplayerSyncPoint(cWaitForMultiplayerSyncPoint_MessageData));
		}
		else
		{
			HostFinishedWaitForMultiplayerSyncPoint(cWaitForMultiplayerSyncPoint_MessageData.m_OnFinish);
		}
	}

	public static void StepCompleteAfterSyncPoint()
	{
		m_StepCompleteAfterSync++;
	}

	private IEnumerator WaitForMultiplayerSyncPoint(CWaitForMultiplayerSyncPoint_MessageData messageData)
	{
		m_HostAllowedWaitForMultiplayerSyncPointToContinue = false;
		bool reportedSoftlock = false;
		float timeOutTime = Timekeeper.instance.m_GlobalClock.time + 10f;
		if (FFSNetwork.IsHost)
		{
			m_WaitForMultiplayerSyncPointPlayers.Add(PlayerRegistry.MyPlayer);
			do
			{
				yield return new WaitForEndOfFrame();
				if (!reportedSoftlock && Timekeeper.instance.m_GlobalClock.time > timeOutTime)
				{
					reportedSoftlock = true;
					UIMultiplayerNotifications.ShowPossibleTimeout();
				}
				if (!FFSNetwork.IsOnline)
				{
					HostFinishedWaitForMultiplayerSyncPoint(messageData.m_OnFinish);
					yield break;
				}
			}
			while (PlayerRegistry.PlayersWeShouldWaitFor.Any((NetworkPlayer x) => m_WaitForMultiplayerSyncPointPlayers.Find((NetworkPlayer y) => y.PlayerID == x.PlayerID) == null));
			Synchronizer.SendSideAction(GameActionType.HostConfirmsAllClientsReachedSyncPoint);
		}
		else
		{
			Synchronizer.SendSideAction(GameActionType.ClientReachedSyncPoint, null, canBeUnreliable: false, sendToHostOnly: true);
			do
			{
				yield return new WaitForEndOfFrame();
				if (!reportedSoftlock && Timekeeper.instance.m_GlobalClock.time > timeOutTime)
				{
					reportedSoftlock = true;
					UIMultiplayerNotifications.ShowPossibleTimeout();
				}
				if (!FFSNetwork.IsOnline)
				{
					HostFinishedWaitForMultiplayerSyncPoint(messageData.m_OnFinish);
					yield break;
				}
			}
			while (!m_HostAllowedWaitForMultiplayerSyncPointToContinue);
		}
		yield return null;
		HostFinishedWaitForMultiplayerSyncPoint(messageData.m_OnFinish);
	}

	private void HostFinishedWaitForMultiplayerSyncPoint(Action action)
	{
		UIMultiplayerNotifications.HidePossibleTimeout();
		SyncPointCoroutine = null;
		SetBlockClientMessageProcessing(active: false);
		GameState.FinishedMultiplayerSyncWait();
		m_WaitForMultiplayerSyncPointPlayers.Clear();
		ScenarioRuleClient.ToggleMessageProcessing(process: false);
		if (ScenarioManager.CurrentScenarioState != null)
		{
			action?.Invoke();
			for (int i = 0; i < m_StepCompleteAfterSync; i++)
			{
				ScenarioRuleClient.StepComplete();
			}
		}
		m_StepCompleteAfterSync = 0;
		ScenarioRuleClient.ToggleMessageProcessing(process: true);
	}

	public static void ClientReachedSyncPoint(GameAction action)
	{
		NetworkPlayer player = PlayerRegistry.GetPlayer(action.PlayerID);
		if (player != null)
		{
			if (!m_WaitForMultiplayerSyncPointPlayers.Contains(player))
			{
				m_WaitForMultiplayerSyncPointPlayers.Add(player);
				Log.SimpleInfo("Host acknowledged client " + player.Username + "( ID: " + player.PlayerID.ToString() + " ) ready for logic thread to resume.");
			}
			else
			{
				Log.Error("Player " + player.PlayerID.ToString() + " is already added to m_WaitForMultiplayerSyncPointPlayers");
			}
		}
		else
		{
			Log.NetworkWarning("Error determining the player who reached logic thread sync check. NetworkPlayer returns null.");
		}
	}

	public static void HostConfirmAllClientsReachedSyncPoint()
	{
		m_HostAllowedWaitForMultiplayerSyncPointToContinue = true;
	}

	private IEnumerator WaitForGenericCondition(Func<bool> predicate, Action onFinish)
	{
		while (!predicate())
		{
			yield return new WaitForEndOfFrame();
		}
		onFinish();
	}

	[MessageHandler(CMessageData.MessageType.ShowElementPicker)]
	private void Handle_ShowElementPicker(CMessageData message)
	{
		CShowElementPicker_MessageData messageData = (CShowElementPicker_MessageData)message;
		CAbility ability = (CAbility)(((object)messageData.m_ConsumeAbility) ?? ((object)messageData.m_InfuseAbility));
		if (ability != null)
		{
			WorldspaceStarHexDisplay.Instance.SetDisplayAbility(ability);
			WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
			WorldspacePanelUIController.ResetPreviewEffects();
		}
		int num = messageData.m_InfuseAbility.ElementsToInfuse.Count((ElementInfusionBoardManager.EElement w) => w == ElementInfusionBoardManager.EElement.Any);
		m_UndoButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player && messageData.m_InfuseAbility.CanUndo && FirstAbility, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
		m_SkipButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player && messageData.m_InfuseAbility.CanSkip, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, null, () =>
		{
			if (ability == null)
			{
				PhaseManager.CurrentPhaseAction?.ElementsToInfuse.Clear();
			}
			m_ElementsInfusedThisAbility.Clear();
			messageData.m_InfuseAbility.SelectedElementsToInfuse.Clear();
		});
		Singleton<HelpBox>.Instance.ShowTranslated((num <= 1) ? LocalizationManager.GetTranslation("GUI_CHOOSE_ELEMENT_INFUSE") : string.Format(LocalizationManager.GetTranslation("GUI_CHOOSE_ELEMENTS_INFUSE"), num));
		CPlayerActor cPlayerActor;
		if (messageData.m_ActorSpawningMessage is CPlayerActor)
		{
			cPlayerActor = (CPlayerActor)messageData.m_ActorSpawningMessage;
		}
		else
		{
			cPlayerActor = ((!(messageData.m_ActorSpawningMessage is CHeroSummonActor)) ? (CurrentPlayerActor ?? (InitiativeTrack.Instance.SelectedActor().Actor as CPlayerActor)) : ((CHeroSummonActor)messageData.m_ActorSpawningMessage).Summoner);
		}
		if (cPlayerActor != null && !cPlayerActor.IsDead && (cPlayerActor.MindControlAbility == null || cPlayerActor.MindControlAbility.TargetingActor != cPlayerActor))
		{
			Singleton<CardsHandManager>.Instance.Show(cPlayerActor, CardHandMode.ActionSelection, (!cPlayerActor.IsTakingExtraTurn) ? CardPileType.Round : CardPileType.ExtraTurn, CardPileType.Any, 0, fadeUnselectableCards: false, highlightSelectableCards: false, allowFullCardPreview: true, CardsHandUI.CardActionsCommand.NONE);
		}
		Singleton<UIUseAbilitiesBar>.Instance.ShowInfuseAbilities(cPlayerActor, new List<CAbilityInfuse> { messageData.m_InfuseAbility }, (CAbility cAbility, List<ElementInfusionBoardManager.EElement> elements) =>
		{
			Log.Trace("Will Infuse element: " + elements);
			messageData.m_InfuseAbility.SelectedElementsToInfuse.AddRange(elements);
			readyButton.SetInteractable(messageData.m_InfuseAbility.SelectedElementsToInfuse.Count > 0);
		}, (CAbility cAbility, List<ElementInfusionBoardManager.EElement> elements) =>
		{
			Log.Trace("Will NOT Infuse element: " + elements);
			foreach (ElementInfusionBoardManager.EElement element in elements)
			{
				messageData.m_InfuseAbility.SelectedElementsToInfuse.Remove(element);
			}
			readyButton.SetInteractable(messageData.m_InfuseAbility.SelectedElementsToInfuse.Count > 0);
		});
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONTINUE, LocalizationManager.GetTranslation("GUI_CONFIRM"), hideOnClick: true, glowingEffect: true);
		readyButton.SetInteractable(messageData.m_InfuseAbility.SelectedElementsToInfuse.Count > 0);
		if (FFSNetwork.IsOnline)
		{
			if (!messageData.m_ActorSpawningMessage.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ElementPicking, savePreviousState: true);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ElementPicking, savePreviousState: true);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ChosenAbilityChanged)]
	private void Handle_ChosenAbilityChanged(CMessageData message)
	{
		CChosenAbilityChanged_MessageData cChosenAbilityChanged_MessageData = (CChosenAbilityChanged_MessageData)message;
		WorldspaceStarHexDisplay.Instance.SetDisplayAbility(cChosenAbilityChanged_MessageData.m_ChooseAbility);
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
