	[MessageHandler(CMessageData.MessageType.ForceShowTilePreview)]
	private void Handle_ForceShowTilePreview(CMessageData message)
	{
		CForceShowTilePreview_MessageData cForceShowTilePreview_MessageData = (CForceShowTilePreview_MessageData)message;
		TryForceShowTilePreview(cForceShowTilePreview_MessageData.m_Ability);
	}

	public void TryForceShowTilePreview(CAbility ability)
	{
		foreach (IHexControl.HexMode value in Enum.GetValues(typeof(IHexControl.HexMode)))
		{
			string text = "ForcePreviewTiles";
			if (value != IHexControl.HexMode.Selected)
			{
				text += value;
			}
			if (!ability.GetVar(text).isUnknown)
			{
				WorldspaceStarHexDisplay.Instance.SetDisplayAbility(ability, WorldspaceStarHexDisplay.EAbilityDisplayType.SelectObjectPosition, ability.SpawnTypePreview);
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.TargetSelection;
				WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
				break;
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.AddNewCards)]
	private void Handle_AddNewCards(CMessageData message)
	{
		CAddNewCards_MessageData cAddNewCards_MessageData = (CAddNewCards_MessageData)message;
		List<CAbilityCard> list = new List<CAbilityCard>();
		foreach (CAbilityCard allAbilityCard in CharacterClassManager.AllAbilityCards)
		{
			if (cAddNewCards_MessageData.ids.Contains(allAbilityCard.ID))
			{
				list.Add(allAbilityCard);
			}
		}
		if (list.Count == 0)
		{
			return;
		}
		foreach (CAbilityCard card in list)
		{
			CPlayerActor cPlayerActor = ScenarioManager.Scenario.PlayerActors.FirstOrDefault((CPlayerActor x) => x.CharacterClass.ID == card.ClassID);
			Singleton<CardsHandManager>.Instance.GetHand(cPlayerActor).SpawnCardUIFromCheat(card);
			Singleton<CardsHandManager>.Instance.UpdateElements(cPlayerActor);
			if (Singleton<CardsHandManager>.Instance.IsActive())
			{
				CardsHandManager.ShowCardsSelection(cPlayerActor);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ShowSelectAbility)]
	private void Handle_ShowSelectAbility(CMessageData message)
	{
		CShowSelectAbility_MessageData cShowSelectAbility_MessageData = (CShowSelectAbility_MessageData)message;
		CAbilityChooseAbility ability = cShowSelectAbility_MessageData.m_ChooseAbility;
		WorldspaceStarHexDisplay.Instance.SetDisplayAbility(ability);
		m_CurrentActor = ability.TargetingActor;
		readyButton.ClearAlternativeAction();
		Singleton<UIUseItemsBar>.Instance.Hide(!(message.m_ActorSpawningMessage is CPlayerActor) || !ability.IsItemAbility);
		if (ability.ApplicableAbilities.Count > 0)
		{
			bool flag = ability.CanUndo && message.m_ActorSpawningMessage.Type == CActor.EType.Player;
			m_UndoButton.Toggle(flag, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
			m_UndoButton.SetInteractable(flag && cShowSelectAbility_MessageData.m_IsFirstAbility);
			if (flag)
			{
				if (GameState.OverridenActionActorStack.TryPeek(out var overrideData))
				{
					m_UndoButton.SetOnClickOverrider(() =>
					{
						m_UndoButton.ClearOnClickOverriders();
						CPhaseAction.CPhaseAbility currentPhaseAbility = PhaseManager.CurrentPhaseAction.CurrentPhaseAbility;
						currentPhaseAbility.m_PostEndAction = (Action)Delegate.Combine(currentPhaseAbility.m_PostEndAction, (Action)(() =>
						{
							if (overrideData != null)
							{
								GameState.OverrideCurrentActorForOneAction(ability.TargetingActor, null, overrideData.OverrideKillActor, overrideData.AddedAugments, overrideData.ControllingActor, overrideData.UseControllingActorModifierDeck);
							}
							PhaseManager.CurrentPhaseAction.StackNextAbilities(new List<CAbility> { ability }, ability.TargetingActor);
						}));
						Pass();
					}, UndoButton.EButtonState.EUNDOBUTTONUNDO);
				}
			}
			m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, ability.CanSkip);
			readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONTINUE, LocalizationManager.GetTranslation(ability.IsItemAbility ? "GUI_CONFIRM_USE_ITEM" : "GUI_CONFIRM"), hideOnClick: true, glowingEffect: true);
			readyButton.SetInteractable(ability.ChosenAbility != null);
			readyButton.QueueAlternativeAction(() =>
			{
				ScenarioRuleClient.StepComplete();
				Singleton<UIUseAbilitiesBar>.Instance.Hide();
				Singleton<UIAbilityCardPicker>.Instance.Hide();
				readyButton.ClearAlternativeAction();
			});
			if (!string.IsNullOrEmpty(ability.PerkID))
			{
				PerksYMLData perkData = ability.perkData;
				Singleton<HelpBox>.Instance.Show(perkData.Description, ability);
			}
			else if (ability.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
			{
				ShowAbilityHelpBoxTooltip(ability);
			}
			else
			{
				string text = ((ability.GetAbilityBaseCard() != null) ? ability.GetAbilityBaseCard().Name : ability.ParentAbilityBaseCard.Name);
				if (!string.IsNullOrEmpty(text) && ability.GetAbilityBaseCard().CardType != CBaseCard.ECardType.Dummy)
				{
					Singleton<HelpBox>.Instance.Show($"GUI_CHOOSE_ABILITY_{text}", ability);
				}
			}
			if (ability.GetMiscVar("ShowMonsterCards").GetBool())
			{
				List<MonsterCardChoice> list = new List<MonsterCardChoice>();
				string monsterClassKey = ability.GetMiscVar("MonsterClassID").GetString();
				CMonsterClass cMonsterClass = MonsterClassManager.Classes.Find((CMonsterClass x) => x.NonEliteVariant == null && x.ID.StartsWith(monsterClassKey, StringComparison.InvariantCultureIgnoreCase));
				foreach (CAbility chooseAbility in ability.ChooseAbilities)
				{
					int id = chooseAbility.GetMiscVar("CardIdToShow").GetInt();
					CMonsterAbilityCard abilityCard = cMonsterClass.AbilityCardsPool.FirstOrDefault((CMonsterAbilityCard x) => x.ID == id);
					list.Add(new MonsterCardChoice(ability, abilityCard, cMonsterClass));
				}
				Singleton<UIAbilityCardPicker>.Instance.Show(ability.TargetingActor, list, 1, (List<IAbilityCardOption> selectedAbility) =>
				{
					MonsterCardChoice monsterCardChoice = selectedAbility?.FirstOrDefault() as MonsterCardChoice;
					CAbility cAbility = ability.ApplicableAbilities.FirstOrDefault((CAbility x) => x.Name.Equals(monsterCardChoice.AbilityCard.ID.ToString()));
					if (cAbility != null)
					{
						ability.AbilityChosen(ability.ApplicableAbilities.IndexOf(cAbility));
						readyButton.SetInteractable(interactable: true);
					}
					else
					{
						ability.AbilityChosen(-1);
						readyButton.SetInteractable(interactable: false);
					}
				}, () =>
				{
					ability.ResetChosenAbility();
					readyButton.SetInteractable(interactable: false);
				});
			}
			else
			{
				Singleton<UIUseAbilitiesBar>.Instance.ShowChooseAbility(cShowSelectAbility_MessageData.m_ActorSpawningMessage, ability, (CAbility selectedAbility) =>
				{
					ability.AbilityChosen(ability.ApplicableAbilities.IndexOf(selectedAbility));
					readyButton.SetInteractable(interactable: true);
				}, () =>
				{
					ability.ResetChosenAbility();
					readyButton.SetInteractable(interactable: false);
				});
			}
		}
		else
		{
			bool flag2 = ability.CanUndo && message.m_ActorSpawningMessage.Type == CActor.EType.Player;
			m_UndoButton.Toggle(flag2, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
			m_UndoButton.SetInteractable(flag2 && cShowSelectAbility_MessageData.m_IsFirstAbility);
			m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, ability.CanSkip);
		}
		if (FFSNetwork.IsOnline && !message.m_ActorSpawningMessage.IsUnderMyControl())
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionProcessor.CurrentPhase);
		}
	}

