			}
			m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, ability.CanSkip);
			readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONTINUE, LocalizationManager.GetTranslation(ability.IsItemAbility ? "GUI_CONFIRM_USE_ITEM" : "GUI_CONFIRM"), hideOnClick: true, glowingEffect: true);
			readyButton.SetInteractable(ability.CanBePerformed());
			readyButton.QueueAlternativeAction(() =>
			{
				ScenarioRuleClient.StepComplete();
				Singleton<UIUseAbilitiesBar>.Instance.Hide();
				readyButton.ClearAlternativeAction();
			});
			if (!string.IsNullOrEmpty(ability.PerkID))
			{
				PerksYMLData perkData = ability.perkData;
				Singleton<HelpBox>.Instance.Show(perkData.Description, ability);
			}
			else if (ability.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
			{
				ShowAbilityHelpBoxTooltip(ability);
			}
			else
			{
				string text = ((ability.GetAbilityBaseCard() != null) ? ability.GetAbilityBaseCard().Name : ability.ParentAbilityBaseCard.Name);
				if (!string.IsNullOrEmpty(text) && ability.GetAbilityBaseCard().CardType != CBaseCard.ECardType.Dummy)
				{
					Singleton<HelpBox>.Instance.Show($"GUI_CHOOSE_ABILITY_{text}", ability);
				}
			}
			Singleton<UIUseAbilitiesBar>.Instance.ShowChooseNextModifiers(cShowSetNextAttackModifiers_MessageData.m_ActorSpawningMessage, ability);
		}
		else
		{
			bool flag2 = ability.CanUndo && message.m_ActorSpawningMessage.Type == CActor.EType.Player;
			m_UndoButton.Toggle(flag2, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
			m_UndoButton.SetInteractable(flag2 && cShowSetNextAttackModifiers_MessageData.m_IsFirstAbility);
			m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, ability.CanSkip);
		}
		if (FFSNetwork.IsOnline && !message.m_ActorSpawningMessage.IsUnderMyControl())
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionProcessor.CurrentPhase);
		}
	}

