	[MessageHandler(CMessageData.MessageType.EndAbility)]
	private void Handle_EndAbility(CMessageData message)
	{
		if (PhaseManager.CurrentPhaseAction == null)
		{
			onCharacterAbilityComplete?.Invoke();
			onCharacterAbilityComplete = null;
			if (m_WaitState.m_State == ChoreographerStateType.WaitingForEndAbilityAnimSync)
			{
				SetChoreographerState(ChoreographerStateType.Play, 0, null);
			}
			return;
		}
		CEndActorAbility_MessageData messageData = (CEndActorAbility_MessageData)message;
		WorldspaceStarHexDisplay.Instance.ResetPlayerAttackType();
		if (messageData.m_ActorSpawningMessage != null && messageData.m_ActorSpawningMessage.OriginalType == CActor.EType.Player)
		{
			InitiativeTrackActorBehaviourBase initiativeTrackActorBehaviourBase = InitiativeTrack.Instance.FindInitiativeTrackActor(messageData.m_ActorSpawningMessage);
			if (initiativeTrackActorBehaviourBase != null)
			{
				initiativeTrackActorBehaviourBase.RefreshAbilities();
			}
		}
		WorldspaceStarHexDisplay.Instance.LockView = false;
		m_UndoButton.Toggle(active: false);
		m_SkipButton.Toggle(active: false);
		TileBehaviour.SetCallback(TileHandler);
		if (messageData.m_IsLastAbility)
		{
			InfusionBoardUI.Instance?.UnreserveElements();
		}
		Singleton<UIUseItemsBar>.Instance.Hide();
		Singleton<UIActiveBonusBar>.Instance.Hide();
		Singleton<UIUseAbilitiesBar>.Instance.Hide();
		Waypoint.s_LockWaypoints = false;
		Waypoint.Clear();
		CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
		if (ActorsBeingTargetedForVFX != null)
		{
			ActorsBeingTargetedForVFX.Clear();
		}
		Singleton<CardsHandManager>.Instance.OnAbilityEnd(m_CurrentActor, m_CurrentAbility);
		SetChoreographerState(ChoreographerStateType.Play, 0, null);
		Log.Info("End Ability OnCharacterAbilityComplete Action is " + ((onCharacterAbilityComplete != null) ? "NOT NULL" : "NULL"));
		if (onCharacterAbilityComplete != null && messageData.m_IsLastAbility)
		{
			Action<bool> onFinish = (bool switchBackToSavedStateIfOnline) =>
			{
				onCharacterAbilityComplete();
				onCharacterAbilityComplete = null;
				if (FFSNetwork.IsOnline & switchBackToSavedStateIfOnline)
				{
					ActionProcessor.SetState(ActionProcessorStateType.SwitchBackToSavedState);
				}
				if (messageData.m_AdvanceGameState)
				{
					ScenarioRuleClient.EndAbilitySynchronise();
				}
			};
			if (messageData.m_ActorSpawningMessage != null && message.m_ActorSpawningMessage.Type == CActor.EType.Player)
			{
				if (PhaseManager.PhaseType == CPhase.PhaseType.Action && ((CPhaseAction)PhaseManager.Phase).AbilityHappened())
				{
					CardsActionControlller.s_Instance.PickAnyInfusionElements(message.m_ActorSpawningMessage, (bool pickingSuccessful) =>
					{
						onFinish(pickingSuccessful);
					});
				}
				else
				{
					onFinish(obj: false);
				}
			}
			else
			{
				onFinish(obj: false);
			}
		}
		else
		{
			Action onFinish2 = () =>
			{
				if (messageData.m_AdvanceGameState)
				{
					ScenarioRuleClient.EndAbilitySynchronise();
				}
			};
			if (messageData.m_ActorSpawningMessage != null && message.m_ActorSpawningMessage is CHeroSummonActor cHeroSummonActor)
			{
				CAbility currentAbility = m_CurrentAbility;
				if (currentAbility != null && currentAbility.AbilityType == CAbility.EAbilityType.Attack && cHeroSummonActor.SummonData.AttackInfuse == ElementInfusionBoardManager.EElement.Any)
				{
					Singleton<UIUseAbilitiesBar>.Instance.ShowGenericInfusion(cHeroSummonActor.Summoner, (ElementInfusionBoardManager.EElement element) =>
					{
						Singleton<UIUseAbilitiesBar>.Instance.Hide();
						if (FFSNetwork.IsOnline)
						{
							ActionProcessor.SetState(ActionProcessorStateType.SwitchBackToSavedState);
						}
						onFinish2();
					}, m_CurrentAbility, cHeroSummonActor.BaseCard, LocalizationManager.GetTranslation(cHeroSummonActor.ActorLocKey()), LocalizationManager.GetTranslation("GUI_CHOOSE_ELEMENT_INFUSE"));
					if (FFSNetwork.IsOnline)
					{
						if (!cHeroSummonActor.Summoner.IsUnderMyControl())
						{
							ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ElementPicking, savePreviousState: true);
						}
						else
						{
							ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ElementPicking, savePreviousState: true);
						}
					}
					goto IL_0350;
				}
			}
			if (messageData.m_AdvanceGameState)
			{
				ScenarioRuleClient.EndAbilitySynchronise();
			}
		}
		goto IL_0350;
		IL_0350:
		m_CurrentAbility = null;
		FirstAbility = false;
	}

	[MessageHandler(CMessageData.MessageType.ShowConsumes)]
	private void Handle_ShowConsumes(CMessageData message)
	{
		CShowConsumes_MessageData messageData = (CShowConsumes_MessageData)message;
		messageData.m_Ability.DontMoveAbilityState = true;
		messageData.m_Ability.WaitingForUI = true;
		m_CurrentActor = messageData.m_ActorSpawningMessage;
		Singleton<UIUseAbilitiesBar>.Instance.ShowConsumeAbilities((CPlayerActor)messageData.m_ActorSpawningMessage, new List<CAbilityConsume> { messageData.m_Ability }, (CAbility ability, List<ElementInfusionBoardManager.EElement> elements) =>
		{
			Log.Trace("Consuming element: " + elements);
			messageData.m_Ability.ElementsToConsume.AddRange(elements);
			messageData.m_Ability.TrophiesToConsume = messageData.m_Ability.Consumes.Sum((AbilityConsume consume) => consume.ConsumeData.Trohpies);
			messageData.m_Ability.ResonanceToConsume = messageData.m_Ability.Consumes.Sum((AbilityConsume consume) => consume.ConsumeData.Resonance);
			bool num = messageData.m_Ability.ElementsToConsume.Count > 0 || messageData.m_Ability.TrophiesToConsume > 0 || messageData.m_Ability.ResonanceToConsume > 0;
			bool flag = AnyConsumeGivesAttackAbility(messageData.m_Ability.Consumes);
			bool flag2 = messageData.m_ActorSpawningMessage.Tokens.HasKey(CCondition.ENegativeCondition.Disarm);
			bool interactable = num && !(flag & flag2) && messageData.m_Ability.CanConsume();
			readyButton.SetInteractable(interactable);
		}, (CAbility ability, List<ElementInfusionBoardManager.EElement> elements) =>
		{
			Log.Trace("NOT Consuming element: " + elements);
			foreach (ElementInfusionBoardManager.EElement element in elements)
			{
				messageData.m_Ability.ElementsToConsume.Remove(element);
			}
			readyButton.SetInteractable(messageData.m_Ability.ElementsToConsume.Count > 0);
		});
		if (messageData.m_Ability.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
		{
			Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation(messageData.m_Ability.HelpBoxTooltipLocKey));
		}
		m_UndoButton.Toggle(messageData.m_Ability.CanUndo, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
		m_UndoButton.SetInteractable(messageData.m_IsFirstAbility);
		m_SkipButton.Toggle(messageData.m_Ability.CanSkip, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, messageData.m_Ability.CanSkip);
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONTINUE, LocalizationManager.GetTranslation("GUI_CONFIRM"), hideOnClick: true, glowingEffect: true);
		readyButton.AlternativeAction(() =>
		{
			messageData.m_Ability.DontMoveAbilityState = false;
			messageData.m_Ability.WaitingForUI = false;
			readyButton.ClearAlternativeAction();
			m_UndoButton.ClearOnClickOverriders();
			Singleton<UIActiveBonusBar>.Instance.Hide();
			Singleton<UIUseAbilitiesBar>.Instance.Hide(clearSelection: true);
			ScenarioRuleClient.StepComplete();
			InfusionBoardUI.Instance?.UpdateBoard();
		}, ReadyButton.EButtonState.EREADYBUTTONCONFIRM);
		readyButton.AddUntoggleAction(() =>
		{
			messageData.m_Ability.WaitingForUI = false;
		});
		readyButton.SetInteractable(messageData.m_Ability.ElementsToConsume.Count > 0);
		if (FFSNetwork.IsOnline)
		{
			if (!messageData.m_ActorSpawningMessage.IsUnderMyControl())
			{
				messageData.m_Ability.WaitingForUI = false;
				messageData.m_Ability.DontMoveAbilityState = false;
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ElementPicking, savePreviousState: true);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ElementPicking, savePreviousState: true);
			}
		}
		static bool AnyConsumeGivesAttackAbility(List<AbilityConsume> consumeAbilities)
		{
			if (consumeAbilities == null)
			{
				return false;
			}
			foreach (AbilityConsume consumeAbility in consumeAbilities)
			{
				List<CActionAugmentationOp> augmentationOps = consumeAbility.ConsumeData.AugmentationOps;
				if (augmentationOps != null && augmentationOps.Any((CActionAugmentationOp a) => a.Ability.AbilityType == CAbility.EAbilityType.Attack))
				{
					return true;
				}
			}
			return false;
		}
	}

	[MessageHandler(CMessageData.MessageType.AbilityStartUpdateCombatLog)]
	private void Handle_AbilityStartUpdateCombatLog(CMessageData message)
	{
		m_ActorsKilledThisAbility.Clear();
		m_MessagesAfterKilledActors.Clear();
		CAbilityStartUpdateCombatLog_MessageData cAbilityStartUpdateCombatLog_MessageData = (CAbilityStartUpdateCombatLog_MessageData)message;
		SEventAction sEventAction = cAbilityStartUpdateCombatLog_MessageData.m_Event;
		if ((cAbilityStartUpdateCombatLog_MessageData.m_Ability != null && cAbilityStartUpdateCombatLog_MessageData.m_Ability.ExplicitlyDoesNothing) || sEventAction == null)
		{
			return;
		}
		CActor targetingActor = cAbilityStartUpdateCombatLog_MessageData.m_Ability.TargetingActor;
		if (!(targetingActor is CPlayerActor))
		{
			return;
		}
		if (cAbilityStartUpdateCombatLog_MessageData.m_Ability.ActiveSingleTargetActiveBonuses.Count > 0)
		{
			foreach (CActiveBonus activeSingleTargetActiveBonuse in cAbilityStartUpdateCombatLog_MessageData.m_Ability.ActiveSingleTargetActiveBonuses)
			{
				if (activeSingleTargetActiveBonuse.BaseCard.CardType == CBaseCard.ECardType.Item && activeSingleTargetActiveBonuse.SingleTarget != null)
				{
					CombatLogFilter filter = CombatLogFilter.ITEMS;
					string text = LocalizationNameConverter.MultiLookupLocalization(activeSingleTargetActiveBonuse.BaseCard.Name, out var _, suppressErrors: true);
					if (text != null)
					{
						string arg = LocalizationManager.GetTranslation(targetingActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(targetingActor);
						Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_USES"), arg, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{text}</color></b></font>"), filter);
					}
				}
			}
			return;
		}
		if (sEventAction.CardType == CBaseCard.ECardType.Item)
		{
			CombatLogFilter filter2 = CombatLogFilter.ITEMS;
			string text2 = LocalizationNameConverter.MultiLookupLocalization(sEventAction.CardName, out var _, suppressErrors: true);
			if (text2 != null)
			{
				string arg2 = LocalizationManager.GetTranslation(targetingActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(targetingActor);
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_USES"), arg2, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{text2}</color></b></font>"), filter2);
			}
		}
		else if (!sEventAction.CurrentPhaseAbilityName.IsNullOrEmpty() && !m_AbilitiesUsedThisTurn.Contains(sEventAction.CurrentPhaseAbilityName))
		{
			m_AbilitiesUsedThisTurn.Add(sEventAction.CurrentPhaseAbilityName);
			CombatLogFilter filter3 = CombatLogFilter.ABILITIES;
			string text3 = LocalizationNameConverter.MultiLookupLocalization(sEventAction.CurrentPhaseAbilityName, out var isItem3, suppressErrors: true);
			if (sEventAction.DefaultAbility != "")
			{
				text3 = text3 + " - " + LocalizationManager.GetTranslation(sEventAction.DefaultAbility);
			}
			if (isItem3)
			{
				filter3 = CombatLogFilter.ITEMS;
			}
			if (text3 != null)
			{
				string arg3 = LocalizationManager.GetTranslation(targetingActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(targetingActor);
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_USES"), arg3, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{text3}</color></b></font>"), filter3);
			}
		}
	}

