	[MessageHandler(CMessageData.MessageType.AbilityEndUpdateCombatLog)]
	private void Handle_AbilityEndUpdateCombatLog(CMessageData message)
	{
		CAbilityEndUpdateCombatLog_MessageData cAbilityEndUpdateCombatLog_MessageData = (CAbilityEndUpdateCombatLog_MessageData)message;
		switch (cAbilityEndUpdateCombatLog_MessageData.m_AbilityType)
		{
		case CAbility.EAbilityType.Move:
		{
			SEventAction sEventAction7 = SEventLog.FindLastActionEventOfSubType(onlyUnprocessed: false, ESESubTypeAction.ActionNextStep, toScrape: false);
			SEventAbilityMove moveAbilityEvent = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilityMove>(onlyUnprocessed: false, CAbility.EAbilityType.Move, ESESubTypeAbility.AbilityEnded);
			if (moveAbilityEvent == null || sEventAction7 == null || moveAbilityEvent == null)
			{
				break;
			}
			CActor cActor8 = ScenarioManager.Scenario.AllActors.SingleOrDefault((CActor x) => x.ActorGuid == moveAbilityEvent.MainActorGUID);
			string text7 = LocalizationManager.GetTranslation(cActor8.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cActor8);
			LogConsumes(cActor8, cAbilityEndUpdateCombatLog_MessageData.m_Ability);
			if (cAbilityEndUpdateCombatLog_MessageData.m_Ability == null || cAbilityEndUpdateCombatLog_MessageData.m_Ability.AbilityHasHappened)
			{
				if (moveAbilityEvent.ActualMoved > 0)
				{
					Singleton<CombatLogHandler>.Instance.AddLog(text7 + string.Format("<b>{0}</b>", " " + LocalizationManager.GetTranslation("COMBAT_LOG_MOVE") + " <sprite name=Move> " + moveAbilityEvent.ActualMoved) + " " + LocalizationManager.GetTranslation("COMBAT_LOG_HEXES"), CombatLogFilter.ABILITIES);
				}
				if (cActor8 != null && (moveAbilityEvent.MovedFromPoint.X != moveAbilityEvent.MovedToPoint.X || moveAbilityEvent.MovedFromPoint.Y != moveAbilityEvent.MovedToPoint.Y))
				{
					Log.SimpleInfo(text7 + " moved from: " + moveAbilityEvent.MovedFromPoint.X + "," + moveAbilityEvent.MovedFromPoint.Y + " to: " + moveAbilityEvent.MovedToPoint.X + "," + moveAbilityEvent.MovedToPoint.Y);
				}
