				Singleton<CombatLogHandler>.Instance.AddLog(string.Format((item4.DistanceMoved > 1) ? LocalizationManager.GetTranslation("COMBAT_LOG_PULL_MULTIPLE") : LocalizationManager.GetTranslation("COMBAT_LOG_PULL"), arg16, LocalizationManager.GetTranslation(item4.Name) + item4.ID, item4.DistanceMoved), CombatLogFilter.ABILITIES);
				Log.SimpleInfo(item4.Name + " moved from: " + item4.MovedFromPoint.X + "," + item4.MovedFromPoint.Y + " to: " + item4.MovedToPoint.X + "," + item4.MovedToPoint.Y);
			}
			break;
		}
		case CAbility.EAbilityType.Push:
		{
			SEventAction sEventAction13 = SEventLog.FindLastActionEventOfSubType(onlyUnprocessed: false, ESESubTypeAction.ActionNextStep, toScrape: false);
			SEventAbilityPush sEventAbilityPush = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilityPush>(onlyUnprocessed: false, CAbility.EAbilityType.Push, ESESubTypeAbility.AbilityEnded);
			if (sEventAbilityPush == null || sEventAction13 == null || sEventAbilityPush == null)
			{
				break;
			}
			CActor cActor13 = ScenarioManager.FindActor(sEventAction13.CurrentPhaseActorGuid);
			LogConsumes(cActor13, cAbilityEndUpdateCombatLog_MessageData.m_Ability);
			string arg12 = LocalizationManager.GetTranslation(cActor13.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cActor13);
			foreach (CAbilityPush.PushedActorStats item5 in sEventAbilityPush.ActorsDistanceMoved)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format((item5.DistanceMoved > 1) ? LocalizationManager.GetTranslation("COMBAT_LOG_PUSH_MULTIPLE") : LocalizationManager.GetTranslation("COMBAT_LOG_PUSH"), arg12, LocalizationManager.GetTranslation(item5.Name) + item5.ID, item5.DistanceMoved), CombatLogFilter.ABILITIES);
				Log.SimpleInfo(item5.Name + " moved from: " + item5.MovedFromPoint.X + "," + item5.MovedFromPoint.Y + " to: " + item5.MovedToPoint.X + "," + item5.MovedToPoint.Y);
			}
			break;
		}
		case CAbility.EAbilityType.Fear:
		{
			SEventAction sEventAction10 = SEventLog.FindLastActionEventOfSubType(onlyUnprocessed: false, ESESubTypeAction.ActionNextStep, toScrape: false);
			SEventAbilityFear sEventAbilityFear = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilityFear>(onlyUnprocessed: false, CAbility.EAbilityType.Fear, ESESubTypeAbility.AbilityEnded);
			if (sEventAbilityFear == null || sEventAction10 == null || sEventAbilityFear == null)
			{
				break;
			}
			CActor cActor11 = ScenarioManager.FindActor(sEventAction10.CurrentPhaseActorGuid);
			LogConsumes(cActor11, cAbilityEndUpdateCombatLog_MessageData.m_Ability);
			string arg10 = LocalizationManager.GetTranslation(cActor11.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cActor11);
			foreach (CAbilityFear.FearedActorStats item6 in sEventAbilityFear.ActorsDistanceMoved)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format((item6.DistanceMoved > 1) ? LocalizationManager.GetTranslation("COMBAT_LOG_FEAR_MULTIPLE") : LocalizationManager.GetTranslation("COMBAT_LOG_FEAR"), arg10, item6.Name, item6.DistanceMoved), CombatLogFilter.ABILITIES);
				Log.SimpleInfo(item6.Name + " feared from: " + item6.MovedFromPoint.X + "," + item6.MovedFromPoint.Y + " to: " + item6.MovedToPoint.X + "," + item6.MovedToPoint.Y);
			}
			break;
		}
		case CAbility.EAbilityType.Teleport:
		{
			SEventAction sEventAction16 = SEventLog.FindLastActionEventOfSubType(onlyUnprocessed: false, ESESubTypeAction.ActionNextStep, toScrape: false);
			SEventAbilityTeleport sEventAbilityTeleport2 = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilityTeleport>(onlyUnprocessed: false, CAbility.EAbilityType.Teleport, ESESubTypeAbility.AbilityEnded);
			if (sEventAbilityTeleport2 != null && sEventAction16 != null && sEventAbilityTeleport2 != null)
			{
				CActor cActor17 = ScenarioManager.FindActor(sEventAction16.CurrentPhaseActorGuid);
				LogConsumes(cActor17, cAbilityEndUpdateCombatLog_MessageData.m_Ability);
				string text12 = LocalizationManager.GetTranslation(cActor17.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cActor17);
				Log.SimpleInfo(text12 + " moved from: " + ((sEventAbilityTeleport2.MovedFromPoint == null) ? "null" : (sEventAbilityTeleport2.MovedFromPoint.X + "," + sEventAbilityTeleport2.MovedFromPoint.Y)) + " to: " + ((sEventAbilityTeleport2.MovedToPoint == null) ? "null" : (sEventAbilityTeleport2.MovedToPoint.X + "," + sEventAbilityTeleport2.MovedToPoint.Y)));
			}
			break;
		}
		case CAbility.EAbilityType.AddTarget:
		{
			SEventAbilityTargeting sEventAbilityTargeting = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilityTargeting>(onlyUnprocessed: false, CAbility.EAbilityType.AddTarget, ESESubTypeAbility.AbilityEnded);
			if (sEventAbilityTargeting != null && sEventAbilityTargeting != null)
			{
				CActor cActor15 = ScenarioManager.FindActor(sEventAbilityTargeting.CurrentPhaseActorGuid);
				LogConsumes(cActor15, cAbilityEndUpdateCombatLog_MessageData.m_Ability);
				string text11 = LocalizationManager.GetTranslation(cActor15.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cActor15);
				Singleton<CombatLogHandler>.Instance.AddLog(text11 + string.Format("<b>{0}</b>", string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ADD_TARGET"), sEventAbilityTargeting.Strength)), CombatLogFilter.ABILITIES);
			}
			break;
		}
		case CAbility.EAbilityType.Swap:
		{
			SEventAction sEventAction11 = SEventLog.FindLastActionEventOfSubType(onlyUnprocessed: false, ESESubTypeAction.ActionNextStep, toScrape: false);
			SEventAbilitySwap sEventAbilitySwap = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilitySwap>(onlyUnprocessed: false, CAbility.EAbilityType.Swap, ESESubTypeAbility.AbilityEnded);
			if (sEventAbilitySwap != null && sEventAction11 != null && sEventAbilitySwap != null)
			{
				Log.SimpleInfo(sEventAbilitySwap.FirstTargetName + " moved from: " + sEventAbilitySwap.FirstTargetStartLocation.X + "," + sEventAbilitySwap.FirstTargetStartLocation.Y + " to: " + sEventAbilitySwap.SecondTargetStartLocation.X + "," + sEventAbilitySwap.SecondTargetStartLocation.Y);
				Log.SimpleInfo(sEventAbilitySwap.SecondTargetName + " moved from: " + sEventAbilitySwap.SecondTargetStartLocation.X + "," + sEventAbilitySwap.SecondTargetStartLocation.Y + " to: " + sEventAbilitySwap.FirstTargetStartLocation.X + "," + sEventAbilitySwap.FirstTargetStartLocation.Y);
				LogConsumes(cAbilityEndUpdateCombatLog_MessageData.m_ActorSpawningMessage, cAbilityEndUpdateCombatLog_MessageData.m_Ability);
			}
			break;
		}
		case CAbility.EAbilityType.AddModifierToMonsterDeck:
		{
			SEventAbilityAddModifierToMonsterDeck sEventAbilityAddModifierToMonsterDeck = SEventLog.FindLastAbilityEventOfAbilityType<SEventAbilityAddModifierToMonsterDeck>(onlyUnprocessed: false, CAbility.EAbilityType.AddModifierToMonsterDeck, ESESubTypeAbility.AbilityEnded);
			if (sEventAbilityAddModifierToMonsterDeck == null || sEventAbilityAddModifierToMonsterDeck == null)
			{
				break;
			}
			CActor cActor = ScenarioManager.FindActor(sEventAbilityAddModifierToMonsterDeck.CurrentPhaseActorGuid);
			LogConsumes(cActor, cAbilityEndUpdateCombatLog_MessageData.m_Ability);
			string arg = LocalizationManager.GetTranslation(cActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cActor);
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < sEventAbilityAddModifierToMonsterDeck.AddModifierStrings.Count; i++)
			{
				stringBuilder.Append(sEventAbilityAddModifierToMonsterDeck.AddModifierStrings[i]);
				if (i != sEventAbilityAddModifierToMonsterDeck.AddModifierStrings.Count - 1)
				{
					stringBuilder.Append(", ");
				}
			}
			if (sEventAbilityAddModifierToMonsterDeck.AddModifierStrings.Count > 1)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format("<b>{0}</b>", string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ADD_MULTIPLE_MODIFIERS_TO_MONSTER_DECKS"), arg, stringBuilder)), CombatLogFilter.ABILITIES);
			}
			else
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format("<b>{0}</b>", string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ADD_MODIFIERS_TO_MONSTER_DECKS"), arg, stringBuilder)), CombatLogFilter.ABILITIES);
			}
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = cAbilityEndUpdateCombatLog_MessageData.m_ActorSpawningMessage;
			ProcessActorAnimation(cAbilityEndUpdateCombatLog_MessageData.m_Ability, cAbilityEndUpdateCombatLog_MessageData.m_ActorSpawningMessage, new List<string> { cAbilityEndUpdateCombatLog_MessageData.AnimOverload }, out animationShouldPlay, out animatingActorToWaitFor);
			if (animatingActorToWaitFor != null)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
			}
			break;
		}
		default:
			LogConsumes(cAbilityEndUpdateCombatLog_MessageData.m_ActorSpawningMessage, cAbilityEndUpdateCombatLog_MessageData.m_Ability);
			break;
		}
		if (cAbilityEndUpdateCombatLog_MessageData.m_Ability.ActiveEnhancements.Count > 0)
		{
			string text13 = " ";
			foreach (CEnhancement activeEnhancement in cAbilityEndUpdateCombatLog_MessageData.m_Ability.ActiveEnhancements)
			{
				text13 = text13 + string.Format("<b>{0}</b>", LocalizationManager.GetTranslation("ENHANCEMENT_" + activeEnhancement.Enhancement)) + ", ";
			}
			text13 = text13.Substring(0, text13.Length - 2);
			Singleton<CombatLogHandler>.Instance.AddLog(LocalizationManager.GetTranslation("COMBAT_LOG_ENHANCEMENTS") + text13, CombatLogFilter.ABILITIES);
		}
		foreach (Tuple<string, CActor.ECauseOfDeath> actorDeadTuple in m_ActorsKilledThisAbility)
		{
			if (actorDeadTuple.Item2 == CActor.ECauseOfDeath.ActorRemovedFromMap)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ACTOR_ESCAPE"), LocalizationManager.GetTranslation(actorDeadTuple.Item1)), CombatLogFilter.DEATHS);
				continue;
			}
			bool flag = ScenarioManager.Scenario.AllPlayers.Any((CPlayerActor x) => x.ActorLocKey() == actorDeadTuple.Item1);
			bool flag2 = ScenarioManager.Scenario.AllObjects.Any((CObjectActor x) => x.ActorLocKey() == actorDeadTuple.Item1);
			string term;
			if (flag)
			{
				term = "COMBAT_LOG_ACTOR_EXHAUSTED";
			}
			else
			{
				term = ((!flag2) ? "COMBAT_LOG_ACTOR_DIE" : "COMBAT_LOG_OBJECTACTOR_DIE");
			}
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(term), LocalizationManager.GetTranslation(actorDeadTuple.Item1)), CombatLogFilter.DEATHS);
		}
		m_ActorsKilledThisAbility.Clear();
		LogDelayedMessages();
		LogInfusedElements();
		if (PhaseManager.CurrentPhaseAction?.CurrentPhaseAbility?.m_Ability == null)
		{
			WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
			WorldspaceStarHexDisplay.Instance.SetDisplayAbility(null);
		}
		if (cAbilityEndUpdateCombatLog_MessageData.m_Ability != null && cAbilityEndUpdateCombatLog_MessageData.m_Ability == m_CurrentAbility)
		{
			m_CurrentAbility = null;
		}
	}

	private void LogDelayedMessages()
	{
		foreach (CMessageData messagesAfterKilledActor in m_MessagesAfterKilledActors)
		{
			PostMessageFromUI(messagesAfterKilledActor);
		}
		m_MessagesAfterKilledActors.Clear();
	}

	[MessageHandler(CMessageData.MessageType.ActorDowned)]
	private void Handle_ActorDowned(CMessageData message)
	{
		CActorDowned_MessageData cActorDowned_MessageData = (CActorDowned_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(cActorDowned_MessageData.m_Actor);
		if (gameObject != null)
		{
			CameraController.s_CameraController.RemoveFocusFromObject(gameObject);
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
			if (actorBehaviour.m_WorldspacePanelUI != null)
			{
				actorBehaviour.m_WorldspacePanelUI.CancelRetaliateEffect();
			}
			ActorBehaviour.UpdateHealth(gameObject);
		}
		string item = "Downed";
		if (!LoadingComplete || ScenarioManager.IsFastReloading)
		{
			item = "DownedIdle";
		}
		ProcessActorAnimation(null, cActorDowned_MessageData.m_Actor, new List<string> { item }, out var _, out var _);
	}

	[MessageHandler(CMessageData.MessageType.DownedActorRevived)]
	private void Handle_DownedActorRevived(CMessageData message)
	{
		CDownedActorRevived_MessageData cDownedActorRevived_MessageData = (CDownedActorRevived_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(cDownedActorRevived_MessageData.m_Actor);
		if (!(gameObject == null))
		{
			ProcessActorAnimation(null, cDownedActorRevived_MessageData.m_Actor, new List<string> { "Revive" }, out var _, out var _);
			ActorBehaviour.UpdateHealth(gameObject);
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorDead)]
	private void Handle_ActorDead(CMessageData message)
	{
		CActorDead_MessageData cActorDead_MessageData = (CActorDead_MessageData)message;
		if (!cActorDead_MessageData.m_DontLog)
		{
			if (cActorDead_MessageData.m_Actor.CauseOfDeath == CActor.ECauseOfDeath.NoMoreCards)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ACTOR_EXHAUSTED_LACKOFCARDS"), LocalizationManager.GetTranslation(cActorDead_MessageData.m_Actor.ActorLocKey())), CombatLogFilter.DEATHS);
			}
			else
			{
				m_ActorsKilledThisAbility.Add(new Tuple<string, CActor.ECauseOfDeath>(cActorDead_MessageData.m_Actor.ActorLocKey(), cActorDead_MessageData.m_Actor.CauseOfDeath));
			}
		}
		bool flag = cActorDead_MessageData.m_Actor.CauseOfDeath == CActor.ECauseOfDeath.ActorRemovedFromMap;
		GameObject gameObject = FindClientActorGameObject(cActorDead_MessageData.m_Actor);
		if (gameObject != null)
		{
			CameraController.s_CameraController.RemoveFocusFromObject(gameObject);
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
			if (actorBehaviour.m_WorldspacePanelUI != null)
			{
				actorBehaviour.m_WorldspacePanelUI.CancelRetaliateEffect();
			}
			actorBehaviour.FadeInPreviousCharacterOnPosition();
			m_ActorObjectsToDropLootDelayed.Add(gameObject);
			DeathDissolve componentInChildren = gameObject.GetComponentInChildren<DeathDissolve>();
			if (cActorDead_MessageData.m_Actor.CauseOfDeath != CActor.ECauseOfDeath.SummonActiveBonusCancelled && cActorDead_MessageData.m_Actor.CauseOfDeath != CActor.ECauseOfDeath.SummonerDied && (!cActorDead_MessageData.m_OnDeathAbility || !componentInChildren.PlayedExternally()))
			{
				m_InterruptMessagesProcessing = true;
				bool animationShouldPlay = false;
				CActor animatingActorToWaitFor = cActorDead_MessageData.m_Actor;
				List<string> list = new List<string>();
				if (flag)
				{
					list.Add("Cheer");
				}
				List<string> list2 = list;
				string item;
				if (flag)
				{
					item = "PowerUp";
				}
				else
				{
					item = (cActorDead_MessageData.m_ActorWasAsleep ? "SleepDeath" : "Death");
				}
				list2.Add(item);
				list.Add("Death");
				ProcessActorAnimation(null, cActorDead_MessageData.m_Actor, list, out animationShouldPlay, out animatingActorToWaitFor);
			}
			gameObject.transform.SetParent(null);
			if (cActorDead_MessageData.m_Actor is CPlayerActor)
			{
				m_ClientDeadActors.Add(gameObject);
			}
			else
			{
				AllActorsInScene.Remove(gameObject);
			}
			m_ClientPlayers.Remove(gameObject);
			m_ClientEnemies.Remove(gameObject);
			m_ClientHeroSummons.Remove(gameObject);
			m_ClientAllyMonsters.Remove(gameObject);
			m_ClientEnemy2Monsters.Remove(gameObject);
			m_ClientNeutralMonsters.Remove(gameObject);
			m_ClientObjects.Remove(gameObject);
			ActorBehaviour.UpdateHealth(gameObject, 0, updateUI: false, isActorDead: true);
			if (cActorDead_MessageData.m_InstantlyDeletePrefab || MF.GetGameObjectAnimatorController(gameObject) == null || cActorDead_MessageData.m_Actor is CObjectActor { IsAttachedToProp: not false })
			{
				ActorBehaviour.GetActorBehaviour(gameObject)?.m_WorldspacePanelUI?.Destroy();
				CharacterManager characterManager = CharacterManager.GetCharacterManager(gameObject);
				CharacterOutlineRegistration(characterManager, register: false);
				characterManager.DeinitializeCharacter();
				if (characterManager.CharacterActor is CPlayerActor cPlayerActor)
				{
					characterManager.gameObject.transform.position = DeadPlayerLocation;
					if (Singleton<UIReadyTrackerBar>.Instance != null)
					{
						Singleton<UIReadyTrackerBar>.Instance.RemoveTracker(cPlayerActor.CharacterClass.ID);
					}
				}
				else
				{
					ObjectPool.Recycle(gameObject, characterManager.CharacterPrefab);
				}
			}
			CTile propTile = ScenarioManager.Tiles[cActorDead_MessageData.m_Actor.ArrayIndex.X, cActorDead_MessageData.m_Actor.ArrayIndex.Y];
			if (propTile != null)
			{
				CObjectObstacle cObjectObstacle = propTile.FindProp(ScenarioManager.ObjectImportType.Obstacle) as CObjectObstacle;
				if (cObjectObstacle == null)
				{
					cObjectObstacle = CObjectProp.FindPropWithPathingBlocker(propTile.m_ArrayIndex, ref propTile);
				}
				if (cObjectObstacle != null && ScenarioManager.CurrentScenarioState.TransparentProps.Contains(cObjectObstacle))
				{
					ScenarioManager.CurrentScenarioState.TransparentProps.Remove(cObjectObstacle);
					GameObject gameObject2 = FindPropGameObject(cObjectObstacle);
					if (gameObject2 != null)
					{
						Log.Info("Prop found for transparency");
						CustomObjectPositionToChildMaterials componentInChildren2 = gameObject2.GetComponentInChildren<CustomObjectPositionToChildMaterials>();
						if (componentInChildren2 != null)
						{
							Log.Info("Script found for transparency");
							componentInChildren2.fadeSourceObject = null;
							componentInChildren2.enableFade = false;
							Log.Info("Transparency disabled");
						}
						else
						{
							Log.Warning("Could not find CustomObjectPositionToChildMaterial.cs script on Prop\n" + cObjectObstacle.PrefabName);
						}
					}
				}
			}
		}
		if (FFSNetwork.IsOnline && PhaseManager.PhaseType == CPhase.PhaseType.SelectAbilityCardsOrLongRest && PlayerRegistry.MyPlayer != null && cActorDead_MessageData.m_Actor.Type == CActor.EType.Player && cActorDead_MessageData.m_Actor.IsUnderMyControl() && !PlayerRegistry.MyPlayer.MyControllables.Any((NetworkControllable x) => x.IsAlive))
		{
			Singleton<UIReadyToggle>.Instance.SetInteractable(interactable: false);
			Singleton<UIReadyToggle>.Instance.ReadyUp(toggledOn: true);
		}
		Action action = null;
		if (cActorDead_MessageData.m_Actor.OriginalType == CActor.EType.Player)
		{
			if (ScenarioManager.Scenario.PlayerActors.Count == 0)
			{
				DisableNextPhaseButtons();
			}
			UnityAction checkActorsDeadAction = () =>
			{
				if (ScenarioManager.Scenario.AllPlayers.All((CPlayerActor p) => p.IsDead && !p.PhasedOut) && ScenarioManager.Scenario.AllPlayers.Any((CPlayerActor p) => p.IsDeadForObjectives))
				{
					if (ScenarioManager.CurrentScenarioState.WinObjectives.All((CObjective o) => o.WinsDespiteExhaustion))
					{
						if (ScenarioManager.CurrentScenarioState.CheckObjectivesComplete() == EObjectiveResult.Win)
						{
							Log.SimpleInfo("Win triggered at ActorDead message as all player actors are dead, where all win objectives have WinsDespiteExhaustion == true");
							WinScenario();
						}
						else
						{
							Log.SimpleInfo("Lose triggered at ActorDead message as all player actors are dead.");
							LoseScenario();
						}
					}
					else
					{
						Log.SimpleInfo("Lose triggered at ActorDead message as all player actors are dead.");
						LoseScenario();
					}
				}
			};
			if (cActorDead_MessageData.m_Actor.Health <= 0 && PhaseManager.PhaseType != CPhase.PhaseType.EndTurn)
			{
				action = Singleton<PhaseBannerHandler>.Instance.ShowDie;
				SetBlockClientMessageProcessing(active: true);
				Singleton<PhaseBannerHandler>.Instance.ShowPreDie(cActorDead_MessageData.m_Actor.ActorLocKey(), () =>
				{
					checkActorsDeadAction?.Invoke();
					SetBlockClientMessageProcessing(active: false);
				});
			}
			else
			{
				checkActorsDeadAction?.Invoke();
			}
			if (flag && ScenarioManager.CurrentScenarioState.CheckObjectivesComplete() == EObjectiveResult.Win)
			{
				WinScenario(forceUI: false);
			}
		}
		else if (cActorDead_MessageData.m_Actor is CHeroSummonActor cHeroSummonActor)
		{
			Singleton<CardsHandManager>.Instance.RefreshPendingActiveBonus(cHeroSummonActor.Summoner);
		}
		if (gameObject != null)
		{
			DeathDissolve componentInChildren3 = gameObject.GetComponentInChildren<DeathDissolve>();
			if (cActorDead_MessageData.m_OnDeathAbility && componentInChildren3 != null && componentInChildren3.PlayedExternally())
			{
				action?.Invoke();
				ActorBehaviour.GetActorBehaviour(gameObject).m_WorldspacePanelUI?.Destroy();
				if (componentInChildren3 != null)
				{
					componentInChildren3.ExternalCleanup();
				}
			}
			else
			{
				if (componentInChildren3 != null)
				{
					StartCoroutine(componentInChildren3.Play());
				}
				Action onDestroy = action;
				ActorBehaviour.GetActorBehaviour(gameObject)?.m_WorldspacePanelUI?.Destroy(onDestroy);
			}
		}
		else
		{
			action?.Invoke();
		}
		UIEventManager.AddUIEvent(new UIEvent(UIEvent.EUIEventType.AllActorsDeadFiltered));
	}

	[MessageHandler(CMessageData.MessageType.UpdateObjectiveProgress)]
	private void Handle_UpdateObjectiveProgress(CMessageData message)
	{
		if (SaveData.Instance.Global.GameMode == EGameMode.LevelEditor)
		{
			return;
		}
		_ = (CUpdateObjectiveProgress_MessageData)message;
		Singleton<ScenarioInfoModule>.Instance.MissionObjectiveContainer.UpdateProgress();
		Singleton<ScenarioInfoModule>.Instance.UpdateProgress();
		if (PhaseManager.PhaseType != CPhase.PhaseType.SelectAbilityCardsOrLongRest)
		{
			return;
		}
		if (!PlayersInValidStartingPositions)
		{
			InitiativeTrack.Instance.helpBox.Show("GUI_TOOLTIP_PLAYER_STARTING_PLACEMENT", "GUI_TOOLTIP_TITLE_START_TURN");
			Singleton<HelpBox>.Instance.HighlightWarning();
		}
		else if (AnyPlayersInInvalidStartingPositionsForCompanionSummons)
		{
			List<CPlayerActor> list = PlayersInInvalidStartingPositionsForCompanionSummons();
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < list.Count; i++)
			{
				string value = LocalizationManager.GetTranslation(list[i].ActorLocKey()) + ((list.Count > 1 && i >= list.Count - 1) ? ", " : " ");
				stringBuilder.Append(value);
			}
			string text = string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_STARTING_PLACEMENT_COMPANION_SUMMONS"), stringBuilder);
			string translation = LocalizationManager.GetTranslation("GUI_TOOLTIP_TITLE_START_TURN");
			InitiativeTrack.Instance.helpBox.ShowTranslated(text, translation);
			Singleton<HelpBox>.Instance.HighlightWarning();
		}
		else
		{
			InitiativeTrack.Instance.helpBox.Show(StartTurnHelpBoxKey(), "GUI_TOOLTIP_TITLE_START_TURN");
		}
