	[MessageHandler(CMessageData.MessageType.CombatLogMessage)]
	private void Handle_CombatLogMessage(CMessageData message)
	{
		CCombatLogMessage_MessageData cCombatLogMessage_MessageData = (CCombatLogMessage_MessageData)message;
		if (cCombatLogMessage_MessageData.m_Params != null)
		{
			for (int i = 0; i < cCombatLogMessage_MessageData.m_Params.Count; i++)
			{
				string translation;
				if (cCombatLogMessage_MessageData.m_Params[i].StartsWith("Actor_") && int.TryParse(cCombatLogMessage_MessageData.m_Params[i].Replace("Actor_", ""), out var result))
				{
					CActor cActor = cCombatLogMessage_MessageData.m_Actors[result];
					cCombatLogMessage_MessageData.m_Params[i] = LocalizationManager.GetTranslation(cActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cActor);
				}
				else if (LocalizationManager.TryGetTranslation(cCombatLogMessage_MessageData.m_Params[i], out translation))
				{
					cCombatLogMessage_MessageData.m_Params[i] = translation;
				}
			}
		}
		CombatLogHandler instance = Singleton<CombatLogHandler>.Instance;
		string translation2 = LocalizationManager.GetTranslation(cCombatLogMessage_MessageData.m_MessageKey);
		object[] args;
		if (cCombatLogMessage_MessageData.m_Params == null)
		{
			args = new object[0];
		}
		else
		{
			object[] array = cCombatLogMessage_MessageData.m_Params.ToArray();
			args = array;
		}
		instance.AddLog(string.Format(translation2, args));
	}

	[MessageHandler(CMessageData.MessageType.LogMovedTrap)]
	private void Handle_LogMovedTrapMessage(CMessageData message)
	{
		CLogMovedTrapMessage_MessageData cLogMovedTrapMessage_MessageData = (CLogMovedTrapMessage_MessageData)message;
		CActor actorSpawningMessage = cLogMovedTrapMessage_MessageData.m_ActorSpawningMessage;
		string arg = LocalizationManager.GetTranslation(actorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorSpawningMessage);
		SEventAbilityTrap sEventAbilityTrap = cLogMovedTrapMessage_MessageData.m_Event;
		string text = LocalizationManager.GetTranslation(sEventAbilityTrap.TrapName) + ".";
		if (sEventAbilityTrap.Strength > 0)
		{
			text = text + " " + LocalizationManager.GetTranslation("Damage") + string.Format("<b><color=#f76767>{0}</color></b>", " <sprite name=Attack> " + sEventAbilityTrap.Strength);
		}
		if (sEventAbilityTrap.TrapHeal > 0)
		{
			text = text + " " + LocalizationManager.GetTranslation("Heal") + " <sprite name=Heal> " + sEventAbilityTrap.TrapHeal;
		}
		if (sEventAbilityTrap.AddedNegativeConditionData != null && sEventAbilityTrap.AddedNegativeConditionData.Count > 0)
		{
			foreach (SEventAbility.SEventAbilityAddedConditionData addedNegativeConditionDatum in sEventAbilityTrap.AddedNegativeConditionData)
			{
				text = text + " + " + string.Format("<b>{0}</b>", "<sprite name=" + addedNegativeConditionDatum.AddedConditionType.ToString() + ">");
			}
		}
		if (sEventAbilityTrap.AddedPositiveConditionData != null && sEventAbilityTrap.AddedPositiveConditionData.Count > 0)
		{
			foreach (SEventAbility.SEventAbilityAddedConditionData addedPositiveConditionDatum in sEventAbilityTrap.AddedPositiveConditionData)
			{
				text = text + " + " + string.Format("<b>{0}</b>", "<sprite name=" + addedPositiveConditionDatum.AddedConditionType.ToString() + ">");
			}
		}
		Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_MOVE_PROP"), arg, text), CombatLogFilter.ABILITIES);
	}

	[MessageHandler(CMessageData.MessageType.EndTurn)]
	private void Handle_EndTurn(CMessageData message)
	{
		if (!(PhaseManager.CurrentPhase is CPhaseEndTurn))
		{
			return;
		}
		SaveData.Instance.Global.DisallowSpeedUp();
		ElementInfusionBoardManager.ProcessEndTurnInfusions();
		InfusionBoardUI.Instance?.UnreserveElements();
		CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
		if (InitiativeTrack.Instance?.SelectedActor()?.Actor?.Class != null && InitiativeTrack.Instance.SelectedActor().Actor.Class is CCharacterClass)
		{
			Singleton<CardsHandManager>.Instance.Reset((CPlayerActor)InitiativeTrack.Instance.SelectedActor().Actor);
		}
		Singleton<UIScenarioMultiplayerController>.Instance.OnEndTurn();
		HideSelectionUI();
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = false;
		GameObject gameObject = FindClientActorGameObject(message.m_ActorSpawningMessage);
		if (gameObject != null)
		{
			ActorBehaviour.GetActorBehaviour(gameObject).PauseLoco(pause: false);
		}
		if (m_CurrentActor != null)
		{
			UIEventManager.AddActorEndedTurnEvent(m_CurrentActor);
			m_CurrentActor = null;
			if (FFSNetwork.IsOnline)
			{
				InitiativeTrack.Instance.PlayersUI.ForEach((InitiativeTrackPlayerBehaviourExtension f) =>
				{
					f.Base.Avatar.RefreshActiveInteractable();
				});
			}
			Singleton<ScenarioInfoModule>.Instance.HideBattleGoals();
		}
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		SetChoreographerState(ChoreographerStateType.WaitingForEndTurnSync, 0, null);
	}

	[MessageHandler(CMessageData.MessageType.EndRound)]
	private void Handle_EndRound(CMessageData message)
	{
		CEndRound_MessageData messageData = message as CEndRound_MessageData;
		if (messageData.m_SyncMultiplayer && FFSNetwork.IsOnline)
		{
			ProcessMessage(new CWaitForMultiplayerSyncPoint_MessageData
			{
				m_OnFinish = () =>
				{
					messageData.m_SyncMultiplayer = false;
					ProcessMessage(messageData);
				}
			});
			return;
		}
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(ActionProcessorStateType.Halted);
		}
		Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = !FFSNetwork.IsOnline;
		Singleton<CardsHandManager>.Instance.Hide();
		ClearStars();
		m_ActorObjectsToDropLootDelayed.Clear();
		ClearHilightedActors();
		m_SkipButton.Toggle(active: false);
		CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
		switch (ScenarioManager.CurrentScenarioState.CheckObjectivesComplete(isEndOfRound: true))
		{
		case EObjectiveResult.Win:
			Log.SimpleInfo("Win triggered at EndRound message after checking objective state.");
			s_Choreographer.WinScenario();
			break;
		case EObjectiveResult.Lose:
			Log.SimpleInfo("Lose triggered at EndRound message after checking objective state.");
			s_Choreographer.LoseScenario();
			break;
		default:
			if (s_Choreographer.LastMessage.m_Type != CMessageData.MessageType.EndAbilityAnimSync)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForEndRoundSync, 0, null);
			}
			break;
		}
		if (GameState.s_AutoRestorePlayerCards)
		{
			DebugMenu.Cmd_RestorePlayerCards(null);
		}
	}

