	{
		Singleton<ScenarioRewardManager>.Instance.StackRewardsToShow(actor, rewards, sourceType);
	}

	[MessageHandler(CMessageData.MessageType.ActivateProp)]
	private void Handle_ActivateProp(CMessageData message)
	{
		CActivateProp_MessageData cActivateProp_MessageData = (CActivateProp_MessageData)message;
		Log.Info("Attempting to activate prop instance name: " + cActivateProp_MessageData.m_Prop.InstanceName);
		if (cActivateProp_MessageData.m_ActorSpawningMessage != null)
		{
			CActor actorSpawningMessage = cActivateProp_MessageData.m_ActorSpawningMessage;
			string text = LocalizationManager.GetTranslation(actorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorSpawningMessage);
			Log.SimpleInfo(text + " activated prop: " + cActivateProp_MessageData.m_Prop.InstanceName + " of type: " + cActivateProp_MessageData.m_Prop.ObjectType.ToString() + " at ArrayIndex: " + cActivateProp_MessageData.m_Prop.ArrayIndex.ToString());
		}
		ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cActivateProp_MessageData.m_Prop.ArrayIndex.X, cActivateProp_MessageData.m_Prop.ArrayIndex.Y].m_TileBehaviour.RefreshWorldSpaceIcon();
		CActor cActor = ((cActivateProp_MessageData.m_CreditActor == null) ? cActivateProp_MessageData.m_ActorSpawningMessage : cActivateProp_MessageData.m_CreditActor);
		string text4;
		switch (cActivateProp_MessageData.m_Prop.ObjectType)
		{
		case ScenarioManager.ObjectImportType.Door:
			CheckOpenDoor(cActivateProp_MessageData.m_Prop, cActivateProp_MessageData.m_ActorSpawningMessage, cActivateProp_MessageData.m_InitialLoad, openDoorOnly: false);
			break;
		case ScenarioManager.ObjectImportType.Chest:
		case ScenarioManager.ObjectImportType.GoalChest:
		{
			m_RewardsToShowcase.Clear();
			m_RewardsToShowcase_SourceType = cActivateProp_MessageData.m_Prop.ObjectType;
			CTile cTile = ScenarioManager.Tiles[cActivateProp_MessageData.m_Prop.ArrayIndex.X, cActivateProp_MessageData.m_Prop.ArrayIndex.Y];
			CObjectChest cObjectChest = cActivateProp_MessageData.m_Prop as CObjectChest;
			if (SaveData.Instance.Global.GameMode == EGameMode.Campaign)
			{
				if (cObjectChest.HasChestPrepopulated)
				{
					m_RewardsToShowcase = cObjectChest.GetRewardsFromStartingItems();
					if (cObjectChest.DamageValue > 0)
					{
						m_RewardsToShowcase.Add(new Reward(ETreasureType.Damage, cObjectChest.DamageValue, ETreasureDistributionType.None, cActor.Class.ID));
					}
					List<Reward> rewards = m_RewardsToShowcase.ToList();
					for (int num = m_RewardsToShowcase.Count - 1; num >= 0; num--)
					{
						Reward reward = m_RewardsToShowcase[num];
						if (reward.Item != null && reward.Item.YMLData.Slot == CItem.EItemSlot.QuestItem)
						{
							CItem newItem = reward.Item.Copy($"QuestItem {num} - {reward.ItemID}", 0u);
							cActor.TryLootItem(newItem);
						}
					}
					if (cObjectChest.ObjectType == ScenarioManager.ObjectImportType.GoalChest)
					{
						ScenarioManager.CurrentScenarioState.GoalChestRewards.Add(new Tuple<string, RewardGroup>("party", new RewardGroup(rewards)));
					}
					if (cActivateProp_MessageData.m_Rewards != null)
					{
						m_RewardsToShowcase.AddRange(cActivateProp_MessageData.m_Rewards);
					}
					if (cObjectChest.IsFHLoot && cObjectChest.ObjectType == ScenarioManager.ObjectImportType.Chest && (cObjectChest.ChestTreasureTablesID == null || cObjectChest.ChestTreasureTablesID.Count == 0) && cObjectChest.Type != CObjectChest.EType.None)
					{
						ScenarioManager.CurrentScenarioState.LootedChests.Add(cObjectChest.Type.ToString());
					}
				}
				CMap hexMap = ScenarioManager.Tiles[cActivateProp_MessageData.m_Prop.ArrayIndex.X, cActivateProp_MessageData.m_Prop.ArrayIndex.Y].m_HexMap;
				m_RewardsToShowcase.AddRange(SaveData.Instance.Global.CurrentAdventureData.AdventureMapState.RollTreasureChest(cObjectChest, hexMap.MapGuid, cActivateProp_MessageData.m_ActorSpawningMessage.Class.ID));
			}
			else if (cObjectChest.HasChestPrepopulated)
			{
				m_RewardsToShowcase = cObjectChest.GetRewardsFromStartingItems();
				if (cObjectChest.DamageValue > 0)
				{
					m_RewardsToShowcase.Add(new Reward(ETreasureType.Damage, cObjectChest.DamageValue, ETreasureDistributionType.None, cActor.Class.ID));
				}
				for (int num2 = m_RewardsToShowcase.Count - 1; num2 >= 0; num2--)
				{
					Reward reward2 = m_RewardsToShowcase[num2];
					if (reward2.Item != null && reward2.Item.YMLData.Slot == CItem.EItemSlot.QuestItem)
					{
						CItem newItem2 = reward2.Item.Copy($"QuestItem {num2} - {reward2.ItemID}", 0u);
						cActor.TryLootItem(newItem2);
					}
				}
				if (cObjectChest.ObjectType == ScenarioManager.ObjectImportType.GoalChest)
				{
					ScenarioManager.CurrentScenarioState.GoalChestRewards.Add(new Tuple<string, RewardGroup>("party", new RewardGroup(m_RewardsToShowcase)));
				}
				if (cActivateProp_MessageData.m_Rewards != null)
				{
					m_RewardsToShowcase.AddRange(cActivateProp_MessageData.m_Rewards);
				}
			}
			if (!cObjectChest.Conditions.IsNullOrEmpty())
			{
				foreach (CCondition.ENegativeCondition condition in cObjectChest.Conditions)
				{
					m_RewardsToShowcase.Add(new Reward(new List<RewardCondition>
					{
						new RewardCondition(RewardCondition.EConditionMapDuration.None, condition, -1)
					}, forEnemy: false));
				}
			}
			if (cActor != null)
			{
				foreach (Reward item in m_RewardsToShowcase)
				{
					item.GiveToCharacterType = EGiveToCharacterType.Equip;
					item.GiveToCharacterID = cActor.Class.ID;
				}
			}
			GameObject gameObject2 = FindPropGameObject(cActivateProp_MessageData.m_Prop);
			ScenarioManager.CurrentScenarioState.DestroyedProps.Add(cActivateProp_MessageData.m_Prop);
			if (gameObject2 != null)
			{
				CharacterManager characterManager = CharacterManager.GetCharacterManager(FindClientActorGameObject(cActivateProp_MessageData.m_ActorSpawningMessage));
				if (characterManager != null)
				{
					characterManager.ChestsToCollect.Add(gameObject2);
				}
				PlayableDirector componentInChildren2 = gameObject2.GetComponentInChildren<PlayableDirector>();
				if (componentInChildren2 != null)
				{
					componentInChildren2.Play();
					StartCoroutine(DestroyPropDelayedCoro((float)componentInChildren2.duration, cActivateProp_MessageData.m_Prop));
				}
				if (SEventLog.FindLastObjectEventOfSubTypeAndObjectType(onlyUnprocessed: false, ESESubTypeObjectProp.Activated, ScenarioManager.ObjectImportType.Chest, toScrape: false, checkQueue: true) is SEventObjectPropChest sEventObjectPropChest)
				{
					CActor actorSpawningMessage2 = cActivateProp_MessageData.m_ActorSpawningMessage;
					if (actorSpawningMessage2 != null)
					{
						string arg = LocalizationManager.GetTranslation(actorSpawningMessage2.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorSpawningMessage2);
						Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ACTIVATE_CHESTDAMAGE"), arg, $"<b>{LocalizationManager.GetTranslation(sEventObjectPropChest.ObjectName)}</b>", string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Attack> " + sEventObjectPropChest.Damage)), CombatLogFilter.DAMAGE);
					}
				}
				cTile.DelProp(cActivateProp_MessageData.m_Prop);
				if (!m_RewardsToShowcase.IsNullOrEmpty())
				{
					StackRewardsToShow(cActor, m_RewardsToShowcase, m_RewardsToShowcase_SourceType.ToString());
				}
				else
				{
					ScenarioRuleClient.ToggleMessageProcessing(process: true);
				}
				break;
			}
			throw new Exception("Prop GameObject for instance name: " + cActivateProp_MessageData.m_Prop.InstanceName + " not found");
		}
		case ScenarioManager.ObjectImportType.MoneyToken:
		{
			GameObject gameObject6 = FindPropGameObject(cActivateProp_MessageData.m_Prop);
			if (gameObject6 != null)
			{
				ScenarioManager.CurrentScenarioState.DestroyedProps.Add(cActivateProp_MessageData.m_Prop);
				CActor actorSpawningMessage5 = cActivateProp_MessageData.m_ActorSpawningMessage;
				GameObject character2 = FindClientActorGameObject(actorSpawningMessage5);
				CharacterManager characterManager3 = CharacterManager.GetCharacterManager(character2);
				if (characterManager3 != null)
				{
					if (MF.GameObjectAnimatorStateBehaviours<CollectLootSMB>(character2).Count == 0)
					{
						CollectLootSMB.CollectLoot(gameObject6);
					}
					else
					{
						characterManager3.LootTokensToCollect.Add(gameObject6);
					}
				}
				else
				{
					Log.Error("Failed to pick up gold pile");
				}
				if (cActor == null)
				{
					break;
				}
				m_RewardsToShowcase.Clear();
				m_RewardsToShowcase_SourceType = cActivateProp_MessageData.m_Prop.ObjectType;
				if (cActivateProp_MessageData.m_Rewards != null)
				{
					m_RewardsToShowcase.AddRange(cActivateProp_MessageData.m_Rewards);
				}
				if (m_RewardsToShowcase.IsNullOrEmpty())
				{
					break;
				}
				foreach (Reward item2 in m_RewardsToShowcase)
				{
					item2.GiveToCharacterType = EGiveToCharacterType.Equip;
					item2.GiveToCharacterID = cActor.Class.ID;
				}
				StackRewardsToShow(cActor, m_RewardsToShowcase, m_RewardsToShowcase_SourceType.ToString());
				break;
			}
			throw new Exception("Prop GameObject for instance name: " + cActivateProp_MessageData.m_Prop.InstanceName + " not found");
		}
		case ScenarioManager.ObjectImportType.Trap:
		{
			GameObject gameObject8 = FindPropGameObject(cActivateProp_MessageData.m_Prop);
			if (gameObject8 != null)
			{
				ScenarioManager.CurrentScenarioState.DestroyedProps.Add(cActivateProp_MessageData.m_Prop);
				StartCoroutine(PrimePropActivationAnimation(gameObject8, "Trap_Shut"));
				cActivateProp_MessageData.m_Prop.PropTile.DelProp(cActivateProp_MessageData.m_Prop);
				SEventObjectProp sEventObjectProp2 = SEventLog.FindLastObjectEventOfSubTypeAndObjectType(onlyUnprocessed: false, ESESubTypeObjectProp.Activated, ScenarioManager.ObjectImportType.Trap, toScrape: false, checkQueue: true);
				if (sEventObjectProp2 == null)
				{
					break;
				}
				CActor actorSpawningMessage7 = cActivateProp_MessageData.m_ActorSpawningMessage;
				if (actorSpawningMessage7 == null)
				{
					break;
				}
				string arg5 = LocalizationManager.GetTranslation(actorSpawningMessage7.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorSpawningMessage7);
				SEventObjectPropTrap sEventObjectPropTrap2 = (SEventObjectPropTrap)sEventObjectProp2;
				if (cActivateProp_MessageData.m_Prop is CObjectTrap { HealValue: 0, Conditions: var conditions } cObjectTrap && (conditions == null || conditions.Count == 0))
				{
					List<CCondition.EPositiveCondition> positiveConditions = cObjectTrap.PositiveConditions;
					if (positiveConditions == null || positiveConditions.Count == 0)
					{
						text4 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ACTIVATE_TRAP"), arg5, $"<b>{LocalizationManager.GetTranslation(sEventObjectProp2.ObjectName)}</b>", string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Damage> " + sEventObjectPropTrap2.Damage));
						goto IL_0b07;
					}
				}
				string text5 = string.Empty;
				foreach (string item3 in sEventObjectPropTrap2.EffectTextInOrderOfApplication)
				{
					if (item3.Contains("Damage"))
					{
						if (!string.IsNullOrEmpty(text5))
						{
							text5 += ", ";
						}
						text5 += $"<b><color=#f76767>{item3}</color></b>";
					}
					else
					{
						if (!string.IsNullOrEmpty(text5))
						{
							text5 += ", ";
						}
						text5 += item3;
					}
				}
				text4 = string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ACTIVATE_TRAP_WITH_EFFECTS"), arg5, $"<b>{LocalizationManager.GetTranslation(sEventObjectProp2.ObjectName)}</b>", text5);
				goto IL_0b07;
			}
			throw new Exception("Prop GameObject for instance name: " + cActivateProp_MessageData.m_Prop.InstanceName + " not found");
		}
		case ScenarioManager.ObjectImportType.Spawner:
		{
			string guid = cActivateProp_MessageData.m_Prop.InstanceName;
			GameObject gameObject7 = FindPropGameObject(cActivateProp_MessageData.m_Prop);
			if (gameObject7 == null)
			{
				gameObject7 = ((EnvironmentLoader.Instance?.EnvironmentRoot == null) ? null : EnvironmentLoader.Instance.EnvironmentRoot.GetComponentsInChildren<UnityGameEditorSpawnerProp>(includeInactive: true)?.FirstOrDefault((UnityGameEditorSpawnerProp a) => a != null && a.gameObject != null && a.name.Contains(guid))?.gameObject);
			}
			if (gameObject7 == null)
			{
				gameObject7 = ((EnvironmentLoader.Instance?.ApparanceMapsRoot == null) ? null : EnvironmentLoader.Instance.ApparanceMapsRoot.GetComponentsInChildren<UnityGameEditorSpawnerProp>(includeInactive: true)?.FirstOrDefault((UnityGameEditorSpawnerProp a) => a != null && a.gameObject != null && a.name.Contains(guid))?.gameObject);
			}
			if (gameObject7 != null)
			{
				Log.Error($"OBSOLETE: Spawner activation shouldn't be used anymore? {cActivateProp_MessageData.m_Prop}");
				DestroyPropImmediate(cActivateProp_MessageData.m_Prop);
			}
			else if (cActivateProp_MessageData.m_Prop.RuntimeAttachedSpawner == null || cActivateProp_MessageData.m_Prop.RuntimeAttachedSpawner.Prop != null)
			{
				throw new Exception("Prop GameObject for instance name: " + guid + " not found");
			}
			break;
		}
		case ScenarioManager.ObjectImportType.PressurePlate:
		{
