				string text2 = ((!string.IsNullOrEmpty(cActivateProp_MessageData.m_Prop.PropCustomLocKey)) ? cActivateProp_MessageData.m_Prop.PropCustomLocKey : cActivateProp_MessageData.m_Prop.PrefabName);
				if (LocalizationManager.TryGetTranslation(text2, out var translation))
				{
					text2 = translation;
