				PlayableDirector componentInChildren3 = gameObject3.GetComponentInChildren<PlayableDirector>();
				if (componentInChildren3 != null)
				{
					componentInChildren3.Play();
					StartCoroutine(DestroyPropDelayedCoro((float)componentInChildren3.duration, cActivateProp_MessageData.m_Prop));
