		case ScenarioManager.ObjectImportType.Resource:
		{
			GameObject gameObject5 = FindPropGameObject(cActivateProp_MessageData.m_Prop);
			CActor actorSpawningMessage4 = cActivateProp_MessageData.m_ActorSpawningMessage;
			if (actorSpawningMessage4 != null && !cActivateProp_MessageData.m_Prop.PrefabName.Contains("Favorite"))
			{
				string arg3 = LocalizationManager.GetTranslation(actorSpawningMessage4.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorSpawningMessage4);
				string text3 = ((!string.IsNullOrEmpty(cActivateProp_MessageData.m_Prop.PropCustomLocKey)) ? cActivateProp_MessageData.m_Prop.PropCustomLocKey : cActivateProp_MessageData.m_Prop.PropHealthDetails?.CustomLocKey);
				CObjectResource cObjectResource = cActivateProp_MessageData.m_Prop as CObjectResource;
				string translation2 = LocalizationManager.GetTranslation((!text3.IsNullOrEmpty()) ? text3 : cObjectResource.ResourceData.ID);
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_LOOT"), arg3, translation2));
			}
			if (gameObject5 != null)
			{
				if (cActivateProp_MessageData.m_Prop is CObjectResource { ResourceData: { StayActiveAfterLooted: not false } })
				{
					break;
				}
				ScenarioManager.CurrentScenarioState.DestroyedProps.Add(cActivateProp_MessageData.m_Prop);
				PlayableDirector componentInChildren4 = gameObject5.GetComponentInChildren<PlayableDirector>();
				if (componentInChildren4 != null)
				{
					TimelineAssets componentInChildren5 = gameObject5.GetComponentInChildren<TimelineAssets>();
					if (((componentInChildren5 == null) ? null : componentInChildren5.FindTimelineAsset("LOOTPickUpTimeline ")) != null)
					{
						GameObject character = FindClientActorGameObject(actorSpawningMessage4);
						CharacterManager characterManager2 = CharacterManager.GetCharacterManager(character);
						List<CollectLootSMB> list = ((characterManager2 == null) ? null : MF.GameObjectAnimatorStateBehaviours<CollectLootSMB>(character));
						if (list == null || list.Count == 0)
						{
							CollectLootSMB.CollectLoot(gameObject5);
						}
						else
						{
							characterManager2.LootTokensToCollect.Add(gameObject5);
						}
					}
					else
					{
						componentInChildren4.Play();
						StartCoroutine(DestroyPropDelayedCoro((float)componentInChildren4.duration, cActivateProp_MessageData.m_Prop));
					}
				}
				else
				{
					StartCoroutine(DestroyPropDelayedCoro(1f, cActivateProp_MessageData.m_Prop));
				}
			}
			else if (!cActivateProp_MessageData.m_CarriedByActor)
			{
				throw new Exception("Prop GameObject for instance name: " + cActivateProp_MessageData.m_Prop.InstanceName + " not found");
			}
			break;
		}
		case ScenarioManager.ObjectImportType.GenericProp:
		case ScenarioManager.ObjectImportType.MonsterGrave:
			{
				GameObject gameObject = FindPropGameObject(cActivateProp_MessageData.m_Prop);
				if (gameObject != null)
				{
					PlayableDirector componentInChildren = gameObject.GetComponentInChildren<PlayableDirector>();
					if (componentInChildren != null)
					{
						componentInChildren.Play();
						StartCoroutine(DestroyPropDelayedCoro((float)componentInChildren.duration, cActivateProp_MessageData.m_Prop));
					}
					else
					{
						StartCoroutine(DestroyPropDelayedCoro(1f, cActivateProp_MessageData.m_Prop));
					}
				}
				else if (!cActivateProp_MessageData.m_CarriedByActor)
				{
					throw new Exception("Prop GameObject for instance name: " + cActivateProp_MessageData.m_Prop.InstanceName + " not found");
				}
				break;
			}
			IL_0b07:
			Singleton<CombatLogHandler>.Instance.AddLog(text4, CombatLogFilter.DAMAGE);
			break;
		}
		UIEventManager.AddUIEvent(new UIEvent(UIEvent.EUIEventType.PropActivated, null, cActivateProp_MessageData.m_Prop.PropGuid, 0, null, cActivateProp_MessageData.m_Prop.ActorActivated));
	}

	[MessageHandler(CMessageData.MessageType.DeactivatePropAnim)]
	private void Handle_DeactivatePropAnim(CMessageData message)
	{
		CDeactivatePropAnim_MessageData cDeactivatePropAnim_MessageData = (CDeactivatePropAnim_MessageData)message;
		GameObject gameObject = FindPropGameObject(cDeactivatePropAnim_MessageData.m_Prop);
		if (gameObject != null)
		{
			switch (cDeactivatePropAnim_MessageData.m_Prop.ObjectType)
			{
			case ScenarioManager.ObjectImportType.Trap:
				MF.GameObjectAnimatorPlay(gameObject, "Trap_Shut");
				break;
			case ScenarioManager.ObjectImportType.PressurePlate:
				MF.GameObjectAnimatorPlay(gameObject, "UnPressed");
				break;
			case ScenarioManager.ObjectImportType.Spawner:
				MF.GameObjectAnimatorPlay(gameObject, "Deactivate");
				break;
			case ScenarioManager.ObjectImportType.Door:
				MF.GameObjectAnimatorPlay(gameObject, "Idle");
				break;
