			Log.Warning("Unable to find game object for prop: " + cDeactivatePropAnim_MessageData.m_Prop.InstanceName);
		}
		UIEventManager.AddUIEvent(new UIEvent(UIEvent.EUIEventType.PropDeactivated, null, cDeactivatePropAnim_MessageData.m_Prop.PropGuid));
	}

