	[MessageHandler(CMessageData.MessageType.ActorIsSelectingTeleport2Tile)]
	private void Handle_ActorIsSelectingTeleport2Tile(CMessageData message)
	{
		CActorIsSelectingTeleport2Tile_MessageData cActorIsSelectingTeleport2Tile_MessageData = message as CActorIsSelectingTeleport2Tile_MessageData;
		Waypoint.s_MovingActor = cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.ActorToTeleport;
		s_Choreographer.m_CurrentActor = cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.TargetingActor;
		s_Choreographer.m_CurrentAbility = cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability;
		ClearAllActorEvents();
		if (message.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			if (!m_FollowCameraDisabled)
			{
				CameraController.s_CameraController.DisableCameraInput(disableInput: false, this);
			}
			GameObject nextWaypoint = Waypoint.GetNextWaypoint();
			if (nextWaypoint != null)
			{
				Waypoint waypointComponent = Waypoint.GetWaypointComponent(nextWaypoint);
				s_Choreographer.TileHandler(waypointComponent.ClientTile, Waypoint.GetCTileList());
				Waypoint.DestroyWaypoint(nextWaypoint);
				GUIInterface.s_GUIInterface.SetStatusText("Next stage of path" + message.m_ActorSpawningMessage.ID + " Waypoint Order " + waypointComponent.Order);
			}
			else
			{
				TileBehaviour.SetCallback(Waypoint.TileHandler);
				SetChoreographerState(ChoreographerStateType.WaitingForPlayerTeleport2WaypointSelection, 0, null);
				WorldspaceStarHexDisplay.Instance.CurrentMoveDisplayType = WorldspaceStarHexDisplay.EMoveDisplayType.Teleport2;
				WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.MovementSelection;
				WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
				DisableTileSelection(active: false);
				GUIInterface.s_GUIInterface.SetStatusText($"Select teleport destination for {message.m_ActorSpawningMessage.ID}");
			}
		}
		else
		{
			GUIInterface.s_GUIInterface.SetStatusText("Monster " + LocalizationManager.GetTranslation(message.m_ActorSpawningMessage.ActorLocKey()) + " teleporting");
		}
		if (!m_FollowCameraDisabled)
		{
			GameObject target = FindClientActorGameObject(cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.ActorToTeleport);
			CameraController.s_CameraController.SmartFocus(target, pauseDuringTransition: true);
		}
		if (m_WaitState.m_State != ChoreographerStateType.WaitingForMoveAnim)
		{
			m_SkipButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player, LocalizationManager.GetTranslation("GUI_SKIP_TELEPORT2"), hideOnClick: true, cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.CanSkip);
			readyButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player, ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED, LocalizationManager.GetTranslation("GUI_CONFIRM_TELEPORT2"), hideOnClick: true, glowingEffect: true);
			m_UndoButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player);
			m_UndoButton.SetInteractable(cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.CanUndo && FirstAbility);
		}
		List<CTile> teleportTiles = cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.GetTeleportTiles(cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.TargetingActor.ArrayIndex, cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.Strength);
		if (cActorIsSelectingTeleport2Tile_MessageData.m_Teleport2Ability.GetVar("TargetShadows").GetBool() && teleportTiles.Count == 1)
		{
			CTile cTile = teleportTiles[0];
			CClientTile clientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cTile.m_ArrayIndex.X, cTile.m_ArrayIndex.Y];
			Waypoint.AddValidSelectionTiles(cTile.m_ArrayIndex);
			Waypoint.TileHandler(clientTile, null, networkActionIfOnline: false);
			m_UndoButton.SetInteractable(FirstAbility);
			Waypoint.s_LockWaypoints = true;
		}
		if (FFSNetwork.IsOnline && message.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			if (!message.m_ActorSpawningMessage.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.Teleport2TileSelection);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.Teleport2TileSelection);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorIsTeleporting2)]
	private void Handle_ActorIsTeleporting2(CMessageData message)
	{
		CActorIsTeleporting2_MessageData cActorIsTeleporting2_MessageData = (CActorIsTeleporting2_MessageData)message;
		CurrentAttackTargets.Clear();
		CurrentAttackArea.Clear();
		if (cActorIsTeleporting2_MessageData.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		}
		CActor actorToTeleport = cActorIsTeleporting2_MessageData.m_ActorToTeleport;
		GameObject actorGO = FindClientActorGameObject(actorToTeleport);
		ClearStars();
		TileBehaviour.SetCallback(TileHandler);
		if (cActorIsTeleporting2_MessageData.m_Teleport2Ability.UseFade())
		{
			StartCoroutine(TeleportFadeOutCrt(actorGO, Vector3.zero, actorToTeleport, callFadeIn: false));
			return;
		}
		GameObject gameObject = FindClientActorGameObject(actorToTeleport);
		GameObject go = FindClientActorGameObject(cActorIsTeleporting2_MessageData.m_ActorSpawningMessage);
		StartCoroutine(RotateToFaceTarget(go, gameObject.transform.position));
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cActorIsTeleporting2_MessageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cActorIsTeleporting2_MessageData.m_Teleport2Ability, actorToTeleport, new List<string> { cActorIsTeleporting2_MessageData.AnimOverload, "Jump Into" }, out animationShouldPlay, out animatingActorToWaitFor);
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorHasTeleported2)]
	private void Handle_ActorHasTeleported2(CMessageData message)
	{
		CActorHasTeleported2_MessageData cActorHasTeleported2_MessageData = (CActorHasTeleported2_MessageData)message;
		ClearAllActorEvents();
		CAbilityTeleport2 teleport2Ability = cActorHasTeleported2_MessageData.m_Teleport2Ability;
		CActor actorToTeleport = cActorHasTeleported2_MessageData.m_ActorToTeleport;
		GameObject gameObject = FindClientActorGameObject(actorToTeleport);
		CTile destinationTile = cActorHasTeleported2_MessageData.m_DestinationTile;
		GameObject gameObject2 = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[destinationTile.m_ArrayIndex.X, destinationTile.m_ArrayIndex.Y].m_GameObject;
		Vector3 position = gameObject2.transform.position;
		CameraController.s_CameraController.SmartFocus(gameObject2);
		if (gameObject != null)
		{
			if (teleport2Ability.UseFade())
			{
				StartCoroutine(TeleportFadeInCrt(gameObject, position, actorToTeleport));
			}
			else
			{
				ActorBehaviour.GetActorBehaviour(gameObject).TeleportToLocation(position);
				bool animationShouldPlay = false;
				CActor animatingActorToWaitFor = actorToTeleport;
				ProcessActorAnimation(teleport2Ability, animatingActorToWaitFor, new List<string> { cActorHasTeleported2_MessageData.AnimOverload, "Jump Outof", "PowerUp" }, out animationShouldPlay, out animatingActorToWaitFor);
				if (animatingActorToWaitFor != null)
				{
					SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
				}
				if (!animationShouldPlay)
				{
					ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
				}
			}
		}
		Waypoint.Clear();
	}

