	[MessageHandler(CMessageData.MessageType.ActorIsPushing)]
	private void Handle_ActorIsPushing(CMessageData message)
	{
		CActorIsPushing_MessageData cActorIsPushing_MessageData = (CActorIsPushing_MessageData)message;
		CurrentAttackTargets.Clear();
		CurrentAttackArea.Clear();
		ClearStars();
		TileBehaviour.SetCallback(TileHandler);
		if (cActorIsPushing_MessageData.m_PushAbility.ValidTilesInAreaAffected != null && cActorIsPushing_MessageData.m_PushAbility.ValidTilesInAreaAffected.Count > 0)
		{
			foreach (CTile item in cActorIsPushing_MessageData.m_PushAbility.ValidTilesInAreaAffected)
			{
				CurrentAttackArea.Add(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item.m_ArrayIndex.X, item.m_ArrayIndex.Y]);
			}
		}
		bool flag = cActorIsPushing_MessageData.m_PushAbility.GetMiscVar("SkipAnimAndRotation").GetBool();
		if (!cActorIsPushing_MessageData.m_PushAbility.UseSubAbilityTargeting && !flag)
		{
			GameObject gameObject = FindClientActorGameObject(cActorIsPushing_MessageData.m_PushAbility.CurrentTarget);
			GameObject go = FindClientActorGameObject(cActorIsPushing_MessageData.m_ActorSpawningMessage);
			StartCoroutine(RotateToFaceTarget(go, gameObject.transform.position));
			bool animationShouldPlay = false;
			CActor animatingActorToWaitFor = cActorIsPushing_MessageData.m_ActorSpawningMessage;
			ProcessActorAnimation(cActorIsPushing_MessageData.m_PushAbility, cActorIsPushing_MessageData.m_ActorSpawningMessage, new List<string> { cActorIsPushing_MessageData.AnimOverload, "Push" }, out animationShouldPlay, out animatingActorToWaitFor);
			if (animatingActorToWaitFor != null)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
			}
		}
		else
		{
			ScenarioRuleClient.StepComplete();
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorHasPushed)]
	private void Handle_ActorHasPushed(CMessageData message)
	{
		CActorHasPushed_MessageData cActorHasPushed_MessageData = (CActorHasPushed_MessageData)message;
