				CameraController.s_CameraController.DisableCameraInput(CameraController.ECameraInput.Move, this);
			}
			Vector3 position = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cActorHasPushed_MessageData.m_ActorBeingPushed.ArrayIndex.X, cActorHasPushed_MessageData.m_ActorBeingPushed.ArrayIndex.Y].m_GameObject.transform.position;
			int num = 0;
			if (MF.GetGameObjectAnimatorController(gameObject) != null)
			{
				num = 10000;
				ActorBehaviour.GetActorBehaviour(gameObject).PushPullToLocation(position, dontCheckAnimator: true);
			}
			else
			{
				num = 400;
