	[MessageHandler(CMessageData.MessageType.UpdateAdditionalPushDamagePreview)]
	private void Handle_UpdateAdditionalPushDamagePreview(CMessageData message)
	{
		CUpdateAdditionalPushDamagePreview_MessageData cUpdateAdditionalPushDamagePreview_MessageData = (CUpdateAdditionalPushDamagePreview_MessageData)message;
		if (cUpdateAdditionalPushDamagePreview_MessageData.m_PushAbility.ValidActorsInRange == null)
		{
			return;
		}
		if (cUpdateAdditionalPushDamagePreview_MessageData.m_PushAbility.AdditionalPushDamageSummary != null)
		{
			int targetIndex = 0;
			CAttackSummary.TargetSummary targetSummary = cUpdateAdditionalPushDamagePreview_MessageData.m_PushAbility.AdditionalPushDamageSummary.FindTarget(cUpdateAdditionalPushDamagePreview_MessageData.m_PushAbility.CurrentTarget, ref targetIndex);
			if (targetSummary != null)
			{
				ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(cUpdateAdditionalPushDamagePreview_MessageData.m_PushAbility.CurrentTarget)).m_WorldspacePanelUI?.OnSelectingDamageFocus(cUpdateAdditionalPushDamagePreview_MessageData.m_PushAbility, cUpdateAdditionalPushDamagePreview_MessageData.m_ActorSpawningMessage, targetSummary);
			}
		}
		else
		{
			ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(cUpdateAdditionalPushDamagePreview_MessageData.m_PushAbility.CurrentTarget)).m_WorldspacePanelUI?.ResetDamagePreview(0);
		}
	}

	[MessageHandler(CMessageData.MessageType.ActionAbilityHasHappened)]
	private void Handle_ActionAbilityHasHappened(CMessageData message)
	{
		CActionAbilityHasHappened_MessageData cActionAbilityHasHappened_MessageData = (CActionAbilityHasHappened_MessageData)message;
		if (message.m_ActorSpawningMessage.Type == CActor.EType.Player)
		{
			if (cActionAbilityHasHappened_MessageData.PendingElementsToInfuse)
			{
				Singleton<CardsHandManager>.Instance.UpdateElements(message.m_ActorSpawningMessage as CPlayerActor);
			}
			if (m_CurrentAbility != null && m_CurrentAbility.AbilityType == CAbility.EAbilityType.ImprovedShortRest)
			{
				InitiativeTrack.Refresh(message.m_ActorSpawningMessage, isActiveButton: true);
			}
			if (cActionAbilityHasHappened_MessageData.m_Ability != null)
			{
				Singleton<AbilityEffectManager>.Instance.RemoveEffect(cActionAbilityHasHappened_MessageData.m_Ability);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.PlayEnvAudio)]
	private void Handle_PlayEnvAudio(CMessageData message)
	{
		GameObject gameObject = GameObject.Find(((CPlayEnvAudio_MessageData)message).m_RoomId);
		if ((bool)gameObject)
		{
			StaticEnvSFX[] componentsInChildren = gameObject.GetComponentsInChildren<StaticEnvSFX>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].PlayAudio();
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.PlaySound)]
	private void Handle_PlaySound(CMessageData message)
	{
		if (LoadingComplete && !ScenarioManager.IsFastReloading && (!(TransitionManager.s_Instance != null) || TransitionManager.s_Instance.TransitionDone))
		{
			AudioController.Play(((CPlaySound_MessageData)message).m_AudioItem);
		}
	}

	[MessageHandler(CMessageData.MessageType.Spawn)]
	private void Handle_Spawn(CMessageData message)
	{
		CSpawn_MessageData cSpawn_MessageData = (CSpawn_MessageData)message;
		if (!cSpawn_MessageData.m_Prop.SkipVisuals)
		{
			if (cSpawn_MessageData.m_SpawnDelay > 0f)
			{
				StartCoroutine(SpawnProp(cSpawn_MessageData));
			}
			else
			{
				SpawnPropInstant(cSpawn_MessageData);
			}
		}
		else
		{
			Watchman.Instance.Complete(cSpawn_MessageData.m_Prop.InstanceName);
		}
	}

	[MessageHandler(CMessageData.MessageType.Summon)]
	private void Handle_Summon(CMessageData message)
	{
		CSummon_MessageData cSummon_MessageData = (CSummon_MessageData)message;
		ClearAllActorEvents();
		s_Choreographer.m_CurrentAbility = cSummon_MessageData.m_SummonAbility;
		GameObject gameObject = FindClientActorGameObject(cSummon_MessageData.m_ActorSummoning);
		Vector3 zero = Vector3.zero;
		foreach (CTile summonTile in cSummon_MessageData.m_SummonTiles)
		{
			zero += ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[summonTile.m_ArrayIndex.X, summonTile.m_ArrayIndex.Y].m_GameObject.transform.position;
		}
		zero /= (float)cSummon_MessageData.m_SummonTiles.Count;
		if (gameObject != null)
		{
			StartCoroutine(RotateToFaceTarget(gameObject, zero));
		}
		ActorsBeingTargetedForVFX?.Clear();
		m_LastSelectedTiles = cSummon_MessageData.m_SummonTiles.Select((CTile t) => ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[t.m_ArrayIndex.X, t.m_ArrayIndex.Y]).ToList();
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cSummon_MessageData.m_ActorSummoning;
		ProcessActorAnimation(cSummon_MessageData.m_SummonAbility, cSummon_MessageData.m_ActorSummoning, new List<string>
		{
			cSummon_MessageData.AnimOverload,
			GetNonOverloadAnim(cSummon_MessageData.m_SummonAbility)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		if (animatingActorToWaitFor != null && !cSummon_MessageData.m_SkipChoreographerWait)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay || cSummon_MessageData.m_SummonAbility == null)
		{
			if (gameObject != null)
			{
				ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
			}
			SummonSMB.SummonCharacters(cSummon_MessageData.m_SummonedActors);
		}
	}

	[MessageHandler(CMessageData.MessageType.Revive)]
	private void Handle_Revive(CMessageData message)
	{
		CRevive_MessageData cRevive_MessageData = (CRevive_MessageData)message;
		ClearAllActorEvents();
		s_Choreographer.m_CurrentAbility = cRevive_MessageData.m_ReviveAbility;
		GameObject go = FindClientActorGameObject(cRevive_MessageData.m_ActorReviving);
		Vector3 zero = Vector3.zero;
		foreach (CTile reviveTile in cRevive_MessageData.m_ReviveTiles)
		{
			zero += ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[reviveTile.m_ArrayIndex.X, reviveTile.m_ArrayIndex.Y].m_GameObject.transform.position;
		}
		zero /= (float)cRevive_MessageData.m_ReviveTiles.Count;
		StartCoroutine(RotateToFaceTarget(go, zero));
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cRevive_MessageData.m_ActorReviving;
		ProcessActorAnimation(cRevive_MessageData.m_ReviveAbility, cRevive_MessageData.m_ActorReviving, new List<string>
		{
			cRevive_MessageData.AnimOverload,
			GetNonOverloadAnim(cRevive_MessageData.m_ReviveAbility)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(go).ProgressChoreographer();
		}
	}

	[MessageHandler(CMessageData.MessageType.RevealProp)]
	private void Handle_RevealProp(CMessageData message)
	{
		CRevealDoor_MessageData cRevealDoor_MessageData = (CRevealDoor_MessageData)message;
		GameObject gameObject = FindPropGameObject(cRevealDoor_MessageData.m_Prop);
		if (gameObject != null && gameObject.activeSelf && cRevealDoor_MessageData.m_Prop.ObjectType == ScenarioManager.ObjectImportType.Door)
		{
			Renderer[] componentsInChildren = gameObject.GetComponentsInChildren<Renderer>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].enabled = true;
			}
			UnityGameEditorDoorProp component = gameObject.GetComponent<UnityGameEditorDoorProp>();
			if (component != null)
			{
				component.m_InitiallyVisable = true;
			}
			gameObject.FindInChildren("Generated Content", includeInactive: true).SetActive(value: true);
		}
	}

	[MessageHandler(CMessageData.MessageType.ElementsConsumed)]
	private void Handle_ElementsConsumed(CMessageData message)
	{
		CElementsConsumed_MessageData cElementsConsumed_MessageData = (CElementsConsumed_MessageData)message;
		CBaseCard cBaseCard = cElementsConsumed_MessageData.m_Consume?.GetAbilityBaseCard();
		if (cBaseCard == null)
		{
			cBaseCard = cElementsConsumed_MessageData.m_Card;
		}
		LogConsumedElements(message.m_ActorSpawningMessage, cElementsConsumed_MessageData.m_ChangedElements, cBaseCard);
	}

	[MessageHandler(CMessageData.MessageType.ElementsInfused)]
	private void Handle_ElementsInfused(CMessageData message)
	{
		CElementsInfused_MessageData cElementsInfused_MessageData = (CElementsInfused_MessageData)message;
		bool flag = cElementsInfused_MessageData.m_InfuseAbility != null;
		CAbility cAbility = cElementsInfused_MessageData.m_ConsumeAbility;
		if (flag)
		{
			cAbility = cElementsInfused_MessageData.m_InfuseAbility;
		}
		ClearAllActorEvents();
		if (cAbility != null)
		{
			DisableNextPhaseButtons();
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cElementsInfused_MessageData.m_ActorSpawningMessage;
		if (cAbility != null && !cAbility.IsModifierAbility)
		{
			ProcessActorAnimation(cAbility, cElementsInfused_MessageData.m_ActorSpawningMessage, new List<string>
			{
				cElementsInfused_MessageData.AnimOverload,
				GetNonOverloadAnim(cAbility)
			}, out animationShouldPlay, out animatingActorToWaitFor);
			if (animatingActorToWaitFor != null)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
			}
		}
		if (flag)
		{
			InfusionBoardUI.Instance?.UpdateBoard(cElementsInfused_MessageData.m_ChangedElements);
		}
		else if (cElementsInfused_MessageData.m_IsConsume)
		{
			LogConsumedElements(cElementsInfused_MessageData.m_ActorSpawningMessage, cElementsInfused_MessageData.m_ChangedElements);
		}
		if (cAbility != null)
		{
			Singleton<UIUseItemsBar>.Instance.Hide();
		}
		if (message.m_ActorSpawningMessage != null)
		{
			GameObject gameObject = FindClientActorGameObject(message.m_ActorSpawningMessage);
			if (!animationShouldPlay)
			{
				ActorEvents.GetActorEvents(gameObject)?.ProgressChoreographer();
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ElementInfuseCancelled)]
