		CAbility cAbility = cElementInfuseCancelled_MessageData.m_ConsumeAbility;
		if (flag)
		{
			cAbility = cElementInfuseCancelled_MessageData.m_InfuseAbility;
		}
		ClearAllActorEvents();
		if (cAbility != null)
		{
			DisableNextPhaseButtons();
		}
		InfusionBoardUI.Instance?.RemoveElementsInCreation(cElementInfuseCancelled_MessageData.m_InfusedElements);
		foreach (ElementInfusionBoardManager.EElement e in cElementInfuseCancelled_MessageData.m_InfusedElements)
