		if (cAbility != null)
		{
			Singleton<UIUseItemsBar>.Instance.Hide();
		}
	}

	[MessageHandler(CMessageData.MessageType.WaitForProgressChoreographer)]
	private void Handle_WaitForProgressChoreographer(CMessageData message)
	{
		if (s_Choreographer.m_WaitState.m_State == ChoreographerStateType.WaitingForEndAbilityAnimSync)
		{
			Log.Warning("Trying to set choreographer wait state to WaitingForProgressChoreographer while WaitingForEndAbilityAnimSync is currently in progress. This is gamebreakingly illegal, please investigate how it happened. \nCall stack: " + message.CallStack);
			StartCoroutine(WaitForGenericCondition(() => s_Choreographer.m_WaitState.m_State == ChoreographerStateType.Play, () =>
			{
				Log.Info("Finished waiting for WaitingForEndAbilityAnimSync, resuming WaitingForProgressChoreographer");
				Handle_WaitForProgressChoreographer(message);
			}));
			return;
		}
		if (s_Choreographer.m_WaitState.m_State != ChoreographerStateType.WaitingForItemRefresh && s_Choreographer.m_WaitState.m_State != ChoreographerStateType.WaitingForAttackAnim)
		{
			CWaitForProgressChoreographer_MessageData cWaitForProgressChoreographer_MessageData = message as CWaitForProgressChoreographer_MessageData;
			if (cWaitForProgressChoreographer_MessageData.ClearEvents)
			{
				ClearAllActorEvents();
			}
			SetChoreographerState(ChoreographerStateType.WaitingForProgressChoreographer, cWaitForProgressChoreographer_MessageData.WaitTickFrame, cWaitForProgressChoreographer_MessageData.WaitActor);
		}
		if (PhaseManager.PhaseType != CPhase.PhaseType.Action)
		{
			return;
		}
		CPhaseAction cPhaseAction = (CPhaseAction)PhaseManager.Phase;
		if (cPhaseAction != null && cPhaseAction.CurrentPhaseAbility?.m_Ability != null && cPhaseAction.CurrentPhaseAbility.m_Ability is CAbilityConsumeItemCards cAbilityConsumeItemCards)
		{
			string arg = (cAbilityConsumeItemCards.SlotsToConsume.IsNullOrEmpty() ? string.Empty : LocalizationManager.GetTranslation($"GUI_ITEM_SLOT_{cAbilityConsumeItemCards.SlotsToConsume[0]}"));
			if (cAbilityConsumeItemCards.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
			{
				ShowAbilityHelpBoxTooltip(cAbilityConsumeItemCards);
			}
			else
			{
				Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_CONSUME_ITEMS_TIP"), arg), string.Format(LocalizationManager.GetTranslation("GUI_CONSUME_ITEMS_TITLE"), arg));
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ForcedWaitForProgressChoreographer)]
