	[MessageHandler(CMessageData.MessageType.ClearWaypointsAndTargets)]
	private void Handle_ClearWaypointsAndTargets(CMessageData message)
	{
		if (!GameState.ThreadIsSleeping)
		{
			while (Waypoint.s_Waypoints.Count > 0)
			{
				Waypoint.GetLastWaypoint.OnDelete();
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.RecreateWaypoints)]
	private void Handle_RecreateWaypoints(CMessageData message)
	{
		CAbilityMove moveAbility = (message as CRecreateWaypoints_MessageData).m_MoveAbility;
		s_Choreographer.m_CurrentAbility = moveAbility;
		Waypoint.Clear();
		foreach (CTile allSelectedPlayerWaypoint in moveAbility.AllSelectedPlayerWaypoints)
		{
			CClientTile clientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[allSelectedPlayerWaypoint.m_ArrayIndex.X, allSelectedPlayerWaypoint.m_ArrayIndex.Y];
			Waypoint.AddValidSelectionTiles(allSelectedPlayerWaypoint.m_ArrayIndex);
			Waypoint.TileHandler(clientTile, null, networkActionIfOnline: false);
		}
		if (Waypoint.GetLastWaypoint == null)
		{
			if (moveAbility.AllSelectedPlayerWaypoints.Count <= 0)
			{
				ScenarioRuleClient.StepComplete();
				return;
			}
			CTile cTile = moveAbility.AllSelectedPlayerWaypoints[0];
			if (moveAbility.TargetingActor.Tile == cTile && !moveAbility.CanReceiveTileSelection())
			{
				moveAbility.DontMoveAbilityState = true;
				ScenarioRuleClient.StepComplete();
				return;
			}
			Waypoint.Create(ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cTile.m_ArrayIndex.X, cTile.m_ArrayIndex.Y], moveAbility.RemainingMovesAfterLimit, 1, 0, 0, Waypoint.EWaypointType.Move, moveAbility.Fly, tileIsBlocked: false);
		}
		if (moveAbility.CanReceiveTileSelection())
		{
			ActionsViewService.ConfirmMovement();
			return;
		}
		moveAbility.DontMoveAbilityState = true;
		ScenarioRuleClient.StepComplete();
	}

	[MessageHandler(CMessageData.MessageType.ToggledActionAugmentation)]
	private void Handle_ToggledActionAugmentation(CMessageData message)
	{
		CToggledActionAugmentation_MessageData cToggledActionAugmentation_MessageData = (CToggledActionAugmentation_MessageData)message;
		CAbility ability = cToggledActionAugmentation_MessageData.m_CurrentAbilityAfterToggling;
		using (new CActiveBonus.ActiveBonusCalculationScope())
		{
			readyButton.SetInteractable(ability.EnoughTargetsSelected());
			m_UndoButton.SetInteractable(ability.CanUndo && FirstAbility);
			m_SkipButton.SetInteractable(ability.CanSkip);
			InfusionBoardUI.Instance?.MarkElementsDirty();
			while (Waypoint.s_Waypoints.Count > 0)
			{
				Waypoint.GetLastWaypoint.OnDelete();
			}
			bool flag = CurrentActor.IsUnderMyControl();
			Singleton<UIUseAugmentationsBar>.Instance.SetInteractionAvailableSlots(flag, onlyChangeUnselected: false, checkForSingleConsume: true);
			Singleton<UIActiveBonusBar>.Instance.SetInteractionAvailableSlots(flag);
			Singleton<UIUseItemsBar>.Instance.SetItemsInteractable(flag);
			Singleton<UIUseItemsBar>.Instance.ShowUsableItems(ability.TargetingActor, (CItem item) => item.YMLData.Data.CompareAbility != null && (item.YMLData.Data.CompareAbility.CompareAbility(ability) || item.SlotState == CItem.EItemSlotState.Selected), (ability.ActiveSingleTargetItems.Count == 0) ? "GUI_USE_ITEM_ATTACK_TIP" : "GUI_TOOLTIP_ITEM_SINGLE_TARGET_TIP", (ability.ActiveSingleTargetItems.Count == 0) ? "GUI_USE_ITEM_TITLE" : "GUI_TOOLTIP_ITEM_SINGLE_TARGET_TITLE");
			if (FFSNetwork.IsOnline && !ability.TargetingActor.IsUnderMyControl() && ActionProcessor.HasSavedStateInSamePhase)
			{
				if (ActionProcessor.CurrentState.StateType == ActionProcessorStateType.Halted)
				{
					ActionProcessor.SetState(ActionProcessorStateType.SwitchBackToSavedState);
				}
				else
				{
					ActionProcessor.ClearSavedState();
				}
			}
			if (!(PhaseManager.Phase is CPhaseAction cPhaseAction))
			{
				return;
			}
			foreach (CTile item in ability.TilesSelected)
			{
				CActor cActor = ScenarioManager.Scenario.FindActorAt(item.m_ArrayIndex.X, item.m_ArrayIndex.Y);
				if (cActor != null)
				{
					ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(cActor)).m_WorldspacePanelUI?.PreviewEffects(ability, cActor, !cPhaseAction.ActionAugmentationsToConsume.Contains(cToggledActionAugmentation_MessageData.m_CurrentAugment));
				}
			}
			WorldspacePanelUIController.PreviewAugmentEffects(cToggledActionAugmentation_MessageData.m_CurrentAugment, ability, cPhaseAction.ActionAugmentationsToConsume.Contains(cToggledActionAugmentation_MessageData.m_CurrentAugment));
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorIsApplyingControlActor)]
	private void Handle_ActorIsApplyingControlActor(CMessageData message)
	{
		CActorIsApplyingControlActor cActorIsApplyingControlActor = (CActorIsApplyingControlActor)message;
		ClearAllActorEvents();
		if (ActorsBeingTargetedForVFX == null)
		{
			m_ActorsBeingTargetedForVFX = new List<CActor>();
		}
		ActorsBeingTargetedForVFX?.Clear();
		Vector3 zero = Vector3.zero;
		foreach (CActor item in cActorIsApplyingControlActor.m_ActorsAppliedTo)
		{
			GameObject gameObject = FindClientActorGameObject(item);
			if (gameObject != null)
			{
				zero += gameObject.transform.position;
				CurrentAttackTargets.Add(gameObject);
				ActorsBeingTargetedForVFX.Add(item);
			}
		}
		zero /= (float)cActorIsApplyingControlActor.m_ActorsAppliedTo.Count;
		StartCoroutine(RotateToFaceTarget(FindClientActorGameObject(cActorIsApplyingControlActor.m_ActorSpawningMessage), zero));
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cActorIsApplyingControlActor.m_ActorSpawningMessage;
		ProcessActorAnimation(cActorIsApplyingControlActor.m_ControlActorAbility, cActorIsApplyingControlActor.m_ActorSpawningMessage, new List<string>
		{
			cActorIsApplyingControlActor.AnimOverload,
			GetNonOverloadAnim(cActorIsApplyingControlActor.m_ControlActorAbility)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, 0, animatingActorToWaitFor);
		DisableTileSelection(active: true);
		GameObject gameObject2 = FindClientActorGameObject(cActorIsApplyingControlActor.m_ActorSpawningMessage);
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(gameObject2).ProgressChoreographer();
		}
	}

