	[MessageHandler(CMessageData.MessageType.OnItemCallback)]
	private void Handle_OnItemCallback(CMessageData message)
	{
		COnItemCallback_MessageData messageData = (COnItemCallback_MessageData)message;
		if (messageData.m_Callback != null)
		{
			messageData.m_Callback(messageData.m_Item, EventArgs.Empty);
		}
		if ((!messageData.m_HideLog && (messageData.m_CallbackType == ESESubTypeItem.ItemUnrestrictedUsed || messageData.m_CallbackType == ESESubTypeItem.ItemConsumed || messageData.m_CallbackType == ESESubTypeItem.ItemSpent) && (messageData.m_Item.YMLData.ItemType == CItem.EItemType.Vars || messageData.m_Item.GetVar("LogUse").GetBool())) || (messageData.m_CallbackType == ESESubTypeItem.ItemLocked && (messageData.m_Item.YMLData.ItemType == CItem.EItemType.Vars || messageData.m_Item.GetVar("LogUseOnLocked").GetBool())) || (messageData.m_CallbackType == ESESubTypeItem.ItemConsumed && messageData.m_Item.GetVar("LogUseConsumed").GetBool()))
		{
			string arg = LocalizationManager.GetTranslation(messageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(messageData.m_ActorSpawningMessage);
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_USES"), arg, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(messageData.m_Item.Name)}</color></b></font>"), CombatLogFilter.ITEMS);
		}
		else if (messageData.m_CallbackType == ESESubTypeItem.ItemActive && (messageData.m_Item.YMLData.Trigger == CItem.EItemTrigger.OnNegativeConditionFromEnemy || messageData.m_Item.YMLData.Trigger == CItem.EItemTrigger.OnNegativeConditionGlobal || messageData.m_Item.YMLData.Trigger == CItem.EItemTrigger.OnPositiveConditionFromEnemy || messageData.m_Item.YMLData.Trigger == CItem.EItemTrigger.OnPositiveConditionGlobal))
		{
			string arg2 = LocalizationManager.GetTranslation(messageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(messageData.m_ActorSpawningMessage);
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_USES"), arg2, $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(messageData.m_Item.Name)}</color></b></font>"), CombatLogFilter.ITEMS);
		}
		Singleton<UIUseItemsBar>.Instance.RefreshTooltip();
		Singleton<TakeDamagePanel>.Instance.RefreshDamageTooltip();
		if (messageData.m_CallbackType == ESESubTypeItem.ItemRefreshed)
		{
			if (messageData.m_ActorSpawningMessage != null)
			{
				CardsHandUI cardsHandUI = Singleton<CardsHandManager>.Instance.cardHandsUI.SingleOrDefault((CardsHandUI x) => x.PlayerActor.CharacterClass.ID == messageData.m_ActorSpawningMessage.Class.ID);
				if (cardsHandUI != null)
				{
					cardsHandUI.ResetItemElements(messageData.m_Item);
				}
			}
			else
			{
				Singleton<CardsHandManager>.Instance.CurrentHand.ResetItemElements(messageData.m_Item);
			}
		}
		CPhase phase = PhaseManager.Phase;
		if (phase != null && phase.Type == CPhase.PhaseType.Action)
		{
			CAbility cAbility = ((CPhaseAction)phase).CurrentPhaseAbility?.m_Ability;
			if (messageData.m_Item.SlotState == CItem.EItemSlotState.Selected && cAbility != null && ((cAbility.AreaEffect != null && WorldspaceStarHexDisplay.Instance.IsAOELocked()) || (cAbility.ActorsToTarget != null && cAbility.ActorsToTarget.Count > 1)) && messageData.m_Item.SingleTarget == null && cAbility.ActiveSingleTargetItems.Contains(messageData.m_Item))
			{
				List<CCondition.ENegativeCondition> list = new List<CCondition.ENegativeCondition>();
				if (messageData.m_Item.YMLData.Data.Overrides != null)
				{
					foreach (CAbilityOverride @override in messageData.m_Item.YMLData.Data.Overrides)
					{
						if (@override != null && @override.NegativeConditions != null)
						{
							list.AddRange(@override.NegativeConditions);
						}
					}
				}
				if (messageData.m_Item.YMLData.Data.Abilities != null)
				{
					foreach (CAbility ability in messageData.m_Item.YMLData.Data.Abilities)
					{
						if (ability != null && ability.NegativeConditions != null)
						{
							list.AddRange(ability.NegativeConditions.Keys);
						}
					}
				}
				if (list.Count > 0)
				{
					StringBuilder stringBuilder = new StringBuilder();
					for (int num = 0; num < list.Count; num++)
					{
						if (num > 0)
						{
							stringBuilder.Append((num == list.Count - 1) ? " and " : ", ");
						}
						stringBuilder.AppendFormat("{0} <sprite name={1}>", list[num].ToString().ToUpper(), list[num]);
					}
					InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_ITEM_SINGLE_TARGET_TIP") + " " + LocalizationManager.GetTranslation("to") + " {0}", stringBuilder), messageData.m_Item);
				}
				else
				{
					InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_ITEM_SINGLE_TARGET_TIP"), messageData.m_Item);
				}
				readyButton.SetInteractable(interactable: false);
			}
			if (cAbility != null)
			{
				if (cAbility.AbilityType == CAbility.EAbilityType.LoseCards && m_CurrentActor is CPlayerActor)
				{
					int num2 = ((((CPlayerActor)m_CurrentActor).CharacterClass.HandAbilityCards.Count < cAbility.Strength) ? ((CPlayerActor)m_CurrentActor).CharacterClass.HandAbilityCards.Count : cAbility.Strength);
					InitiativeTrack.Instance.helpBox.ShowTranslated((num2 > 1) ? string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_LOSE_CARDS"), cAbility.Strength) : LocalizationManager.GetTranslation("GUI_TOOLTIP_SELECT_LOSE_CARD"));
				}
				else if (cAbility.AbilityType == CAbility.EAbilityType.DiscardCards && m_CurrentActor is CPlayerActor)
				{
					int num3 = ((((CPlayerActor)m_CurrentActor).CharacterClass.HandAbilityCards.Count < cAbility.Strength) ? ((CPlayerActor)m_CurrentActor).CharacterClass.HandAbilityCards.Count : cAbility.Strength);
					InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation((num3 > 1) ? "GUI_TOOLTIP_SELECT_DISCARD_CARDS" : "GUI_TOOLTIP_SELECT_DISCARD_CARD"), cAbility.Strength), string.Format(LocalizationManager.GetTranslation((num3 > 1) ? "GUI_TOOLTIP_SELECT_DISCARD_CARDS_TITLE" : "GUI_TOOLTIP_SELECT_DISCARD_CARD_TITLE"), cAbility.Strength));
				}
			}
		}
		else if (phase != null && phase.Type == CPhase.PhaseType.ActionSelection && m_CurrentActor is CPlayerActor cPlayerActor && cPlayerActor.CharacterClass.LongRest)
		{
			InitiativeTrack.Instance.helpBox.Show("GUI_TOOLTIP_LONG_REST", "GUI_LONG_REST");
		}
	}

	[MessageHandler(CMessageData.MessageType.OnItemAbilityUnstacked)]
	private void Handle_OnItemAbilityUnstacked(CMessageData message)
	{
		COnItemAbilityUnstacked_MessageData cOnItemAbilityUnstacked_MessageData = (COnItemAbilityUnstacked_MessageData)message;
		using (new CActiveBonus.ActiveBonusCalculationScope())
		{
			if (cOnItemAbilityUnstacked_MessageData.m_ItemAbility != null)
			{
				foreach (CActor item in cOnItemAbilityUnstacked_MessageData.m_ItemAbility.ValidActorsInRange)
				{
					ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(item)).m_WorldspacePanelUI?.PreviewEffects(cOnItemAbilityUnstacked_MessageData.m_ItemAbility, item, removePreview: true);
				}
			}
			if (!(PhaseManager.Phase is CPhaseAction { CurrentPhaseAbility: var currentPhaseAbility }))
			{
				return;
			}
			CAbility cAbility = currentPhaseAbility?.m_Ability;
			if (cAbility != null)
			{
				foreach (CActor item2 in cAbility.ValidActorsInRange)
				{
					ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(item2)).m_WorldspacePanelUI?.PreviewEffects(cAbility, item2);
				}
			}
			WorldspacePanelUIController.PreviewAugmentEffects();
		}
	}

