	[MessageHandler(CMessageData.MessageType.ActiveBonusDoomSlotChoice)]
	private void Handle_ActiveBonusDoomSlotChoice(CMessageData message)
	{
		CActiveBonusDoomSlotChoice_MessageData messageData = (CActiveBonusDoomSlotChoice_MessageData)message;
		int doomSlots = messageData.m_ActorSpawningMessage.DoomSlots;
		Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_CHOOSE_DOOM_DISCARD"), doomSlots), $"<color=#{UIInfoTools.Instance.GetCharacterHexColor(ECharacter.Doomstalker)}>{((messageData.m_ActorSpawningMessage.CachedAddDoomSlotActiveBonuses.Count == 0) ? null : messageData.m_ActorSpawningMessage.CachedAddDoomSlotActiveBonuses[0].BaseCard)}");
		Action onConfirmed = null;
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONNA, LocalizationManager.GetTranslation("GUI_END_SELECTION"));
		readyButton.AlternativeAction(() =>
		{
			m_UndoButton.ClearOnClickOverriders();
			m_SkipButton.ClearSkipAction();
			onConfirmed?.Invoke();
			Singleton<UIAbilityCardPicker>.Instance.Hide();
			ScenarioRuleClient.StepComplete();
		});
		readyButton.SetInteractable(interactable: false);
		Action undoAction = null;
		undoAction = () =>
		{
			Singleton<UIAbilityCardPicker>.Instance.ClearSelection();
			m_UndoButton.SetOnClickOverrider(undoAction, UndoButton.EButtonState.EUNDOBUTTONUNDO);
			m_UndoButton.SetInteractable(active: false);
		};
		m_UndoButton.Toggle(active: true);
		m_UndoButton.SetInteractable(active: false);
		m_UndoButton.SetOnClickOverrider(undoAction, UndoButton.EButtonState.EUNDOBUTTONUNDO);
		m_UndoButton.SetInteractable(active: false);
		SkipButton skipButton = m_SkipButton;
		Action onSkipAction = Singleton<UIAbilityCardPicker>.Instance.Hide;
		skipButton.Toggle(active: true, null, hideOnClick: true, null, onSkipAction);
		List<DoomPickerChoice> choices = messageData.m_ActorSpawningMessage.Dooms.Select((CDoom it) => new DoomPickerChoice(it, (CAbilityCard)messageData.m_ActorSpawningMessage.FindCardWithAbility(it.DoomAbilities[0]))).ToList();
		choices.Add(new DoomPickerChoice(messageData.m_NewDoom, (CAbilityCard)messageData.m_ActorSpawningMessage.FindCardWithAbility(messageData.m_NewDoom.DoomAbilities[0])));
		Singleton<UIAbilityCardPicker>.Instance.Show(messageData.m_ActorSpawningMessage, choices, doomSlots, (List<IAbilityCardOption> selectedDooms) =>
		{
			IAbilityCardOption replacedDoom = choices.Except(selectedDooms).SingleOrDefault();
			if (replacedDoom == null)
			{
				onConfirmed = null;
			}
			else
			{
				onConfirmed = () =>
				{
					messageData.m_ActorSpawningMessage.ReplaceDoom(messageData.m_NewDoom, ((DoomPickerChoice)replacedDoom).Doom, messageData.m_DoomTargetActor);
				};
			}
			m_UndoButton.SetInteractable(active: true);
			readyButton.SetInteractable(interactable: true);
		}, () =>
		{
			m_UndoButton.SetInteractable(active: false);
			readyButton.SetInteractable(interactable: false);
		});
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.DoomTransfering);
		}
	}

	[MessageHandler(CMessageData.MessageType.TransferDoomChoice)]
	private void Handle_TransferDoomChoice(CMessageData message)
	{
		CTransferDoomChoice_MessageData messageData = (CTransferDoomChoice_MessageData)message;
		if (messageData.m_TransferDoomAbility.Strength >= messageData.m_ActorSpawningMessage.Dooms.Count)
		{
			for (int i = 0; i < messageData.m_ActorSpawningMessage.Dooms.Count; i++)
			{
				messageData.m_ActorSpawningMessage.TransferDoom(messageData.m_ActorSpawningMessage.Dooms[i], messageData.m_NewDoomTargetActor);
			}
			ScenarioRuleClient.StepComplete();
			return;
		}
		Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_CHOOSE_DOOM_TRANSFER"), messageData.m_TransferDoomAbility);
		List<IAbilityCardOption> selectedChoices = null;
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONNA, LocalizationManager.GetTranslation("GUI_END_SELECTION"));
		readyButton.AlternativeAction(() =>
		{
			m_UndoButton.ClearOnClickOverriders();
			m_SkipButton.ClearSkipAction();
			for (int j = 0; j < selectedChoices.Count; j++)
			{
				messageData.m_ActorSpawningMessage.ReplaceDoom(((DoomPickerChoice)selectedChoices[j]).Doom, ((DoomPickerChoice)selectedChoices[j]).Doom, messageData.m_NewDoomTargetActor);
			}
			Singleton<UIAbilityCardPicker>.Instance.Hide();
			ScenarioRuleClient.StepComplete();
		});
		readyButton.SetInteractable(interactable: false);
		m_UndoButton.Toggle(active: true);
		m_UndoButton.SetInteractable(active: false);
		Action undoAction = null;
		undoAction = () =>
		{
			Singleton<UIAbilityCardPicker>.Instance.ClearSelection();
			m_UndoButton.SetOnClickOverrider(undoAction, UndoButton.EButtonState.EUNDOBUTTONUNDO);
			m_UndoButton.SetInteractable(active: false);
		};
		m_UndoButton.SetOnClickOverrider(undoAction, UndoButton.EButtonState.EUNDOBUTTONUNDO);
		m_UndoButton.SetInteractable(active: false);
		m_SkipButton.Toggle(active: true, null, hideOnClick: true, null, () =>
		{
			Singleton<UIAbilityCardPicker>.Instance.Hide();
			for (int j = 0; j < Mathf.Min(messageData.m_ActorSpawningMessage.Dooms.Count, messageData.m_TransferDoomAbility.Strength); j++)
			{
				messageData.m_ActorSpawningMessage.ReplaceDoom(messageData.m_ActorSpawningMessage.Dooms[j], messageData.m_ActorSpawningMessage.Dooms[j], messageData.m_NewDoomTargetActor);
			}
		});
		List<DoomPickerChoice> options = messageData.m_ActorSpawningMessage.Dooms.Select((CDoom it) => new DoomPickerChoice(it, (CAbilityCard)messageData.m_ActorSpawningMessage.FindCardWithAbility(it.DoomAbilities[0]))).ToList();
		Singleton<UIAbilityCardPicker>.Instance.Show(messageData.m_ActorSpawningMessage, options, messageData.m_TransferDoomAbility.Strength, (List<IAbilityCardOption> selectedDooms) =>
		{
			selectedChoices = selectedDooms;
			m_UndoButton.SetInteractable(active: true);
			readyButton.SetInteractable(interactable: true);
		}, () =>
		{
			selectedChoices = null;
			m_UndoButton.SetInteractable(active: false);
			readyButton.SetInteractable(interactable: false);
		});
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.DoomTransfering);
		}
	}

	[MessageHandler(CMessageData.MessageType.RefreshWorldSpaceStarHexDisplay)]
