	[MessageHandler(CMessageData.MessageType.ActorEarnedXP)]
	private void Handle_ActorEarnedXP(CMessageData message)
	{
		if (m_ActorsKilledThisAbility.Count > 0)
		{
			m_MessagesAfterKilledActors.Add(message);
			return;
		}
		CActorEarnedXP_MessageData messageData = (CActorEarnedXP_MessageData)message;
		if (messageData.m_ActorSpawningMessage.Type != CActor.EType.Player)
		{
			return;
		}
		if (ScenarioManager.Scenario.HasActor(messageData.m_ActorSpawningMessage))
		{
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(message.m_ActorSpawningMessage));
			if (actorBehaviour != null)
			{
				actorBehaviour.m_WorldspacePanelUI?.OnEarnedXP(messageData.m_xpAmount);
			}
		}
		CActor actorSpawningMessage = message.m_ActorSpawningMessage;
		string arg = LocalizationManager.GetTranslation(actorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorSpawningMessage);
		Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_XP"), arg, messageData.m_xpAmount), CombatLogFilter.ABILITIES);
		int num = 0;
		int num2 = 0;
		try
		{
			if (SaveData.Instance.Global.GameMode == EGameMode.Campaign)
			{
				int? num3 = SaveData.Instance.Global.CurrentAdventureData?.AdventureMapState?.MapParty.SelectedCharacters.ToList().SingleOrDefault((CMapCharacter x) => x.CharacterID == messageData.m_ActorSpawningMessage.Class.ID)?.EXP;
				if (num3.HasValue)
				{
					num2 = num3.Value;
				}
			}
			num2 += messageData.m_scenarioXP;
			num = num2 - messageData.m_xpAmount;
		}
		catch (Exception exception)
		{
			Log.Exception(exception, "Exception calculating XP.");
		}
		Log.SimpleInfo($"{arg} XP Change: {num} -> {num2}");
	}

