	[MessageHandler(CMessageData.MessageType.SpawnerSpawningUnit)]
	private void Handle_SpawnerSpawningUnit(CMessageData message)
	{
		CSpawnerSpawningUnit_MessageData messageData = (CSpawnerSpawningUnit_MessageData)message;
		StartCoroutine(SpawnerSpawningUnit(messageData));
	}

	private IEnumerator SpawnerSpawningUnit(CSpawnerSpawningUnit_MessageData messageData)
	{
		if (messageData.m_SpawnDelay > 0)
		{
			using (WaitPendingAnimationScope(messageData))
			{
				yield return Timekeeper.instance.WaitForSeconds(messageData.m_SpawnDelay);
			}
		}
		CEnemyActor spawnEnemy = messageData.m_SpawnEnemy;
		string text = LocalizationManager.GetTranslation(spawnEnemy.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(spawnEnemy);
		if (!FindClientEnemy(spawnEnemy))
		{
			CClientTile tile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[messageData.m_SpawnTile.m_ArrayIndex.X, messageData.m_SpawnTile.m_ArrayIndex.Y];
			GameObject gameObject = s_Choreographer.CreateCharacterActor(tile, spawnEnemy, messageData.m_TreatAsSummon);
			if (!(gameObject != null))
			{
				Log.Error("Unable to create character actorOriginallyAttacked object");
				throw new Exception();
			}
			if (spawnEnemy is CObjectActor)
			{
				s_Choreographer.m_ClientObjects.Add(gameObject);
			}
			else if (spawnEnemy.Type == CActor.EType.Enemy)
			{
				s_Choreographer.m_ClientEnemies.Add(gameObject);
			}
			else if (spawnEnemy.Type == CActor.EType.HeroSummon)
			{
				s_Choreographer.m_ClientHeroSummons.Add(gameObject);
			}
			else if (spawnEnemy.Type == CActor.EType.Ally)
			{
				s_Choreographer.m_ClientAllyMonsters.Add(gameObject);
			}
			else if (spawnEnemy.Type == CActor.EType.Enemy2)
			{
				s_Choreographer.m_ClientEnemy2Monsters.Add(gameObject);
			}
			else if (spawnEnemy.Type == CActor.EType.Neutral)
			{
				s_Choreographer.m_ClientNeutralMonsters.Add(gameObject);
			}
			s_Choreographer.SetCharacterPositions();
			if (ActorBehaviour.GetActorBehaviour(gameObject) == null)
			{
				Log.ErrorFormat("Unable to find actorOriginallyAttacked behaviour for spawned character actorOriginallyAttacked object {0}", text);
			}
		}
		if (messageData.m_SpawnSource != null)
		{
			string arg = LocalizationManager.GetTranslation(messageData.m_SpawnSource.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(messageData.m_SpawnSource);
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_SUMMON"), arg, text), CombatLogFilter.ABILITIES);
		}
		else
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_SPAWNER_SPAWNED"), text), CombatLogFilter.ABILITIES);
		}
	}

	[MessageHandler(CMessageData.MessageType.PhaseOut)]
	private void Handle_PhaseOut(CMessageData message)
	{
		CPhaseOut_MessageData cPhaseOut_MessageData = (CPhaseOut_MessageData)message;
		CActor actor = cPhaseOut_MessageData.m_Actor;
		_ = LocalizationManager.GetTranslation(actor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actor);
		GameObject gameObject = FindClientActorGameObject(actor);
		gameObject.transform.SetParent(null);
		ActorBehaviour.GetActorBehaviour(gameObject)?.m_WorldspacePanelUI?.Destroy();
		if (cPhaseOut_MessageData.m_PhaseOutInstantly)
		{
			CharacterManager characterManager = CharacterManager.GetCharacterManager(gameObject);
			m_ClientPlayers.Remove(gameObject);
			m_ClientEnemies.Remove(gameObject);
			m_ClientHeroSummons.Remove(gameObject);
			m_ClientAllyMonsters.Remove(gameObject);
			m_ClientEnemy2Monsters.Remove(gameObject);
			m_ClientNeutralMonsters.Remove(gameObject);
			m_ClientObjects.Remove(gameObject);
			AllActorsInScene.Remove(gameObject);
			s_Choreographer.FirstAbility = false;
			if (characterManager != null)
			{
				CharacterOutlineRegistration(characterManager, register: false);
				characterManager.DeinitializeCharacter();
			}
		}
		else
		{
			Handle_ActorDead(new CActorDead_MessageData(actor)
			{
				m_Actor = actor,
				m_DontLog = true
			});
		}
	}

	[MessageHandler(CMessageData.MessageType.PhaseIn)]
	private void Handle_PhaseIn(CMessageData message)
	{
		CPhaseIn_MessageData cPhaseIn_MessageData = (CPhaseIn_MessageData)message;
		CActor actor = cPhaseIn_MessageData.m_Actor;
		GameObject gameObject = FindClientActorGameObject(actor);
		string text = LocalizationManager.GetTranslation(actor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actor);
		if (gameObject != null)
		{
			m_ClientDeadActors.Remove(gameObject);
		}
		else
		{
			CClientTile tile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cPhaseIn_MessageData.m_Tile.m_ArrayIndex.X, cPhaseIn_MessageData.m_Tile.m_ArrayIndex.Y];
			gameObject = s_Choreographer.CreateCharacterActor(tile, actor);
			if (!(gameObject != null))
			{
				Log.Error("Unable to create character actorOriginallyAttacked object");
				throw new Exception();
			}
			if (actor is CPlayerActor)
			{
				s_Choreographer.m_ClientPlayers.Add(gameObject);
			}
			else if (actor is CHeroSummonActor)
			{
				s_Choreographer.m_ClientHeroSummons.Add(gameObject);
			}
			else if (actor is CEnemyActor { OriginalType: CActor.EType.Enemy })
			{
				s_Choreographer.m_ClientEnemies.Add(gameObject);
			}
			else
			{
				s_Choreographer.m_ClientAllyMonsters.Add(gameObject);
			}
			s_Choreographer.SetCharacterPositions();
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
			if (actorBehaviour == null)
			{
				Log.ErrorFormat("Unable to find actorOriginallyAttacked behaviour for spawned character actorOriginallyAttacked object {0}", text);
			}
			else
			{
				actorBehaviour.StopLoco(null);
			}
		}
		if (InitiativeTrack.Instance.FindInitiativeTrackActor(cPhaseIn_MessageData.m_Actor) == null)
		{
			GameState.SortIntoInitiativeAndIDOrder();
		}
		InitiativeTrack.Refresh(cPhaseIn_MessageData.m_Actor, isActiveButton: true);
	}

	[MessageHandler(CMessageData.MessageType.ShiftingForm)]
	private void Handle_ShiftingForm(CMessageData message)
	{
		CShiftingForm_MessageData cShiftingForm_MessageData = (CShiftingForm_MessageData)message;
		GameObject gameObject = FindClientActorGameObject(cShiftingForm_MessageData.m_Actor);
		if (!(gameObject == null))
		{
			CActor animatingActorToWaitFor = cShiftingForm_MessageData.m_Actor;
			ProcessActorAnimation(null, cShiftingForm_MessageData.m_Actor, new List<string> { "Switch" }, out var animationShouldPlay, out animatingActorToWaitFor);
			if (animatingActorToWaitFor != null)
			{
				SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
			}
			if (!animationShouldPlay)
			{
				ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ShiftForm)]
	private void Handle_ShiftForm(CMessageData message)
	{
		CShiftForm_MessageData cShiftForm_MessageData = (CShiftForm_MessageData)message;
		CEnemyActor actor = cShiftForm_MessageData.m_Actor;
		string text = LocalizationManager.GetTranslation(actor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actor);
		GameObject gameObject = null;
		GameObject gameObject2 = FindClientEnemy(actor);
		gameObject2.transform.SetParent(null);
		m_ClientPlayers.Remove(gameObject2);
		m_ClientEnemies.Remove(gameObject2);
		m_ClientHeroSummons.Remove(gameObject2);
		m_ClientAllyMonsters.Remove(gameObject2);
		m_ClientEnemy2Monsters.Remove(gameObject2);
		m_ClientNeutralMonsters.Remove(gameObject2);
		m_ClientObjects.Remove(gameObject2);
		AllActorsInScene.Remove(gameObject2);
		ActorBehaviour.GetActorBehaviour(gameObject2)?.m_WorldspacePanelUI?.Destroy();
		CharacterManager characterManager = CharacterManager.GetCharacterManager(gameObject2);
		CharacterOutlineRegistration(characterManager, register: false);
		characterManager.DeinitializeCharacter();
		ObjectPool.Recycle(gameObject2, characterManager.CharacterPrefab);
		if (!FindClientEnemy(actor))
		{
			CClientTile tile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cShiftForm_MessageData.m_Tile.m_ArrayIndex.X, cShiftForm_MessageData.m_Tile.m_ArrayIndex.Y];
			gameObject = s_Choreographer.CreateCharacterActor(tile, actor);
			if (!(gameObject != null))
			{
				Log.Error("Unable to create character actorOriginallyAttacked object");
				throw new Exception();
			}
			s_Choreographer.m_ClientEnemies.Add(gameObject);
			s_Choreographer.SetCharacterPositions();
			if (ActorBehaviour.GetActorBehaviour(gameObject) == null)
			{
				Log.ErrorFormat("Unable to find actorOriginallyAttacked behaviour for spawned character actorOriginallyAttacked object {0}", text);
			}
		}
		if (InitiativeTrack.Instance.FindInitiativeTrackActor(cShiftForm_MessageData.m_Actor) == null)
		{
			GameState.SortIntoInitiativeAndIDOrder();
		}
		InitiativeTrack.Refresh(cShiftForm_MessageData.m_Actor, isActiveButton: true);
		Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_SHIFT_FORM"), text), CombatLogFilter.ABILITIES);
		CActor animatingActorToWaitFor = cShiftForm_MessageData.m_Actor;
		ProcessActorAnimation(null, cShiftForm_MessageData.m_Actor, new List<string> { "SwitchEnd" }, out var animationShouldPlay, out animatingActorToWaitFor);
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
		}
	}

	[MessageHandler(CMessageData.MessageType.PlayerActorChangedForm)]
	private void Handle_PlayerActorChangedForm(CMessageData message)
	{
		CPlayerActorChangedForm_MessageData cPlayerActorChangedForm_MessageData = (CPlayerActorChangedForm_MessageData)message;
		CPlayerActor cPlayerActor = cPlayerActorChangedForm_MessageData.m_PlayerActor as CPlayerActor;
		if (cPlayerActor == null)
		{
			cPlayerActor = cPlayerActorChangedForm_MessageData.m_PlayerActor?.GetMirrorActor(includeMirroredClone: true) as CPlayerActor;
		}
		if (cPlayerActor.Class.ID == "GeminateID" && (cPlayerActorChangedForm_MessageData.m_NewForm == CPlayerActor.EForm.Melee || cPlayerActorChangedForm_MessageData.m_NewForm == CPlayerActor.EForm.Range))
		{
			_ = cPlayerActorChangedForm_MessageData.m_NewForm;
			_ = 2;
			GameObject gameObject = FindClientActor(cPlayerActorChangedForm_MessageData.m_PlayerActor);
			if (gameObject == null)
			{
				cPlayerActorChangedForm_MessageData.Processed = true;
				return;
			}
			CameraController.s_CameraController.SmartFocus(gameObject, pauseDuringTransition: true);
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
			ChangeActorForm(actorBehaviour, cPlayerActorChangedForm_MessageData.m_NewForm, cPlayerActorChangedForm_MessageData.m_Instant);
		}
		cPlayerActorChangedForm_MessageData.Processed = true;
	}

	private void ChangeActorForm(ActorBehaviour actorBehaviour, CPlayerActor.EForm form, bool instant)
	{
		if (!(actorBehaviour == null))
		{
			int index = ((form != CPlayerActor.EForm.Melee) ? 1 : 0);
			actorBehaviour.SwitchBody(index, instant);
		}
	}

	[MessageHandler(CMessageData.MessageType.PlayerActorChangedPendingForm)]
	private void Handle_PlayerActorChangedPendingForm(CMessageData message)
	{
		CPlayerActorChangedPendingForm_MessageData cPlayerActorChangedPendingForm_MessageData = (CPlayerActorChangedPendingForm_MessageData)message;
		if (cPlayerActorChangedPendingForm_MessageData.m_PlayerActor.Class.ID == "GeminateID" && (cPlayerActorChangedPendingForm_MessageData.m_PendingForm == CPlayerActor.EForm.Melee || cPlayerActorChangedPendingForm_MessageData.m_PendingForm == CPlayerActor.EForm.Range) && (ScenarioManager.CurrentScenarioState.RoundNumber == 1 || cPlayerActorChangedPendingForm_MessageData.m_CurrentForm == CPlayerActor.EForm.Choose) && PhaseManager.IsInCardsSelectionPhase)
		{
			int index = ((cPlayerActorChangedPendingForm_MessageData.m_PendingForm != CPlayerActor.EForm.Melee) ? 1 : 0);
			GameObject gameObject = FindClientActor(cPlayerActorChangedPendingForm_MessageData.m_PlayerActor);
			if (!(gameObject == null))
			{
				ActorBehaviour.GetActorBehaviour(gameObject).SwitchBody(index, instant: true);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.RebuildProceduralLevel)]
	private void Handle_RebuildProceduralLevel(CMessageData message)
	{
		LevelEditorController.RegenerateApparance();
	}

	[MessageHandler(CMessageData.MessageType.ToggleTileHighlights)]
	private void Handle_ToggleTileHighlights(CMessageData message)
	{
		CToggleTileHighlights_MessageData cToggleTileHighlights_MessageData = (CToggleTileHighlights_MessageData)message;
		List<Tuple<CClientTile, Color?>> genericHighlightedTiles = ClientScenarioManager.s_ClientScenarioManager.GenericHighlightedTiles;
		Color? color = null;
		if (cToggleTileHighlights_MessageData.Color != null)
		{
			CVector4 color2 = cToggleTileHighlights_MessageData.Color;
			color = new Color(color2.X, color2.Y, color2.Z, color2.W);
		}
		foreach (Point tileIndex in cToggleTileHighlights_MessageData.TileIndices)
		{
			CClientTile tile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[tileIndex.X, tileIndex.Y];
			if (cToggleTileHighlights_MessageData.Enabled && tile != null)
			{
				if (genericHighlightedTiles.FindIndex((Tuple<CClientTile, Color?> x) => x.Item1 == tile) >= 0)
				{
					genericHighlightedTiles.RemoveAll((Tuple<CClientTile, Color?> x) =>
					{
						if (x.Item1 == tile)
						{
							Color? item = x.Item2;
							Color? color3 = color;
							if (item.HasValue != color3.HasValue)
							{
								return false;
							}
							if (!item.HasValue)
							{
								return true;
							}
							return item.GetValueOrDefault() == color3.GetValueOrDefault();
						}
						return false;
					});
				}
				genericHighlightedTiles.Add(new Tuple<CClientTile, Color?>(tile, color));
				if (cToggleTileHighlights_MessageData.StandingHighlights)
				{
					InteractabilityHighlightCanvas.s_Instance?.TryAddHighlightToTile(new TileIndex(tileIndex), "Yellow");
				}
			}
			else
			{
				if (cToggleTileHighlights_MessageData.Enabled || tile == null)
				{
					continue;
				}
				genericHighlightedTiles.RemoveAll((Tuple<CClientTile, Color?> x) =>
				{
					if (x.Item1 == tile)
					{
						Color? item = x.Item2;
						Color? color3 = color;
						if (item.HasValue != color3.HasValue)
						{
							return false;
						}
						if (!item.HasValue)
						{
							return true;
						}
						return item.GetValueOrDefault() == color3.GetValueOrDefault();
					}
					return false;
				});
				if (cToggleTileHighlights_MessageData.StandingHighlights)
				{
					InteractabilityHighlightCanvas.s_Instance?.TryRemoveHighlightFromTile(new TileIndex(tileIndex));
				}
			}
		}
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
	}

	[MessageHandler(CMessageData.MessageType.ToggleTileLinks)]
	private void Handle_ToggleTileLinks(CMessageData message)
	{
		CToggleTileLinks_MessageData cToggleTileLinks_MessageData = (CToggleTileLinks_MessageData)message;
		List<(CClientTile, CClientTile)> genericHighlightedLinks = ClientScenarioManager.s_ClientScenarioManager.GenericHighlightedLinks;
		foreach (var link in cToggleTileLinks_MessageData.Links)
		{
			Point item = link.Item1;
			Point item2 = link.Item2;
			CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item.X, item.Y];
			CClientTile cClientTile2 = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[item2.X, item2.Y];
			if (cClientTile != null && cClientTile2 != null)
			{
				if (cToggleTileLinks_MessageData.Enabled && !genericHighlightedLinks.Contains((cClientTile, cClientTile2)))
				{
					genericHighlightedLinks.Add((cClientTile, cClientTile2));
				}
				else if (!cToggleTileLinks_MessageData.Enabled)
				{
					genericHighlightedLinks.Remove((cClientTile, cClientTile2));
				}
			}
		}
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
	}

	[MessageHandler(CMessageData.MessageType.SpawnObject)]
	private void Handle_SpawnObject(CMessageData message)
	{
		CSpawnObject_MessageData messageData = (CSpawnObject_MessageData)message;
		StartCoroutine(SpawnObject(messageData));
	}

	private IEnumerator SpawnObject(CSpawnObject_MessageData messageData)
	{
		if (messageData.m_SpawnDelay > 0f)
		{
			using (WaitPendingAnimationScope(messageData))
			{
				yield return Timekeeper.instance.WaitForSeconds(messageData.m_SpawnDelay);
			}
		}
		string objectId = messageData.m_ObjectID;
		CActor.EType enemyType = messageData.m_enemyType;
		int level = messageData.m_Level;
		CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[messageData.m_Tile.m_ArrayIndex.X, messageData.m_Tile.m_ArrayIndex.Y];
		CObjectClass cObjectClass = MonsterClassManager.ObjectClasses.SingleOrDefault((CObjectClass x) => x.ID == objectId);
		cObjectClass.SetMonsterStatLevel(level);
		int nextID = cObjectClass.GetNextID();
		int num;
		for (num = nextID; num > cObjectClass.Models.Count - 1; num -= cObjectClass.Models.Count)
		{
		}
		ObjectState objectState = new ObjectState(cObjectClass.ID, num, null, cClientTile.m_Tile.m_HexMap.MapGuid, new TileIndex(cClientTile.m_Tile.m_ArrayIndex), cObjectClass.Health(), cObjectClass.Health(), level, new List<PositiveConditionPair>(), new List<NegativeConditionPair>(), playedThisRound: true, CActor.ECauseOfDeath.StillAlive, isSummon: false, null, 1, enemyType);
		objectState.ID = nextID;
		CObjectActor objectActor = ScenarioManager.Scenario.AddObject(objectState, initial: false);
		ScenarioManager.CurrentScenarioState.Objects.Add(objectState);
		objectState.IsRevealed = cClientTile.m_Tile.m_HexMap.Revealed;
		s_Choreographer.m_ClientObjects.Add(s_Choreographer.CreateCharacterActor(cClientTile, ScenarioManager.Scenario.Objects.Last()));
		s_Choreographer.SetCharacterPositions();
		if (messageData.m_PropToAlignTo != null)
		{
			yield return null;
			GameObject gameObject = FindClientActorGameObject(messageData.m_PropToAlignTo.RuntimeAttachedActor, shouldReturnDummyActorsProp: true);
			GameObject gameObject2 = FindClientActorGameObject(objectActor, shouldReturnDummyActorsProp: true);
			if ((bool)gameObject && (bool)gameObject2)
			{
				GameObject gameObject3 = gameObject.FindInChildren("Generated Content");
				if ((bool)gameObject3)
				{
					Transform child = gameObject3.transform.GetChild(0);
					gameObject2.transform.rotation = child.rotation;
				}
			}
		}
		ScenarioManager.CurrentScenarioState.Update();
	}

	[MessageHandler(CMessageData.MessageType.ScenarioDamage)]
	private void Handle_ScenarioDamage(CMessageData message)
	{
		CScenarioDamage_MessageData cScenarioDamage_MessageData = (CScenarioDamage_MessageData)message;
		if (cScenarioDamage_MessageData.m_DamageSourceLocKey != null)
		{
			string translation = LocalizationManager.GetTranslation(cScenarioDamage_MessageData.m_DamageSourceLocKey);
			string arg = LocalizationManager.GetTranslation(cScenarioDamage_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cScenarioDamage_MessageData.m_ActorSpawningMessage);
			int? num = cScenarioDamage_MessageData.m_DamageAmount;
			if (cScenarioDamage_MessageData.m_OverrideLogMessageLocKey != null)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(cScenarioDamage_MessageData.m_OverrideLogMessageLocKey), arg, $"<b><color=#f76767>{num}</color></b>", translation), CombatLogFilter.DAMAGE);
				return;
			}
			CombatLogHandler instance = Singleton<CombatLogHandler>.Instance;
			string translation2 = LocalizationManager.GetTranslation("COMBAT_LOG_SCENARIO_DAMAGE_TARGET");
			int? num2 = num;
			instance.AddLog(string.Format(translation2, arg, string.Format("<b><color=#f76767>{0}</color></b>", num2 + " " + LocalizationManager.GetTranslation("Damage").ToLower()), translation), CombatLogFilter.DAMAGE);
		}
		else
		{
			int? num3 = cScenarioDamage_MessageData.m_DamageAmount;
			if (num3.HasValue)
			{
				string attackingName = LocalizationManager.GetTranslation(cScenarioDamage_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cScenarioDamage_MessageData.m_ActorSpawningMessage);
				string targetName = LocalizationManager.GetTranslation(cScenarioDamage_MessageData.m_ActorSpawningMessage.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(cScenarioDamage_MessageData.m_ActorSpawningMessage);
				LogDamage(num3.Value, targetName, attackingName, cScenarioDamage_MessageData.m_TreatAsScenarioEffect, cScenarioDamage_MessageData.m_TreatAsScenarioRule, cScenarioDamage_MessageData.m_TreatAsEventEffect);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ShowAugmentationBar)]
	private void Handle_ShowAugmentationBar(CMessageData message)
	{
		CShowAugmentationBar_MessageData cShowAugmentationBar_MessageData = (CShowAugmentationBar_MessageData)message;
		CActor actorSpawningMessage = cShowAugmentationBar_MessageData.m_ActorSpawningMessage;
		CAbility ability = cShowAugmentationBar_MessageData.m_Ability;
		if (actorSpawningMessage.Tokens.HasKey(CCondition.ENegativeCondition.Stun))
		{
			AbilityData.MiscAbilityData miscAbilityData = ability.MiscAbilityData;
			if (miscAbilityData == null || miscAbilityData.IgnoreStun != true)
			{
				return;
			}
		}
		ShowAugmentationBar = true;
		if (ability.AbilityType != CAbility.EAbilityType.Attack || (ability.MeetsStartAbilityRequirements(actorSpawningMessage) && !ability.StoppedByDisarm()))
		{
			CardsActionControlller.s_Instance.RefreshConsumeBar(actorSpawningMessage, ability, WaitingForConfirm);
			WaitingForConfirm = false;
		}
	}

	[MessageHandler(CMessageData.MessageType.ShowForgoActiveBonus)]
	private void Handle_ShowForgoActiveBonus(CMessageData message)
	{
		CShowForgoActiveBonusBar_MessageData messageData = (CShowForgoActiveBonusBar_MessageData)message;
		m_CurrentActor = messageData.m_ActorSpawningMessage;
		if (FFSNetwork.IsOnline && m_CurrentActor is CPlayerActor)
		{
			InitiativeTrack.Instance.PlayersUI.ForEach((InitiativeTrackPlayerBehaviourExtension f) =>
			{
				f.Base.Avatar.RefreshActiveInteractable();
			});
		}
		if (CurrentPlayerActor == null)
		{
			Singleton<ScenarioInfoModule>.Instance.HideBattleGoals();
		}
		else
		{
			Singleton<ScenarioInfoModule>.Instance.ShowBattleGoals(CurrentPlayerActor);
		}
		Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_FORGO_ACTIONS_FOR_COMPANION", messageData.m_Ability);
		Singleton<UIActiveBonusBar>.Instance.ShowActiveBonus(messageData.m_ActorSpawningMessage, CAbility.EAbilityType.ForgoActionsForCompanion, CActiveBonus.EActiveBonusBehaviourType.None, (CActiveBonus bonus, bool selected) =>
		{
			bool flag = s_Choreographer.ActorOrHisSummonerIsUnderMyControl(messageData.m_ActorSpawningMessage);
			if (FFSNetwork.IsOnline & flag)
			{
				UIUseActiveBonus slotForActiveBonus = Singleton<UIActiveBonusBar>.Instance.GetSlotForActiveBonus(bonus);
				List<ElementInfusionBoardManager.EElement> list = (selected ? slotForActiveBonus.GetSelectedConsumes() : null);
				Synchronizer.SendGameAction(GameActionType.ClickActiveBonusSlot, ActionProcessor.CurrentPhase, validateOnServerBeforeExecuting: false, disableAutoReplication: false, messageData.m_ActorSpawningMessage.ID, 0, 0, 0, supplementaryDataBoolean: false, null, new ActiveBonusToken(bonus, selected, list.IsNullOrEmpty() ? ((ElementInfusionBoardManager.EElement?)null) : new ElementInfusionBoardManager.EElement?(list[0]), slotForActiveBonus.SelectedOptions));
			}
			readyButton.AlternativeAction(() =>
			{
				readyButton.ClearAlternativeAction();
				m_UndoButton.ClearOnClickOverriders();
				Singleton<UIActiveBonusBar>.Instance.Hide();
				Singleton<CardsHandManager>.Instance.Hide();
				(bonus as CForgoActionsForCompanionActiveBonus).ApplyToggledActiveBonusesToCompanionSummon();
				ScenarioRuleClient.StepComplete();
			}, ReadyButton.EButtonState.EREADYBUTTONCONFIRM);
			readyButton.SetInteractable(selected);
			m_UndoButton.SetInteractable(selected);
		});
		m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"));
		m_SkipButton.SetInteractable(active: true);
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED, LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION"), hideOnClick: true, glowingEffect: true);
		Action undo = null;
		undo = () =>
		{
			Singleton<UIActiveBonusBar>.Instance.UndoSelection();
			readyButton.SetInteractable(interactable: false);
			m_UndoButton.SetInteractable(active: false);
			m_UndoButton.SetOnClickOverrider(undo, UndoButton.EButtonState.EUNDOBUTTONUNDO);
			m_UndoButton.SetInteractable(active: false);
		};
		m_UndoButton.Toggle(active: true, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
		m_UndoButton.SetInteractable(active: false);
		m_UndoButton.SetOnClickOverrider(undo, UndoButton.EButtonState.EUNDOBUTTONUNDO);
		m_UndoButton.SetInteractable(active: false);
		if (FFSNetwork.IsOnline)
		{
			if (!m_CurrentActor.IsUnderMyControl())
			{
				ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.ForgoActionForBoost);
			}
			else
			{
				ActionProcessor.SetState(ActionProcessorStateType.Halted, ActionPhaseType.ForgoActionForBoost);
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.FinishedProcessingTileSelected)]
	private void Handle_FinishedProcessingTileSelected(CMessageData message)
	{
		CFinishedProcessingTileSelected_MessageData cFinishedProcessingTileSelected_MessageData = (CFinishedProcessingTileSelected_MessageData)message;
		if (cFinishedProcessingTileSelected_MessageData.m_Ability.AutoTrigger && cFinishedProcessingTileSelected_MessageData.m_Ability.CanBePerformed())
		{
			return;
		}
		if (PhaseManager.Phase.Type == CPhase.PhaseType.Action && ((CPhaseAction)PhaseManager.Phase).CurrentPhaseAbility != null)
		{
			readyButton.SetInteractable(cFinishedProcessingTileSelected_MessageData.m_Ability.RequiresWaypointSelection() ? (Waypoint.s_Waypoints.Count > 0) : (cFinishedProcessingTileSelected_MessageData.m_Ability.EnoughTargetsSelected() && cFinishedProcessingTileSelected_MessageData.m_Ability.CanBePerformed()));
			m_UndoButton.SetInteractable(cFinishedProcessingTileSelected_MessageData.m_Ability.CanUndo && (FirstAbility || cFinishedProcessingTileSelected_MessageData.m_Ability.AllowUndoAfterFirst));
			m_SkipButton.SetInteractable(cFinishedProcessingTileSelected_MessageData.m_Ability.CanSkip);
			if (cFinishedProcessingTileSelected_MessageData.m_Ability.AreaEffect != null || cFinishedProcessingTileSelected_MessageData.m_Ability.AreaEffectBackup != null)
			{
				if (!WorldspaceStarHexDisplay.Instance.IsAOELocked() && (cFinishedProcessingTileSelected_MessageData.m_Ability.ValidActorsInRange.Count > 0 || cFinishedProcessingTileSelected_MessageData.m_Ability.TilesSelected.Count > 0 || (cFinishedProcessingTileSelected_MessageData.m_Ability.ActorsToTarget != null && cFinishedProcessingTileSelected_MessageData.m_Ability.ActorsToTarget.Count > 0)) && cFinishedProcessingTileSelected_MessageData.m_AreaEffectLocked && (!cFinishedProcessingTileSelected_MessageData.m_Ability.RequiresAllyTargeting() || cFinishedProcessingTileSelected_MessageData.m_Ability.ValidAlliesTargeted()))
				{
					AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
					m_UndoButton.Toggle(active: true, UndoButton.EButtonState.EUNDOBUTTONCLEARTARGETS, LocalizationManager.GetTranslation("GUI_CLEARTARGETS"));
					m_SkipButton.SetInteractable(active: false);
					WorldspaceStarHexDisplay.Instance.SetAOELocked(locked: true);
					bool flag = !cFinishedProcessingTileSelected_MessageData.m_Ability.RequiresAllyTargeting() || cFinishedProcessingTileSelected_MessageData.m_Ability.ValidAlliesTargeted();
					if (flag && cFinishedProcessingTileSelected_MessageData.m_Ability.RequiresAnySelectedTileToBeAdjacentToCaster())
					{
						List<CTile> adjacentTiles = new List<CTile>();
						GameState.GetAdjacentTiles(cFinishedProcessingTileSelected_MessageData.m_Ability.TargetingActor.ArrayIndex, adjacentTiles);
						flag = cFinishedProcessingTileSelected_MessageData.m_Ability.TilesSelected.Any((CTile x) => adjacentTiles.Contains(x));
					}
					readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONFIRMTARGETS, LocalizationManager.GetTranslation("GUI_CONFIRM_TARGETS"), hideOnClick: true, glowingEffect: true, flag);
					if (cFinishedProcessingTileSelected_MessageData.m_Ability.ActorsToTarget != null && cFinishedProcessingTileSelected_MessageData.m_Ability.MaxTargetsSelected())
					{
						foreach (GameObject clientActorObject in ClientActorObjects)
						{
							ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(clientActorObject);
							if (!cFinishedProcessingTileSelected_MessageData.m_Ability.ActorsToTarget.Contains(actorBehaviour.Actor))
							{
								actorBehaviour.m_WorldspacePanelUI?.ResetPreview();
							}
						}
					}
				}
				else
				{
					AudioControllerUtils.PlaySound(UIInfoTools.Instance.InvalidOptionAudioItem);
				}
			}
			else
			{
				CClientTile clientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cFinishedProcessingTileSelected_MessageData.m_SelectedTile.m_ArrayIndex.X, cFinishedProcessingTileSelected_MessageData.m_SelectedTile.m_ArrayIndex.Y];
				bool flag2 = WorldspaceStarHexDisplay.Instance.CurrentNumberSelectedTargets() > 0;
				if ((!cFinishedProcessingTileSelected_MessageData.m_Ability.AbilityFilter.HasTargetTypeFlag(CAbilityFilter.EFilterTargetType.Self, exclusive: true) & flag2) && (!cFinishedProcessingTileSelected_MessageData.m_Ability.AllTargets || FirstAbility))
				{
					bool flag3 = cFinishedProcessingTileSelected_MessageData.m_Ability.CanUndo && FirstAbility;
					bool flag4 = cFinishedProcessingTileSelected_MessageData.m_Ability.CanClearTargets();
					if ((!cFinishedProcessingTileSelected_MessageData.m_Ability.IsInlineSubAbility && !cFinishedProcessingTileSelected_MessageData.m_Ability.UseSubAbilityTargeting) | flag4)
					{
						m_UndoButton.Toggle(flag3 || (flag4 & flag2), (!cFinishedProcessingTileSelected_MessageData.m_Ability.AllTargets && flag4) ? UndoButton.EButtonState.EUNDOBUTTONCLEARTARGETS : UndoButton.EButtonState.EUNDOBUTTONUNDO, (cFinishedProcessingTileSelected_MessageData.m_Ability.AllTargets || !flag4) ? LocalizationManager.GetTranslation("GUI_UNDO") : LocalizationManager.GetTranslation("GUI_CLEARTARGETS"));
					}
					if (cFinishedProcessingTileSelected_MessageData.m_Ability.MaxTargetsSelected())
					{
						foreach (CActor item in cFinishedProcessingTileSelected_MessageData.m_Ability.ValidActorsInRange)
						{
							if (cFinishedProcessingTileSelected_MessageData.m_Ability.ActorsToTarget.Contains(item))
							{
								continue;
							}
							GameObject gameObject = FindClientActor(item);
							if (gameObject != null)
							{
								ActorBehaviour actorBehaviour2 = ActorBehaviour.GetActorBehaviour(gameObject);
								if (actorBehaviour2 != null)
								{
									actorBehaviour2.m_WorldspacePanelUI?.ResetPreview();
								}
							}
						}
						if (cFinishedProcessingTileSelected_MessageData.m_Ability is CAbilityAttack { ActorsToTarget: not null } cAbilityAttack && cAbilityAttack.ActorsToTarget.Count > 0)
						{
							foreach (CActor item2 in cAbilityAttack.ActorsToTarget)
							{
								CAttackSummary.TargetSummary targetSummary = cAbilityAttack.AttackSummary.FindTarget(item2);
								WorldspacePanelUIController.PreviewAttackTargets(targetSummary.AttackAbilityWithOverrides, cAbilityAttack.AttackSummary, targetSummary);
							}
						}
					}
				}
				if (m_WaitState.m_State == ChoreographerStateType.WaitingForTileSelected)
				{
					if (WorldspaceStarHexDisplay.Instance.AlreadySelected(clientTile))
					{
						AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileClickAudioItem);
					}
					else
					{
						AudioControllerUtils.PlaySound(UIInfoTools.Instance.InvalidOptionAudioItem);
					}
				}
			}
		}
		if (m_WaitState.m_State == ChoreographerStateType.WaitingForTileSelected)
		{
			bool hideHelpBox = true;
			if (cFinishedProcessingTileSelected_MessageData.m_Ability is CAbilityNullHex)
			{
				hideHelpBox = false;
			}
			SetChoreographerState(ChoreographerStateType.Play, 0, null, hideHelpBox);
			WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		}
		if (cFinishedProcessingTileSelected_MessageData.m_Ability is CAbilityHeal cAbilityHeal)
		{
			WorldspacePanelUIController.RefreshHealPreviews(cAbilityHeal, cAbilityHeal.TargetingActor);
		}
		if (m_BufferedSelectedTile != null)
		{
			CClientTile bufferedSelectedTile = m_BufferedSelectedTile;
			bool bufferedTileNetworked = m_BufferedTileNetworked;
			bool bufferedSecondClickToConfirm = m_BufferedSecondClickToConfirm;
			DisableTileSelection(active: false);
			TileHandler(bufferedSelectedTile, null, bufferedTileNetworked, isUserClick: false, bufferedSecondClickToConfirm);
		}
		else
		{
			DisableTileSelection(active: false);
		}
		if (Singleton<UIUseItemsBar>.Instance.IsShown)
		{
			Singleton<UIUseItemsBar>.Instance.RefreshTooltip();
		}
		CAbility ability = cFinishedProcessingTileSelected_MessageData.m_Ability;
		CAbilityTargeting targetingAbility = ability as CAbilityTargeting;
		if (targetingAbility != null && targetingAbility.TargetingActor != null)
		{
			Singleton<UIUseItemsBar>.Instance.ShowUsableItems(targetingAbility.TargetingActor, (CItem item) => item.YMLData.Data.CompareAbility != null && item.YMLData.Data.CompareAbility.CompareAbility(targetingAbility, null, checkActorsToTarget: true));
		}
		if (cFinishedProcessingTileSelected_MessageData.m_ActorSpawningMessage == null && m_CurrentActor != null)
		{
			if (m_CurrentActor.Tokens.HasKey(CCondition.ENegativeCondition.Stun) && cFinishedProcessingTileSelected_MessageData.m_Ability?.MiscAbilityData?.IgnoreStun != true)
			{
				InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_STUNNED"), LocalizationManager.GetTranslation(m_CurrentActor.ActorLocKey())));
				ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(m_CurrentActor)).m_WorldspacePanelUI?.StunnedWarnEffect(active: true);
			}
			else if (cFinishedProcessingTileSelected_MessageData.m_Ability.StoppedByDisarm())
			{
				InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_DISARMED"), LocalizationManager.GetTranslation(m_CurrentActor.ActorLocKey())));
				ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(m_CurrentActor)).m_WorldspacePanelUI?.DisarmedWarnEffect(active: true);
			}
			else if (m_CurrentActor.Tokens.HasKey(CCondition.ENegativeCondition.Impair))
			{
				InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_IMPAIRED"), LocalizationManager.GetTranslation(m_CurrentActor.ActorLocKey())));
				ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(m_CurrentActor)).m_WorldspacePanelUI?.ImpairedWarnEffect(active: true);
			}
			else if (m_CurrentActor.Tokens.HasKey(CCondition.ENegativeCondition.Sleep))
			{
				InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_SLEEPING"), LocalizationManager.GetTranslation(m_CurrentActor.ActorLocKey())));
				ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(m_CurrentActor)).m_WorldspacePanelUI?.SleepingWarnEffect(active: true);
			}
			else if (cFinishedProcessingTileSelected_MessageData.m_Ability is CAbilitySummon cAbilitySummon)
			{
				string translation = LocalizationManager.GetTranslation(cAbilitySummon.SelectedLocKey);
				Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SUMMON_SELECT_HEX"), translation), string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SUMMON"), translation));
			}
			else if (cFinishedProcessingTileSelected_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.AddDoom)
			{
				if (cFinishedProcessingTileSelected_MessageData.m_Ability.ActorsToTarget.Count != 1)
				{
					Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_ADD_DOOM"), string.Format("<color=#{0}>{1}</color>", UIInfoTools.Instance.GetCharacterHexColor(ECharacter.Doomstalker), LocalizationManager.GetTranslation("ChooseAbility")));
				}
				else
				{
					int count = cFinishedProcessingTileSelected_MessageData.m_Ability.ActorsToTarget[0].CachedDoomActiveBonuses.Count;
					List<CActiveBonus> source = CharacterClassManager.FindAllActiveBonuses(CAbility.EAbilityType.AddDoomSlots, m_CurrentActor);
					if (1 + source.Sum((CActiveBonus it) => it.Ability.Strength) <= count)
					{
						Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_ADD_DOOM"), string.Format("<color=#{0}>{1}</color>", UIInfoTools.Instance.GetCharacterHexColor(ECharacter.Doomstalker), LocalizationManager.GetTranslation("ChooseAbility")));
					}
				}
			}
			else if (cFinishedProcessingTileSelected_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.TransferDooms)
			{
				Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_TRANSFER_DOOM"), cFinishedProcessingTileSelected_MessageData.m_Ability);
			}
			else if (cFinishedProcessingTileSelected_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.RemoveConditions)
			{
				if (cFinishedProcessingTileSelected_MessageData.m_Ability.Strength == -1)
				{
					if (cFinishedProcessingTileSelected_MessageData.m_Ability.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
					{
						ShowAbilityHelpBoxTooltip(cFinishedProcessingTileSelected_MessageData.m_Ability);
					}
					else if (cFinishedProcessingTileSelected_MessageData.m_Ability.AbilityFilter.HasTargetTypeFlag(CAbilityFilter.EFilterTargetType.Ally, exclusive: true))
					{
						Singleton<HelpBox>.Instance.Show("FH/GUI_TOOLTIP_REMOVE_CONDITIONS_ALLY", cFinishedProcessingTileSelected_MessageData.m_Ability);
					}
					else
					{
						Singleton<HelpBox>.Instance.Show("GUI_TOOLTIP_REMOVE_CONDITIONS", cFinishedProcessingTileSelected_MessageData.m_Ability);
					}
				}
			}
			else if (cFinishedProcessingTileSelected_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.Choose)
			{
				foreach (CActor item3 in cFinishedProcessingTileSelected_MessageData.m_Ability.ValidActorsInRange)
				{
					ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActorGameObject(item3)).m_WorldspacePanelUI?.Focus(focus: false);
				}
				if (cFinishedProcessingTileSelected_MessageData.m_Ability.HelpBoxTooltipLocKey.IsNOTNullOrEmpty())
				{
					ShowAbilityHelpBoxTooltip(cFinishedProcessingTileSelected_MessageData.m_Ability);
				}
				else if (cFinishedProcessingTileSelected_MessageData.m_Ability.PerkID != null)
				{
					Singleton<HelpBox>.Instance.Show($"GUI_CHOOSE_ABILITY_TARGET_{cFinishedProcessingTileSelected_MessageData.m_Ability.PerkID}", cFinishedProcessingTileSelected_MessageData.m_Ability);
				}
				else
				{
					string text = cFinishedProcessingTileSelected_MessageData.m_Ability.GetAbilityBaseCard().Name;
					if (!string.IsNullOrEmpty(text) && cFinishedProcessingTileSelected_MessageData.m_Ability.GetAbilityBaseCard().CardType != CBaseCard.ECardType.Dummy)
					{
						Singleton<HelpBox>.Instance.Show($"GUI_CHOOSE_ABILITY_TARGET_{text}", cFinishedProcessingTileSelected_MessageData.m_Ability);
					}
				}
			}
			else
			{
				ShowAbilityHelpBoxTooltip(cFinishedProcessingTileSelected_MessageData.m_Ability);
			}
			TryShowAbilityInvalidTile(cFinishedProcessingTileSelected_MessageData.m_Ability);
		}
		if (FFSNetwork.IsOnline && ActionProcessor.HasSavedStateInSamePhase)
		{
			if (ActionProcessor.CurrentState.StateType == ActionProcessorStateType.Halted)
			{
				ActionProcessor.SetState(ActionProcessorStateType.SwitchBackToSavedState);
			}
			else
			{
				ActionProcessor.ClearSavedState();
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.FinishedProcessingTileDeselected)]
	private void Handle_FinishedProcessingTileDeselected(CMessageData message)
	{
		CFinishedProcessingTileDeselected_MessageData cFinishedProcessingTileDeselected_MessageData = (CFinishedProcessingTileDeselected_MessageData)message;
		if (PhaseManager.Phase.Type == CPhase.PhaseType.Action && ((CPhaseAction)PhaseManager.Phase).CurrentPhaseAbility != null)
		{
			if (cFinishedProcessingTileDeselected_MessageData.m_Ability.AreaEffect != null)
			{
				AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileCancelClickAudioItem);
				if (cFinishedProcessingTileDeselected_MessageData.m_Ability.MiscAbilityData != null && cFinishedProcessingTileDeselected_MessageData.m_Ability.MiscAbilityData.ExactRange.HasValue && cFinishedProcessingTileDeselected_MessageData.m_Ability.MiscAbilityData.ExactRange.Value)
				{
					readyButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.EnoughTargetsSelected());
					m_UndoButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.CanUndo && (FirstAbility || cFinishedProcessingTileDeselected_MessageData.m_Ability.AllowUndoAfterFirst));
					m_SkipButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.CanSkip);
				}
				else if (WorldspaceStarHexDisplay.Instance.IsAOELocked())
				{
					m_UndoButton.Toggle(active: true, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
					m_UndoButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.CanUndo && (FirstAbility || cFinishedProcessingTileDeselected_MessageData.m_Ability.AllowUndoAfterFirst));
					m_SkipButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.CanSkip);
					WorldspaceStarHexDisplay.Instance.SetAOELocked(locked: false);
					WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
					readyButton.SetInteractable(interactable: false);
				}
				else
				{
					m_UndoButton.Toggle(active: true, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
					m_UndoButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.CanUndo && (FirstAbility || cFinishedProcessingTileDeselected_MessageData.m_Ability.AllowUndoAfterFirst));
					m_SkipButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.CanSkip);
					readyButton.SetInteractable(interactable: false);
				}
			}
			else
			{
				if (WorldspaceStarHexDisplay.Instance.CurrentNumberSelectedTargets() <= 0)
				{
					AudioControllerUtils.PlaySound(UIInfoTools.Instance.tileCancelClickAudioItem);
					if (cFinishedProcessingTileDeselected_MessageData.m_Ability.CanUndo && FirstAbility)
					{
						m_UndoButton.Toggle(active: true, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
					}
				}
				bool interactable = cFinishedProcessingTileDeselected_MessageData.m_Ability.EnoughTargetsSelected() && cFinishedProcessingTileDeselected_MessageData.m_Ability.CanBePerformed();
				readyButton.SetInteractable(interactable);
				m_UndoButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.CanUndo && (FirstAbility || cFinishedProcessingTileDeselected_MessageData.m_Ability.AllowUndoAfterFirst));
				m_SkipButton.SetInteractable(cFinishedProcessingTileDeselected_MessageData.m_Ability.CanSkip);
			}
		}
		if (m_WaitState.m_State == ChoreographerStateType.WaitingForTileSelected)
		{
			bool hideHelpBox = true;
			if (cFinishedProcessingTileDeselected_MessageData.m_Ability is CAbilityNullHex)
			{
				hideHelpBox = false;
			}
			SetChoreographerState(ChoreographerStateType.Play, 0, null, hideHelpBox);
			WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		}
		if (m_BufferedSelectedTile != null)
		{
			CClientTile bufferedSelectedTile = m_BufferedSelectedTile;
			bool bufferedTileNetworked = m_BufferedTileNetworked;
			bool bufferedSecondClickToConfirm = m_BufferedSecondClickToConfirm;
			DisableTileSelection(active: false);
			TileHandler(bufferedSelectedTile, null, bufferedTileNetworked, isUserClick: false, bufferedSecondClickToConfirm);
		}
		else
		{
			DisableTileSelection(active: false);
		}
		if (cFinishedProcessingTileDeselected_MessageData.m_ActorSpawningMessage == null && m_CurrentActor != null)
		{
			if (m_CurrentActor.Tokens.HasKey(CCondition.ENegativeCondition.Stun) && cFinishedProcessingTileDeselected_MessageData.m_Ability?.MiscAbilityData?.IgnoreStun != true)
			{
				InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_STUNNED"), LocalizationManager.GetTranslation(m_CurrentActor.ActorLocKey())));
				ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(m_CurrentActor)).m_WorldspacePanelUI?.StunnedWarnEffect(active: true);
			}
			else if (cFinishedProcessingTileDeselected_MessageData.m_Ability.StoppedByDisarm())
			{
				InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_DISARMED"), LocalizationManager.GetTranslation(m_CurrentActor.ActorLocKey())));
				ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(m_CurrentActor)).m_WorldspacePanelUI?.DisarmedWarnEffect(active: true);
			}
			else if (m_CurrentActor.Tokens.HasKey(CCondition.ENegativeCondition.Sleep))
			{
				InitiativeTrack.Instance.helpBox.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_PLAYER_SLEEPING"), LocalizationManager.GetTranslation(m_CurrentActor.ActorLocKey())));
				ActorBehaviour.GetActorBehaviour(FindClientActorGameObject(m_CurrentActor)).m_WorldspacePanelUI?.SleepingWarnEffect(active: true);
			}
			else if (cFinishedProcessingTileDeselected_MessageData.m_Ability is CAbilitySummon cAbilitySummon)
			{
				string translation = LocalizationManager.GetTranslation(cAbilitySummon.SelectedLocKey);
				Singleton<HelpBox>.Instance.ShowTranslated(string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SUMMON_SELECT_HEX"), translation), string.Format(LocalizationManager.GetTranslation("GUI_TOOLTIP_SUMMON"), translation));
			}
			else if (cFinishedProcessingTileDeselected_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.TransferDooms)
			{
				Singleton<HelpBox>.Instance.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_TRANSFER_DOOM"), cFinishedProcessingTileDeselected_MessageData.m_Ability);
			}
			else if (cFinishedProcessingTileDeselected_MessageData.m_Ability is CAbilityAttack { State: CAbilityAttack.EAttackState.SelectAttackFocusAdditionalTargets })
			{
				InitiativeTrack.Instance.helpBox.ShowTranslated(LocalizationManager.GetTranslation("GUI_TOOLTIP_ADD_TARGET_TIP"), string.Format("<color=#{1}>{0}</color>", LocalizationManager.GetTranslation("GUI_TOOLTIP_ADD_TARGET"), UIInfoTools.Instance.regularModifierColor.ToHex()));
			}
			else
			{
				ShowAbilityHelpBoxTooltip(cFinishedProcessingTileDeselected_MessageData.m_Ability);
			}
			TryShowAbilityInvalidTile(cFinishedProcessingTileDeselected_MessageData.m_Ability);
		}
		if (FFSNetwork.IsOnline && ActionProcessor.HasSavedStateInSamePhase)
		{
			if (ActionProcessor.CurrentState.StateType == ActionProcessorStateType.Halted)
			{
				ActionProcessor.SetState(ActionProcessorStateType.SwitchBackToSavedState);
			}
			else
			{
				ActionProcessor.ClearSavedState();
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.ShowChooseAbilityUI)]
	private void Handle_ShowChooseAbilityUI(CMessageData message)
	{
		CShowChooseAbilityUI_MessageData cShowChooseAbilityUI_MessageData = (CShowChooseAbilityUI_MessageData)message;
		if (cShowChooseAbilityUI_MessageData.m_ActorSpawningMessage is CPlayerActor)
		{
			m_UndoButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
			m_UndoButton.SetInteractable(cShowChooseAbilityUI_MessageData.m_ChooseAbility.CanUndo && FirstAbility);
			m_SkipButton.Toggle(message.m_ActorSpawningMessage.Type == CActor.EType.Player, LocalizationManager.GetTranslation("GUI_SKIP_ABILITY"), hideOnClick: true, cShowChooseAbilityUI_MessageData.m_ChooseAbility.CanSkip);
		}
	}

	[MessageHandler(CMessageData.MessageType.HideChooseAbilityUI)]
	private void Handle_HideChooseAbilityUI(CMessageData message)
	{
		_ = (CHideChooseAbilityUI_MessageData)message;
		Singleton<UIUseAbilitiesBar>.Instance.Hide();
	}

	[MessageHandler(CMessageData.MessageType.StartTurnActiveBonusTriggered)]
	private void Handle_StartTurnActiveBonusTriggered(CMessageData message)
	{
		Singleton<CardsHandManager>.Instance.Hide();
	}

	[MessageHandler(CMessageData.MessageType.CheckForInitiativeAdjustments)]
	private void Handle_CheckForInitiativeAdjustments(CMessageData message)
	{
		CCheckForInitiativeAdjustments_MessageData cCheckForInitiativeAdjustments_MessageData = (CCheckForInitiativeAdjustments_MessageData)message;
		if (message.m_ActorSpawningMessage is CPlayerActor)
		{
			m_CurrentActor = message.m_ActorSpawningMessage;
			Singleton<UIActiveBonusBar>.Instance.ShowActiveBonus(cCheckForInitiativeAdjustments_MessageData.m_ActorSpawningMessage, CAbility.EAbilityType.AdjustInitiative);
		}
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONENDSELECTION, LocalizationManager.GetTranslation("GUI_CONTINUE"), hideOnClick: true, glowingEffect: false, !FFSNetwork.IsOnline || message.m_ActorSpawningMessage.IsUnderMyControl(), disregardTurnControlForInteractability: true);
		if (FFSNetwork.IsOnline)
		{
			ActionProcessor.SetState(ActionProcessorStateType.ProcessFreely, ActionPhaseType.InitiativeAdjustments);
		}
	}

	[MessageHandler(CMessageData.MessageType.EndInitiativeAdjustments)]
	private void Handle_EndInitiativeAdjustments(CMessageData message)
	{
		_ = (CEndInitiativeAdjustments_MessageData)message;
		if (message.m_ActorSpawningMessage is CPlayerActor)
		{
			Singleton<UIActiveBonusBar>.Instance.Hide();
		}
	}

	[MessageHandler(CMessageData.MessageType.UpdateInitiativeTrack)]
	private void Handle_UpdateInitiativeTrack(CMessageData message)
	{
		_ = (CUpdateInitiativeTrack_MessageData)message;
		InitiativeTrack.Instance.UpdateActors();
		readyButton.SetInteractable(interactable: true);
	}

	[MessageHandler(CMessageData.MessageType.ChangeModifier)]
	private void Handle_ChangeModifier(CMessageData message)
	{
		CChangeModifier_MessageData cChangeModifier_MessageData = (CChangeModifier_MessageData)message;
		if (cChangeModifier_MessageData.m_ActiveBonus != null && cChangeModifier_MessageData.m_ActiveBonus.BaseCard is CItem)
		{
