	[MessageHandler(CMessageData.MessageType.ActorIsRedistributingDamage)]
	private void Handle_ActorIsRedistributingDamage(CMessageData message)
	{
		CActorIsRedistributingDamage_MessageData cActorIsRedistributingDamage_MessageData = (CActorIsRedistributingDamage_MessageData)message;
		WorldspaceStarHexDisplay.Instance.ResetPlayerAttackType();
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		ClearAllActorEvents();
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cActorIsRedistributingDamage_MessageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cActorIsRedistributingDamage_MessageData.m_RedistributeDamageAbility, cActorIsRedistributingDamage_MessageData.m_ActorSpawningMessage, new List<string> { cActorIsRedistributingDamage_MessageData.AnimOverload, "PowerUp" }, out animationShouldPlay, out animatingActorToWaitFor);
		foreach (CActor item in cActorIsRedistributingDamage_MessageData.m_ActorsRedistributingDamageTo)
		{
			string arg = LocalizationManager.GetTranslation(item.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(item);
			GameObject gameObject = FindClientActorGameObject(item);
			int healthChangeForActor = cActorIsRedistributingDamage_MessageData.m_RedistributeDamageAbility.GetHealthChangeForActor(item);
			if (healthChangeForActor == item.Health)
			{
				continue;
			}
			if (healthChangeForActor > item.Health)
			{
				StringBuilder stringBuilder = new StringBuilder(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_HEALED"), arg));
				stringBuilder.AppendFormat(" {0}", string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_HEALED_HEAL"), string.Format("<b>{0}</b>", "<sprite name=Heal>" + (healthChangeForActor - item.Health))));
				Singleton<CombatLogHandler>.Instance.AddLog(stringBuilder.ToString(), CombatLogFilter.HEALING);
			}
			else
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_DAMAGED"), arg, string.Format("<b>{0}</b>", "<sprite name=Damage>" + Math.Abs(item.Health - healthChangeForActor))), CombatLogFilter.DAMAGE);
				if (!item.IsDowned)
				{
					bool animationShouldPlay2 = false;
					ProcessActorAnimation(cActorIsRedistributingDamage_MessageData.m_RedistributeDamageAbility, item, new List<string> { "Hit" }, out animationShouldPlay2, out var _);
					animationShouldPlay |= animationShouldPlay2;
				}
			}
			GameObject prefab = ((healthChangeForActor > item.Health) ? GlobalSettings.Instance.m_GlobalParticles.DefaultHealEffect : GlobalSettings.Instance.m_DefaultHitEffects.DefaultStandardHitEffect);
			GameObject gameObject2 = ObjectPool.Spawn(prefab, gameObject.transform);
			ObjectPool.Recycle(gameObject2, VFXShared.GetEffectLifetime(gameObject2), prefab, "@ VFX Pool");
		}
		DisableNextPhaseButtons();
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		GameObject gameObject3 = FindClientActorGameObject(message.m_ActorSpawningMessage);
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(gameObject3).ProgressChoreographer();
		}
	}

