	[MessageHandler(CMessageData.MessageType.ForcedChangeCharacterModel)]
	private void Handle_ForcedChangeCharacterModel(CMessageData message)
	{
		CActor actorToChange = ((CForcedChangeCharacterModel_MessageData)message).m_ActorToChange;
		GameObject gameObject = s_Choreographer.FindClientActor(actorToChange);
		ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
		CharacterManager characterManager = CharacterManager.GetCharacterManager(gameObject);
		Quaternion rotation = gameObject.transform.rotation;
		gameObject.transform.SetParent(null);
		s_Choreographer.m_ClientPlayers.Remove(gameObject);
		s_Choreographer.m_ClientDeadActors.Remove(gameObject);
		s_Choreographer.m_ClientEnemies.Remove(gameObject);
		s_Choreographer.m_ClientHeroSummons.Remove(gameObject);
		s_Choreographer.m_ClientAllyMonsters.Remove(gameObject);
		s_Choreographer.m_ClientEnemy2Monsters.Remove(gameObject);
		s_Choreographer.m_ClientNeutralMonsters.Remove(gameObject);
		s_Choreographer.m_ClientObjects.Remove(gameObject);
		s_Choreographer.AllActorsInScene.Remove(gameObject);
		actorBehaviour.m_WorldspacePanelUI?.Destroy();
		CharacterOutlineRegistration(characterManager, register: false);
		characterManager.DeinitializeCharacter();
		ObjectPool.Recycle(gameObject, characterManager.CharacterPrefab);
		CClientTile tile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[actorToChange.ArrayIndex.X, actorToChange.ArrayIndex.Y];
		GameObject gameObject2 = s_Choreographer.CreateCharacterActor(tile, actorToChange);
		if (actorToChange.Type == CActor.EType.Player)
		{
			s_Choreographer.m_ClientPlayers.Add(gameObject2);
		}
		else if (actorToChange.Type == CActor.EType.Enemy)
		{
			s_Choreographer.m_ClientEnemies.Add(gameObject2);
		}
		else if (actorToChange.Type == CActor.EType.HeroSummon)
		{
			s_Choreographer.m_ClientHeroSummons.Add(gameObject2);
		}
		else if (actorToChange.Type == CActor.EType.Ally)
		{
			s_Choreographer.m_ClientAllyMonsters.Add(gameObject2);
		}
		else if (actorToChange.Type == CActor.EType.Enemy2)
		{
			s_Choreographer.m_ClientEnemy2Monsters.Add(gameObject2);
		}
		else if (actorToChange.Type == CActor.EType.Neutral)
		{
			s_Choreographer.m_ClientNeutralMonsters.Add(gameObject2);
		}
		else if (actorToChange is CObjectActor)
		{
			s_Choreographer.m_ClientObjects.Add(gameObject2);
		}
		ActorBehaviour.GetActorBehaviour(gameObject2).UpdateWorldspaceConditionsUI();
		gameObject2.transform.SetPositionAndRotation(gameObject2.transform.position, rotation);
		FaceNearestEnemy(gameObject2);
		InitiativeTrack.Refresh(forceSelectFirstActor: false);
	}

