	[MessageHandler(CMessageData.MessageType.PlayCharacterAnimation)]
	private void Handle_PlayCharacterAnimation(CMessageData message)
	{
		CPlayCharacterAnimation_MessageData cPlayCharacterAnimation_MessageData = (CPlayCharacterAnimation_MessageData)message;
		bool blockClientMessageProcessing = m_BlockClientMessageProcessing;
		if (cPlayCharacterAnimation_MessageData.m_BlockMessageProcessingDuringAnimation)
		{
			m_BlockClientMessageProcessing = true;
		}
		GameObject gameObject = FindClientActorGameObject(cPlayCharacterAnimation_MessageData.m_ActorSpawningMessage);
		if (gameObject == null)
		{
			if (cPlayCharacterAnimation_MessageData.m_Ability != null && !cPlayCharacterAnimation_MessageData.m_Ability.HasEnded)
			{
				PhaseManager.StepComplete();
			}
			return;
		}
		if (cPlayCharacterAnimation_MessageData.m_TileToLookAt != null)
		{
			CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cPlayCharacterAnimation_MessageData.m_TileToLookAt.m_ArrayIndex.X, cPlayCharacterAnimation_MessageData.m_TileToLookAt.m_ArrayIndex.Y];
			StartCoroutine(RotateToFaceTarget(gameObject, cClientTile.m_GameObject.transform.position));
		}
		m_ActorsBeingTargetedForVFX?.Clear();
		m_LastSelectedTiles?.Clear();
		if (cPlayCharacterAnimation_MessageData.m_TargetedTilesForVFX != null && cPlayCharacterAnimation_MessageData.m_TargetedTilesForVFX.Count > 0)
		{
			m_LastSelectedTiles = cPlayCharacterAnimation_MessageData.m_TargetedTilesForVFX.Select((CTile t) => ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[t.m_ArrayIndex.X, t.m_ArrayIndex.Y]).ToList();
		}
		CurrentAttackArea?.Clear();
		if (cPlayCharacterAnimation_MessageData.m_AreaTilesForVFX != null && cPlayCharacterAnimation_MessageData.m_AreaTilesForVFX.Count > 0)
		{
			CurrentAttackArea = cPlayCharacterAnimation_MessageData.m_AreaTilesForVFX.Select((CTile t) => ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[t.m_ArrayIndex.X, t.m_ArrayIndex.Y]).ToList();
		}
		CActor animatingActorToWaitFor = cPlayCharacterAnimation_MessageData.m_ActorSpawningMessage;
		ProcessActorAnimation(cPlayCharacterAnimation_MessageData.m_Ability, cPlayCharacterAnimation_MessageData.m_ActorSpawningMessage, new List<string>
		{
			cPlayCharacterAnimation_MessageData.AnimOverload,
			cPlayCharacterAnimation_MessageData.m_IsFromItem ? "UseItem" : ""
		}, out var animationShouldPlay, out animatingActorToWaitFor);
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(gameObject).ProgressChoreographer();
			m_BlockClientMessageProcessing = blockClientMessageProcessing;
		}
		else if (cPlayCharacterAnimation_MessageData.m_BlockMessageProcessingDuringAnimation)
		{
			StartCoroutine(WaitForIdleAndUnblock(animatingActorToWaitFor, gameObject, blockClientMessageProcessing));
		}
		IEnumerator WaitForIdleAndUnblock(CActor actorToWaitFor, GameObject actorGO, bool prevBlockState)
		{
			int waitCount = 1000;
			do
			{
				yield return null;
			}
			while (!IsPlayingIdleAnimation(actorGO) && waitCount-- > 0);
			m_BlockClientMessageProcessing = prevBlockState;
		}
	}

	[MessageHandler(CMessageData.MessageType.ActorSelectedNullHexes)]
	private void Handle_ActorSelectedNullHexes(CMessageData message)
	{
		CActorSelectedNullHexes_MessageData cActorSelectedNullHexes_MessageData = (CActorSelectedNullHexes_MessageData)message;
		ClearAllActorEvents();
		GameObject go = FindClientActorGameObject(cActorSelectedNullHexes_MessageData.m_Ability.TargetingActor);
		m_lastSelectedTile = null;
		m_LastSelectedTiles = cActorSelectedNullHexes_MessageData.m_Ability.TilesSelected.Select((CTile t) => ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[t.m_ArrayIndex.X, t.m_ArrayIndex.Y]).ToList();
		WorldspaceStarHexDisplay.Instance.ClearNonTargetHexHighlights(null, null, m_LastSelectedTiles);
		if (m_LastSelectedTiles.Count > 0)
		{
			Vector3 zero = Vector3.zero;
			foreach (CClientTile lastSelectedTile in m_LastSelectedTiles)
			{
				zero += lastSelectedTile.m_GameObject.transform.position;
			}
			zero /= (float)m_LastSelectedTiles.Count;
			StartCoroutine(RotateToFaceTarget(go, zero));
		}
		bool animationShouldPlay = false;
		CActor animatingActorToWaitFor = cActorSelectedNullHexes_MessageData.m_Ability.TargetingActor;
		ProcessActorAnimation(cActorSelectedNullHexes_MessageData.m_Ability, cActorSelectedNullHexes_MessageData.m_Ability.TargetingActor, new List<string>
		{
			cActorSelectedNullHexes_MessageData.AnimOverload,
			GetNonOverloadAnim(cActorSelectedNullHexes_MessageData.m_Ability)
		}, out animationShouldPlay, out animatingActorToWaitFor);
		if (animatingActorToWaitFor != null)
		{
			SetChoreographerState(ChoreographerStateType.WaitingForGeneralAnim, animationShouldPlay ? 10000 : 400, animatingActorToWaitFor);
		}
		if (!animationShouldPlay)
		{
			ActorEvents.GetActorEvents(go).ProgressChoreographer();
		}
		readyButton.Toggle(active: false, ReadyButton.EButtonState.EREADYBUTTONNA, "");
		m_UndoButton.Toggle(active: false);
		m_SkipButton.Toggle(active: false);
	}

