	[MessageHandler(CMessageData.MessageType.MoveProp)]
	private void Handle_MoveProp(CMessageData message)
	{
		CMoveProp_MessageData cMoveProp_MessageData = (CMoveProp_MessageData)message;
		if (cMoveProp_MessageData.m_MoveSpeed <= 0f)
		{
			GameObject gameObject = FindPropGameObject(cMoveProp_MessageData.m_MoveProp);
