	private IEnumerator LerpPropRoutine(CLerpProp_MessageData msg)
	{
		GameObject propGO = FindPropGameObject(msg.Prop);
		CClientTile tile = ClientScenarioManager.s_ClientScenarioManager.GetTile(msg.TargetLocation);
		Vector3 targetLocation = tile.m_GameObject.transform.position;
		Quaternion targetRotation = Quaternion.Euler(GloomUtility.CVToV(msg.TargetRotation));
		ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(s_Choreographer.FindClientActor(msg.Actor));
		float num = ((actorBehaviour != null && msg.UseActorSpeed) ? actorBehaviour.RunSpeed : msg.Speed);
		if (num > 0f)
		{
			Vector3 startLocation = propGO.transform.position;
			Quaternion startRotation = propGO.transform.rotation;
			float num2 = Vector3.Distance(startLocation, targetLocation);
			float duration = num2 / num;
			float startTime = Timekeeper.instance.m_GlobalClock.time;
			float passedTime = 0f;
			while (passedTime < duration)
			{
				float t = passedTime / duration;
				propGO.transform.position = Vector3.Lerp(startLocation, targetLocation, t);
				propGO.transform.rotation = Quaternion.Lerp(startRotation, targetRotation, t);
				passedTime = Timekeeper.instance.m_GlobalClock.time - startTime;
				yield return null;
			}
		}
		propGO.transform.position = targetLocation;
		propGO.transform.rotation = targetRotation;
		m_LerpPropCoroutines.Remove(msg.Prop);
	}

	[MessageHandler(CMessageData.MessageType.LerpProp)]
	private void Handle_LerpProp(CMessageData message)
	{
		CLerpProp_MessageData cLerpProp_MessageData = (CLerpProp_MessageData)message;
		if (m_LerpPropCoroutines.TryGetValue(cLerpProp_MessageData.Prop, out var value))
		{
			StopCoroutine(value);
		}
		m_LerpPropCoroutines[cLerpProp_MessageData.Prop] = LerpPropRoutine(cLerpProp_MessageData);
		StartCoroutine(m_LerpPropCoroutines[cLerpProp_MessageData.Prop]);
	}

	private IEnumerator LerpActorRoutine(CLerpActor_MessageData msg)
	{
		CClientTile tile = ClientScenarioManager.s_ClientScenarioManager.GetTile(msg.TargetLocation);
		Vector3 targetLocation = tile.m_GameObject.transform.position;
		Quaternion targetRotation = Quaternion.Euler(GloomUtility.CVToV(msg.TargetRotation));
		GameObject gameObject = s_Choreographer.FindClientActor(msg.Actor);
		GameObject gameObject2 = s_Choreographer.FindClientActor(msg.DriverActor);
		ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
		ActorBehaviour actorBehaviour2 = ActorBehaviour.GetActorBehaviour(gameObject2);
		float num = ((actorBehaviour2 != null && msg.UseDriverActorSpeed) ? actorBehaviour2.RunSpeed : msg.Speed);
		if (num > 0f)
		{
			Vector3 startLocation = gameObject.transform.position;
			Quaternion startRotation = gameObject.transform.rotation;
			float num2 = Vector3.Distance(startLocation, targetLocation);
			float duration = num2 / num;
			float startTime = Timekeeper.instance.m_GlobalClock.time;
			float passedTime = 0f;
			while (passedTime < duration)
			{
				float t = passedTime / duration;
				Vector3 target = Vector3.Lerp(startLocation, targetLocation, t);
				Quaternion transformRotation = Quaternion.Lerp(startRotation, targetRotation, t);
				actorBehaviour.ForceSetLocoIntermediateTarget(target);
				actorBehaviour.SetTransformRotation(transformRotation);
				passedTime = Timekeeper.instance.m_GlobalClock.time - startTime;
				yield return null;
			}
		}
		actorBehaviour.ForceSetLocoIntermediateTarget(targetLocation);
		actorBehaviour.SetTransformRotation(targetRotation);
		m_LerpActorRoutine = null;
	}

	[MessageHandler(CMessageData.MessageType.LerpActor)]
	private void Handle_LerpActor(CMessageData message)
	{
		CLerpActor_MessageData msg = (CLerpActor_MessageData)message;
		if (m_LerpActorRoutine != null)
		{
			StopCoroutine(m_LerpActorRoutine);
		}
		m_LerpActorRoutine = LerpActorRoutine(msg);
		StartCoroutine(m_LerpActorRoutine);
	}

