	[MessageHandler(CMessageData.MessageType.FinishedProcessingActiveBonusToggle)]
	private void Handle_FinishedProcessingActiveBonusToggle(CMessageData message)
	{
		CFinishedProcessingActiveBonusToggle_MessageData cFinishedProcessingActiveBonusToggle_MessageData = (CFinishedProcessingActiveBonusToggle_MessageData)message;
		bool flag = CurrentActor.IsUnderMyControl();
		Singleton<UIUseAugmentationsBar>.Instance.SetInteractionAvailableSlots(flag, onlyChangeUnselected: false, checkForSingleConsume: true);
		Singleton<UIActiveBonusBar>.Instance.SetInteractionAvailableSlots(flag);
		Singleton<UIUseItemsBar>.Instance.SetItemsInteractable(flag);
		if (!(PhaseManager.CurrentPhaseAction?.CurrentPhaseAbility?.m_Ability?.ID != m_CurrentAbility?.ID) || (GameState.ThreadIsSleeping && GameState.ThreadSleepReason == "ActiveBonusToggle"))
		{
			if (m_CurrentAbility != null)
			{
				readyButton.SetInteractable((!m_CurrentAbility.RequiresWaypointSelection()) ? (!(m_CurrentAbility is CAbilityChooseAbility) && ((m_CurrentAbility is CAbilityConsume cAbilityConsume) ? (cAbilityConsume.ElementsToConsume.Count > 0) : (m_CurrentAbility.EnoughTargetsSelected() && m_CurrentAbility.ValidAlliesTargeted()))) : ((bool)Waypoint.GetLastWaypoint && Waypoint.GetLastWaypoint.CanEndMovementHere));
				bool flag2 = WorldspaceStarHexDisplay.Instance.SavedAbility == m_CurrentAbility && WorldspaceStarHexDisplay.Instance.CurrentNumberSelectedTargets() > 0;
				m_UndoButton.SetInteractable(m_CurrentAbility.CanUndo && (flag2 || FirstAbility));
				m_SkipButton.SetInteractable(m_CurrentAbility.CanSkip);
			}
			else if (GameState.ThreadIsSleeping)
			{
				readyButton.SetInteractable(!FFSNetwork.IsOnline || cFinishedProcessingActiveBonusToggle_MessageData.m_ActorSpawningMessage.IsUnderMyControl());
			}
			if (Singleton<TakeDamagePanel>.Instance.IsOpen)
			{
				Singleton<TakeDamagePanel>.Instance.RefreshDamageInformation();
			}
		}
		if (FFSNetwork.IsOnline && !cFinishedProcessingActiveBonusToggle_MessageData.m_ActorSpawningMessage.IsUnderMyControl() && ActionProcessor.HasSavedStateInSamePhase)
		{
			if (ActionProcessor.CurrentState.StateType == ActionProcessorStateType.Halted)
			{
				ActionProcessor.SetState(ActionProcessorStateType.SwitchBackToSavedState);
			}
			else
			{
				ActionProcessor.ClearSavedState();
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.FinishedProcessingItemToggle)]
	private void Handle_FinishedProcessingItemToggle(CMessageData message)
	{
		CFinishedProcessingItemToggle_MessageData cFinishedProcessingItemToggle_MessageData = (CFinishedProcessingItemToggle_MessageData)message;
		Singleton<UIUseItemsBar>.Instance.SetItemsInteractable(enable: true);
		if (cFinishedProcessingItemToggle_MessageData.m_Ability != null && PhaseManager.CurrentPhaseAction != null)
		{
			if (cFinishedProcessingItemToggle_MessageData.m_Ability.AreaEffect != null)
			{
				bool flag = (cFinishedProcessingItemToggle_MessageData.m_Ability.RequiresWaypointSelection() ? (Waypoint.s_Waypoints.Count > 0) : (cFinishedProcessingItemToggle_MessageData.m_Ability.EnoughTargetsSelected() && cFinishedProcessingItemToggle_MessageData.m_Ability.CanBePerformed()));
				bool interactable = (cFinishedProcessingItemToggle_MessageData.m_Ability.RequiresAllyTargeting() ? cFinishedProcessingItemToggle_MessageData.m_Ability.ValidAlliesTargeted() : flag);
				readyButton.SetInteractable(interactable);
			}
			else
			{
				readyButton.SetInteractable((!cFinishedProcessingItemToggle_MessageData.m_Ability.RequiresWaypointSelection()) ? cFinishedProcessingItemToggle_MessageData.m_Ability.EnoughTargetsSelected() : ((bool)Waypoint.GetLastWaypoint && Waypoint.GetLastWaypoint.CanEndMovementHere));
			}
			m_UndoButton.SetInteractable(cFinishedProcessingItemToggle_MessageData.m_Ability.CanUndo && FirstAbility);
			m_SkipButton.SetInteractable(cFinishedProcessingItemToggle_MessageData.m_Ability.CanSkip);
		}
		if (FFSNetwork.IsOnline && ActionProcessor.HasSavedStateInSamePhase)
		{
			if (ActionProcessor.CurrentState.StateType == ActionProcessorStateType.Halted)
			{
				ActionProcessor.SetState(ActionProcessorStateType.SwitchBackToSavedState);
			}
			else
			{
				ActionProcessor.ClearSavedState();
			}
		}
	}

	[MessageHandler(CMessageData.MessageType.FinishedProcessingUndo)]
	private void Handle_FinishedProcessingUndo(CMessageData message)
	{
		CFinishedProcessingUndo_MessageData cFinishedProcessingUndo_MessageData = (CFinishedProcessingUndo_MessageData)message;
		CAbility ability = cFinishedProcessingUndo_MessageData.m_Ability;
		bool isItemAbility = ability.IsItemAbility;
		CAbility parentAbility = ability.ParentAbility;
		bool num = parentAbility != null && parentAbility.AbilityType == CAbility.EAbilityType.ChooseAbility;
		Singleton<UIUseItemsBar>.Instance.ShowCurrentlyPlayingItems(cFinishedProcessingUndo_MessageData.m_ActorSpawningMessage);
		if (!num)
		{
			ElementInfusionBoardManager.RestoreState();
			InfusionBoardUI.Instance?.RestoreState();
			InfusionBoardUI.Instance?.UpdateBoard();
		}
		TileBehaviour.SetCallback(s_Choreographer.TileHandler);
		Waypoint.s_LockWaypoints = false;
		Waypoint.Clear();
		WorldspaceStarHexDisplay.Instance.Clear();
		SetChoreographerState(ChoreographerStateType.Play, 0, null, cFinishedProcessingUndo_MessageData.m_HideHelpBox);
		if (isItemAbility && s_Choreographer.FirstAbility)
		{
			CardsActionControlller.s_Instance.RefreshConsumeBar(cFinishedProcessingUndo_MessageData.m_Ability.TargetingActor, cFinishedProcessingUndo_MessageData.m_Ability);
		}
		m_CurrentAbility = null;
		FirstAbility = false;
	}

	[MessageHandler(CMessageData.MessageType.FinishedProcessingClearTargets)]
	private void Handle_FinishedProcessingClearTargets(CMessageData message)
	{
		CFinishedProcessingClearTargets_MessageData cFinishedProcessingClearTargets_MessageData = (CFinishedProcessingClearTargets_MessageData)message;
		CAbility ability = cFinishedProcessingClearTargets_MessageData.m_Ability;
		s_Choreographer.m_LastSelectedTiles?.Clear();
		WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		Singleton<UIUseItemsBar>.Instance.ShowCurrentlyPlayingItems(cFinishedProcessingClearTargets_MessageData.m_ActorSpawningMessage);
		if (ability.AreaEffect != null || ability.AreaEffectBackup != null || ability.AllTargetsOnAttackPath)
		{
			s_Choreographer.SetChoreographerState(ChoreographerStateType.WaitingForAreaAttackFocusSelection, 0, null, hideHelpBox: false);
		}
		m_UndoButton.Toggle((FirstAbility || ability.IsItemAbility || cFinishedProcessingClearTargets_MessageData.m_Ability.AllowUndoAfterFirst) && ability.CanUndo && !ability.IsControlAbility, UndoButton.EButtonState.EUNDOBUTTONUNDO, LocalizationManager.GetTranslation("GUI_UNDO"));
		string term = "GUI_SKIP_ABILITY";
		if (cFinishedProcessingClearTargets_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.Push)
		{
			term = "GUI_SKIP_PUSH";
		}
		if (cFinishedProcessingClearTargets_MessageData.m_Ability.AbilityType == CAbility.EAbilityType.Pull)
		{
			term = "GUI_SKIP_PULL";
		}
		m_SkipButton.Toggle(active: true, LocalizationManager.GetTranslation(term), hideOnClick: true, ability.CanSkip);
		readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONCONFIRMDISABLED, LocalizationManager.GetTranslation("GUI_CONFIRM_ACTION"), hideOnClick: true, glowingEffect: true);
		Singleton<UIUseItemsBar>.Instance.RefreshItems(clear: true);
		Singleton<UIUseItemsBar>.Instance.SetItemsInteractable(enable: true);
		Singleton<UIActiveBonusBar>.Instance.SetInteractionAvailableSlots(interactable: true);
		Singleton<UIUseAugmentationsBar>.Instance.SetInteractionAvailableSlots(interactable: true);
	}

