	[MessageHandler(CMessageData.MessageType.PlayerFinishedLongRest)]
	private void Handle_PlayerFinishedLongRest(CMessageData message)
	{
		CPlayerFinishedLongRest_MessageData messageData = (CPlayerFinishedLongRest_MessageData)message;
		CPlayerActor playerActor = messageData.m_ActorSpawningMessage as CPlayerActor;
		WorldspaceStarHexDisplay.Instance.CurrentDisplayState = WorldspaceStarHexDisplay.WorldSpaceStarDisplayState.ShowNone;
		if (messageData.m_LostCard == null)
		{
			Singleton<CardsHandManager>.Instance.ShowLongRested(playerActor);
			Singleton<CardsHandManager>.Instance.EnableCancelActiveAbilities = !FFSNetwork.IsOnline || playerActor.IsUnderMyControl();
			return;
		}
		CardsHandUI playerHand = Singleton<CardsHandManager>.Instance.GetHand(playerActor);
		List<AbilityCardUI> selectedCards = playerHand.AllCards.Where((AbilityCardUI x) => x.AbilityCard == messageData.m_LostCard).ToList();
		if (!messageData.m_ImprovedShortRestUsed)
		{
			return;
		}
		playerHand.shortRested = true;
		playerHand.UpdateShortRest();
		if (gameObject.activeInHierarchy)
		{
			UIManager.Instance.StartCoroutine(playerHand.AnimateCardsLost(selectedCards, () =>
			{
				Log.GUIInfo("HandleImprovedShortRest");
				playerHand.UpdateView(CardHandMode.CardsSelection, CardPileType.Any, new List<CardPileType>
				{
					CardPileType.Hand,
					CardPileType.Round
				}, playerActor.MaxCardsClampedToHand);
			}));
		}
	}

