	[MessageHandler(CMessageData.MessageType.UpdateTrapVisualState)]
	public void Handle_UpdateTrapVisualState(CMessageData message)
	{
		StartCoroutine(UpdateTrapVisualState(message));
	}

	private IEnumerator UpdateTrapVisualState(CMessageData message)
	{
		CUpdateTrapVisualState_MessageData messageData = (CUpdateTrapVisualState_MessageData)message;
		if (messageData.m_delay > 0f)
		{
			yield return Timekeeper.instance.WaitForSeconds(messageData.m_delay);
		}
		CObjectTrap trap = messageData.m_trap;
		GameObject propGO = FindPropGameObject(trap);
		if (propGO == null)
		{
			yield return Timekeeper.instance.WaitForSeconds(0.001f);
			propGO = FindPropGameObject(trap);
			if (propGO == null)
			{
				yield break;
			}
		}
		List<Transform> children = new List<Transform>();
		RecursiveGetAllChildren(propGO.transform, children);
		int generationWaitCount = 0;
		while (children.Count == 1 && children[0].name == "Generated Content")
		{
			yield return 0;
			children.Clear();
			RecursiveGetAllChildren(propGO.transform, children);
			if (generationWaitCount++ > 1000)
			{
				Log.Error("Waiting infinitely for generated content: " + propGO);
				break;
			}
		}
		UpdateTrapVisualState(messageData.m_trap, propGO);
	}

	private void UpdateTrapVisualState(CObjectTrap trap, GameObject propGO)
	{
		List<Transform> list = new List<Transform>();
		RecursiveGetAllChildren(propGO.transform, list);
		bool flag = trap.HealValue > 0 || (trap.PositiveConditions != null && trap.PositiveConditions.Count > 0);
		bool flag2 = trap.DamageValue > 0 || (trap.Conditions != null && trap.Conditions.Count > 0);
		string text = null;
		if (flag & flag2)
		{
			text = "StateMixed";
		}
		else if (flag)
		{
			text = "StatePositive";
		}
		else if (flag2)
		{
			text = "StateNegative";
		}
		foreach (Transform item in list)
		{
			if (item.name.StartsWith("State"))
			{
				item.gameObject.SetActive(item.name == text);
			}
		}
	}

	private IEnumerator ChangePropVisualState(CMessageData message)
	{
		CChangePropVisualState_MessageData messageData = (CChangePropVisualState_MessageData)message;
		if (messageData.m_delay > 0f)
		{
			yield return Timekeeper.instance.WaitForSeconds(messageData.m_delay);
		}
		GameObject propGO = FindPropGameObject(messageData.m_prop);
		if (propGO == null)
		{
			yield return Timekeeper.instance.WaitForSeconds(0.001f);
			propGO = FindPropGameObject(messageData.m_prop);
			if (propGO == null)
			{
				yield break;
			}
		}
		List<Transform> children = new List<Transform>();
		RecursiveGetAllChildren(propGO.transform, children);
		int generationWaitCount = 0;
		while (children.Count == 1 && children[0].name == "Generated Content")
		{
			yield return 0;
			children.Clear();
			RecursiveGetAllChildren(propGO.transform, children);
			if (generationWaitCount++ > 1000)
			{
				Log.Error("Waiting infinitely for generated content: " + propGO);
				break;
			}
		}
		if (messageData.m_DestructionVFXDelay > 0f && !string.IsNullOrEmpty(messageData.m_DestructionVFXName))
		{
			List<Transform> list = new List<Transform>();
			List<Transform> list2 = new List<Transform>();
			foreach (Transform item in children)
			{
				if (item.name == messageData.m_stateName)
				{
					list.Add(item);
				}
				if (item.name == messageData.m_DestructionVFXName)
				{
					list2.Add(item);
				}
			}
			if (list2 != null && list != null)
			{
				List<Transform> childrenOfStateGo = new List<Transform>();
				foreach (Transform item2 in list)
				{
					item2.gameObject.SetActive(value: true);
					RecursiveGetAllChildren(item2, childrenOfStateGo);
				}
				foreach (Transform item3 in list2)
				{
					item3.gameObject.SetActive(value: true);
				}
				foreach (Transform item4 in childrenOfStateGo)
				{
					bool active = false;
					Transform transform = item4;
					while (transform != null)
					{
						if (list2.Contains(transform))
						{
							active = true;
							break;
						}
						transform = transform.parent;
					}
					item4.gameObject.SetActive(active);
				}
				yield return Timekeeper.instance.WaitForSeconds(messageData.m_DestructionVFXDelay);
				foreach (Transform item5 in childrenOfStateGo)
				{
					item5.gameObject.SetActive(value: true);
				}
			}
		}
		foreach (Transform item6 in children)
		{
			if (item6.name.StartsWith("State"))
			{
				item6.gameObject.SetActive(item6.name == messageData.m_stateName);
			}
		}
	}

