	[MessageHandler(CMessageData.MessageType.RefreshProps_VFX_LOS)]
	private void Handle_RefreshProps_VFX_LOS(CMessageData message)
	{
		CObjectProp[] props = ((CRefreshProps_VFX_LOS_MessageData)message).m_Props;
		foreach (CObjectProp cObjectProp in props)
		{
			GameObject gameObject = FindPropGameObject(cObjectProp);
			if (gameObject == null)
			{
				Log.Error($"Prop {cObjectProp} doesn't have game object");
				continue;
			}
			VFX_LOS[] componentsInChildren = gameObject.GetComponentsInChildren<VFX_LOS>();
			for (int j = 0; j < componentsInChildren.Length; j++)
			{
				componentsInChildren[j].RefreshLOS();
			}
		}
	}

	public void RecursiveGetAllChildren(Transform parent, List<Transform> res)
	{
		for (int i = 0; i < parent.childCount; i++)
		{
			Transform child = parent.GetChild(i);
			res.Add(child);
			RecursiveGetAllChildren(child, res);
		}
	}

	public Transform RecursiveFindChild(Transform parent, string childName)
	{
		Transform transform = null;
		for (int i = 0; i < parent.childCount; i++)
		{
			transform = parent.GetChild(i);
			if (transform.name == childName)
			{
				break;
			}
			transform = RecursiveFindChild(transform, childName);
			if (transform != null)
			{
				break;
			}
		}
		return transform;
	}

	private IEnumerator HidePropChild(CMessageData message)
	{
		CHidePropChild_MessageData messageData = (CHidePropChild_MessageData)message;
		if (messageData.m_delay > 0f)
		{
			yield return Timekeeper.instance.WaitForSeconds(messageData.m_delay);
		}
		GameObject gameObject = FindPropGameObject(messageData.m_prop);
		if (gameObject != null)
		{
			Transform transform = RecursiveFindChild(gameObject.transform, messageData.m_childName);
			if (transform != null)
			{
				transform.gameObject.SetActive(!messageData.m_hidden);
			}
		}
	}

