	{
		CTryPlayVfxOnTile_MessageData cTryPlayVfxOnTile_MessageData = (CTryPlayVfxOnTile_MessageData)message;
		CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[cTryPlayVfxOnTile_MessageData.m_ArrayIndex.X, cTryPlayVfxOnTile_MessageData.m_ArrayIndex.Y];
		GameObject propPrefab = GlobalSettings.GetPropPrefab(cTryPlayVfxOnTile_MessageData.m_VFXPropType);
		if (propPrefab == null)
		{
			Log.Error("Unable to find asset for vfx prop " + cTryPlayVfxOnTile_MessageData.m_VFXPropType);
			return;
		}
		Quaternion value = Quaternion.identity;
		if (cTryPlayVfxOnTile_MessageData.m_Rotation != null)
		{
			value = Quaternion.Euler(cTryPlayVfxOnTile_MessageData.m_Rotation.X, cTryPlayVfxOnTile_MessageData.m_Rotation.Y, cTryPlayVfxOnTile_MessageData.m_Rotation.Z);
		}
		else if (cTryPlayVfxOnTile_MessageData.m_faceTowards != default(Point))
		{
			ScenarioRuleLibrary.MF.ArrayIndexToCartesianCoord(cTryPlayVfxOnTile_MessageData.m_ArrayIndex, 1f, 1f, out var x, out var y);
			ScenarioRuleLibrary.MF.ArrayIndexToCartesianCoord(cTryPlayVfxOnTile_MessageData.m_faceTowards, 1f, 1f, out var x2, out var y2);
			value = Quaternion.LookRotation((new Vector3(x2, 0f, y2) - new Vector3(x, 0f, y)).normalized, Vector3.up);
		}
		TryPlayEffect(propPrefab, cClientTile.m_GameObject.transform, null, value);
	}

	[MessageHandler(CMessageData.MessageType.HideShowChildObject)]
	private void Handle_HideShowChildObject(CMessageData message)
	{
		HideShowChildObject_MessageData messageData = (HideShowChildObject_MessageData)message;
		StartCoroutine(Handle_HideShowChildObject(messageData));
	}

	private IEnumerator Handle_HideShowChildObject(HideShowChildObject_MessageData messageData)
	{
		if (EnvironmentLoader.Instance != null)
		{
			while (!EnvironmentLoader.Instance.IsLoadingComplete)
			{
				yield return new WaitForEndOfFrame();
			}
		}
		GameObject gameObject = FindClientActorGameObject(messageData.m_ActorSpawningMessage, shouldReturnDummyActorsProp: true);
		if (gameObject == null)
		{
			if (messageData.m_waitForActorCreation)
			{
				int attempts = 1000;
				while (gameObject == null && attempts > 0)
				{
					yield return null;
					gameObject = FindClientActorGameObject(messageData.m_ActorSpawningMessage, shouldReturnDummyActorsProp: true);
					attempts--;
				}
			}
			if (gameObject == null)
			{
				Log.Error("Unable to find GO for " + messageData.m_ActorSpawningMessage);
				yield break;
			}
		}
		GameObject gameObject2 = gameObject.FindInChildren(messageData.m_GOName, includeInactive: true);
		if (gameObject2 == null)
		{
			if (!messageData.m_SilentFail)
			{
				Log.Error("Unable to find child object in " + gameObject.name);
			}
		}
		else
		{
			gameObject2.SetActive(messageData.m_Show);
		}
	}

	[MessageHandler(CMessageData.MessageType.StartCinematic)]
	private void Handle_StartCinematic(CMessageData message)
	{
		StartCinematic_MessageData startCinematic_MessageData = (StartCinematic_MessageData)message;
		GameObject gameObject = UnityEngine.Object.Instantiate(GlobalSettings.GetCinematicPrefab(startCinematic_MessageData.m_PrefabName));
		PlayableDirector component = gameObject.GetComponent<PlayableDirector>();
		TimelineAsset timelineAsset = (TimelineAsset)component.playableAsset;
		TrackAsset key = (TrackAsset)timelineAsset.outputs.First().sourceObject;
		component.SetGenericBinding(key, Camera.main.gameObject);
		Transform[] componentsInChildren = gameObject.GetComponentsInChildren<Transform>();
		foreach (Transform transform in componentsInChildren)
		{
			CinematicPlaceholder component2 = transform.GetComponent<CinematicPlaceholder>();
			if (!component2 || string.IsNullOrEmpty(component2.ActorId))
			{
				continue;
			}
			GameObject gameObject2 = GameObject.Find(component2.ActorId);
			if (!gameObject2)
			{
				continue;
			}
			Animator componentInChildren = gameObject2.GetComponentInChildren<Animator>();
			if (!componentInChildren)
			{
				continue;
			}
			foreach (PlayableBinding output in timelineAsset.outputs)
			{
				TrackAsset key2 = (TrackAsset)output.sourceObject;
				Animator animator = component.GetGenericBinding(key2) as Animator;
				if (animator != null && animator.gameObject == transform.gameObject)
				{
					component.SetGenericBinding(key2, componentInChildren.gameObject);
					break;
				}
			}
		}
		StartCoroutine(WaitForCinematic(component, startCinematic_MessageData.m_NextPhase));
	}

	[MessageHandler(CMessageData.MessageType.AddCasterVFX)]
	private void Handle_AddCasterVFX(CMessageData message)
	{
		CAddCasterVFX_MessageData cAddCasterVFX_MessageData = (CAddCasterVFX_MessageData)message;
		GameObject propPrefab = GlobalSettings.GetPropPrefab(cAddCasterVFX_MessageData.m_VFXName);
		if (propPrefab == null)
		{
			Log.Error("Unable to find asset for vfx prop " + cAddCasterVFX_MessageData.m_VFXName);
			return;
		}
		propPrefab.name = cAddCasterVFX_MessageData.m_VFXName;
		StartCoroutine(Handle_AddCasterVFX(cAddCasterVFX_MessageData, propPrefab));
	}

	private IEnumerator Handle_AddCasterVFX(CAddCasterVFX_MessageData messageData, GameObject vfxPropGO)
	{
		if (messageData.m_delay > 0f)
		{
			yield return Timekeeper.instance.WaitForSeconds(messageData.m_delay);
		}
		int attempts = 10000;
		while (!TryPlayEffectOnActor(vfxPropGO, messageData.m_ActorSpawningMessage) && attempts > 0)
		{
			yield return null;
			attempts--;
		}
	}

	[MessageHandler(CMessageData.MessageType.RemoveCasterVFX)]
	private void Handle_RemoveCasterVFX(CMessageData message)
	{
		CRemoveCasterVFX_MessageData cRemoveCasterVFX_MessageData = (CRemoveCasterVFX_MessageData)message;
		if (cRemoveCasterVFX_MessageData == null)
		{
			return;
		}
		GameObject gameObject = FindClientActorGameObject(cRemoveCasterVFX_MessageData.m_ActorSpawningMessage);
		if (gameObject == null)
		{
			gameObject = GameObject.Find(cRemoveCasterVFX_MessageData.m_ActorSpawningMessage.ActorGuid);
			if (gameObject == null)
			{
				return;
			}
		}
		GameObject gameObject2 = null;
		foreach (Transform item in gameObject.transform)
		{
			if (!(item == null) && !string.IsNullOrEmpty(item.name) && item.name.Contains(cRemoveCasterVFX_MessageData.m_VFXName))
			{
				gameObject2 = item.gameObject;
				break;
			}
		}
		if (gameObject2 != null && !VFXShared.TryRecycleEffect(gameObject2))
		{
			ObjectPool.Recycle(gameObject2);
		}
	}

	private void SendMessageToWorldspace(CMessageData message)
	{
		try
		{
			foreach (GameObject clientActorObject in ClientActorObjects)
			{
				if (clientActorObject == null)
				{
					Log.ErrorFormat("Trying to access a null actorOriginallyAttacked game object");
					continue;
				}
				ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(clientActorObject);
				if (actorBehaviour == null)
				{
					Log.ErrorFormat("Trying to access a null ActorBehaviour for {0}", clientActorObject.name);
				}
				else if (actorBehaviour.Actor == null)
				{
					Log.ErrorFormat("Trying to access a null ActorBehaviour.Actor for {0}", clientActorObject.name);
				}
				else if (actorBehaviour.m_WorldspacePanelUI == null)
				{
					if (!actorBehaviour.Actor.IsDead)
					{
						Log.ErrorFormat("Trying to access a null m_WorldspacePanelUI for {0}", actorBehaviour.Actor.ActorLocKey() + GetActorIDForCombatLogIfNeeded(actorBehaviour.Actor));
					}
				}
				else
				{
					actorBehaviour.m_WorldspacePanelUI.OnMessage(message);
				}
			}
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred while processing SendMessageToWorldspace");
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00144", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
		}
	}

