	private void EnableEndTurnButton(CPlayerActor currentPlayer)
	{
		try
		{
			string translation = LocalizationManager.GetTranslation(currentPlayer.ActorLocKey());
			string text;
			ReadyButton.EButtonState state;
			if (m_CurrentState.IsOnEscapeZone(currentPlayer) && m_CurrentState.AllowEscapeZone(currentPlayer))
			{
				text = LocalizationManager.GetTranslation("GUI_ESCAPE");
				state = ReadyButton.EButtonState.EREADYBUTTONESCAPE;
				string text2 = string.Format(LocalizationManager.GetTranslation("GUI_END_TURN"), translation);
				m_SkipButton.Toggle(active: true, text2);
			}
			else
			{
				text = string.Format(LocalizationManager.GetTranslation(currentPlayer.IsTakingExtraTurn ? "GUI_END_EXTRA_TURN" : "GUI_END_TURN"), translation);
				state = ReadyButton.EButtonState.EREADYBUTTONENDTURN;
				m_SkipButton.Toggle(active: false);
			}
			readyButton.Toggle(active: true, state, text, hideOnClick: true, glowingEffect: true);
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred while processing EnableEndTurnButton");
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00145", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
		}
	}

	private void ShowAbilityHelpBoxTooltip(CAbility ability, bool clearOldInfo = true)
	{
		string text = ability.HelpBoxTooltipLocKey;
		TValue miscVar = ability.GetMiscVar("HelpBoxTooltipLocKeyOverride");
		string text2 = null;
		if (!miscVar.isUnknown)
		{
			CVars cVars = new CVars();
			CVarsContext context = new CVarsContext(cVars, ability.VarsContext);
			cVars.Set("IsHost", !FFSNetwork.IsOnline || FFSNetwork.IsHost);
			cVars.Set("Ability", new TValue(ability));
			text2 = miscVar.GetString(context);
		}
		if (!string.IsNullOrEmpty(text2))
		{
			text = text2;
		}
		string text3 = (text.IsNullOrEmpty() ? "" : LocalizationManager.GetTranslation(text));
		text3 = text3.Replace("{CURRENT_TARGETS}", (ability.NumberTargets - ability.NumberTargetsRemaining).ToString()).Replace("{TOTAL_TARGETS}", ability.NumberTargets.ToString());
		text3 = text3.Replace("{STRENGTH}", ability.Strength.ToString());
		text3 = text3.Replace("{RANGE}", ability.Range.ToString());
		string newValue = "";
		if (GameState.CurrentActor != null)
		{
			newValue = LocalizationManager.GetTranslation(GameState.CurrentActor.ActorLocKey());
		}
		text3 = text3.Replace("{CURRENT_ACTOR_CLASS}", newValue);
		if (ability?.MiscVars != null)
		{
			List<string> list = new List<string>();
			foreach (var miscVar2 in ability.MiscVars)
			{
				if (miscVar2.Item1.Contains("HelpBoxArg"))
				{
					TValue item = miscVar2.Item2;
					string text4 = item.GetString(ability.VarsContext);
					if (LocalizationManager.TryGetTranslation(text4, out var translation))
					{
						list.Add(translation);
					}
					else
					{
						list.Add(text4);
					}
				}
			}
			if (list.Count > 0)
			{
				string format = text3;
				object[] args = list.ToArray();
				text3 = string.Format(format, args);
			}
		}
		if (ability.GetMiscVar("UseHelpBoxTooltipAsTooltipTitle").GetBool())
		{
			Singleton<UIUseItemsBar>.Instance.SetCustomTooltips(ability.HelpBoxTooltipLocKey, ability.HelpBoxTooltipLocKey);
		}
		Singleton<HelpBox>.Instance.ShowTranslated(text3, ability, HelpBox.FormatTarget.NONE, null, clearOldInfo);
		ScenarioScriptFrontend.ShowAbilityHelpBoxTooltip(ability);
		if (FFSNetwork.IsOnline)
		{
			Singleton<UIScenarioMultiplayerController>.Instance.OnUpdateAbilityHelpText(ability);
		}
	}

	public void LogScenarioResult(SEventActorFinishedScenario.EScenarioResult result)
	{
		if (AdventureState.MapState?.MapParty?.SelectedCharacters == null)
		{
			return;
		}
		foreach (CMapCharacter selectedCharacter in AdventureState.MapState.MapParty.SelectedCharacters)
		{
			CPlayerActor actor = selectedCharacter.GetActor();
			if (actor != null)
			{
				SEventLogMessageHandler.AddEventLogMessage(new SEventActorFinishedScenario(result, new SEventActor.SEventActorBaseData(ESESubTypeActor.ActorFinishedScenario, actor)));
			}
		}
	}

	public void WinScenario(bool forceUI = true, int forcedConclusionindex = -1)
	{
		if (forcedConclusionindex != -1)
		{
			ScenarioManager.CurrentScenarioState.ForcedConclusionIndex = forcedConclusionindex;
		}
		Singleton<FHScenarioViewController>.Instance?.WinScenario();
		StartCoroutine(WinScenarioCoroutine(forceUI));
	}

	private IEnumerator WaitForEndOfScenarioRewards(bool won)
	{
		WaitingForEndOfScenarioRewards = true;
		readyButton.Toggle(active: false);
		if (FFSNetwork.IsOnline)
		{
			Singleton<UIReadyToggle>.Instance.ToggleVisibility(visible: false);
		}
		ScenarioRuleClient.ApplyScenarioRewards(won);
		do
		{
			yield return null;
		}
		while ((Singleton<LevelEventsController>.InstanceFast?.IsBusy ?? false) || ScenarioRuleClient.IsProcessingOrMessagesQueued || s_Choreographer.m_MessageQueue.Count > 0 || (Singleton<ScenarioRewardManager>.Instance?.rewardInfoStack?.Count).GetValueOrDefault() > 0 || (m_WaitState != null && m_WaitState.m_State == ChoreographerStateType.WaitingForRewardsProcess));
		WaitingForEndOfScenarioRewards = false;
	}

	private IEnumerator WinScenarioCoroutine(bool forceUI)
	{
		Log.SimpleInfo("Entered win scenario coroutine");
		if (IsRestarting || ScenarioRuleClient.ScenarioRuleClientStopped)
		{
			Log.SimpleInfo("Win scenario coroutine exited early. IsRestarting: " + IsRestarting + ". ScenarioRuleClientStopped: " + ScenarioRuleClient.ScenarioRuleClientStopped);
			yield break;
		}
		Singleton<CardsHandManager>.Instance.DisableHands();
		yield return WaitForEndOfScenarioRewards(won: true);
		IsRestarting = true;
		yield return SceneController.Instance.EndScenarioSafely();
		IsRestarting = false;
		try
		{
			if (ScenarioManager.Scenario != null)
			{
				if (!forceUI && ScenarioManager.Scenario.CurrentScenarioResult == SEventActorFinishedScenario.EScenarioResult.Win)
				{
					Log.SimpleInfo("Win scenario coroutine exited early. CurrentScenarioResult != Win");
					yield break;
				}
				ScenarioManager.Scenario.CurrentScenarioResult = SEventActorFinishedScenario.EScenarioResult.Win;
			}
			Log.SimpleInfo("Scenario Won");
			LogScenarioResult(SEventActorFinishedScenario.EScenarioResult.Win);
			Singleton<CardsHandManager>.Instance.IsFullDeckPreviewAllowed = false;
			Singleton<PhaseBannerHandler>.Instance.Disable();
			DisableNextPhaseButtons();
			SaveData.Instance.Global.CurrentAdventureData?.AdventureMapState?.ApplyRoundChestRewards();
			Action<UnityAction> onFinishedResultAnimation = (UnityAction endScenarioAction) =>
			{
				if (LevelEventsController.s_EventsControllerActive)
				{
					Singleton<LevelEventsController>.Instance.CompleteLevel(completionSuccess: true, userQuit: false, endScenarioAction);
				}
				else
				{
					endScenarioAction?.Invoke();
				}
			};
			foreach (CActor allActor in ScenarioManager.Scenario.AllActors)
			{
				GameState.LogEndTurn(allActor);
			}
			UINewAdventureResultsManager.Implementation.Show(1.5f, EndGame, EResult.Win, UIResultsManager.ERetryOptionType.None, null, onFinishedResultAnimation);
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred while processing Scenario Win");
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00146", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
		}
	}

