	private IEnumerator LoseScenarioCoroutine(bool forceUI)
	{
		Log.SimpleInfo("Entered lose scenario coroutine");
		if (Singleton<TakeDamagePanel>.Instance.IsOpen)
		{
			Singleton<TakeDamagePanel>.Instance.ResetAndHide();
		}
		if (IsRestarting || ScenarioRuleClient.ScenarioRuleClientStopped)
		{
			Log.SimpleInfo("Lose scenario coroutine exited early. IsRestarting: " + IsRestarting + ". ScenarioRuleClientStopped: " + ScenarioRuleClient.ScenarioRuleClientStopped);
			yield break;
		}
		Singleton<CardsHandManager>.Instance.DisableHands();
		yield return WaitForEndOfScenarioRewards(won: false);
		IsRestarting = true;
		yield return SceneController.Instance.EndScenarioSafely();
		IsRestarting = false;
		try
		{
			if (ScenarioManager.Scenario != null)
			{
				if (!forceUI && ScenarioManager.Scenario.CurrentScenarioResult == SEventActorFinishedScenario.EScenarioResult.Lose)
				{
					Log.SimpleInfo("Lose scenario coroutine exited early. CurrentScenarioResult != Lose");
					yield break;
				}
				ScenarioManager.Scenario.CurrentScenarioResult = SEventActorFinishedScenario.EScenarioResult.Lose;
			}
			Log.SimpleInfo("Scenario Lost");
			LogScenarioResult(SEventActorFinishedScenario.EScenarioResult.Lose);
			Singleton<CardsHandManager>.Instance.IsFullDeckPreviewAllowed = false;
			Singleton<PhaseBannerHandler>.Instance.Disable();
			DisableNextPhaseButtons();
			SaveData.Instance.Global.CurrentAdventureData?.AdventureMapState?.ApplyRoundChestRewards();
			Action<UnityAction> onFinishedResultAnimation = (UnityAction endScenarioAction) =>
			{
				if (LevelEventsController.s_EventsControllerActive)
				{
					Singleton<LevelEventsController>.Instance.CompleteLevel(completionSuccess: false, userQuit: false, endScenarioAction);
				}
				else
				{
					endScenarioAction?.Invoke();
				}
			};
			if (SaveData.Instance.Global.GameMode == EGameMode.SingleScenario || SaveData.Instance.Global.GameMode == EGameMode.Autotest)
			{
				Singleton<UIResultsManager>.Instance.Show(1.5f, EndGame, EResult.Lose);
				yield break;
			}
			bool num = SaveData.Instance.Global.GameMode == EGameMode.FrontEndTutorial || ScenarioManager.CurrentScenarioState?.ScenarioSetup?.IsInPrologue == true || IsInNoPartyCampaign();
			bool flag = true;
			if (SaveData.Instance?.Global?.CurrentAdventureData?.FrosthavenCampaign?.ActiveScenario?.Def?.CanNotBeReplayedInTactical == true)
			{
				flag = false;
			}
			if (num)
			{
				UINewAdventureResultsManager.Implementation.Show(1.5f, EndGame, EResult.Lose, UIResultsManager.ERetryOptionType.Only, UIManager.RestartScenarioFromInitial, onFinishedResultAnimation);
			}
			else
			{
				UINewAdventureResultsManager.Implementation.Show(1.5f, EndGame, EResult.Lose, UIResultsManager.ERetryOptionType.Additional, flag ? new UnityAction(UIManager.RegenerateAndRestartScenarioKeepGoldAndXP) : null, onFinishedResultAnimation);
			}
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred while processing Scenario Lose");
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00147", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
		}
	}

