		StartCoroutine(AbandonScenarioCoroutine());
	}

	private IEnumerator AbandonScenarioCoroutine()
	{
		Log.SimpleInfo("Entered abandon scenario coroutine");
		if (IsRestarting || ScenarioRuleClient.ScenarioRuleClientStopped)
		{
			Log.SimpleInfo("Abandon scenario coroutine exited early. IsRestarting: " + IsRestarting + ". ScenarioRuleClientStopped: " + ScenarioRuleClient.ScenarioRuleClientStopped);
			yield break;
		}
		Singleton<CardsHandManager>.Instance.DisableHands();
		if (FFSNetwork.IsHost)
		{
			Synchronizer.SendSideAction(GameActionType.AbandonScenario);
		}
		yield return WaitForEndOfScenarioRewards(won: false);
		IsRestarting = true;
		yield return SceneController.Instance.EndScenarioSafely();
		IsRestarting = false;
		try
		{
			SaveData.Instance.Global.DisallowSpeedUp();
			Log.SimpleInfo("Scenario Abandoned");
			LogScenarioResult(SEventActorFinishedScenario.EScenarioResult.Resign);
			Singleton<CardsHandManager>.Instance.IsFullDeckPreviewAllowed = false;
			if (LevelEventsController.s_EventsControllerActive)
			{
				Singleton<LevelEventsController>.Instance.CompleteLevel(completionSuccess: false, userQuit: true);
			}
			SaveData.Instance.Global.CurrentAdventureData?.AdventureMapState?.ApplyRoundChestRewards();
			if (SaveData.Instance.Global.GameMode == EGameMode.SingleScenario || SaveData.Instance.Global.GameMode == EGameMode.Autotest)
			{
				Singleton<UIResultsManager>.Instance.Show(1.5f, EndGame, EResult.Resign);
			}
			else
			{
				bool num = SaveData.Instance.Global.GameMode == EGameMode.FrontEndTutorial || ScenarioManager.CurrentScenarioState?.ScenarioSetup?.IsInPrologue == true || IsInNoPartyCampaign();
				bool flag = true;
				if (SaveData.Instance?.Global?.CurrentAdventureData?.FrosthavenCampaign?.ActiveScenario?.Def?.CanNotBeReplayedInTactical == true)
				{
					flag = false;
				}
				if (num)
				{
					UINewAdventureResultsManager.Implementation.Show(1.5f, EndGame, EResult.Resign, UIResultsManager.ERetryOptionType.Only, UIManager.RestartScenarioFromInitial);
				}
				else
				{
					UINewAdventureResultsManager.Implementation.Show(1.5f, EndGame, EResult.Resign, UIResultsManager.ERetryOptionType.Additional, flag ? new UnityAction(UIManager.RegenerateAndRestartScenarioKeepGoldAndXP) : null);
				}
			}
			Singleton<PhaseBannerHandler>.Instance.Disable();
			DisableNextPhaseButtons();
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred while processing Abandon Scenario Lose");
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00148", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
		}
	}

	public void ProcessAutosavesThreaded()
	{
		ScenarioRuleClient.ExecuteSRLCommand(null, null, () =>
		{
			ProcessAutosavesThread();
		}, "AUTOSAVE");
	}

	public async Task ProcessAutosavesThread()
	{
		SaveData.Instance.IsSavingThreadActive = true;
		ScenarioRuleLibrary.ScenarioState currentState = await m_CurrentState.CopyScenarioState();
		if (SaveData.Instance.Global.GameMode == EGameMode.Campaign)
		{
			await SaveData.Instance.Global.CurrentAdventureData.UpdateScenarioCheckpoint(currentState);
		}
		else if (SaveData.Instance.Global.GameMode == EGameMode.SingleScenario)
		{
			await SaveData.Instance.Global.CurrentAdventureData.UpdateScenarioCheckpoint(currentState);
		}
		SaveData.Instance.IsSavingThreadActive = false;
	}

	private void ReplaceInteractAnimationStates(CActor actor, List<string> orderedStates)
	{
		if (!actor.Interacting || orderedStates == null)
		{
			return;
		}
		int i = 0;
		while (i < orderedStates.Count)
		{
			if (orderedStates[i] != null)
			{
				string text = interactOverrides.Find((string s) => s.Contains(orderedStates[i]));
				if (text != null)
				{
					orderedStates[i] = text;
				}
			}
			int num = i + 1;
			i = num;
		}
	}

	public void ProcessActorAnimation(CAbility ability, CActor defaultActorToApplyTo, List<string> orderedStatesToTry, out bool animationShouldPlay, out CActor animatingActorToWaitFor, bool ignoreSkipAnimation = false)
	{
		ReplaceInteractAnimationStates(defaultActorToApplyTo, orderedStatesToTry);
		if (ability != null && ability is CAbilityTargeting { OriginatesFromAnAura: not false } cAbilityTargeting)
		{
			animatingActorToWaitFor = null;
			bool flag = false;
			if (cAbilityTargeting.AuraTriggerAbilityAnimType == CActiveBonus.EAuraTriggerAbilityAnimType.AnimateAuraOriginator || cAbilityTargeting.AuraTriggerAbilityAnimType == CActiveBonus.EAuraTriggerAbilityAnimType.AnimateBoth)
			{
				List<string> list = orderedStatesToTry?.ToList() ?? new List<string>();
				if (!string.IsNullOrEmpty(cAbilityTargeting.OriginatingAuraAnimOverload))
				{
					list.Insert(0, cAbilityTargeting.OriginatingAuraAnimOverload);
				}
				GameObject gameObject = FindClientActorGameObject(cAbilityTargeting.OriginatingAuraOwner, shouldReturnDummyActorsProp: true);
				if (gameObject != null)
				{
					flag = PlayFirstAvailableAnimationStateOnObject(gameObject, list);
				}
				animatingActorToWaitFor = cAbilityTargeting.OriginatingAuraOwner;
			}
			bool flag2 = false;
			if (animatingActorToWaitFor != defaultActorToApplyTo && (cAbilityTargeting.AuraTriggerAbilityAnimType == CActiveBonus.EAuraTriggerAbilityAnimType.AnimateAuraReceiver || cAbilityTargeting.AuraTriggerAbilityAnimType == CActiveBonus.EAuraTriggerAbilityAnimType.AnimateBoth))
			{
				GameObject gameObject2 = FindClientActorGameObject(defaultActorToApplyTo, shouldReturnDummyActorsProp: true);
				if (gameObject2 != null)
				{
					flag2 = PlayFirstAvailableAnimationStateOnObject(gameObject2, orderedStatesToTry);
				}
				animatingActorToWaitFor = defaultActorToApplyTo;
			}
			animationShouldPlay = flag | flag2;
		}
		else if (ability != null && ((!ignoreSkipAnimation && ability.SkipAnim) || ability.IsModifierAbility))
		{
			animatingActorToWaitFor = defaultActorToApplyTo;
			animationShouldPlay = false;
		}
		else
		{
			GameObject objectToAnimate = FindClientActorGameObject(defaultActorToApplyTo, shouldReturnDummyActorsProp: true);
			animationShouldPlay = PlayFirstAvailableAnimationStateOnObject(objectToAnimate, orderedStatesToTry);
			animatingActorToWaitFor = defaultActorToApplyTo;
		}
	}

	private bool PlayFirstAvailableAnimationStateOnObject(GameObject objectToAnimate, List<string> statesToTry)
	{
		if (objectToAnimate == null || statesToTry == null || statesToTry.Count == 0)
		{
			return false;
		}
		Animator gameObjectAnimator = MF.GetGameObjectAnimator(objectToAnimate);
		if (gameObjectAnimator == null || !gameObjectAnimator.enabled)
		{
			return false;
		}
		if (gameObjectAnimator != null)
		{
			for (int i = 0; i < statesToTry.Count; i++)
			{
				if (MF.AnimatorPlay(gameObjectAnimator, statesToTry[i]))
				{
					return true;
				}
			}
		}
		return false;
	}

	private IEnumerator MoveProp(CMoveProp_MessageData messageData)
	{
		GameObject propGO = FindPropGameObject(messageData.m_MoveProp);
		CClientTile clientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[messageData.m_MoveToTile.m_ArrayIndex.X, messageData.m_MoveToTile.m_ArrayIndex.Y];
		propGO.transform.SetParent(clientTile.m_GameObject.transform.parent);
		Vector3 startPosition = propGO.transform.position;
		if (messageData.m_MoveFromTile != null)
		{
			CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[messageData.m_MoveFromTile.m_ArrayIndex.X, messageData.m_MoveFromTile.m_ArrayIndex.Y];
			startPosition = cClientTile.m_GameObject.transform.position;
		}
		Vector3 endPosition = clientTile.m_GameObject.transform.position;
		float num = Vector3.Distance(startPosition, endPosition);
		float locoPeriod = (Mathf.Approximately(num, 0f) ? 0.1f : num) / messageData.m_MoveSpeed;
		float locoTimer = locoPeriod;
		float startTime = Timekeeper.instance.m_GlobalClock.time;
		using (WaitPendingAnimationScope(messageData))
		{
			float lerpProgress = 0f;
			while (lerpProgress < 1f)
			{
				lerpProgress = Math.Max(0f, 1f - (locoTimer - (Timekeeper.instance.m_GlobalClock.time - startTime)) / locoPeriod);
				propGO.transform.position = Vector3.Lerp(startPosition, endPosition, lerpProgress);
				if (messageData.m_MoveFromRotation != null && messageData.m_MoveToRotation != null)
				{
					Vector3 euler = GloomUtility.CVToV(messageData.m_MoveFromRotation);
					Quaternion rotation = Quaternion.Lerp(b: Quaternion.Euler(GloomUtility.CVToV(messageData.m_MoveToRotation)), a: Quaternion.Euler(euler), t: lerpProgress);
					propGO.transform.rotation = rotation;
				}
				yield return null;
			}
		}
		if (messageData.m_MoveProp.Rotation != null)
		{
			propGO.transform.eulerAngles = new Vector3(0f, messageData.m_MoveProp.Rotation.Y, 0f);
		}
		if (messageData.m_MoveLogicPos)
		{
			messageData.m_MoveProp.SetLocation(new TileIndex(clientTile.m_Tile.m_ArrayIndex), GloomUtility.VToCV(propGO.transform.position), GloomUtility.VToCV(propGO.transform.eulerAngles));
		}
		clientTile.m_TileBehaviour.RefreshWorldSpaceIcon();
		if (messageData.m_OnFinish != null)
		{
			messageData.m_OnFinish();
		}
	}

	public IEnumerator SpawnProp(CSpawn_MessageData messageData, bool isPlayMode = true)
	{
		if (isPlayMode && messageData.m_SpawnDelay > 0f)
		{
			using (new MiniProfilerScope("SpawnProp.Delay"))
			{
				using (WaitPendingAnimationScope(messageData))
				{
					yield return Timekeeper.instance.WaitForSeconds(messageData.m_SpawnDelay);
				}
			}
		}
		SpawnPropInstant(messageData, isPlayMode);
	}

	public void SpawnPropInstant(CSpawn_MessageData messageData, bool isPlayMode = true)
	{
		using (new MiniProfilerScope("SpawnPropInstant"))
		{
			if (messageData.m_Prop.RuntimeAttachedSpawner != null && messageData.m_Prop.RuntimeAttachedSpawner.Prop == null)
			{
				return;
			}
			CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[messageData.m_Prop.ArrayIndex.X, messageData.m_Prop.ArrayIndex.Y];
			if (cClientTile == null || cClientTile.m_GameObject == null)
			{
				throw new Exception($"Unable to find tile {messageData.m_Prop.ArrayIndex}");
			}
			GameObject gameObject = cClientTile?.m_GameObject?.transform.parent?.Find(messageData?.m_Prop?.InstanceName ?? "")?.gameObject;
			if (gameObject == null)
			{
				gameObject = cClientTile?.m_GameObject1?.transform.parent?.Find(messageData?.m_Prop?.InstanceName ?? "")?.gameObject;
			}
			if (gameObject == null && messageData != null && messageData.m_Prop?.InstanceName != null)
			{
				gameObject = FindPropGameObject(messageData.m_Prop);
			}
			bool flag = gameObject != null;
			bool flag2 = !DontRotate(messageData.m_Prop);
			if (!flag)
			{
				using (new MiniProfilerScope("SpawnProp.Instantiate"))
				{
					GameObject propPrefab = GlobalSettings.GetPropPrefab(messageData.m_Prop.PrefabName);
					if (propPrefab == null)
					{
						throw new Exception("Unable to find prop " + messageData.m_Prop.PrefabName);
					}
					Vector3 position = cClientTile.m_GameObject.transform.position;
					Vector3 euler = (((messageData.m_Prop.Rotation != null) & flag2) ? new Vector3(0f, messageData.m_Prop.Rotation.Y, 0f) : Vector3.zero);
					gameObject = (isPlayMode ? new Func<GameObject, Vector3, Quaternion, Transform, GameObject>(UnityEngine.Object.Instantiate) : new Func<GameObject, Vector3, Quaternion, Transform, GameObject>(SceneUtil.Instantiate))(propPrefab, position, Quaternion.Euler(euler), cClientTile.m_GameObject.transform.parent);
					gameObject.name = messageData.m_Prop.InstanceName;
					messageData.m_Prop.SetLocation(new TileIndex(cClientTile.m_Tile.m_ArrayIndex), GloomUtility.VToCV(gameObject.transform.position), messageData.m_Prop.Rotation);
					if (EnvironmentLoader.IsInstanceValid && EnvironmentLoader.Instance.IsLoadingComplete)
					{
						EnvironmentLoader.Instance.AddProp(gameObject, messageData.m_Prop.PropGuid);
					}
				}
			}
			else if (gameObject != null)
			{
				BreakableObject componentInChildren = gameObject.GetComponentInChildren<BreakableObject>(includeInactive: true);
				if (componentInChildren != null)
				{
					componentInChildren.Restore();
				}
				PropHealthState[] array = gameObject?.GetComponentsInChildren<PropHealthState>(includeInactive: true);
				for (int i = 0; i < array.Length; i++)
				{
					array[i].ResetDeathDisolve();
				}
				Vector3 position2 = cClientTile.m_GameObject.transform.position;
				Vector3 euler2 = (((messageData.m_Prop.Rotation != null) & flag2) ? new Vector3(0f, messageData.m_Prop.Rotation.Y, 0f) : Vector3.zero);
				if (flag2 && !(messageData.m_Prop is CObjectDoor) && (messageData.m_Prop.Rotation != null || cClientTile.m_GameObject.transform.parent != gameObject.transform.parent))
				{
					gameObject.transform.SetParent(cClientTile.m_GameObject.transform.parent);
					gameObject.transform.rotation = Quaternion.Euler(euler2);
					gameObject.transform.position = position2;
				}
			}
			UnityGameEditorObject component = gameObject.GetComponent<UnityGameEditorObject>();
			if (component == null)
			{
				throw new Exception("No UnityGameEditorObject script found on Trap " + gameObject.name);
			}
			component.PropObject = messageData.m_Prop;
			if (!flag)
			{
				EnvironmentLoader.Instance.OnRuntimePropSpawn(gameObject, messageData.m_Prop, cClientTile);
			}
			if (flag)
			{
				if (messageData.m_Prop is CObjectDoor cObjectDoor)
				{
					MF.GameObjectAnimatorPlay(gameObject, cObjectDoor.Activated ? "Open" : "Idle");
					if (cObjectDoor.DoorIsLocked)
					{
						LockUnlockedDoor(cObjectDoor);
					}
					else
					{
						UnlockLockedDoorWithoutOpening(cObjectDoor);
					}
					if (ScenarioScript.current != null && ScenarioScript.current.LoopUnopenedDoorParticlesOnLoad())
					{
						ParticleSystem[] componentsInChildren = gameObject.GetComponentsInChildren<ParticleSystem>();
						if (componentsInChildren != null && !cObjectDoor.Activated)
						{
							ParticleSystem[] array2 = componentsInChildren;
							foreach (ParticleSystem obj in array2)
							{
								ParticleSystem.MainModule main = obj.main;
								main.loop = true;
								obj.Play();
							}
						}
					}
				}
				else if (messageData.m_Prop is CObjectTrap trap)
				{
					UpdateTrapVisualState(trap, gameObject);
				}
				else if (messageData.m_Prop is CObjectChest)
				{
					PlayableDirector componentInChildren2 = gameObject.GetComponentInChildren<PlayableDirector>();
					if (componentInChildren2 != null)
					{
						componentInChildren2.Stop();
						componentInChildren2.time = 0.0;
						componentInChildren2.Evaluate();
					}
				}
				else if (gameObject != null)
				{
					BreakableObject componentInChildren3 = gameObject.GetComponentInChildren<BreakableObject>(includeInactive: true);
					if (componentInChildren3 != null)
					{
						componentInChildren3.Restore();
					}
					PropHealthState[] array3 = gameObject?.GetComponentsInChildren<PropHealthState>(includeInactive: true);
					if (array3 != null && array3.Length != 0)
					{
						CObjectActor runtimeAttachedActor = messageData.m_Prop.RuntimeAttachedActor;
						PropHealthState[] array = array3;
						foreach (PropHealthState propHealthState in array)
						{
							propHealthState.ResetDeathDisolve();
							if (runtimeAttachedActor != null)
							{
								propHealthState.UpdateState(runtimeAttachedActor.Health, runtimeAttachedActor.MaxHealth, runtimeAttachedActor.IsDead);
							}
						}
					}
					DelayedDestroyProp[] array4 = gameObject?.GetComponentsInChildren<DelayedDestroyProp>(includeInactive: true);
					if (array4 != null && array4.Length != 0)
					{
						DelayedDestroyProp[] array5 = array4;
						for (int i = 0; i < array5.Length; i++)
						{
							array5[i].Restore();
						}
					}
				}
			}
			if (flag)
			{
				return;
			}
			PropParent orAdd = gameObject.GetOrAdd<PropParent>();
			orAdd.Init(placedBeforehand: false);
			ProceduralMapTile componentInParent = orAdd.GetComponentInParent<ProceduralMapTile>();
			if (componentInParent != null)
			{
				orAdd.SetPropLighting(visible: true, componentInParent.Ambience);
			}
			if (LevelEditorController.s_Instance.IsEditing || LevelEditorController.s_Instance.IsPreviewingLevel || SaveData.Instance.Global.CurrentlyPlayingCustomLevel || !isPlayMode)
			{
				CCustomLevelData cCustomLevelData = (LevelEditorController.s_Instance.IsEditing ? SaveData.Instance.Global.CurrentEditorLevelData : SaveData.Instance.Global.CurrentCustomLevelData);
				if (cCustomLevelData.HasApparanceOverrides)
				{
					CApparanceOverrideDetails apparanceOverrideDetailsForGUID = cCustomLevelData.GetApparanceOverrideDetailsForGUID(messageData.m_Prop.PropGuid);
					if (apparanceOverrideDetailsForGUID != null)
					{
						GameObject gameObject2 = m_MapSceneRoot.FindInChildren(messageData.m_Prop.InstanceName, includeInactive: true);
						if (gameObject2 != null)
						{
							gameObject2.GetComponent<ProceduralStyle>()?.InitialiseWithOverride(apparanceOverrideDetailsForGUID);
						}
					}
				}
			}
			if (isPlayMode)
			{
				if (messageData.m_Prop.ObjectType == ScenarioManager.ObjectImportType.PressurePlate && messageData.m_Prop.Activated)
				{
					GameObject propGO = gameObject;
					StartCoroutine(PrimePropActivationAnimation(propGO, "Pressed"));
				}
				cClientTile.m_TileBehaviour.RefreshWorldSpaceIcon();
				if (messageData.m_Prop is CObjectDoor cObjectDoor2)
				{
					if (cObjectDoor2.DoorHasExtraLock)
					{
						LockUnlockedDoor(cObjectDoor2);
					}
					else
					{
						UnlockLockedDoorWithoutOpening(cObjectDoor2);
					}
				}
				if ((bool)gameObject.GetComponentInChildren<PropDynamicYPos>())
				{
					IEnumerable<CObjectProp> enumerable = cClientTile.m_Tile.m_Props.Where((CObjectProp p) => p.ObjectType == ScenarioManager.ObjectImportType.MoneyToken);
					int num = enumerable.Count();
					if (num > 1)
					{
						Vector3 vector = new Vector3(0f, 0f, 0.4f);
						float num2 = 360f / (float)num;
						float num3 = 0f;
						foreach (CObjectProp item in enumerable)
						{
							GameObject gameObject3 = FindPropGameObject(item);
							if ((bool)gameObject3)
							{
								PropDynamicYPos componentInChildren4 = gameObject3.GetComponentInChildren<PropDynamicYPos>();
								if ((bool)componentInChildren4)
								{
									Vector3 vector2 = Quaternion.Euler(new Vector3(0f, num3, 0f)) * vector;
									componentInChildren4.HorizontalOffset = new Vector2(vector2.x, vector2.z);
								}
								num3 += num2;
							}
						}
					}
				}
				OnPropSpawned(gameObject, messageData.m_Prop);
			}
			Watchman.Instance.Complete(messageData.m_Prop.InstanceName);
		}
		static bool DontRotate(CObjectProp prop)
		{
			if (!(prop is CObjectHazardousTerrain) && !(prop is CObjectIceTerrain) && prop.PropType != EPropType.TerrainIce && prop.PropType != EPropType.TerrainHotCoals && prop.PropType != EPropType.TerrainThorns)
			{
				return prop.PropType == EPropType.TerrainWater;
			}
			return true;
		}
	}

	private IEnumerator DestroyPropDelayedCoro(float destroyDelay, CObjectProp destroyProp, CTile targetTile = null, bool forceDestroy = false)
	{
		if (destroyDelay > 0f)
		{
			using (WaitPendingAnimationScope(destroyProp))
			{
				yield return Timekeeper.instance.WaitForSeconds(destroyDelay);
			}
		}
		DestroyPropImmediate(destroyProp, targetTile, forceDestroy);
	}

	public static void TryPlugTerrainHole(CObjectProp prop, GameObject propGO)
	{
		if (!(prop is CObjectDifficultTerrain) && !(prop is CObjectHazardousTerrain) && !(prop is CObjectIceTerrain) && !(propGO?.GetComponentInChildren<ProceduralTile>() != null))
		{
			return;
		}
		string mapGuid = prop.PropTile.m_HexMap.MapGuid;
		foreach (Point tile2 in prop.GetTiles())
		{
			CTile tile = ScenarioManager.GetTile(tile2);
			if (tile.FindDoor() == null)
			{
				CClientTile cClientTile = ClientScenarioManager.s_ClientScenarioManager.ClientTileArray[tile2.X, tile2.Y];
				EnvironmentLoader.Instance.PlugTerrainHole(cClientTile.m_GameObject.transform.position, tile?.m_Hex?.TileGuid, mapGuid, propGO);
			}
		}
	}

	public void DestroyPropImmediate(CObjectProp destroyProp, CTile targetTile = null, bool forceDestroy = false)
	{
		GameObject gameObject = FindPropGameObject(destroyProp);
		if (gameObject == null)
		{
			return;
		}
		PropHealthState[] array = gameObject?.GetComponentsInChildren<PropHealthState>(includeInactive: true);
		TryPlugTerrainHole(destroyProp, gameObject);
		if (forceDestroy)
		{
			(gameObject?.GetComponent<UnityGameEditorObject>())?.ReleasePathing();
			EnvironmentLoader.Instance.BeforePropDestroyed(gameObject, destroyProp);
			UnityEngine.Object.Destroy(gameObject);
		}
		else
		{
			BreakableObject[] array2 = gameObject?.GetComponentsInChildren<BreakableObject>();
			if (array2 != null && array2.Length != 0)
			{
				BreakableObject[] array3 = array2;
				for (int i = 0; i < array3.Length; i++)
				{
					array3[i].BreakObject();
				}
			}
			else
			{
				DelayedDestroyProp[] array4 = gameObject?.GetComponentsInChildren<DelayedDestroyProp>();
				if (array4 != null && array4.Length != 0)
				{
					DelayedDestroyProp[] array5 = array4;
					for (int i = 0; i < array5.Length; i++)
					{
						array5[i].DelayDestroy(destroyProp);
					}
				}
				else if (array != null && array.Length != 0)
				{
					int currentHealth = 0;
					int maxHealth = 1;
					bool flag = true;
					CObjectActor runtimeAttachedActor = destroyProp.RuntimeAttachedActor;
					if (runtimeAttachedActor != null)
					{
						currentHealth = runtimeAttachedActor.Health;
						maxHealth = runtimeAttachedActor.MaxHealth;
						flag = runtimeAttachedActor.IsDead;
					}
					if (flag)
					{
						PropHealthState[] array6 = array;
						for (int i = 0; i < array6.Length; i++)
						{
							array6[i].UpdateState(currentHealth, maxHealth, isActorDead: true);
						}
					}
				}
				else
				{
					if (destroyProp.PropHealthDetails != null && destroyProp.PropHealthDetails.HasHealth && destroyProp.PropHealthDetails.DeathAction == PropHealthDetails.EDeathAction.Activate)
					{
						if (destroyProp is CObjectDoor)
						{
							return;
						}
						Log.Error($"Destroying a prop {destroyProp} with an Activate death action. This is wrong, either give the prop health state components, or don't destroy it");
					}
					EnvironmentLoader.Instance.BeforePropDestroyed(gameObject, destroyProp);
					UnityEngine.Object.Destroy(gameObject);
				}
			}
		}
		UIEventManager.AddUIEvent(new UIEvent(UIEvent.EUIEventType.PropDestroyed, null, destroyProp?.PropGuid));
	}

	private IEnumerator PrimePropActivationAnimation(GameObject propGO, string animParam)
	{
		float animatorCheckTimeout = 10f;
		int frameIntervalBetweenChecks = 10;
		float timeAtStart = Timekeeper.instance.m_GlobalClock.time;
		bool timedOut = false;
		int currentFrameInterval = frameIntervalBetweenChecks;
		while (propGO != null)
		{
			if (currentFrameInterval == frameIntervalBetweenChecks)
			{
				if (MF.GameObjectAnimatorPlay(propGO, animParam))
				{
					break;
				}
				currentFrameInterval = 0;
				if (timeAtStart - Timekeeper.instance.m_GlobalClock.time >= animatorCheckTimeout)
				{
					timedOut = true;
					break;
				}
			}
			yield return null;
			currentFrameInterval++;
		}
		if (timedOut)
		{
			Log.WarningFormat("Prop activation animation timed out. Prop:{0} | AnimationParameter:{1}");
		}
	}

	public void CheckOpenDoor(CObjectProp prop, CActor actorOpeningDoor, bool initialLoad, bool openDoorOnly)
	{
		if (((CObjectDoor)prop).LockType != CObjectDoor.ELockType.None)
		{
			GameObject gameObject = FindPropGameObject(prop);
			if (gameObject == null)
			{
				Log.Warning("Missing door gameobject for " + prop.InstanceName + " while trying to activate it - might result in missing lock gameobjects later");
			}
			else
			{
				UnityGameEditorDoorLockProp[] componentsInChildren = gameObject.GetComponentsInChildren<UnityGameEditorDoorLockProp>();
				for (int i = 0; i < componentsInChildren.Length; i++)
				{
					componentsInChildren[i].gameObject.SetActive(value: false);
				}
			}
		}
		if (actorOpeningDoor != null)
		{
			m_ActorOpeningDoor = actorOpeningDoor;
		}
		OpenDoor(prop, initialLoad, openDoorOnly);
	}

	public void OpenDoor(CObjectProp prop, bool initialLoad, bool openDoorOnly)
	{
		GameObject doorGO = FindPropGameObject(prop);
		if (doorGO == null)
		{
			Log.Warning("Failed to find door object to open");
			return;
		}
		UnityAction unityAction = () =>
		{
			MF.GameObjectAnimatorPlay(doorGO, "Open");
			if (!MF.GameObjectAnimatorControllerIsCurrentState(doorGO, "Open") && EnvironmentLoader.IsInstanceValid && EnvironmentLoader.Instance.IsLoadingComplete)
			{
				string audioID = "Door_Opening";
				DoorAudio componentInChildren = doorGO.GetComponentInChildren<DoorAudio>();
				if ((bool)componentInChildren)
				{
					audioID = componentInChildren.OpenAudioEvent;
				}
				AudioController.Play(audioID, doorGO.transform);
			}
			OutlineWrapper componentInChildren2 = doorGO.GetComponentInChildren<OutlineWrapper>();
			if (componentInChildren2 != null)
			{
				componentInChildren2.enabled = false;
			}
			if (openDoorOnly && m_ActorOpeningDoor != null)
			{
				GameObject gameObject2 = FindClientActorGameObject(m_ActorOpeningDoor);
				if (gameObject2 != null)
				{
					ActorBehaviour.GetActorBehaviour(gameObject2).PauseLoco(pause: false);
				}
				m_ActorOpeningDoor = null;
			}
		};
		if ((bool)MF.GetGameObjectAnimator(doorGO))
		{
			unityAction();
		}
		else
		{
			ProceduralProp component = doorGO.GetComponent<ProceduralProp>();
			if (component != null)
			{
				component.PlacementCompleteAction = unityAction;
			}
		}
		if (!initialLoad)
		{
			RevealRoomCreateCharacterActors();
			WorldspaceStarHexDisplay.Instance.ActorIsSelectingDoor(active: false);
			WorldspaceStarHexDisplay.Instance.RefreshCurrentState();
		}
		if (m_ActorOpeningDoor != null)
		{
			GameObject gameObject = FindClientActorGameObject(m_ActorOpeningDoor);
			if (gameObject != null)
			{
				ActorBehaviour.GetActorBehaviour(gameObject).PauseLoco(pause: false);
			}
			m_ActorOpeningDoor = null;
		}
	}

	public void UnlockLockedDoorWithoutOpening(CObjectProp prop)
	{
		if (((CObjectDoor)prop).LockType == CObjectDoor.ELockType.None)
		{
			return;
		}
		GameObject gameObject = FindPropGameObject(prop);
		if (!(gameObject != null))
		{
			return;
		}
		UnityGameEditorDoorLockProp[] componentsInChildren = gameObject.GetComponentsInChildren<UnityGameEditorDoorLockProp>();
		if (componentsInChildren.Length != 0)
		{
			bool flag = false;
			UnityGameEditorDoorLockProp[] array = componentsInChildren;
			foreach (UnityGameEditorDoorLockProp unityGameEditorDoorLockProp in array)
			{
				flag |= MF.GameObjectAnimatorPlay(unityGameEditorDoorLockProp.gameObject, "Unlock");
			}
		}
		if (m_CurrentActor != null)
		{
			GameObject gameObject2 = FindClientActorGameObject(m_CurrentActor);
			if (gameObject2 != null)
			{
				ActorBehaviour.GetActorBehaviour(gameObject2).PauseLoco(pause: false);
			}
		}
	}

	public void LockUnlockedDoor(CObjectProp prop)
	{
		if (((CObjectDoor)prop).LockType == CObjectDoor.ELockType.None)
		{
			return;
		}
		GameObject gameObject = FindPropGameObject(prop);
		if (gameObject != null)
		{
			UnityGameEditorDoorLockProp[] componentsInChildren = gameObject.GetComponentsInChildren<UnityGameEditorDoorLockProp>(includeInactive: true);
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].Reactivate();
			}
		}
	}

