	private static string FormatAttackModifier(string modifier)
	{
		if (modifier.Contains("Target"))
		{
			return string.Empty;
		}
		Match match = Regex.Match(modifier, "[-+x/][0-9]");
		if (match.Success)
		{
			string text = modifier.Substring(match.Index, 2);
			string text2 = null;
			if (text[0] == '-')
			{
				text2 = "<b><color=#A050E0>";
			}
			else if (text[0] == '+')
			{
				text2 = "<b><color=#FFA414>";
			}
			else if (text[0] == 'x')
			{
				text2 = ((text[1] != '0') ? "<b><color=#D92727>" : "<b><color=#A050E0>");
			}
			else if (text[0] == '/')
			{
				text2 = "<b><color=#A050E0>";
			}
			return string.Format(" {0}{1} {2}{3}", text2, text[0], text[1], "</color></b>");
		}
		return "";
	}

	public void EndGame(EResult result)
	{
		EndGame(result, null);
	}

	public void EndGame(EResult result, Action onFinish)
	{
		SaveData.Instance.EndScenario(result);
		ScenarioRuleClient.Stop();
		AudioController.StopAmbienceSound();
		SceneController.Instance.ShowLoadingScreen();
		Main.Unpause3DWorld(forceUnpause: true);
		StartCoroutine(EndGameCoroutine(result, onFinish));
	}

	public void EndGameAndSkipTutorial()
	{
		SaveData.Instance.EndScenario(EResult.Win);
		ScenarioRuleClient.Stop();
		AudioController.StopAmbienceSound();
		SceneController.Instance.ShowLoadingScreen();
		Main.Unpause3DWorld(forceUnpause: true);
		StartCoroutine(EndGameCoroutine(EResult.Win));
	}

	public IEnumerator EndGameCoroutine(EResult result, Action onUnloaded = null)
	{
		bool wasInFinalTutorial = IsInFinalTutorial();
		SaveData.Instance.Global.DisallowSpeedUp();
		yield return SaveData.Instance.EndScenarioThreaded(result);
		yield return UnityGameEditorRuntime.UnloadScenario();
		onUnloaded?.Invoke();
		if (wasInFinalTutorial)
		{
			PartyAdventureData currentAdventureData = SaveData.Instance.Global.CurrentAdventureData;
			SaveData.Instance.Global.SetResumeCampaign(null);
			Task task = SaveData.Instance.DeleteCampaign(currentAdventureData.PartyName);
			yield return new WaitForTask(task);
			MainMenuUIManager.SetLoadingCompleteCallback(SceneController.Instance.OnFinishedLoadToFrontEndTutorialMenu);
			SceneController.Instance.LoadMainMenu();
		}
		else if (SaveData.Instance.Global.GameMode == EGameMode.Campaign)
		{
			PlayerRegistry.StartWaitingForPlayers();
			SceneController.Instance.CampaignResume(SaveData.Instance.Global.CurrentAdventureData, isJoiningMPClient: false, newLoad: false);
		}
		else if (SaveData.Instance.Global.GameMode == EGameMode.FrontEndTutorial)
		{
			MainMenuUIManager.SetLoadingCompleteCallback(SceneController.Instance.OnFinishedLoadToFrontEndTutorialMenu);
			SceneController.Instance.LoadMainMenu();
		}
		else if (SaveData.Instance.Global.GameMode == EGameMode.MainMenu || SaveData.Instance.Global.GameMode == EGameMode.SingleScenario || SaveData.Instance.Global.GameMode == EGameMode.Autotest)
		{
			SceneController.Instance.LoadMainMenu();
		}
		else
		{
			Log.Error("Unsupported Mode set " + SaveData.Instance.Global.GameMode);
			SceneController.Instance.LoadMainMenu();
		}
	}

	private void LogConditionApplied(CActor applyingActor, CAbility ability, List<CActor> actorsAppliedTo)
	{
		SEventAbilityCondition sEventAbilityCondition = SEventLog.FindLastConditionAbilityEventOfAbilityType(onlyUnprocessed: false, ability.AbilityType, toScrape: false, ESESubTypeAbility.None, checkQueue: true);
		if (sEventAbilityCondition == null)
		{
			return;
		}
		string applyingActorName = LocalizationManager.GetTranslation(applyingActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(applyingActor);
		foreach (CActor item in actorsAppliedTo)
		{
			if (sEventAbilityCondition.AbilityType == CAbility.EAbilityType.AddActiveBonus)
			{
				continue;
			}
			string conditions = LocalizationManager.GetTranslation(sEventAbilityCondition.AbilityType.ToString()) + " <sprite name=" + HelperTools.GetCorrectSprite(sEventAbilityCondition.AbilityType) + ">";
			string actorName = LocalizationManager.GetTranslation(item.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(item);
			LogAbilityApplies(actorName, applyingActorName, conditions, ability.TreatedAsScenarioEffect(), ability.TreatedAsScenarioRule(), ability.TreatAsEventEffect);
			if (ability.AbilityType == CAbility.EAbilityType.Curse || ability.AbilityType == CAbility.EAbilityType.Bless)
			{
				for (int i = 1; i < ability.Strength; i++)
				{
					LogAbilityApplies(actorName, applyingActorName, conditions, ability.TreatedAsScenarioEffect(), ability.TreatedAsScenarioRule(), ability.TreatAsEventEffect);
				}
			}
		}
	}

	public void LogAbilityApplies(string actorName, string applyingActorName, string conditions, bool treatAsScenarioEffect, bool treatAsScenarioRule, bool treatAsEventEffect)
	{
		if (treatAsEventEffect)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_EVENT_APPLIES"), $"<b>{conditions}</b>", actorName), CombatLogFilter.CONDITIONS);
		}
		else if (treatAsScenarioEffect)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_QUEST_APPLIES"), $"<b>{conditions}</b>", actorName), CombatLogFilter.CONDITIONS);
		}
		else if (treatAsScenarioRule)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_QUEST_RULE_APPLIES"), $"<b>{conditions}</b>", actorName), CombatLogFilter.CONDITIONS);
		}
		else
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_APPLY_ABILITY"), applyingActorName, $"<b>{conditions}</b>", actorName), CombatLogFilter.CONDITIONS);
		}
	}

	private void LogAttackModifier(SEventAttackModifier attackModEvent, CActor attackingActor, CActor actorBeingAttacked, CAbility ability)
	{
		List<CCondition.ENegativeCondition> list = new List<CCondition.ENegativeCondition>();
		StringBuilder stringBuilder = new StringBuilder();
		StringBuilder stringBuilder2 = new StringBuilder();
		string arg = LocalizationManager.GetTranslation(attackingActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(attackingActor);
		string arg2 = LocalizationManager.GetTranslation(actorBeingAttacked.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorBeingAttacked);
		Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ATTACK"), arg, arg2, string.Format("<b>{0}</b>", LocalizationManager.GetTranslation("Attack") + " <sprite name=Attack> " + attackModEvent.AttackAbilityAttackStrength)), CombatLogFilter.ABILITIES);
		if (attackModEvent.NegativeConditionsFromModifiers.Count > 0)
		{
			foreach (CCondition.ENegativeCondition negativeConditionsFromModifier in attackModEvent.NegativeConditionsFromModifiers)
			{
				if (!list.Contains(negativeConditionsFromModifier))
				{
					stringBuilder2.Append(" + ");
					stringBuilder2.Append(string.Format("<b>{0}</b>", "<sprite name=" + negativeConditionsFromModifier.ToString() + "> "));
					list.Add(negativeConditionsFromModifier);
				}
			}
		}
		if (attackModEvent.OverrideBuffs.Count() > 0)
		{
			foreach (SEventAttackModifier.OverrideBuffData overrideBuff2 in attackModEvent.OverrideBuffs)
			{
				if (overrideBuff2.OverrideNegativeConditions.Count() <= 0)
				{
					continue;
				}
				foreach (CCondition.ENegativeCondition overrideNegativeCondition in overrideBuff2.OverrideNegativeConditions)
				{
					if (!list.Contains(overrideNegativeCondition))
					{
						stringBuilder2.Append(" + ");
						stringBuilder2.Append(string.Format("<b>{0}</b>", "<sprite name=" + overrideNegativeCondition.ToString() + ">"));
						list.Add(overrideNegativeCondition);
					}
				}
			}
		}
		if (attackModEvent.TargetActorWasPoisoned)
		{
			stringBuilder.Append(" + ");
			stringBuilder.Append(string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Poison> " + 1));
		}
		if (attackModEvent.ExploitedVulnerabilityStrength > 0)
		{
			stringBuilder.Append(" + ");
			stringBuilder.Append($"<b><color=#f76767>{attackModEvent.ExploitedVulnerabilityStrength}</color></b>");
		}
		int num = 0;
		IEnumerable<SEventAttackModifier.OverrideBuffData> enumerable = attackModEvent.OverrideBuffs.Where((SEventAttackModifier.OverrideBuffData x) => !x.IsScalar);
		if (enumerable.Any())
		{
			foreach (SEventAttackModifier.OverrideBuffData item in enumerable)
			{
				if (item.OverrideStrength != 0)
				{
					num += ((item.OverrideBuffType == SEventAttackModifier.OverrideBuffData.EOverrideBuffType.Item) ? item.OverrideStrength : 0);
					stringBuilder.Append(" " + ((item.OverrideStrength < 0) ? "-" : "+") + " ");
					stringBuilder.Append(string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Attack> " + item.OverrideStrength));
				}
			}
		}
		for (int num2 = 0; num2 < attackModEvent.OverrideBuffs.Count; num2++)
		{
			SEventAttackModifier.OverrideBuffData overrideBuff = attackModEvent.OverrideBuffs[num2];
			if (!overrideBuff.LogFullName || overrideBuff.OverrideStrength == 0)
			{
				continue;
			}
			string text = ((overrideBuff.OverrideStrength > 0) ? "+" : string.Empty);
			if (overrideBuff.IsScalar)
			{
				text = "x";
			}
			string text2 = string.Empty;
			if (overrideBuff.OverrideSourceActorClassID != null && ScenarioManager.Scenario.Enemies.Any((CEnemyActor x) => x.Class.ID == overrideBuff.OverrideSourceActorClassID))
			{
				if (!string.IsNullOrEmpty(overrideBuff.OverrideBuffName) && LocalizationManager.TryGetTranslation(overrideBuff.OverrideBuffName, out var translation))
				{
					text2 = translation;
				}
				else
				{
					CEnemyActor cEnemyActor = ScenarioManager.Scenario.Enemies.FirstOrDefault((CEnemyActor x) => x.Class.ID == overrideBuff.OverrideSourceActorClassID);
					if (cEnemyActor != null)
					{
						text2 = LocalizationManager.GetTranslation(cEnemyActor.ActorLocKey());
					}
				}
			}
			else
			{
				text2 = LocalizationManager.GetTranslation(overrideBuff.OverrideBuffName, fixForRTL: true, 0, ignoreRTLnumbers: true, applyParameters: false, null, null, skipWarnings: true, useDefaultIfMissing: false, returnNullIfNotFound: true);
			}
			if (!string.IsNullOrEmpty(text2))
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ATTACK_OVERRIDE_BUFF"), arg, string.Format("<b><color=#f76767>{0}</color></b>", text + overrideBuff.OverrideStrength + "<sprite name=Attack>"), $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{text2}</color></b></font>"));
			}
		}
		StringBuilder stringBuilder3 = new StringBuilder();
		StringBuilder stringBuilder4 = new StringBuilder();
		for (int num3 = 0; num3 < attackModEvent.UsedAttackModifierInfo.Count; num3++)
		{
			string text3 = attackModEvent.UsedAttackModifierInfo[num3].ModifierWithCustomLocalization;
			if (LocalizationManager.TryGetTranslation(text3, out var translation2))
			{
				text3 = translation2;
			}
			stringBuilder3.Append(text3);
			if (num3 != attackModEvent.UsedAttackModifierInfo.Count - 1)
			{
				stringBuilder3.Append(", ");
			}
		}
		for (int num4 = 0; num4 < attackModEvent.UnusedAttackModifierInfo.Count; num4++)
		{
			string text4 = attackModEvent.UnusedAttackModifierInfo[num4].ModifierWithCustomLocalization;
			if (LocalizationManager.TryGetTranslation(text4, out var translation3))
			{
				text4 = translation3;
			}
			stringBuilder4.Append(text4);
			if (num4 != attackModEvent.UnusedAttackModifierInfo.Count - 1)
			{
				stringBuilder4.Append(", ");
			}
		}
		if (attackModEvent.UnusedAttackModifierInfo.Count > 0)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_DRAW_ATTACK_MODIFIERS"), arg, stringBuilder3.ToString(), stringBuilder4.ToString()), CombatLogFilter.MODIFIERS);
		}
		else if (attackModEvent.UsedAttackModifierInfo.Count > 0)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_DRAW_ATTACK_MODIFIER"), arg, stringBuilder3.ToString()), CombatLogFilter.MODIFIERS);
		}
		for (int num5 = 0; num5 < attackModEvent.UsedAttackModifierInfo.Count; num5++)
		{
			SEventAttackModifier.ModifierInfo modifierInfo = attackModEvent.UsedAttackModifierInfo[num5];
			if (modifierInfo.ModifierChangedToValue != "")
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_CHANGE_MODIFIER"), modifierInfo.ModifierWithNoLocalization, modifierInfo.ModifierChangedToValue), CombatLogFilter.MODIFIERS);
			}
		}
		for (int num6 = 0; num6 < attackModEvent.UnusedAttackModifierInfo.Count; num6++)
		{
			SEventAttackModifier.ModifierInfo modifierInfo2 = attackModEvent.UnusedAttackModifierInfo[num6];
			if (modifierInfo2.ModifierChangedToValue != "")
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_CHANGE_MODIFIER"), modifierInfo2.ModifierWithNoLocalization[num6], modifierInfo2.ModifierChangedToValue), CombatLogFilter.MODIFIERS);
			}
		}
	}

	private void LogDamageCalculation(SEventAbilityDamage damageEvent, CActor attackingActor, CActor actorBeingAttacked, CAbility ability)
	{
		if (damageEvent == null)
		{
			return;
		}
		CAttackSummary.TargetSummary targetSummary = null;
		if (ability is CAbilityDamage cAbilityDamage)
		{
			CAttackSummary cAttackSummary = cAbilityDamage.DamageSummary.Copy();
			int targetIndex = 0;
			targetSummary = cAttackSummary.FindTarget(actorBeingAttacked, ref targetIndex);
			if (targetSummary == null)
			{
				targetSummary = cAbilityDamage.TargetsDamagedSummaries.SingleOrDefault((CAttackSummary.TargetSummary x) => x.ActorToAttack == actorBeingAttacked);
			}
		}
		if (targetSummary != null)
		{
			string attackingName = LocalizationManager.GetTranslation(attackingActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(attackingActor);
			string targetName = LocalizationManager.GetTranslation(actorBeingAttacked.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorBeingAttacked);
			int finalAttackStrength = targetSummary.FinalAttackStrength;
			LogDamage(finalAttackStrength, targetName, attackingName, ability.TreatedAsScenarioEffect(), ability.TreatedAsScenarioRule(), ability.TreatAsEventEffect);
		}
	}

	public void LogDamage(int strength, string targetName, string attackingName, bool treatAsScenarioEffect, bool treatAsScenarioRule, bool treatAsEventEffect)
	{
		if (treatAsEventEffect)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_EVENT_DAMAGE"), $"<b><color=#f76767>{strength}</color></b>", targetName), CombatLogFilter.DAMAGE);
		}
		else if (treatAsScenarioEffect)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_QUEST_DAMAGE"), $"<b><color=#f76767>{strength}</color></b>", targetName), CombatLogFilter.DAMAGE);
		}
		else if (treatAsScenarioRule)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_QUEST_RULE_DAMAGE"), $"<b><color=#f76767>{strength}</color></b>", targetName), CombatLogFilter.DAMAGE);
		}
		else
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_CONSUME_DAMAGE_TARGET"), attackingName, string.Format("<b><color=#f76767>{0}</color></b>", strength + " " + LocalizationManager.GetTranslation("Damage").ToLower()), targetName), CombatLogFilter.DAMAGE);
		}
	}

	private void LogDamageCalculation(SEventAbilityAttack attackAbilityEvent, SEventAttackModifier attackModEvent, CActor attackingActor, CActor actorBeingAttacked, CAbility ability, string overrideLogKey = null)
	{
		try
		{
			string text = LocalizationManager.GetTranslation(attackingActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(attackingActor);
			string arg = LocalizationManager.GetTranslation(actorBeingAttacked.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorBeingAttacked);
			if (attackModEvent.TargetActorWasInvulnerable)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_INVULNERABLE"), arg), CombatLogFilter.DAMAGE);
			}
			else
			{
				Singleton<CombatLogHandler>.Instance.AddLog(GetDamageCalcFormulaString(attackAbilityEvent, attackModEvent, attackingActor, actorBeingAttacked, ability, overrideLogKey), CombatLogFilter.DAMAGE);
			}
			StringBuilder stringBuilder = new StringBuilder();
			if (attackModEvent.PositiveConditionsFromModifiers.Count <= 0)
			{
				return;
			}
			foreach (CCondition.EPositiveCondition positiveConditionsFromModifier in attackModEvent.PositiveConditionsFromModifiers)
			{
				stringBuilder.Append("<sprite name=" + positiveConditionsFromModifier.ToString() + "> ");
			}
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_APPLY_ABILITY"), text, stringBuilder, text), CombatLogFilter.CONDITIONS);
		}
		catch (Exception ex)
		{
			Log.Exception(ex, "An exception occurred while processing LogDamageCalculation");
			SceneController.Instance.GlobalErrorMessage.ShowMessageDefaultTitle("ERROR_CHOREO_00215", "GUI_ERROR_MAIN_MENU_BUTTON", ex.StackTrace, UnityGameEditorRuntime.ErrorHandlingUnloadSceneAndLoadMainMenu, ex.Message);
		}
	}

	public static string GetDamageCalcFormulaString(SEventAbilityAttack attackAbilityEvent, SEventAttackModifier attackModEvent, CActor attackingActor, CActor actorBeingAttacked, CAbility ability, string overrideLogKey = null)
	{
		if (attackModEvent == null)
		{
			Log.Warning($"Trying to show damage calculation formula with null attack mod event when {attackingActor} attacks {actorBeingAttacked} with {ability}");
			return string.Empty;
		}
		string text = LocalizationManager.GetTranslation(attackingActor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(attackingActor);
		string text2 = LocalizationManager.GetTranslation(actorBeingAttacked.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actorBeingAttacked);
		CAttackSummary.TargetSummary targetSummary = null;
		List<CCondition.ENegativeCondition> list = new List<CCondition.ENegativeCondition>();
		StringBuilder stringBuilder = new StringBuilder();
		if (ability is CAbilityAttack cAbilityAttack)
		{
			CAttackSummary cAttackSummary = cAbilityAttack.AttackSummary.Copy();
			int targetIndex = 0;
			targetSummary = cAttackSummary.FindTarget(actorBeingAttacked, ref targetIndex);
		}
		StringBuilder stringBuilder2 = new StringBuilder();
		if (attackAbilityEvent.AddedNegativeConditionData.Count > 0)
		{
			foreach (SEventAbility.SEventAbilityAddedConditionData addedNegativeConditionDatum in attackAbilityEvent.AddedNegativeConditionData)
			{
				bool flag = false;
				if (attackModEvent.SecondaryActorNegativeConditions.Count() > 0)
				{
					foreach (NegativeConditionPair secondaryActorNegativeCondition in attackModEvent.SecondaryActorNegativeConditions)
					{
						CCondition.ENegativeCondition negativeCondition = secondaryActorNegativeCondition.NegativeCondition;
						if (addedNegativeConditionDatum.AddedConditionType.ToString() == negativeCondition.ToString())
						{
							flag = true;
						}
					}
				}
				if (flag)
				{
					stringBuilder2.Append(" + ");
					stringBuilder2.Append(string.Format("<b>{0}</b>", "<sprite name=" + addedNegativeConditionDatum.AddedConditionType.ToString() + ">"));
				}
			}
		}
		if (attackModEvent.NegativeConditionsFromModifiers.Count > 0)
		{
			foreach (CCondition.ENegativeCondition negativeConditionsFromModifier in attackModEvent.NegativeConditionsFromModifiers)
			{
				if (!list.Contains(negativeConditionsFromModifier))
				{
					stringBuilder2.Append(" + ");
					stringBuilder2.Append(string.Format("<b>{0}</b>", "<sprite name=" + negativeConditionsFromModifier.ToString() + "> "));
					list.Add(negativeConditionsFromModifier);
				}
			}
		}
		if (attackModEvent.OverrideBuffs.Count() > 0)
		{
			foreach (SEventAttackModifier.OverrideBuffData overrideBuff in attackModEvent.OverrideBuffs)
			{
				if (overrideBuff.OverrideNegativeConditions.Count() <= 0)
				{
					continue;
				}
				foreach (CCondition.ENegativeCondition overrideNegativeCondition in overrideBuff.OverrideNegativeConditions)
				{
					if (!list.Contains(overrideNegativeCondition))
					{
						stringBuilder2.Append(" + ");
						stringBuilder2.Append(string.Format("<b>{0}</b>", "<sprite name=" + overrideNegativeCondition.ToString() + ">"));
						list.Add(overrideNegativeCondition);
					}
				}
			}
		}
		if (attackModEvent.TargetActorWasPoisoned)
		{
			stringBuilder.Append(" + ");
			stringBuilder.Append(string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Poison> " + 1));
		}
		if (attackModEvent.ExploitedVulnerabilityStrength > 0)
		{
			stringBuilder.Append(" + ");
			stringBuilder.Append($"<b><color=#f76767>{attackModEvent.ExploitedVulnerabilityStrength}</color></b>");
		}
		int num = 0;
		IEnumerable<SEventAttackModifier.OverrideBuffData> enumerable = attackModEvent.OverrideBuffs.Where((SEventAttackModifier.OverrideBuffData x) => !x.IsScalar);
		if (enumerable.Any())
		{
			foreach (SEventAttackModifier.OverrideBuffData item2 in enumerable)
			{
				if (item2.OverrideStrength != 0)
				{
					num += ((item2.OverrideBuffType == SEventAttackModifier.OverrideBuffData.EOverrideBuffType.Item) ? item2.OverrideStrength : 0);
					stringBuilder.Append(" " + ((item2.OverrideStrength < 0) ? "-" : "+") + " ");
					stringBuilder.Append(string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Attack> " + item2.OverrideStrength));
				}
			}
		}
		if (targetSummary != null)
		{
			foreach (string additionalNonScalarModifier in targetSummary.AdditionalNonScalarModifiers)
			{
				Match match = Regex.Match(additionalNonScalarModifier, "[-+x/][0-9]");
				if (match.Success)
				{
					string text3 = additionalNonScalarModifier.Substring(match.Index, 2);
					stringBuilder.Append(" " + text3[0] + " ");
					stringBuilder.Append(string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Attack> " + text3[1]));
				}
			}
		}
		List<(string, string)> list2 = new List<(string, string)>();
		List<(string, string)> list3 = new List<(string, string)>();
		for (int num2 = 0; num2 < attackModEvent.UsedAttackModifierInfo.Count; num2++)
		{
			SEventAttackModifier.ModifierInfo modifierInfo = attackModEvent.UsedAttackModifierInfo[num2];
			string modifierValue = modifierInfo.ModifierValue;
			if (modifierValue.Length == 2 && modifierValue.StartsWith("*"))
			{
				string modifierWithNoLocalization = modifierInfo.ModifierWithNoLocalization;
				string modifierChangedToValue = modifierInfo.ModifierChangedToValue;
				string item = ((modifierChangedToValue == "") ? modifierWithNoLocalization : modifierChangedToValue);
				list2.Add((modifierValue, item));
			}
		}
		if (targetSummary != null)
		{
			foreach (var postShieldScalarModifier in targetSummary.PostShieldScalarModifiers)
			{
				list3.Add(postShieldScalarModifier);
			}
		}
		bool flag2 = list2.Count > 0;
		bool flag3 = list3.Count > 0 || attackModEvent.TargetActorHasWard || attackModEvent.TargetActorHasBrittle;
		StringBuilder stringBuilder3 = new StringBuilder();
		stringBuilder3.Append("(");
		if (stringBuilder.Length > 0)
		{
			stringBuilder3.Append("(");
		}
		string value = $"<sprite name=Attack> {attackModEvent.AttackAbilityAttackStrength}";
		int num3 = attackModEvent.BonusStrengthFromAttackModifiers + attackModEvent.BonusStrengthOutsideOfModifiers;
		if (targetSummary != null)
		{
			num3 += targetSummary.ScenarioBonusStrength;
		}
		if (num3 > 0)
		{
			stringBuilder3.Append("(");
			stringBuilder3.Append(value);
			stringBuilder3.Append($" + {num3}");
			stringBuilder3.Append(")");
		}
		else
		{
			stringBuilder3.Append(value);
		}
		if (targetSummary != null && targetSummary.AttackAbilityScalar > 1)
		{
			stringBuilder3.Append(" x " + targetSummary.AttackAbilityScalar);
		}
		stringBuilder3.Append(stringBuilder.ToString());
		if (stringBuilder.Length > 0)
		{
			stringBuilder3.Append(")");
		}
		if (targetSummary != null && targetSummary.AttackScalar > 1)
		{
			stringBuilder3.Append(" x " + targetSummary.AttackScalar);
		}
		stringBuilder3.Append(" ");
		for (int num4 = 0; num4 < attackModEvent.UsedAttackModifierInfo.Count; num4++)
		{
			SEventAttackModifier.ModifierInfo modifierInfo2 = attackModEvent.UsedAttackModifierInfo[num4];
			string mod = modifierInfo2.ModifierValue;
			if (!list3.Any(((string mod, string modString) x) => x.mod == mod) && !list2.Any(((string mod, string modString) x) => x.mod == mod))
			{
				string modifierWithNoLocalization2 = modifierInfo2.ModifierWithNoLocalization;
				string modifierChangedToValue2 = modifierInfo2.ModifierChangedToValue;
				string value2 = FormatAttackModifier((modifierChangedToValue2 == "") ? modifierWithNoLocalization2 : modifierChangedToValue2);
				stringBuilder3.Append(value2);
			}
		}
		if (attackModEvent.FinalPierce > 0)
		{
			if (attackModEvent.FinalPierce >= 99999)
			{
				stringBuilder3.Append(" + <sprite name=IgnoreShield>");
			}
			else
			{
				stringBuilder3.Append(" + <sprite name=Pierce> " + attackModEvent.FinalPierce);
			}
		}
		if (flag2)
		{
			stringBuilder3.Insert(1, "(");
			stringBuilder3.Append(")");
			foreach (var item3 in list2)
			{
				string value3 = FormatAttackModifier(item3.Item2);
				stringBuilder3.Append(value3);
			}
		}
		if (attackModEvent.TargetActorShield > 0 && attackModEvent.FinalPierce < 99999)
		{
			stringBuilder3.Append(" - <sprite name=Shield> " + attackModEvent.TargetActorShield);
		}
		if (flag3)
		{
			stringBuilder3.Insert(1, "(");
			stringBuilder3.Append(")");
			foreach (var item4 in list3)
			{
				string value4 = FormatAttackModifier(item4.Item2);
				stringBuilder3.Append(value4);
			}
			if (attackModEvent.TargetActorHasWard && !attackModEvent.TargetActorHasBrittle)
			{
				stringBuilder3.Append("<b><color=#A050E0> / 2 <sprite name=Ward> </color></b>");
			}
			else if (!attackModEvent.TargetActorHasWard && attackModEvent.TargetActorHasBrittle)
			{
				stringBuilder3.Append("<b><color=#D92727> x 2 <sprite name=Brittle> </color></b>");
			}
		}
		stringBuilder3.Append(" = ");
		stringBuilder3.Append(string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Attack> " + Math.Max(0, attackModEvent.FinalAttackStrength)));
		stringBuilder3.Append(")");
		stringBuilder3.Append(stringBuilder2.ToString());
		return string.Format(LocalizationManager.GetTranslation(string.IsNullOrEmpty(overrideLogKey) ? "COMBAT_LOG_DAMAGE" : overrideLogKey), text, string.Format("<b><color=#f76767>{0}</color></b>", "<sprite name=Attack> " + Math.Max(0, attackModEvent.FinalAttackStrength)), $"<b><color=#BBBBBB>{stringBuilder3.ToString()}</color></b>", text2);
	}

	public void LogActiveAbility(CActor actor, CAbility ability)
	{
		CActiveBonus cActiveBonus = actor.FindCardWithAbility(ability)?.ActiveBonuses.Find((CActiveBonus x) => x.Ability.ID == ability.ID && x.Actor == actor);
		if (cActiveBonus == null || ability.ActiveBonusData.Hidden || ability.ActiveBonusData.HiddenInLog || ability.ActiveBonusData.GetMiscVar("HiddenInCombatLog").GetBool())
		{
			return;
		}
		string text = "";
		string text2 = "";
		UIActiveAbility.CheckForLayoutToGenerate(cActiveBonus);
		if (cActiveBonus.Layout != null)
		{
			text = cActiveBonus.Layout.ListLayouts.FirstOrDefault();
			text2 = cActiveBonus.Layout.CardName;
		}
		if (ability.ActiveBonusData.ListLayoutOverride.Item1 != null)
		{
			text = ability.ActiveBonusData.ListLayoutOverride.Item1;
		}
		if (string.IsNullOrEmpty(text))
		{
			return;
		}
		int strength = cActiveBonus.Ability.Strength;
		List<string> list = cActiveBonus.Ability.ListLayoutOverrideParams(cActiveBonus);
		if (list != null)
		{
			for (int num = 0; num < list.Count; num++)
			{
				if (LocalizationManager.TryGetTranslation(list[num], out var translation))
				{
					list[num] = translation;
				}
			}
		}
		string text3 = CreateLayout.LocaliseText(text, skipWarnings: false, strength.ToString(), list?.FirstOrDefault());
		text3 = (text3.Contains('*'.ToString()) ? CardLayoutRow.ReplaceKey(text3, '*', cActiveBonus.Ability.Strength.ToString()) : text3);
		if (text3 != null)
		{
			string arg = LocalizationManager.GetTranslation(actor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actor);
			string text4 = (text2.IsNOTNullOrEmpty() ? (LocalizationManager.GetTranslation(text2) + " - ") : "");
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_ACTIVE_ABILITY"), arg, $"<b>{text4 + text3}</b>"), CombatLogFilter.ABILITIES);
		}
	}

	public void LogInfusedElements()
	{
		foreach (var item in m_ElementsInfusedThisAbility)
		{
			Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_INFUSING_ELEMENT"), LocalizationManager.GetTranslation(item.actor), LocalizationManager.GetTranslation("GUI_ELEMENT_" + item.element) + " <sprite name=" + item.element + ">"), CombatLogFilter.INFUSIONS);
		}
		m_ElementsInfusedThisAbility.Clear();
	}

	public void LogConsumedElements(CActor actor, List<ElementInfusionBoardManager.EElement> elements, CBaseCard card = null)
	{
		foreach (ElementInfusionBoardManager.EElement element in elements)
		{
			if (card == null || card.CardType == CBaseCard.ECardType.MonsterAbility || card.CardType == CBaseCard.ECardType.Dummy)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_CONSUME"), LocalizationManager.GetTranslation(actor.ActorLocKey()), LocalizationManager.GetTranslation("GUI_ELEMENT_" + element) + " <sprite name=" + element.ToString() + ">"), CombatLogFilter.INFUSIONS);
			}
			else
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation("COMBAT_LOG_CONSUME_ACTIVATE_ACTIVE_BONUS"), LocalizationManager.GetTranslation(actor.ActorLocKey()), LocalizationManager.GetTranslation("GUI_ELEMENT_" + element) + " <sprite name=" + element.ToString() + ">", $"<font=\"MarcellusSC-Regular SDF\"><b><color=#f3ddab>{LocalizationManager.GetTranslation(card.Name)}</color></b></font>"), CombatLogFilter.INFUSIONS);
			}
		}
	}

	public void LogConsumes(CActor actor, CAbility ability)
	{
		string actorName = LocalizationManager.GetTranslation(actor.ActorLocKey()) + GetActorIDForCombatLogIfNeeded(actor);
		IEnumerable<SEventAction> enumerable = SEventLog.FindAllEventsOfType<SEventAction>(onlyUnprocessed: false, toScrape: false).Where((SEventAction x) =>
		{
			if (x.SubTypeAction == ESESubTypeAction.ActionPerform)
			{
				Guid abilityGUID = x.AbilityGUID;
				Guid? guid = ability?.ID;
				return abilityGUID == guid;
			}
			return false;
		});
		IEnumerable<SEventAction> enumerable2 = enumerable.Where((SEventAction e) => e.ActionAugmentationDatas != null && e.ActionAugmentationDatas.Exists((SEventAction.SEventActionAugmentationData aad) => aad.ElementsConsumed.Any()));
		SEventAction sEventAction = (enumerable2.Any() ? enumerable2 : enumerable).LastOrDefault();
		if (sEventAction == null || ability == null || (!ability.AbilityHasHappened && !ability.HasEnded) || sEventAction.ActionAugmentationDatas.Count <= 0)
		{
			return;
		}
		foreach (SEventAction.SEventActionAugmentationData actionAugmentationData in sEventAction.ActionAugmentationDatas)
		{
			foreach (SEventAction.SEventActionAugmentationOpData augmentationOpData in actionAugmentationData.AugmentationOpDatas)
			{
				if (!augmentationOpData.AbilityOverrideData.ID.HasValue)
				{
					continue;
				}
				CAbility cAbility = ability;
				CAbilityOverride cAbilityOverride = ability.FindOverride(augmentationOpData.AbilityOverrideData.ID.Value);
				if (cAbilityOverride == null && PhaseManager.CurrentPhaseAction != null)
				{
					foreach (CPhaseAction.CPhaseAbility currentAndRemainingPhaseAbility in PhaseManager.CurrentPhaseAction.CurrentAndRemainingPhaseAbilities)
					{
						cAbilityOverride = currentAndRemainingPhaseAbility.m_Ability.FindOverride(augmentationOpData.AbilityOverrideData.ID.Value);
						if (cAbilityOverride != null)
						{
							cAbility = currentAndRemainingPhaseAbility.m_Ability;
							break;
						}
					}
				}
				if (cAbilityOverride != null && cAbility != null)
				{
					switch (cAbility.AbilityType)
					{
					case CAbility.EAbilityType.Move:
						LogConsumes(augmentationOpData, actorName, cAbility, actionAugmentationData.ElementsConsumed, "Move", "COMBAT_LOG_CONSUME_MOVE", "COMBAT_LOG_CONSUME_MOVE_NOELEMENT");
						break;
					case CAbility.EAbilityType.Trap:
					case CAbility.EAbilityType.Create:
					case CAbility.EAbilityType.Summon:
					case CAbility.EAbilityType.Teleport:
					case CAbility.EAbilityType.DisarmTrap:
					case CAbility.EAbilityType.DestroyObstacle:
					case CAbility.EAbilityType.AddTarget:
					case CAbility.EAbilityType.Push:
					case CAbility.EAbilityType.Pull:
					case CAbility.EAbilityType.Swap:
					case CAbility.EAbilityType.Fear:
					case CAbility.EAbilityType.AddModifierToMonsterDeck:
					case CAbility.EAbilityType.Teleport2:
						LogConsumes(augmentationOpData, actorName, cAbility, actionAugmentationData.ElementsConsumed, "Targeting");
						break;
					case CAbility.EAbilityType.Heal:
						LogConsumes(augmentationOpData, actorName, cAbility, actionAugmentationData.ElementsConsumed, "Heal", "COMBAT_LOG_CONSUME_HEAL", "COMBAT_LOG_CONSUME_HEAL_NOELEMENT");
						break;
					case CAbility.EAbilityType.Attack:
						LogConsumes(augmentationOpData, actorName, cAbility, actionAugmentationData.ElementsConsumed, "Attack", "COMBAT_LOG_CONSUME_DAMAGE", "COMBAT_LOG_CONSUME_DAMAGE_NOELEMENT");
						break;
					default:
						LogConsumes(augmentationOpData, actorName, cAbility, actionAugmentationData.ElementsConsumed);
						break;
					}
				}
			}
		}
	}

	public void LogConsumes(SEventAction.SEventActionAugmentationOpData opData, string actorName, CAbility ability, List<ElementInfusionBoardManager.EElement> elementsConsumed, string abilityType = null, string consumed = "COMBAT_LOG_CONSUME_ABILITY", string noconsume = "COMBAT_LOG_CONSUME_ABILITY_NOELEMENT", string consumeability = "COMBAT_LOG_CONSUME_ABILITY", string noconsumeability = "COMBAT_LOG_CONSUME_ABILITY_NOELEMENT", string nostrength = "COMBAT_LOG_CONSUME", bool consumeUnknown = true)
	{
		if (abilityType == null)
		{
			abilityType = ability.AbilityType.ToString();
		}
		else if (ability.AbilityInterruptCopy != null)
		{
			return;
		}
		CAbilityOverride cAbilityOverride = null;
		if (opData.AbilityOverrideData.ID.HasValue)
		{
			cAbilityOverride = ability.FindOverride(opData.AbilityOverrideData.ID.Value);
			if (cAbilityOverride == null && PhaseManager.CurrentPhaseAction != null)
			{
				foreach (CPhaseAction.CPhaseAbility item in PhaseManager.CurrentPhaseAction.CurrentPhaseAbilities.Concat(PhaseManager.CurrentPhaseAction.RemainingPhaseAbilities))
				{
					cAbilityOverride = item.m_Ability.FindOverride(opData.AbilityOverrideData.ID.Value);
					if (cAbilityOverride != null)
					{
						break;
					}
				}
			}
		}
		string text = "";
		if (opData.AbilityOverrideData.PositiveConditions != null && opData.AbilityOverrideData.PositiveConditions.Count > 0)
		{
			foreach (CCondition.EPositiveCondition positiveCondition in opData.AbilityOverrideData.PositiveConditions)
			{
				text = text + "<sprite name=" + positiveCondition.ToString() + ">";
			}
		}
		if (opData.AbilityOverrideData.NegativeConditions != null && opData.AbilityOverrideData.NegativeConditions.Count > 0)
		{
			foreach (CCondition.ENegativeCondition negativeCondition in opData.AbilityOverrideData.NegativeConditions)
			{
				text = text + "<sprite name=" + negativeCondition.ToString() + ">";
			}
		}
		if (opData.AbilityOverrideData.NumberOfTargets.HasValue && opData.AbilityOverrideData.NumberOfTargets > 0)
		{
			text = text + "+" + opData.AbilityOverrideData.NumberOfTargets + "<sprite name=Target>";
		}
		bool flag = false;
		int num = (opData.AbilityOverrideData.Strength.HasValue ? opData.AbilityOverrideData.Strength.Value : 0);
		CAbility.EAbilityType eAbilityType = (opData.AbilityOverrideData.AbilityType.HasValue ? opData.AbilityOverrideData.AbilityType.Value : ability.AbilityType);
		if (!(abilityType == "Heal"))
		{
			if (abilityType == "Targeting")
			{
				if (opData.AbilityOverrideData != null && num > 0 && eAbilityType == ability.AbilityType)
				{
					flag = true;
				}
			}
			else if (num > 0)
			{
				flag = true;
			}
		}
		else if (opData.AbilityOverrideData != null && num > 0 && eAbilityType == CAbility.EAbilityType.Heal)
		{
			flag = true;
		}
		if (flag)
		{
			string text2 = abilityType;
			if (abilityType == "Targeting")
			{
				text2 = eAbilityType.ToString();
			}
			if (!(text2 != CAbility.EAbilityType.None.ToString()))
			{
				return;
			}
			if (elementsConsumed.Count > 0)
			{
				string text3 = string.Empty;
				foreach (ElementInfusionBoardManager.EElement item2 in elementsConsumed)
				{
					if (!text3.IsNullOrEmpty())
					{
						text3 = text3 + " " + LocalizationManager.GetTranslation("and") + " ";
					}
					text3 += $"<sprite name={item2}>";
				}
				if (opData.Type == CActionAugmentationOp.EActionAugmentationType.AbilityOverride)
				{
					string text4 = null;
					if (cAbilityOverride?.Vars != null)
					{
						TValue var = cAbilityOverride.GetVar("PreviewOverride");
						if (!var.isUnknown)
						{
							text4 = var.GetString();
						}
					}
					if (string.IsNullOrEmpty(text4))
					{
						text4 = ((num >= 0) ? "+" : "-") + num + " " + LocalizationManager.GetTranslation(text2) + " <sprite name=" + text2 + "> " + text;
					}
					Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(consumed), actorName, text3, $"<b>{text4}</b>"), CombatLogFilter.ABILITIES);
				}
				else
				{
					Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(consumeability), actorName, text3, string.Format("<b>{0}</b>", LocalizationManager.GetTranslation(text2) + " <sprite name=" + text2 + ">" + num)), CombatLogFilter.ABILITIES);
				}
			}
			else if (opData.Type == CActionAugmentationOp.EActionAugmentationType.AbilityOverride)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(noconsume), actorName, string.Format("<b>{0}</b>", ((num >= 0) ? "+" : "-") + num + " " + LocalizationManager.GetTranslation(text2) + " <sprite name=" + text2 + "> " + text)), CombatLogFilter.ABILITIES);
			}
			else
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(noconsumeability), actorName, string.Format("<b>{0}</b>", LocalizationManager.GetTranslation(text2) + " <sprite name=" + text2 + ">" + num)), CombatLogFilter.ABILITIES);
			}
		}
		else
		{
			if (!consumeUnknown)
			{
				return;
			}
			string text5 = string.Empty;
			if (elementsConsumed.Count <= 0)
			{
				return;
			}
			foreach (ElementInfusionBoardManager.EElement item3 in elementsConsumed)
			{
				if (!text5.IsNullOrEmpty())
				{
					text5 = text5 + " " + LocalizationManager.GetTranslation("and") + " ";
				}
				text5 += $"<sprite name={item3}>";
			}
			bool flag2 = false;
			if (abilityType == "Move")
			{
				SEventAction.SEventAbilityOverrideData abilityOverrideData = opData.AbilityOverrideData;
				if (abilityOverrideData != null && abilityOverrideData.Jump == true)
				{
					Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(consumed), actorName, text5, string.Format("<b>{0}</b>", LocalizationManager.GetTranslation("Jump") + " <sprite name=Jump>")), CombatLogFilter.ABILITIES);
					flag2 = true;
				}
			}
			if (!flag2)
			{
				Singleton<CombatLogHandler>.Instance.AddLog(string.Format(LocalizationManager.GetTranslation(nostrength), actorName, text5), CombatLogFilter.ABILITIES);
			}
		}
	}

	public void OnSwitchHand(CPlayerActor cPlayer)
	{
		foreach (GameObject clientPlayer in m_ClientPlayers)
		{
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(clientPlayer);
			if (actorBehaviour.Actor != null)
			{
				actorBehaviour.m_WorldspacePanelUI?.Focus(cPlayer == actorBehaviour.Actor);
			}
		}
		Singleton<UIScenarioMultiplayerController>.Instance.ShowPlayerInfo(cPlayer);
	}

	public static string GetActorIDForCombatLogIfNeeded(CActor actor)
	{
		string result = string.Empty;
		if (!(actor is CHeroSummonActor))
		{
			CEnemyActor enemyActor = actor as CEnemyActor;
			if (enemyActor == null || (enemyActor.MonsterClass.Boss && ScenarioManager.Scenario.AllEnemyMonsters.Count((CEnemyActor x) => x.MonsterClass == enemyActor.MonsterClass) <= 1))
			{
				goto IL_0076;
			}
		}
		result = " (" + actor.ID + ")";
		goto IL_0076;
		IL_0076:
		return result;
	}

	public void HideSelectionUI()
	{
		if (Singleton<UIUseItemsBar>.Instance != null)
		{
			Singleton<UIUseItemsBar>.Instance.Hide();
		}
		if (Singleton<UIActiveBonusBar>.Instance != null)
		{
			Singleton<UIActiveBonusBar>.Instance.Hide(toggle: true);
		}
		if (Singleton<UIUseAbilitiesBar>.Instance != null)
		{
			Singleton<UIUseAbilitiesBar>.Instance.Hide(clearSelection: true);
		}
		if (Singleton<UIUseAugmentationsBar>.Instance != null)
		{
			Singleton<UIUseAugmentationsBar>.Instance.Hide();
		}
	}

	private void TryPlayConditionEffectOnActor(GameObject effectPrefab, CActor cActor, bool alreadyApplied = false, Action onNewlyApplied = null, EffectsBar.FEffect fEffect = EffectsBar.FEffect.None)
	{
		if (cActor.IsDead)
		{
			return;
		}
		UIEventManager.AddUIEvent(new UIEvent(UIEvent.EUIEventType.ActorConditionsChanged, null, contextActorGUID: cActor.ActorGuid, contextId: fEffect.ToString()));
		if (!(effectPrefab == null))
		{
			bool flag = fEffect != EffectsBar.FEffect.None;
			if (flag)
			{
				GUIInterface.s_GUIInterface.SetStatusText(fEffect.ToString());
			}
			GameObject gameObject = FindClientActorGameObject(cActor);
			ActorBehaviour actorBehaviour = ActorBehaviour.GetActorBehaviour(gameObject);
			if (!(gameObject == null) && !(actorBehaviour == null))
			{
				actorBehaviour.TryPlayConditionEffect(alreadyApplied, flag, effectPrefab, fEffect, onNewlyApplied);
			}
		}
	}

	private bool TryPlayEffectOnActor(GameObject effectPrefab, CActor cActor, Vector3? localPosition = null, Quaternion? rotation = null)
	{
		if (effectPrefab == null)
		{
			return false;
		}
		GameObject gameObject = FindClientActorGameObject(cActor);
		if (gameObject == null)
		{
			return false;
		}
		return TryPlayEffect(effectPrefab, gameObject.transform, localPosition, rotation);
	}

	private bool TryPlayEffect(GameObject effectPrefab, Transform parent, Vector3? localPosition = null, Quaternion? rotation = null)
	{
		if (effectPrefab == null)
		{
			return false;
		}
		VFXShared.PlayEffect(effectPrefab, parent, localPosition.HasValue ? localPosition.Value : Vector3.zero, rotation.HasValue ? rotation.Value : Quaternion.identity);
		return true;
	}

	public void ResetDelayedDrops()
	{
