	public void EndOfTurnReachedLocally()
	{
		if (FFSNetwork.IsClient)
		{
			Synchronizer.SendSideAction(GameActionType.EndOfTurnClientReady, null, canBeUnreliable: false, sendToHostOnly: true);
			Log.SimpleInfo("Player " + PlayerRegistry.MyPlayer.Username + " (ID: " + PlayerRegistry.MyPlayer.PlayerID.ToString() + ") reached end of turn as a Client, sending EndOfTurnClientReady to host.");
		}
		else if (!m_WaitForEndOfTurnList.Contains(PlayerRegistry.MyPlayer))
		{
			m_WaitForEndOfTurnList.Add(PlayerRegistry.MyPlayer);
			StartCoroutine(WaitForEndOfTurnComplete());
			Log.SimpleInfo("Player " + PlayerRegistry.MyPlayer.Username + " (ID: " + PlayerRegistry.MyPlayer.PlayerID.ToString() + ") reached end of turn as Host, starting WaitForEndOfTurnComplete coroutine to acknowledge clients.");
		}
		else
		{
			Log.Error("Host player is already added to WaitForEndOfTurnList");
		}
	}

	private IEnumerator WaitForEndOfTurnComplete()
	{
		while (PlayerRegistry.PlayersWeShouldWaitFor.Any((NetworkPlayer x) => m_WaitForEndOfTurnList.Find((NetworkPlayer y) => y.PlayerID == x.PlayerID) == null))
		{
			if (FFSNetwork.IsOnline)
			{
				yield return Timekeeper.instance.WaitForSeconds(0.1f);
				continue;
			}
			m_WaitForEndOfTurnList.Clear();
			TurnEndSyncedAndReadyToProceed();
			yield break;
		}
		Synchronizer.SendSideAction(GameActionType.EndOfTurnAllPlayersReady);
		m_WaitForEndOfTurnList.Clear();
		TurnEndSyncedAndReadyToProceed();
	}

	public void ServerACKClientReachingEndOfTurn(GameAction action)
	{
		NetworkPlayer player = PlayerRegistry.GetPlayer(action.PlayerID);
		if (player != null)
		{
			if (!m_WaitForEndOfTurnList.Contains(player))
			{
				m_WaitForEndOfTurnList.Add(player);
				Log.SimpleInfo("Host acknowledged client " + player.Username + "( ID: " + player.PlayerID.ToString() + " ) reached end of turn.");
			}
			else
			{
				Log.Error("Player " + player.PlayerID.ToString() + " is already added to WaitForEndOfTurnList");
			}
		}
		else
		{
			Log.NetworkWarning("Error determining the player who reached end of turn. NetworkPlayer returns null.");
		}
	}

