	public void EndOfAbilityReachedLocally()
	{
		if (FFSNetwork.IsClient)
		{
			if (m_ClientEndOfAbilityReadyPending)
			{
				Log.SimpleInfo("Player " + PlayerRegistry.MyPlayer.Username + " (ID: " + PlayerRegistry.MyPlayer.PlayerID.ToString() + ") reached end of ability as a Client but is already awaiting EndOfAbilityAllPlayersReady; suppressing duplicate EndOfAbilityClientReady (collapsed sync-point).");
			}
			else
			{
				m_ClientEndOfAbilityReadyPending = true;
				m_TimeOfEndAbilityClientReadySent = Timekeeper.instance.m_GlobalClock.unscaledTime;
				Synchronizer.SendSideAction(GameActionType.EndOfAbilityClientReady, null, canBeUnreliable: false, sendToHostOnly: true);
				Log.SimpleInfo("Player " + PlayerRegistry.MyPlayer.Username + " (ID: " + PlayerRegistry.MyPlayer.PlayerID.ToString() + ") reached end of ability as a Client, sending EndOfAbilityClientReady to host.");
			}
		}
		else if (!m_WaitForEndOfAbilityList.Contains(PlayerRegistry.MyPlayer))
		{
			m_WaitForEndOfAbilityList.Add(PlayerRegistry.MyPlayer);
			StartCoroutine(WaitForEndOfAbilityComplete());
			Log.SimpleInfo("Player " + PlayerRegistry.MyPlayer.Username + " (ID: " + PlayerRegistry.MyPlayer.PlayerID.ToString() + ") reached end of ability as Host, starting WaitForEndOfAbilityComplete coroutine to acknowledge clients.");
		}
		else
		{
			Log.Error("Host player is already added to WaitForEndOfAbilityList");
		}
	}

