	public void ClientProceedToActionSelection()
	{
		if (!m_ClientEndOfAbilityReadyPending)
		{
			Log.SimpleInfo("Received EndOfAbilityAllPlayersReady with no outstanding EndOfAbilityClientReady; ignoring (duplicate release or post-recovery).");
