	public void AbilityEndSyncedAndReadyToProceed()
	{
		if (!HasMessageOnQueue(CMessageData.MessageType.StartAbility))
		{
			CEndActorAbility_MessageData cEndActorAbility_MessageData = new CEndActorAbility_MessageData(m_CurrentActor);
			cEndActorAbility_MessageData.m_IsLastAbility = LastAbility;
			cEndActorAbility_MessageData.m_AdvanceGameState = AdvanceGameStateWhenEndAbilitySyncs;
			AdvanceGameStateWhenEndAbilitySyncs = false;
			Handle_EndAbility(cEndActorAbility_MessageData);
		}
		SaveData.Instance.Global.DisallowSpeedUp();
		SetBlockClientMessageProcessing(active: false);
	}

	private void TriggerAnyOnLongRestAddActiveBonuses(CPlayerActor playerActor)
	{
		StartCoroutine(WaitTriggerAnyOnLongRestAddActiveBonuses(playerActor));
	}

	[MessageHandler(CMessageData.MessageType.PlayerFinishedLongRestWithNoEffects)]
	public void Handle_PlayerFinishedLongRestWithNoEffects(CMessageData message)
	{
		CPlayerActor cPlayerActor = ((CPlayerFinishedLongRestWithNoEffects_MessageData)message).m_ActorSpawningMessage as CPlayerActor;
		EnableEndTurnButton(cPlayerActor);
		Singleton<UIUseItemsBar>.Instance.ShowUsableItems(cPlayerActor);
		Singleton<UIActiveBonusBar>.Instance.ShowActiveBonus(cPlayerActor, CAbility.EAbilityType.None, CActiveBonus.EActiveBonusBehaviourType.DuringTurnAbility);
	}

	[MessageHandler(CMessageData.MessageType.StackRewardsToShow)]
	public void Handle_StackRewardsToShow(CMessageData message)
	{
		CStackRewardsToShow_MessageData cStackRewardsToShow_MessageData = (CStackRewardsToShow_MessageData)message;
		StackRewardsToShow(cStackRewardsToShow_MessageData.m_ActorSpawningMessage, cStackRewardsToShow_MessageData.m_Rewards, cStackRewardsToShow_MessageData.m_SourceType);
	}

	[MessageHandler(CMessageData.MessageType.SetDeathDissolveLifeTime)]
	public void Handle_SetDeathDissolveLifeTime(CMessageData message)
	{
		CSetDeathDissolveLifeTime_MessageData cSetDeathDissolveLifeTime_MessageData = (CSetDeathDissolveLifeTime_MessageData)message;
		FindClientActorGameObject(cSetDeathDissolveLifeTime_MessageData.m_ActorSpawningMessage).GetComponentInChildren<DeathDissolve>().DissolveLifeTime = cSetDeathDissolveLifeTime_MessageData.m_DissolveLifeTime;
	}

	[MessageHandler(CMessageData.MessageType.PlayerFinishedShortRestWithNoEffects)]
	public void Handle_PlayerFinishedShortRestWithNoEffects(CMessageData message)
	{
		if (ShortRest.Instant)
		{
			CPlayerActor cPlayerActor = ((CPlayerFinishedShortRestWithNoEffects_MessageData)message).m_ActorSpawningMessage as CPlayerActor;
			CardsHandUI hand = Singleton<CardsHandManager>.Instance.GetHand(cPlayerActor);
			hand.UpdateCharacterSpecificMechanic();
			if (hand == Singleton<CardsHandManager>.Instance.CurrentHand && !Singleton<CardsHandManager>.Instance.IsShown)
			{
				CardsHandManager.ShowCardsSelection(cPlayerActor, refreshValid: true);
			}
			readyButton.Toggle(active: true, ReadyButton.EButtonState.EREADYBUTTONENDSELECTION, LocalizationManager.GetTranslation("GUI_END_SELECTION"), hideOnClick: true, glowingEffect: true);
			readyButton.SetInteractable(interactable: false);
			InitiativeTrack.Instance.helpBox.ShowDefault();
			ActorBehaviour.UpdateHealth(FindClientPlayer(cPlayerActor));
			InitiativeTrack.Refresh(cPlayerActor, isActiveButton: true);
		}
		else
		{
			((CPhaseShortRest)PhaseManager.CurrentPhase).NextStep();
		}
	}

