			FFSNetwork.HostingStartedEvent.AddListener(OnSwitchedToMultiplayer);
		}
	}

	private IEnumerator WaitForGenericConditionCoroutine(Func<bool> predicate, Action onFinish)
	{
		while (!predicate())
		{
			yield return new WaitForEndOfFrame();
		}
		onFinish();
	}

	[MessageHandler(CMessageData.MessageType.WaitForActorToBeAtTile)]
	public void Handle_WaitForActorToBeAtTile(CMessageData message)
	{
		CWaitForActorToBeAtTile_MessageData cWaitForActorToBeAtTile_MessageData = message as CWaitForActorToBeAtTile_MessageData;
		GameObject actorGO = FindClientActor(cWaitForActorToBeAtTile_MessageData.m_ActorSpawningMessage);
		if (actorGO == null && cWaitForActorToBeAtTile_MessageData.m_WaitForProp != null)
		{
			actorGO = FindPropGameObject(cWaitForActorToBeAtTile_MessageData.m_WaitForProp);
		}
		GameObject targetTile = EnvironmentLoader.Instance.GetTileHex(cWaitForActorToBeAtTile_MessageData.m_TargetTile.m_Hex.TileGuid);
		if (targetTile == null)
		{
			targetTile = EnvironmentLoader.Instance.GetTile(cWaitForActorToBeAtTile_MessageData.m_TargetTile.m_Hex.TileGuid);
		}
		if (actorGO == null || targetTile == null)
		{
			cWaitForActorToBeAtTile_MessageData.m_OnFinish?.Invoke();
			return;
		}
		StartCoroutine(WaitForGenericConditionCoroutine(() =>
		{
			Vector3 vector = actorGO.transform.position - targetTile.transform.position;
			vector.y = 0f;
			return vector.magnitude < 0.1f;
		}, cWaitForActorToBeAtTile_MessageData.m_OnFinish));
	}

	public async Task LoadProcGenScene(ScenarioRuleLibrary.ScenarioState state, bool isFirstLoad, [CanBeNull] KronosProfilingScaffolding profiling)
	{
		using (new MiniProfilerScope("Choreographer.LoadProcGenScene"))
		{
			m_CurrentState = state;
			m_IsFirstLoad = isFirstLoad;
			LoadingComplete = false;
			if (state.IsFirstLoad)
			{
				ProceduralMapTile.RevealedRooms.Clear();
			}
			else
			{
				ProceduralMapTile.RepopulateRevealedRooms(state);
			}
			Watchman.Instance.Start(from p in state.Props
				where !p.SkipVisuals
				select p.InstanceName);
			if (m_ProcGenScene.IsValid() && m_ProcGenScene.isLoaded)
			{
				await UnityGameEditorRuntime.OnSceneLoaded(SceneManager.GetSceneByName("ProcGen"), profiling);
				SceneController.Instance.DisableLoadingScreen();
				return;
			}
			using (new MiniProfilerScope("Choreographer.LoadProcGenScene.LoadSceneAsync"))
			{
				AsyncOperation asyncLoad = SceneManager.LoadSceneAsync("ProcGen", LoadSceneMode.Additive);
				while (!asyncLoad.isDone)
				{
					await Task.Yield();
				}
			}
			m_ProcGenScene = SceneManager.GetSceneByName("ProcGen");
			StartCoroutine(CheckScenarioAssetBundlesAreLoadedCoroutine(profiling));
		}
	}

	public IEnumerator OnSceneLoadedCallbackContinued([CanBeNull] KronosProfilingScaffolding profiling)
	{
		using (new MiniProfilerScope("Choreographer.OnSceneLoadedCallbackContinued"))
		{
			if (AutoTestController.s_AutoTestCurrentlyLoaded)
			{
				CCustomLevelData currentCustomLevelData = SaveData.Instance.Global.CurrentCustomLevelData;
				GameState.ShuffleAttackModsEnabledForPlayers = currentCustomLevelData.ShuffleAttackModsEnabledForPlayers;
				GameState.ShuffleAbilityDecksEnabledForMonsters = currentCustomLevelData.ShuffleAbilityDecksEnabledForMonsters;
				GameState.ShuffleAttackModsEnabledForMonsters = currentCustomLevelData.ShuffleAttackModsEnabledForMonsters;
				GameState.RandomiseOnLoad = false;
			}
			else if (SaveData.Instance.Global.CurrentCustomLevelData != null && SaveData.Instance.Global.GameMode != EGameMode.LevelEditor)
			{
				CCustomLevelData currentCustomLevelData2 = SaveData.Instance.Global.CurrentCustomLevelData;
				GameState.ShuffleAttackModsEnabledForPlayers = currentCustomLevelData2.ShuffleAttackModsEnabledForPlayers;
				GameState.ShuffleAbilityDecksEnabledForMonsters = currentCustomLevelData2.ShuffleAbilityDecksEnabledForMonsters;
				GameState.ShuffleAttackModsEnabledForMonsters = currentCustomLevelData2.ShuffleAttackModsEnabledForMonsters;
				GameState.RandomiseOnLoad = currentCustomLevelData2.RandomiseOnLoad;
			}
			else
			{
				GameState.ShuffleAttackModsEnabledForPlayers = true;
				GameState.ShuffleAbilityDecksEnabledForMonsters = true;
				GameState.ShuffleAttackModsEnabledForMonsters = true;
				GameState.RandomiseOnLoad = false;
			}
			if (AutoTestController.s_AutoTestCurrentlyLoaded)
			{
				AutoTestController.s_Instance.OnProcGenLoadCompleteCallback(SceneController.Instance.GetCurrentScene);
			}
			profiling?.Stopwatch?.Time("Enironment Begin");
			yield return LevelEditorController.s_Instance.LoadGameMaps(m_CurrentState, m_IsFirstLoad, SpawnPropsAndCharactersAsync, profiling);
			Log.Info("Apparance and map loading done.");
			if (SaveData.Instance.Global.GameMode == EGameMode.LevelEditor)
			{
				LevelEditorController.s_Instance.OnProcGenLoadCompleteCallback(SceneController.Instance.GetCurrentScene);
			}
			if (Application.isPlaying)
			{
				SetSeason(m_CurrentState);
			}
			profiling?.Stopwatch?.Time("Enironment Complete");
			if (SceneController.Instance.ScenarioIsLoading)
			{
				Log.Info("Scenario is still loading, waiting for it to finish before hiding curtain.");
				using (new MiniProfilerScope("Choreographer.OnSceneLoadedCallbackContinued.Wait ScenarioIsLoading"))
				{
					yield return new WaitWhile(() => SceneController.Instance.ScenarioIsLoading);
				}
			}
			yield return null;
			GameState.OnAfterLoad();
			SceneController.Instance.DisableLoadingScreen();
			profiling?.Stopwatch?.Time("Load Scenario Complete");
			LoadingComplete = true;
		}
		async void SpawnPropsAndCharactersAsync(ByRef<bool> completed)
		{
			using (new MiniProfilerScope("Choreographer.OnSceneLoadedCallbackContinued.SpawnPropsAndCharactersAsync"))
			{
				if (SaveData.Instance.Global.GameMode != EGameMode.LevelEditor)
				{
					CustomLevelSetPlayerPositions();
				}
				await UnityGameEditorRuntime.OnSceneLoaded(SceneManager.GetSceneByName("ProcGen"), profiling);
				using (new MiniProfilerScope("Choreographer.OnSceneLoadedCallbackContinued.SpawnPropsAndCharactersAsync.wait for Watchman.Instance.IsComplete"))
				{
					int timeout = 20;
					float start = Time.timeSinceLevelLoad;
					while (!Watchman.Instance.IsComplete)
					{
						if (Time.timeSinceLevelLoad - start > (float)timeout)
						{
							Debug.LogError("[ERROR] Timeout waiting for props to spawn. Remaining: " + string.Join(",", Watchman.Instance.GetRemaining()) + ".");
							break;
						}
						await Task.Yield();
					}
					Log.Info("Props and characters done.");
					completed.Value = true;
					profiling?.Stopwatch?.Time("Props and characters done");
				}
			}
		}
	}

