	public IEnumerator CheckScenarioAssetBundlesAreLoadedCoroutine([CanBeNull] KronosProfilingScaffolding profiling)
	{
		using (new MiniProfilerScope("Choreographer.CheckScenarioAssetBundlesAreLoadedCoroutine"))
		{
			using (new MiniProfilerScope("Choreographer.CheckScenarioAssetBundlesAreLoadedCoroutine.Wait ScenarioBundlesLoading"))
			{
				yield return new WaitWhile(() => AssetBundleManager.Instance.ScenarioBundlesLoading);
			}
			yield return OnSceneLoadedCallbackContinued(profiling);
		}
	}

